INSERT INTO `document_chunk` VALUES (19, 3, 1, 18, '        p2.sendMessage();         }     } af://n258 af://n264 2.3.3 两个对象的情况二 2.3.3.1 案例  public class PhoneDemo3 { public static void main(String[] args) {     // 创建对象         Phone p = new Phone();           // 给成员变量赋值         p.brand = \"OPPO\";         p.price = 2999;         p.color = \"白色\";           // 输出成员变量         System.out.println(p.brand + \"‐‐‐\" + p.price + \"‐‐‐\" + p.color);                 // 把p对象赋值给p2 Phone p2 = p;           // 给成员变量赋值         p2.brand = \"魅族\";         p2.price = 1999;', 500, 500, 1, '40f6a113-b72e-450e-b3ad-7696e6d8cb12', NULL, '2026-03-25 23:51:24');
INSERT INTO `document_chunk` VALUES (20, 3, 1, 19, '   // 把p对象赋值给p2 Phone p2 = p;           // 给成员变量赋值         p2.brand = \"魅族\";         p2.price = 1999;         p2.color = \"蓝色\";           // 再次输出成员变量         System.out.println(p.brand + \"‐‐‐\" + p.price + \"‐‐‐\" + p.color);         System.out.println(p2.brand + \"‐‐‐\" + p2.price + \"‐‐‐\" + p2.color);           }     } af://n269 af://n270 2.3.3.2 2个对象的内存图 - 两个引用指向同一个对象 2.4 成员变量和局部变量的区别 2.4.1 在类中的位置不同 成员变量： 类中方法外 局部变量： 方法内或者方法声明上(形式参数) 2.4.2 在内存中的位置不同 成员变量： 堆内存 局部变量： 栈内存 2.4.3 生命周期不同 成员变量： 随着对象的存在而存在，随', 500, 500, 1, '18a5aba8-4f7a-4cad-be40-328954055352', NULL, '2026-03-25 23:51:24');
INSERT INTO `document_chunk` VALUES (21, 3, 1, 20, '变量： 类中方法外 局部变量： 方法内或者方法声明上(形式参数) 2.4.2 在内存中的位置不同 成员变量： 堆内存 局部变量： 栈内存 2.4.3 生命周期不同 成员变量： 随着对象的存在而存在，随着对象的消失而消失 局部变量： 随着方法的调用而存在，随着方法的调用完毕而消失 2.4.4 初始化值不同 成员变量： 有默认的初始化值 局部变量： 没有默认的初始化值，必须先定义，赋值，才能使用。 2.4.5 案例 af://n274 af://n279 af://n280 af://n287 af://n294 af://n301 af://n308   2.5 类名作为形式参数和返回值 2.5.1 类名作为形式参数案例 要的其实是该类的对象 2.5.1.1 案例   public class Variable { /**       * @Fields x : 成员变量x       */       int x;          /**       * @Title: show       * @Description: 显示变量           */     public v', 500, 500, 1, '18aa3370-5fad-405e-b6d3-cf3272fc164d', NULL, '2026-03-25 23:51:25');
