INSERT INTO `document_chunk` VALUES (222, 6, 2, 18, '............................................................................... 201 \n\n\n\n \n\nIII \n\n \n\n第二节 评价的类型 ...................................................................................................... 203 \n\n第三节 课堂教学评价的维度 ....................................................................................... 207 \n\n \n\n \n\n \n\n \n\n \n\n \n\n \n\n \n\n \n\n \n\n \n\n \n\n \n\n \n\n \n\n \n\n \n\n \n\n \n\n \n\n \n\n \n\n \n\n \n\n \n\n \n\n \n\n \n\n\n\n \n\nIV \n\n \n\n \n\n \n\n \n\n\n\n学员专用 请勿外泄 \n\n \n\n1 中公教育学员专用资料 报名专线：400-6300-999 \n\n前言 考情介绍 \n\n一、高中', 497, 497, 1, 'f89fad4d-4a30-41ea-b4b0-b01cf3f38e85', NULL, '2026-03-27 20:07:33');
INSERT INTO `document_chunk` VALUES (223, 6, 2, 19, 'IV \n\n \n\n \n\n \n\n \n\n\n\n学员专用 请勿外泄 \n\n \n\n1 中公教育学员专用资料 报名专线：400-6300-999 \n\n前言 考情介绍 \n\n一、高中 \n\n模块 题型 分值 \n\n物理学科与教学知识 \n单项选择题 8 道×5 分=40 分 \n\n计算题 1 道 20 分 \n\n教学实施 \n案例分析题 2 道 20 分+30 分=50 分 \n\n教学评价 \n\n教学设计 教学设计题 2 道 12 分+28 分=40 分 \n\n合计 \n选择：约 27% \n\n非选择：73% \n \n\n二、初中 \n\n模块 题型 分值 \n\n物理学科与教学知识 \n单项选择题 8 道×5 分=40 分 \n\n简答题 2 道×10 分= 20 分 \n\n教学实施 \n案例分析题 2 道 20 分+30 分=50 分 \n\n教学评价 \n\n教学设计 教学设计题 2 道 12 分+28 分=40 分 \n\n合计 \n选择：约 27% \n\n非选择：73% \n \n\n特殊说明： \n\n1.无论是初中高中教师资格考试，选择题当中都是以高中知识为主，初中教师资格考试可能有 1', 463, 463, 1, 'bec17a09-7cfd-4d98-b344-0d147bc15177', NULL, '2026-03-27 20:07:33');
INSERT INTO `document_chunk` VALUES (224, 6, 2, 20, '道 12 分+28 分=40 分 \n\n合计 \n选择：约 27% \n\n非选择：73% \n \n\n特殊说明： \n\n1.无论是初中高中教师资格考试，选择题当中都是以高中知识为主，初中教师资格考试可能有 1\n\n道或 2 道是初中知识，有可能是课程标准/教学论知识，高中部分则可能有 1 道或 2 道是大学知识。 \n\n2.根据历年考题经验，高中考察的一道计算题一般都是大学物理知识（简单微积分）。 \n\n \n\n\n\n学员专用 请勿外泄 \n\n \n\n2 中公教育学员专用资料 报名专线：400-6300-999 \n\n第一部分 初中物理 \n\n第一章 声现象 \n\n一、声音的产生和传播 \n\n（一）声音的产生 \n\n1.声音是由物体的振动产生的（一切发声的物体都在振动）。2.振动停止，发声停止；但声音并没\n\n立即消失（误区警示：“振动停止，发声也停止”是指当发声的物体停止振动时，发声体将停止发声，\n\n但原来发出的声音却在介质中继续传播，直至消失，所以不能理解为“振动停止，声音消失”）。 \n\n3.产生声音的条件：一是要有发声体，二是发声体在振动。 \n\n（二）声音的传播', 472, 472, 1, 'e9655bb1-c398-4b26-8d90-2426b9ce0761', NULL, '2026-03-27 20:07:33');
INSERT INTO `document_chunk` VALUES (225, 6, 2, 21, '3.产生声音的条件：一是要有发声体，二是发声体在振动。 \n\n（二）声音的传播 \n\n1.声音的传播条件：声音的传播需要介质，一切固体、液体、气体都可以作为介质。真空不能传\n\n声，月球上（太空中）的宇航员只能通过无线电话交谈； \n\n注意：有声音物体一定振动，有振动不一定能听见声音； \n\n2.声音传播形式：；声音在介质中以波的形式传播，叫做声波。 \n\n（三）声速 \n\n1.声速：物体在每秒内传播的距离叫声速，单位是 m/s；声音在 150C 空气中的速度为 340m/s。 \n\n2.声速与介质关系:声音在固体中传播最快，液体中传播较快，气体中最慢。 \n\n3.声速与温度的关系：声速随温度的升高而增大，温度每升高 1℃，声音在空气中每秒传播的距离\n\n增加 0.6m。 \n\n \n\n（四）回声 \n\n声音在传播过程中，遇到障碍物被反射回来，再传入人的耳朵里，人耳听到反射回来的声音叫回\n\n声（如：高山的回声，夏天雷声轰鸣不绝，北京的天坛的回音壁） \n\n1.听见回声的条件：原声与回声之间的时间间隔在 0.1s 以上（教室里听不见老师说话的回声，狭\n\n小房间声音变大是因为原声与回声重合）；', 488, 488, 1, '62e8f0c0-46f8-4333-a178-d175c923b677', NULL, '2026-03-27 20:07:33');
INSERT INTO `document_chunk` VALUES (226, 6, 2, 22, '山的回声，夏天雷声轰鸣不绝，北京的天坛的回音壁） \n\n1.听见回声的条件：原声与回声之间的时间间隔在 0.1s 以上（教室里听不见老师说话的回声，狭\n\n小房间声音变大是因为原声与回声重合）； \n\n\n\n学员专用 请勿外泄 \n\n \n\n3 中公教育学员专用资料 报名专线：400-6300-999 \n\n2.回声的利用：测量距离（车到山，海深，冰川到船的距离）； \n\n二、声音的特性 \n\n（一）声音特性 \n\n1.音调：声音的高低叫音调，频率越高，音调越高（频率：物体在每秒内振动的次数，表示物体振\n\n动的快慢，单位是赫兹；） \n\n2.响度：声音的强弱叫响度；物体振幅越大，响度越大；物体振幅越小，响度越小；听者距发声者\n\n越远响度越小； \n\n3.音色：不同的物体的音调、响度尽管都可能相同，但音色却一定不同，音色受发声体的材料、结\n\n构和发声方式影响。（辨别是什么物体发的声靠音色） \n\n注意：音调、响度、音色三者互不影响，彼此独立； \n\n \n\n4.辨别音调和响度的四种方法： \n\n（1）根据定义辨别：音调是指声音的高低，响度是指声音的强弱 \n\n（2）根据影响因素辨别：', 481, 481, 1, 'be6a5ec7-4bbf-4d5f-9fc3-04ee486d4e24', NULL, '2026-03-27 20:07:33');
INSERT INTO `document_chunk` VALUES (227, 6, 2, 23, '音色） \n\n注意：音调、响度、音色三者互不影响，彼此独立； \n\n \n\n4.辨别音调和响度的四种方法： \n\n（1）根据定义辨别：音调是指声音的高低，响度是指声音的强弱 \n\n（2）根据影响因素辨别： \n\n影响音调的因素是频率，即物体振动的快慢； \n\n影响响度的因素是振幅，即物体振动的幅度，另一个因素是距离发声体的远近。 \n\n（3）根据波形辨别：音调不同，声音的波形疏密不同；响度不同声音的波形振幅不同. \n\n（4）根据对人耳的刺激程度辨别：音调又称声音的尖细，音调高的声音比较尖细，人感到刺耳；\n\n响度又称声音的大小。 \n\n注意：音调高的声音其响度不一定大，同理响度大的声音音调也不一定高。 \n\n例 1.观众对中央电视台举办的成语大赛好评如潮，大赛中涉及的下列成语主要跟声音的响度有关的\n\n是（ ） \n\nA.震耳欲聋 B.燕语莺声 C.掩耳盗铃 D.抑扬顿挫 \n\n（二）超声波、次声波 \n\n1.声音振动的快慢常用频率表示。频率的单位为赫兹(赫)，例如：某音叉每秒振动 50 次，其频率\n\n为 50Hz。', 450, 450, 1, '9e8a73de-3e1e-4254-9ea6-97a55bef550b', NULL, '2026-03-27 20:07:34');
INSERT INTO `document_chunk` VALUES (228, 6, 2, 24, '频率的单位为赫兹(赫)，例如：某音叉每秒振动 50 次，其频率\n\n为 50Hz。 \n\n2.（1）人耳感受到声音的频率有一个范围：20Hz～20000Hz，高于 20000Hz 叫超声波；低于 20Hz\n\n叫次声波；人无法听到次声波和超声波，但是有些动物可以听到次声波或者超声波。 \n\n\n\n学员专用 请勿外泄 \n\n \n\n4 中公教育学员专用资料 报名专线：400-6300-999 \n\n \n\n三、噪声及声音的利用 \n\n（一）噪声 \n\n1.噪声：（1）从物理角度上讲物体做无规则振动时发出的声音叫噪声；（2）从环保的角度上讲，\n\n凡是妨碍人们正常学习、工作、休息的声音以及对人们要听的声音产生干扰的声音都是噪声； \n\n2.乐音：从物理角度上讲，物体做有规则振动发出的声音； \n\n3.常见噪声来源：飞机的轰鸣声、汽车的鸣笛声、鞭炮声、金属之间的摩擦声等等； \n\n4.噪声的等级：表示声音强弱的单位是分贝。符号 dB，超过 90dB 会损害健康；0dB 指人耳刚好能\n\n听见的声音； \n\n5.控制噪声：（1）在声源处减弱（安消声器）；（2）在传播过程中减弱（植树。隔音墙）（3）', 485, 485, 1, '765a1244-93d1-48dd-ad10-4e0290abfe9d', NULL, '2026-03-27 20:07:34');
INSERT INTO `document_chunk` VALUES (229, 6, 2, 25, '符号 dB，超过 90dB 会损害健康；0dB 指人耳刚好能\n\n听见的声音； \n\n5.控制噪声：（1）在声源处减弱（安消声器）；（2）在传播过程中减弱（植树。隔音墙）（3）\n\n在人耳处减弱（戴耳塞） \n\n（二）声音利用 \n\n1.声与信息 \n\n声音可以传递信息，这在医疗、工业、军事、日常生活等各个方面都有应用。 \n\n（1）回声定位：蝙蝠在飞行时会发出超声波，这些超声波碰到障碍物或昆虫时会反射回来，蝙蝠\n\n根据接受到回声的强弱、方向和时间可以确定目标的方位。 \n\n（2）声纳：根据“回声定位”的原理，可用来探测海洋的深度，绘制海底地形图，探测鱼群信息，\n\n判断敌军舰艇的种类、方位及大小等 \n\n（3）B 超：医生用 B 型超声波诊断仪向病人体内发射超声波，然后用移动的探头接收体内脏器\n\n反射回来的超声波，经计算机处理后显示在屏幕上。 \n\n2.声与能量 \n\n声可以传递能量。声波传递能量在日常生产和生活中有广泛的应用 \n\n（1）超声波清洗精密机械； \n\n（2）超声波除去人体内的结石； \n\n\n\n学员专用 请勿外泄 \n\n \n\n5 中公教育学员专用资料 报名专线：400-6300-999', 492, 492, 1, '6cdf27d3-8b0f-4ae9-9d9b-54f85e177aca', NULL, '2026-03-27 20:07:34');
INSERT INTO `document_chunk` VALUES (230, 6, 2, 26, '常生产和生活中有广泛的应用 \n\n（1）超声波清洗精密机械； \n\n（2）超声波除去人体内的结石； \n\n\n\n学员专用 请勿外泄 \n\n \n\n5 中公教育学员专用资料 报名专线：400-6300-999 \n\n（3）超声波加湿空气； \n\n例 2．关于“声现象”的说法正确的是（ ） \n\nA．声和激光都能传播信息且都可以在真空中传播 \n\nB．住宅安装双层玻璃窗是在声源处控制噪音 \n\nC．利用“超声波”除去体内结石是利用声能传递能量 \n\nD．只有主人说出暗语时才能打开“声纹锁”，其辨别声音的主要依据是音调 \n\n \n\n\n\n学员专用 请勿外泄 \n\n \n\n6 中公教育学员专用资料 报名专线：400-6300-999 \n\n第二章 物态变化 \n\n一、温度计的使用 \n\n1.使用前“两看”—量程和分度值； \n\n（1）实验室用温度计：-20℃~110℃、（一般） \n\n（2）体温计：35℃~42℃、0.1℃； \n\n（3）寒暑表：-35℃~50℃、1℃. \n\n2.根据实际情况选择量程适当的温度计；如果待测温度高于温度计的最高温度，就会涨破温度计；\n\n反之则读不出温度。 \n\n3.温度计使用的几个要点', 488, 488, 1, '7682210a-81fb-486c-a4cd-c75727646de0', NULL, '2026-03-27 20:07:34');
INSERT INTO `document_chunk` VALUES (231, 6, 2, 27, '3.温度计使用的几个要点 \n\n（1）温度计的玻璃泡要全部浸泡在待测液体中，不能碰容器底或容器壁。 \n\n（2）温度计的玻璃泡浸入被测液体后要稍等一会，不能在示数上升时读数，待示数稳定后再读数。 \n\n（3）读数时温度计的玻璃泡要继续留在液体中；视线要与温度计中液柱的液面相平. \n\n \n\n4.体温计 \n\n（1）量程：35℃~42℃；分度值：0.1℃. \n\n（2）特殊结构：玻璃泡上方有很细的缩口。使用方法：用前须甩一甩。（否则只升不降） \n\n二、物态变化 \n\n（一）熔化和凝固 \n\n1.定义： \n\n熔化：物质从固态变为液态的过程。凝固：物质从液态变为固态的过程。 \n\n生活中熔化与凝固的现象：蜡烛点燃后，蜡熔化；炼钢铁时，钢铁熔化；冬天水结冰了… \n\n2.实验：探究固体融化时温度变化规律 \n\n（1）酒精灯的使用：①往酒精灯加酒精时，不能超过其容积的 2/3；②加热时用酒精灯的外焰加热，\n\n因为外焰的温度最高；③点燃酒精灯时，一般用火柴点燃，不能用已点燃的酒精灯去引燃另一个酒精灯；\n\n④熄灭酒精灯时，用灯帽盖灭，不能用嘴吹。 \n\n（2）海波熔化实验：用水浴法加热——为了海波受热均匀。', 492, 492, 1, '370d58e8-bc0d-4ea6-b6ae-b95e9f0bd5db', NULL, '2026-03-27 20:07:34');
INSERT INTO `document_chunk` VALUES (232, 6, 2, 28, '（2）海波熔化实验：用水浴法加热——为了海波受热均匀。 \n\n3.固体的分类——晶体与非晶体 \n\n（1）晶体：在熔化过程中不断吸热温度保持不变。常见晶体：冰、金属、萘、海波。 \n\n（2）非晶体：在熔化过程中不断吸热温度继续上升。常见非晶体：松香、石蜡、沥青、玻璃。 \n\n\n\n学员专用 请勿外泄 \n\n \n\n7 中公教育学员专用资料 报名专线：400-6300-999 \n\n（3）熔点：晶体熔化时的温度；凝固点：晶体凝固时的温度。同种晶体的熔点和凝固点是相同的。\n\n非晶体没有熔点，也没有凝固点。 \n\n4. 晶体熔化和凝固曲线图： \n\n \n\n上图中 AD 是晶体熔化曲线图，晶体在 AB 段处于固态，在 BC 段是熔化过程，吸热，但温度不\n\n变，处于固液共存状态，CD 段处于液态；而 DG 是晶体凝固曲线图，DE 段于液态，EF 段落是凝固\n\n过程，放热，温度不变，处于固液共存状态，FG 处于固态。 \n\n5.熔化吸热，凝固放热 \n\n（1）晶体和非晶体熔化时都需要吸热； \n\n（2）凝固是熔化的逆过程。无论晶体还是非晶体，在凝固时都要放热；晶体凝固时放出热量，但', 479, 479, 1, 'f68f3672-d378-493e-904d-660f690cedf8', NULL, '2026-03-27 20:07:35');
INSERT INTO `document_chunk` VALUES (233, 6, 2, 29, '5.熔化吸热，凝固放热 \n\n（1）晶体和非晶体熔化时都需要吸热； \n\n（2）凝固是熔化的逆过程。无论晶体还是非晶体，在凝固时都要放热；晶体凝固时放出热量，但\n\n温度不变，非晶体凝固时放出热量，温度降低。 \n\n（二）汽化和液化 \n\n1.汽化和液化 \n\n汽化：物质从液态变为气态的过程； \n\n液化：物质从气态变为液态的过程。 \n\n生活中汽化、液化的现象：洒在地上的水过段时间就会变干、露珠的形成…… \n\n2.汽化的两种形式——沸腾和蒸发 \n\n（1）沸腾：在一定温度下，液体的内部和表面同时发生的剧烈的汽化现象。 \n\n探究：水沸腾时温度变化规律 \n\n实验现象： \n\n① 温度计示数先上升后保持不变；② 沸腾前后都有气泡产生；③ 声音响度由大变小。 \n\n\n\n学员专用 请勿外泄 \n\n \n\n8 中公教育学员专用资料 报名专线：400-6300-999 \n\n \n\n沸腾的必要条件（缺一不可）：①液体温度达到沸点；②不断吸热。 \n\n沸点：不同的液体在沸腾时都有确定的温度，这个温度叫做沸点。 \n\n不同液体的沸点不同，沸点还与大气压有关。', 461, 461, 1, '257426b7-79f2-4073-9763-d346d554d773', NULL, '2026-03-27 20:07:35');
INSERT INTO `document_chunk` VALUES (234, 6, 2, 30, '沸点：不同的液体在沸腾时都有确定的温度，这个温度叫做沸点。 \n\n不同液体的沸点不同，沸点还与大气压有关。 \n\n（2）蒸发：在任何温度下，只发生在液体表面的缓慢的汽化现象。蒸发具有制冷作用。 \n\n影响蒸发快慢的因素（用控制变量法探究）： \n\nⅠ.液体的温度；Ⅱ.液体的表面积；Ⅲ.液体表面的气流速度。 \n\n沸腾和蒸发的异同点 \n\n 相同点 \n不同点 \n\n发生条件 发生部位 发生程度 \n\n沸腾 \n都是汽化现象，都需要吸热 \n\n一定温度（达到沸点） 液体表面和内部 剧烈 \n\n蒸发 任何温度下 只在液体表面 缓慢 \n\n3.液化——物质从气态变为液态的过程。 \n\n（1）生活中液化的现象： \n\nA.冬天人呼出的“白气”——呼出的水蒸气遇冷液化而成的小水滴 \n\nB.夏天打开冰箱时的“白气”、 雾的形成、露水的形成、夏天冰镇饮料“出汗”——空气中的水\n\n蒸气遇冷液化而成的小水滴 \n\n（2）液化的两种方式：①降低温度；②压缩体积。如：液化石油气 \n\n4.汽化吸热，液化放热 \n\n（三）升华和凝华 \n\n1.升华和凝华 \n\n升华：物质从固态直接变为气态的过程。', 474, 474, 1, '5ff2d037-86c2-4391-9e63-26a1403b92dd', NULL, '2026-03-27 20:07:35');
INSERT INTO `document_chunk` VALUES (235, 6, 2, 31, '如：液化石油气 \n\n4.汽化吸热，液化放热 \n\n（三）升华和凝华 \n\n1.升华和凝华 \n\n升华：物质从固态直接变为气态的过程。 \n\n凝华：物质从气态直接变为固态的过程。 \n\n2.升华吸热，凝华放热。 \n\n升华吸热——制冷或者获得低温。如：利用干冰人工降雨。 \n\n3.升华吸热，凝华放热的应用： \n\n（1）用久了的灯泡的灯丝（钨）会变细，灯泡内壁会变黑。 \n\n（2）人工降雨：人们从陆地向云层发射干冰（固态二氧化碳）或从飞机上向云层撒干冰，从而达\n\n到降雨的目的。固态二氧化碳升华吸收热量，造成温度降低，从而导致空气中的水蒸气发生液化。 \n\n\n\n学员专用 请勿外泄 \n\n \n\n9 中公教育学员专用资料 报名专线：400-6300-999 \n\n（3）谚语说：“霜前冷，雪后寒”，这说明了霜是由于_气温非常低_而使空气中的水蒸气发生凝华\n\n_而形成的；雪后寒是由于_升华吸热_导致气温降低，使人感到寒冷。 \n\n（四）物质的三态联系 \n\n \n\n例 1．对于雨、雪、雾、霜，以下分析正确的是（ ） \n\nA．春天的雨是熔化现象，形成过程需要放热 \n\nB．夏天的雾是液化现象，形成过程需要放热', 489, 489, 1, '2ac3f9bf-07c7-44cc-bd89-2ebf7664467f', NULL, '2026-03-27 20:07:35');
INSERT INTO `document_chunk` VALUES (236, 6, 2, 32, '（四）物质的三态联系 \n\n \n\n例 1．对于雨、雪、雾、霜，以下分析正确的是（ ） \n\nA．春天的雨是熔化现象，形成过程需要放热 \n\nB．夏天的雾是液化现象，形成过程需要放热 \n\nC．秋日的霜是汽化现象，形成过程需要吸热 \n\nD．冬天的雪是汽化现象，形成过程需要吸热 \n\n \n\n\n\n学员专用 请勿外泄 \n\n \n\n10 中公教育学员专用资料 报名专线：400-6300-999 \n\n第三章 内能 \n\n一、比热容 \n\n（一）热量 \n\n热量：物体在热传递过程中转移能量的多少叫做热量。（热量的国际单位是焦耳）注意：热量是一\n\n个过程量，它对应于热传递的过程。不能说：一个物体含有或具有多少热量。只能说：一个物体吸收了\n\n多少热量或放出了多少热量 \n\n（二）比热容 \n\n1.概念：单位质量的某种物质温度升高（或者降低）1℃吸收（或者放出）的热量叫做这种物质的\n\n比热容，用符号 c表示，单位焦每千克摄氏度，符号 J/（kg.℃） \n\n水的比热容是 4.2×10\n3\nJ/（kg.℃）。它的物理意义是：1千克水温度升高（或降低）1℃，吸收（或\n\n放出）的热量是 4.2×10\n3\nJ。', 487, 487, 1, '1f744905-9a0d-4d10-b930-4eb6b59e88c4', NULL, '2026-03-27 20:07:35');
INSERT INTO `document_chunk` VALUES (237, 6, 2, 33, '它的物理意义是：1千克水温度升高（或降低）1℃，吸收（或\n\n放出）的热量是 4.2×10\n3\nJ。 \n\n2.比热容是物质的一种特性，各种物质都有自己的比热。各物质中，水的比热容最大。这就意味着，\n\n在同样受热或冷却的情况下，水的温度变化要小些。（在受太阳照射条件相同时，白天沿海地区比内陆\n\n地区温度升高的慢，夜晚沿海地区温度降低也少。所以一天之中，沿海地区温度变化小，内陆地区温度\n\n变化大。在一年之中，夏季内陆比沿海炎热，冬季内陆比沿海寒冷） \n\n水比热容大的特点，在生产、生活中也经常利用。如汽车发动机、发电机等机器，在工作时要发热，\n\n通常要用循环流动的水来冷却。冬季也常用热水取暖。 \n\n3.说明 \n\n（1）比热容是物质的特性之一，所以某种物质的比热不会因为物质吸收或放出热量的多少而改变，\n\n也不会因为质量的多少或温度变化的多少而改变。 \n\n（2）同种物质在同一状态下，比热是一个不变的定值。 \n\n（3）物质的状态改变了，比热容随之改变。如水变成冰。 \n\n（4）不同物质的比热容一般不同。 \n\n（三）热量的计算 \n\n热传递过程中吸收或放出的热量', 478, 478, 1, 'c27b3ef1-1951-46c1-a4af-41bff45f9187', NULL, '2026-03-27 20:07:35');
INSERT INTO `document_chunk` VALUES (238, 6, 2, 34, '（3）物质的状态改变了，比热容随之改变。如水变成冰。 \n\n（4）不同物质的比热容一般不同。 \n\n（三）热量的计算 \n\n热传递过程中吸收或放出的热量 \n\n（1）温度升高时的吸热公式 )( 0ttcmQ 吸 \n\n（2）温度降低时的放热公式 )( 0 ttcmQ 放 \n\n（c---比热容、m---质量、t0表示原来的初温，t表示末温） \n\n二、内能的利用 \n\n（一）热机 \n\n热机：利用燃料的燃烧来做功的装置。内能转化为机械能（蒸气机——内燃机——喷气式发动机） \n\n\n\n学员专用 请勿外泄 \n\n \n\n11 中公教育学员专用资料 报名专线：400-6300-999 \n\n热机的种类：蒸汽机、内燃机、汽轮机、喷气发动机。尽管他们构造不同，但它们有一个共同点，\n\n就是把内能转化成机械能。 \n\n（二）内燃机 \n\n1.内燃机：燃料直接在发动机气缸内燃烧产生动力的机器叫内燃机。它主要有汽油机和柴油机。 \n\n2.汽油机工作过程：吸气冲程、压缩冲程、做功冲程、排气冲程。在这四个阶段，吸气冲程、压缩\n\n冲程和排气冲程是依靠飞轮的惯性来完成的，而做功冲程是内燃机中唯一对外做功的冲程，是由内能转', 493, 493, 1, '33fbc61e-b88f-424f-b905-b297d69163da', NULL, '2026-03-27 20:07:36');
INSERT INTO `document_chunk` VALUES (239, 6, 2, 35, '2.汽油机工作过程：吸气冲程、压缩冲程、做功冲程、排气冲程。在这四个阶段，吸气冲程、压缩\n\n冲程和排气冲程是依靠飞轮的惯性来完成的，而做功冲程是内燃机中唯一对外做功的冲程，是由内能转\n\n化为机械能。另外压缩冲程将机械能转化为内能。 \n\n \n\n3.汽油机和柴油机的比较： \n\n \n\n（三）燃料的热值 \n\n1.热值：1kg 某种燃料完全燃烧放出的热量，叫做这种燃料的热值。单位：J/kg，酒精的热值是\n\n3.0×107J/kg，它表示：1kg 酒精完全燃烧放出的热量是 3.0×107J。 \n\n2.热值公式：Q=mq 或 Q=Vq（其中 m 为燃料的质量，V 为燃料的体积，q 为燃料的热值）。火箭\n\n常用液态氢做燃料，是因为：液态氢的热值大，体积小便于储存和运输 \n\n（四）热机的效率 \n\n1.热机的效率：热机用来做有用功的那部分能量和完全燃烧放出的能量之比叫做热机的效率。 \n\n\n\n学员专用 请勿外泄 \n\n \n\n12 中公教育学员专用资料 报名专线：400-6300-999 \n\n2.公式： 100%\nW\n\nQ\n  有用\n\n总\n\n，热机效率总是低于 1。', 480, 480, 1, '2f75e358-8a86-4067-a703-c82bda29d8fd', NULL, '2026-03-27 20:07:36');
INSERT INTO `document_chunk` VALUES (240, 6, 2, 36, '学员专用 请勿外泄 \n\n \n\n12 中公教育学员专用资料 报名专线：400-6300-999 \n\n2.公式： 100%\nW\n\nQ\n  有用\n\n总\n\n，热机效率总是低于 1。 \n\n \n\n\n\n学员专用 请勿外泄 \n\n \n\n13 中公教育学员专用资料 报名专线：400-6300-999 \n\n第四章 光现象 \n\n一、光的反射 \n\n（一）光的反射 \n\n1.光的反射：光射到物体的表面上时，有一部分光会被物体表面反射回来，这种现象叫做光的反射。 \n\n \n\n2.光的反射中基本概念： \n\n（1）一点：光的入射点 O。 \n\n（2）两角：入射角 i，入射光线与法线的夹角；反射角 r，反射光线与法线的夹角。 \n\n（3）三线：入射光线 AO；反射光线 OB；法线，经过 O 并垂直于反射面的直线，是一条辅助线。 \n\n（二）光的反射定律 \n\n1、光的反射定律： \n\n①在反射现象中，反射光线、入射光线和法线在同一平面内； \n\n②反射光线和入射光线分居在法线两侧； \n\n③反射角等于入射角。 \n\n简述: ①三线共面②两线分居③两角相等', 459, 459, 1, 'ac91548c-8012-4afa-a6fd-342adc03698c', NULL, '2026-03-27 20:07:36');
INSERT INTO `document_chunk` VALUES (241, 6, 2, 37, '简述: ①三线共面②两线分居③两角相等 \n\n注：①入射角与反射角之间存在因果关系，反射角总是随入射角的变化而变化而变化， \n\n因而只能说“反射角等于入射角”，不能说“入射角等于反射角”。 \n\n②对应于一条入射光线，只有一条反射光线；而入射角大小相等的入射光线有无数条。 \n\n③反射光线经平面镜反射后沿水平方向射出时，水平方向有两个方向，有两条反射光线。 \n\n（三）光路的可逆性 \n\n1、光路的可逆性：如果光线沿原来的反射光线的方向射到界面上，这时的反射光线定会沿原来的\n\n入射光线的方向射出去，这种现象叫做光路具有可逆性。 \n\n2、在反射现象中，光路是可逆的（从镜中互相看到双方眼睛的问题） \n\n（四）镜面反射和漫反射 \n\n1.镜面反射：平行光射到光滑反射面上, 反射光仍然被平行反射出去的现象，叫做镜面反射。 \n\n2.漫反射：平行光射到粗糙反射面上，反射光沿各个方向反射出去的现象，叫做漫反射。 \n\n3.镜面反射和漫反射的异同点 \n\n（1）相同点：镜面反射和漫反射都是反射现象，都遵守光的反射定律。 \n\n\n\n学员专用 请勿外泄', 464, 464, 1, '3a229034-b688-4e20-a4cd-3e6908bd3a26', NULL, '2026-03-27 20:07:36');
INSERT INTO `document_chunk` VALUES (242, 6, 2, 38, '3.镜面反射和漫反射的异同点 \n\n（1）相同点：镜面反射和漫反射都是反射现象，都遵守光的反射定律。 \n\n\n\n学员专用 请勿外泄 \n\n \n\n14 中公教育学员专用资料 报名专线：400-6300-999 \n\n（2）不同点:①反射面不同：镜面反射的反射面是光滑平面，平行光束反射后仍为平行光束；漫反\n\n射的反射面是粗糙不平的，平行光束反射后射向各个方向，不再平行。 \n\n②一个方向的入射光，镜面反射的反射光只射向一个方向（刺眼）；而漫反射射向四面八方。 \n\n二、平面镜成像 \n\n1.探究平面镜成像特点实验 \n\n \n\n探究一:物与像的大小是否相同 \n\n（1）如何确定像的位置？ \n\n方法：用平板玻璃代替镜子，其目的是：便于确定像的位置。 \n\n（2）怎样比较像与物的大小关系？ \n\n方法：用另一个完全相同的物体代替像的位置，观察是否重合。（替代法） \n\n（3）只做一次实验科学吗？ \n\n方法：改变物体到镜面的远近位置，观察物与像是否重合。（多次实验，便于寻找规律，避免偶然\n\n性） \n\n结论:像与物大小相等。 \n\n探究二:物与像到镜面的距离关系', 468, 468, 1, '619a2dd7-d72a-45dd-be3d-be899e2d39d9', NULL, '2026-03-27 20:07:36');
INSERT INTO `document_chunk` VALUES (243, 6, 2, 39, '（多次实验，便于寻找规律，避免偶然\n\n性） \n\n结论:像与物大小相等。 \n\n探究二:物与像到镜面的距离关系 \n\n方法：用尺子量像到平面镜的距离和物到平面镜的距离，再进行比较。 \n\n结论:像到平面镜的距离与物到平面镜的距离相等。像与物关于平面镜对称。 \n\n探究三:实像与虚像 \n\n方法：移去平面镜后另一物体，在镜后像的位置放一光屏（或白纸），看白纸上能否出现镜前物体\n\n的像。 \n\n结论:平面镜成的是虚像。 \n\n实像：能被人看见，也能在光屏上呈现的像叫实像。 \n\n虚像：能被人看见，但不能在光屏上呈现的像叫虚像。 \n\n2.平面镜成像特点 \n\n平面镜成像的特点：正立、等大、等距的虚像 \n\n（1）正立：像是正立的。 \n\n\n\n学员专用 请勿外泄 \n\n \n\n15 中公教育学员专用资料 报名专线：400-6300-999 \n\n像和物上下方向相同，左右方向相反（镜中人的左手是人的右手，看镜子中的钟的时间要看纸张的\n\n反面）。 \n\n（2）等大：像与物大小相等（高度和宽度都相同） \n\n物远离或靠近镜面时，像的大小不变，都与物体相同。', 461, 461, 1, '4f79daf6-af33-40e0-95dc-3cf0ad94ea3b', NULL, '2026-03-27 20:07:36');
INSERT INTO `document_chunk` VALUES (244, 6, 2, 40, '（2）等大：像与物大小相等（高度和宽度都相同） \n\n物远离或靠近镜面时，像的大小不变，都与物体相同。 \n\n（3）等距：像和物到镜面的距离相等。（例：物离水面多高，像离水面就是多远，与水的深度无\n\n关） \n\n注：①如果成像不清楚，可以用光照射物体。 \n\n②无论怎样移动镜后面的物体，都不能与镜前物体的像重合，原因是：玻璃板没有与桌面相垂\n\n直。 \n\n③观察像时，发现两个几乎重叠的像，这是因为玻璃板前后两个表面都能成像造成的，应选用\n\n厚度薄些的玻璃板。 \n\n三、光的折射及色散 \n\n（一）光的折射 \n\n1.光的折射：光从一种介质斜射入另一种介质时，传播方向一般会发生变化，这种现象叫光的折射 \n\n光的折射与光的反射一样都是发生在两种介质的交界处，只是反射光返回原介质中，而折射光则进\n\n入到另一种介质中，由于光在在两种不同的物质里传播速度不同，故在两种介质的交界处传播方向发生\n\n变化，这就是光的折射。 \n\n注意：在两种介质的交界处，既发生折射，同时也发生反射 \n\n2.光的折射规律：光从空气斜射入水或其他介质中时，折射光线与入射光线、法线在同一平面上，', 477, 477, 1, 'c817c061-b85c-41ae-8ad0-b3d2be8d9c65', NULL, '2026-03-27 20:07:36');
INSERT INTO `document_chunk` VALUES (245, 6, 2, 41, '注意：在两种介质的交界处，既发生折射，同时也发生反射 \n\n2.光的折射规律：光从空气斜射入水或其他介质中时，折射光线与入射光线、法线在同一平面上，\n\n折射光线和入射光线分居法线两侧；折射角小于入射角；入射角增大时，折射角也随着增大；当光线垂\n\n直射向介质表面时，传播方向不变，在折射中光路可逆。 \n\n注意：（1）三线一面（2）两线分居（3）两角关系分三种情况：①入射光线垂直界面入射时，折\n\n射角等于入射角等于 0°；②光从空气斜射入水等介质中时，折射角小于入射角；③光从水等介质斜射入\n\n空气中时，折射角大于入射角 \n\n（二）色散 \n\n1.光的色散现象：一束太阳光通过三棱镜，被分成七种色光的现象叫光的色散，这七种色光从上至\n\n下依次排列为红、橙、黄、绿、蓝、靛、紫。同理，被分解后的色光也可以混合成在一起成为白光。 \n\n2.光的色散结论：（1）白光不是单色光，而是由各种单色光组成的复色光；（2）不同的单色光通\n\n过三棱镜时偏折的程度是不同的，红光的偏折程度最小，紫光的偏折程度最大。 \n\n（三）看不见的光 \n\n1.红外线应用：“热谱图”，红外线夜视仪，遥控（如遥控器）', 487, 487, 1, '36c90fb3-024e-49fb-b8d5-aa19a1f08938', NULL, '2026-03-27 20:07:37');
INSERT INTO `document_chunk` VALUES (246, 6, 2, 42, '（三）看不见的光 \n\n1.红外线应用：“热谱图”，红外线夜视仪，遥控（如遥控器） \n\n2.紫外线应用：有助于合成维生素 D，促进钙吸收，杀菌，是荧光物质发光（验钞机） \n\n四、透镜 \n\n（一）透镜及其基本概念 \n\n\n\n学员专用 请勿外泄 \n\n \n\n16 中公教育学员专用资料 报名专线：400-6300-999 \n\n凸透镜：边缘薄，中央厚； \n\n凹透镜：边缘厚，中央薄 \n\n主光轴：通过两个球心的直线 \n\n光心：主光轴上有个特殊的点，通过它的光线传播方向不变。（透镜中心可认为是光心） \n\n焦点：凸透镜能使跟主轴平行的光线会聚在主光轴上的一点，这点叫透镜的焦点，用“F”表示 \n\n虚焦点：跟主光轴平行的光线经凹透镜后变得发散，发散光线的反向延长线相交在主光轴上一点，\n\n这一点不是实际光线的会聚点，所以叫虚焦点。 \n\n焦距：焦点到光心的距离叫焦距，用“f”表示。 \n\n每个透镜都有两个焦点、焦距和一个光心。 \n\n \n\n（二）透镜对光的作用 \n\n凸透镜：对光起会聚作用（如图） \n\n \n\n凹透镜：对光起发散作用（如图） \n\n \n\n五、探究凸透镜成像规律实验', 477, 477, 1, 'a0999419-002b-493b-9f7a-7cab8759a55e', NULL, '2026-03-27 20:07:37');
INSERT INTO `document_chunk` VALUES (247, 6, 2, 43, '每个透镜都有两个焦点、焦距和一个光心。 \n\n \n\n（二）透镜对光的作用 \n\n凸透镜：对光起会聚作用（如图） \n\n \n\n凹透镜：对光起发散作用（如图） \n\n \n\n五、探究凸透镜成像规律实验 \n\n实验器材：凸透镜、光屏、蜡烛、光具座（带刻度尺） \n\n \n\n1.实验过程：实验时点燃蜡烛，使烛焰、凸透镜、光屏的中心大致在同一高度，目的是：使烛焰的\n\n像成在光屏中央。 \n\n2.光路图： \n\n\n\n学员专用 请勿外泄 \n\n \n\n17 中公教育学员专用资料 报名专线：400-6300-999 \n\n \n\n \n\n \n\n \n\n\n\n学员专用 请勿外泄 \n\n \n\n18 中公教育学员专用资料 报名专线：400-6300-999 \n\n \n\n3.实验结论：（凸透镜成像规律） \n\n（1）物体在二倍焦距以外(u>2f)，成倒立、缩小的实像(像距：f<v<2f)，如照相机； \n\n（2）物距等于二倍焦距（u=2f），成倒立、等大的实像（像距：v=2f)）； \n\n（3）物体在焦距和二倍焦距之间(f<u<2f)，成倒立、放大的实像(像距：v>2f)，如幻灯机； \n\n（4）物距等于一倍焦距（u=f），不成像；', 489, 489, 1, '1c19e6d2-d090-46ab-a082-ed60ada91a33', NULL, '2026-03-27 20:07:37');
INSERT INTO `document_chunk` VALUES (248, 6, 2, 44, '），成倒立、等大的实像（像距：v=2f)）； \n\n（3）物体在焦距和二倍焦距之间(f<u<2f)，成倒立、放大的实像(像距：v>2f)，如幻灯机； \n\n（4）物距等于一倍焦距（u=f），不成像； \n\n（5）物体在焦距之内（u<f），成正立、放大的虚像。 \n\n若在实验时，无论怎样移动光屏，在光屏都得不到像，可能得原因有：①蜡烛在焦点以内；②烛焰\n\n在焦点上③烛焰、凸透镜、光屏的中心不在同一高度；④蜡烛到凸透镜的距离稍大于焦距，成像在很远\n\n的地方，光具座的光屏无法移到该位置。 \n\n \n\n\n\n学员专用 请勿外泄 \n\n \n\n19 中公教育学员专用资料 报名专线：400-6300-999 \n\n第五章 压强和浮力 \n\n一、压力和压强 \n\n（一）影响压力作用效果的因素 \n\n \n\n甲乙说明在受力面积一定时，压力越大，压力的作用效果越大； \n\n乙丙说明在压力一定时，受力面积越小，压力的作用效果越大。 \n\n试验方法：控制变量法 \n\n（二）压强 \n\n1.定义：物体单位面积上受到的压力叫压强. \n\n2.公式：P=F/S \n\n3.单位：帕斯卡（pa） \n\n二、液体压强 \n\n（一）液体压强的特点', 492, 492, 1, 'acb2928e-22c7-482e-9292-59071dd9fb1a', NULL, '2026-03-27 20:07:37');
INSERT INTO `document_chunk` VALUES (249, 6, 2, 45, '试验方法：控制变量法 \n\n（二）压强 \n\n1.定义：物体单位面积上受到的压力叫压强. \n\n2.公式：P=F/S \n\n3.单位：帕斯卡（pa） \n\n二、液体压强 \n\n（一）液体压强的特点 \n\n1.产生原因：液体受到重力作用，对支持它的容器底部有压强液体具有流动性，对容器侧壁有压强。 \n\n2.液体压强特点： \n\n（1）液体对容器底部和侧壁都有压强； \n\n（2）液体内部向各个方向都有压强； \n\n（3）液体的压强随深度增加而增加，在同一深度，液体向各个方向的压强相等； \n\n（4）不同液体的压强还跟液体密度有关系。 \n\n（二）液体压强的大小 \n\n1.推导过程：（结合课本）液柱体积 V=Sh ，质量 m=ρV=ρSh 膜片受到的压力：F=G=mg=ρShg . \n\n膜片受到的压强：p= F/S=ρgh \n\n2.说明：从公式中看出：液体的压强只与液体的密度和液体的深度有关，而与液体的质量、体积、\n\n重力、容器的底面积、容器形状均无关。 \n\n三、大气压 \n\n（一）大气压强的存在 \n\n大气压强产生的原因：空气受到重力作用，而且空气能流动，因此空气内部向各个方向都有压强，', 483, 483, 1, '12c26898-d5a1-4e77-ade4-1f78afa2d129', NULL, '2026-03-27 20:07:37');
INSERT INTO `document_chunk` VALUES (250, 6, 2, 46, '三、大气压 \n\n（一）大气压强的存在 \n\n大气压强产生的原因：空气受到重力作用，而且空气能流动，因此空气内部向各个方向都有压强，\n\n这个压强就叫大气压强. \n\n（1）历史上著名的实验——马德堡半球实验 \n\n（2）小实验——覆杯实验、瓶吞鸡蛋实验、皮碗模拟马德堡半球实验。 \n\n（二）大气压的应用 \n\n\n\n学员专用 请勿外泄 \n\n \n\n20 中公教育学员专用资料 报名专线：400-6300-999 \n\n1.大气压的变化 \n\n大气压随海拔高度的增加而减小,这主要是由于离地面越高的地方空气越稀薄,空气的密度越小. \n\n2.大气压的特点 \n\n（1）空气内部向各个方向都有压强，且空气中某点向各个方向的大气压强都相等。大气压随高度\n\n增加而减小，且大气压的值与地点、天气、季节、的变化有关。 \n\n（2）大气压变化规律研究：在海拔 3000 米以内，每上升 10 米，大气压大约降低 100 Pa \n\n3.沸点与气压关系：一切液体的沸点，都是气压减小时降低，气压增大时升高。高山上用普通锅\n\n煮饭煮不熟，是因为高山上的沸点低，所以要用高压锅煮饭，煮饭时高压锅内气压大，水的沸点高，\n\n饭容易煮好。', 494, 494, 1, '7559bfe3-0cdb-4f0f-b4a8-6b0a3867d201', NULL, '2026-03-27 20:07:37');
INSERT INTO `document_chunk` VALUES (251, 6, 2, 47, '高山上用普通锅\n\n煮饭煮不熟，是因为高山上的沸点低，所以要用高压锅煮饭，煮饭时高压锅内气压大，水的沸点高，\n\n饭容易煮好。 \n\n（三）流体流速与压强的关系 \n\n1.物理学中把具有流动性的液体和气体统称为流体。 \n\n2.在气体和液体中，流速越大的位置，压强越小。 \n\n3.应用：（1）乘客候车要站在安全线外；（2）飞机机翼做成流线型，上表面空气流动的速度比\n\n下表面快，因而上表面压强小，下表面压强大，在机翼上下表面就存在着压强差，从而获得向上的升\n\n力。 \n\n四、浮力 \n\n阿基米德原理 \n\n1.实验：浮力大小与物体排开液体所受的重力的关系 \n\n \n\n①用弹簧测力计测出物体所受的重力 G1，小桶所受的重力 G2； \n\n②把物体浸入液体，读出这时测力计的示数为 F1，（计算出物体所受的浮力 F 浮=G1-F1）并且收\n\n集物体所排开的液体; \n\n③测出小桶和物体排开的液体所受的总重力 G3，计算出物体排开液体所受的重力 G 排=G3-G2。 \n\n2.内容：浸在液体中的物体受到向上的浮力，浮力的大小等于它排开液体所受的重力。 \n\n3.公式：F 浮=G 排=ρ 液 gV 排', 488, 488, 1, 'ac0d4333-7fff-47c4-9a5b-4599075c074f', NULL, '2026-03-27 20:07:38');
INSERT INTO `document_chunk` VALUES (252, 6, 2, 48, '2.内容：浸在液体中的物体受到向上的浮力，浮力的大小等于它排开液体所受的重力。 \n\n3.公式：F 浮=G 排=ρ 液 gV 排 \n\n4.从阿基米德原理可知：浮力的只决定于液体的密度、物体排液的体积（物体浸入液体的体积），\n\n与物体的形状、密度、质量、体积、及在液体的深度、运动状态无关。 \n\n物体的浮沉条件 \n\nρ 物>ρ 液，下沉，G 物>F 浮，m 物>m 排 \n\n\n\n学员专用 请勿外泄 \n\n \n\n21 中公教育学员专用资料 报名专线：400-6300-999 \n\nρ 物=ρ 液，悬浮，G 物=F 浮，m 物=m 排 \n\nρ 物<ρ 液，上浮， G 物<F 浮，m 物<m 排 \n\nρ 物<ρ 液，漂浮， G 物=F 浮，m 物=m 排 \n\nρ 物>ρ 液，沉底，G 物=F 浮+F 杯底对物的支持力 \n\n \n\n\n\n学员专用 请勿外泄 \n\n \n\n22 中公教育学员专用资料 报名专线：400-6300-999 \n\n第六章 简单机械 \n\n一、杠杆 \n\n（一）基本形态 \n\n1.定义：作用下能绕固定点转动的硬棒叫杠杆． \n\n2.基本概念： \n\n（1）支点：杠杆绕着转动的点(O)', 491, 491, 1, '77d36396-0506-447d-a3f2-7ecf5f4f9b0a', NULL, '2026-03-27 20:07:38');
INSERT INTO `document_chunk` VALUES (253, 6, 2, 49, '线：400-6300-999 \n\n第六章 简单机械 \n\n一、杠杆 \n\n（一）基本形态 \n\n1.定义：作用下能绕固定点转动的硬棒叫杠杆． \n\n2.基本概念： \n\n（1）支点：杠杆绕着转动的点(O) \n\n（2）动力：使杠杆转动的力(F1) \n\n（3）阻力：阻碍杠杆转动的力(F2) \n\n（4）动力臂：从支点到动力的作用线的距离（L1） \n\n（5）阻力臂：从支点到阻力作用线的距离（L2） \n\n \n\n（二）杠杆的平衡条件 \n\n动力×动力臂＝阻力×阻力臂．用 F1.F2.L1.L2分别表示动力、阻力、动力臂和阻力臂， \n\n杠杆的平衡条件可以写作：F1×L1= F2×L2 \n\n由杠杆平衡条件可知：使用杠杆时，想省力，要使用动力臂比阻力臂长的杠杆；想省距离，要使用\n\n动力臂比阻力臂短的杠杆；等臂杠杆既不省力也不省距离． \n\n（三）杠杆的应用 \n\n三种杠杆： \n\n（1）省力杠杆：L1>L2，平衡时 F1<F2。特点是省力，但费距离。（如剪铁剪刀，铡刀，起子） \n\n（2）费力杠杆：L1<L2，平衡时 F1>F2。特点是费力，但省距离。（如钓鱼杠，理发剪刀等）', 476, 476, 1, '68b4d794-e256-4f00-91a2-364bb6c489de', NULL, '2026-03-27 20:07:38');
INSERT INTO `document_chunk` VALUES (254, 6, 2, 50, '特点是省力，但费距离。（如剪铁剪刀，铡刀，起子） \n\n（2）费力杠杆：L1<L2，平衡时 F1>F2。特点是费力，但省距离。（如钓鱼杠，理发剪刀等） \n\n（3）等臂杠杆：L1=L2，平衡时 F1=F2。特点是既不省力，也不费力。（如：天平） \n\n既省力又省距离的杠杆时不存在的。 \n\n二、滑轮 \n\n（一）定滑轮和动滑轮 \n\n1.滑轮定义：周边有槽，中心有一转动的轮子叫滑轮。因为滑轮可以连续旋转，因此可看作是能够\n\n连续旋转的杠杆，仍可以用杠杆的平衡条件来分析。根据使用情况不同，滑轮可分为定滑轮和动滑轮。 \n\n2.定滑轮 \n\n\n\n学员专用 请勿外泄 \n\n \n\n23 中公教育学员专用资料 报名专线：400-6300-999 \n\n（1）定义：工作时，中间的轴固定不动的滑轮叫定滑轮。如下图所示。 \n\n（2）实质：是个等臂杠杆。（如下中图所示）轴心 O 点固定不动为支点，其动力臂和阻力臂都等\n\n于圆的半径 r，根据杠杆的平衡条件：F1·r=F2·r，可知，因为重物匀速上升可知，则，不省力 \n\n \n\n3.动滑轮（1）定义：工作时，轴随重物一起移动的滑轮叫动滑轮。', 481, 481, 1, '7de2dd15-7b91-4b32-8755-10c2d69bf68c', NULL, '2026-03-27 20:07:38');
INSERT INTO `document_chunk` VALUES (255, 6, 2, 51, '，其动力臂和阻力臂都等\n\n于圆的半径 r，根据杠杆的平衡条件：F1·r=F2·r，可知，因为重物匀速上升可知，则，不省力 \n\n \n\n3.动滑轮（1）定义：工作时，轴随重物一起移动的滑轮叫动滑轮。 \n\n（2）实质：是个动力臂为阻力臂二倍的杠杆。图中 O 可看作是一个能运动的支点，其动力臂 l1=2r，\n\n阻力臂 l2=r，根据杠杆平衡条件：F1l1=F2l2，即 F1·2r=F2·r，得出 21\n2\n\n1\nFF  ，当重物竖直匀速向上时，\n\nF2=G，则 F1=G/2，。 \n\n（二）滑轮组 \n\n1.定义：由若干个定滑轮和动滑轮匹配而成。 \n\n2.特点：可以省力，也可以改变力的方向。使用滑轮组时，有几段绳子吊着物体，提起物体所用\n\n的力就是物重的几分之一，即 物G\nn\n\nF\n1\n\n （条件：不计动滑轮、绳重和摩擦）。 \n\n注意：如果不忽略动滑轮的重量则 ）（ 滑物 GG\nn\n\nF \n1\n\n \n\n3.动力移动的距离 s 和重物移动的距离 h 的关系是：使用滑轮组时，滑轮组用 n 段绳子吊着物体，', 455, 455, 1, 'cc3eb678-803c-4408-8d9a-0390fd010107', NULL, '2026-03-27 20:07:38');
INSERT INTO `document_chunk` VALUES (256, 6, 2, 52, '注意：如果不忽略动滑轮的重量则 ）（ 滑物 GG\nn\n\nF \n1\n\n \n\n3.动力移动的距离 s 和重物移动的距离 h 的关系是：使用滑轮组时，滑轮组用 n 段绳子吊着物体，\n\n提起物体所用的力移动的距离就是物体移动距离的 n 倍，即 s=nh。如下图所示。（n 表示承担物重绳子\n\n的段数） \n\n \n\n \n\n\n\n学员专用 请勿外泄 \n\n \n\n24 中公教育学员专用资料 报名专线：400-6300-999 \n\n4.绳子端的速度与物体上升的速度关系： ）物绳 nvv  \n\n三、机械效率 \n\n1.定义：有用功跟总功的比值。\n总\n\n有用\n\nW\n\nW\n \n\n2.有用功总小于总功，所以机械效率总小于 1 。 \n\n通常用百分数表示。某滑轮机械效率为 60%表示有用功占总功的 60% 。 \n\n3.提高机械效率的方法：减小机械自重、减小机件间的摩擦。 \n\n \n\n\n\n学员专用 请勿外泄 \n\n \n\n25 中公教育学员专用资料 报名专线：400-6300-999 \n\n第二部分 高中物理 \n\n第一章 力学 \n\n第一节 匀变速直线运动 \n\n \n\n一、基本概念', 477, 477, 1, 'b17caa0c-98f0-4d99-9368-2ffff64de905', NULL, '2026-03-27 20:07:38');
INSERT INTO `document_chunk` VALUES (257, 6, 2, 53, '学员专用 请勿外泄 \n\n \n\n25 中公教育学员专用资料 报名专线：400-6300-999 \n\n第二部分 高中物理 \n\n第一章 力学 \n\n第一节 匀变速直线运动 \n\n \n\n一、基本概念 \n\n1.质点：忽略物体的大小形状，简化为一个有质量的物质点。 \n\n（1）可看做质点的条件：物体的大小形状可以忽略，且对研究物体的运动无影响。 \n\n（2）物理方法：质点是一种理想模型，物理学中常见的物理模型有（光线、电场线、点电荷、\n\n单摆、理想气体等等），关键注意理想模型实际不存在，是一种假想。 \n\n2.参考系 \n\n（1）选择不同的参考系来观察一个物体的运动，结果不同。一般选取地面为参考系。 \n\n（2）运动是绝对的（绝对静止的物体不存在），静止是相对的（取决于参考系的选取）。 \n\n3.时间与时刻：利用时间的数轴表示，时刻用点表示，时间间隔用线段表示。 \n\n4.位移与路程 \n\n（1）位移：是描述质点位置变化的物理量，既有大小又有方向，是矢量，是从起点 A 指向终点\n\nB 的有向线段，有向线段的长度表示位移的大小，有向线段的方向表示位移的方向，与质点的运动路\n\n径无关。', 482, 482, 1, 'c8025c09-a448-4c6a-9135-518d7abb0831', NULL, '2026-03-27 20:07:38');
INSERT INTO `document_chunk` VALUES (258, 6, 2, 54, '（1）位移：是描述质点位置变化的物理量，既有大小又有方向，是矢量，是从起点 A 指向终点\n\nB 的有向线段，有向线段的长度表示位移的大小，有向线段的方向表示位移的方向，与质点的运动路\n\n径无关。 \n\n（2）路程：是质点运动轨迹的长度，它是标量，只有大小，没有方向。路程的大小与质点的运\n\n动路径有关，但它不能描述质点位置的变化。 \n\n（3）位移和路程的比较：由于位移是矢量，而路程是标量，所以不能说位移等于路程；但质点做\n\n单向直线运动时，位移的大小等于路程。 \n\n5.速度与速率 \n\n（1）速度：①\nt\n\nx\nv\n\n\n\n\n （比值定义的物理量），普遍适用。②矢量，方向表示物体运动的方向。 \n\n（2）速率：表示速度的大小，标量。 \n\n \n\n6.平均速度与平均速率；瞬时速度与瞬时速率 \n\n（1）平均速度=\n时间\n\n位移\n；平均速率=\n\n时间\n\n路程\n \n\n举例：匀速圆周运动速率一定，但是速度不断变化。 \n\n\n\n学员专用 请勿外泄 \n\n \n\n26 中公教育学员专用资料 报名专线：400-6300-999 \n\n（2） ）（瞬时速度 0\n\n\n\n t\n\nt', 485, 485, 1, 'cca268dc-0422-4c30-b1d3-7255d716058b', NULL, '2026-03-27 20:07:39');
INSERT INTO `document_chunk` VALUES (259, 6, 2, 55, '学员专用 请勿外泄 \n\n \n\n26 中公教育学员专用资料 报名专线：400-6300-999 \n\n（2） ）（瞬时速度 0\n\n\n\n t\n\nt\n\nx\nv ，瞬时速度的大小为瞬时速率。 \n\n（3）瞬时速度：瞬时速度是物体经过某一位置、时刻时的速度。 \n\n（4）瞬时速率：瞬时速度的大小。 \n\n7.速度变化量与速度变化率 \n\n（1）速度变化量 0vvv t  \n\n（2）速度变化率\nt\n\nv\n\n\n\n\n，用来表示速度变化快慢 \n\n8.加速度 \n\n（1）\nt\n\nv\na\n\n\n\n\n （定义式），\n\nm\n\nF\na  （决定式） \n\n（2）方向：与速度变化的方向一致，即与 v 的方向一致。 \n\n（3）a 的方向与速度 v 方向无关。举例：竖直上抛运动或简谐振动中存在，v=0，a≠0 的情况。 \n\n（4）匀变速直线运动中，a 与初速度 v0同向，物体做加速运动；a 与初速度 v0反向，物体做加速\n\n运动。 \n\n二、基本公式 \n\n（一）基本量： tv 、 0v 、t、a、x，（知三求二）。 \n\n（二）基本公式 \n\n1.速度公式： \n\n2.位移公式： \n\n① \n\n2', 491, 491, 1, '56e0de4b-1962-4847-ace7-2dc4537cf5d4', NULL, '2026-03-27 20:07:39');
INSERT INTO `document_chunk` VALUES (260, 6, 2, 56, '二、基本公式 \n\n（一）基本量： tv 、 0v 、t、a、x，（知三求二）。 \n\n（二）基本公式 \n\n1.速度公式： \n\n2.位移公式： \n\n① \n\n2\n\n2\n\n1\nattvx t  ②（逆向思维应用）举例:在某一运动中，不知道物体的初速度，但是已知末速度。 \n\nt\nvv\n\nx t\n\n2\n\n0  ③（仅适用于匀变速直线运动，无 a 公式） \n\n3.速度与位移的关系： （无 t 公式） \n\n4..平均速度：\nt\n\nx\nv  （通用）\n\n， 2\n\n0 tvv\nv\n\n\n （仅适用于匀变速直线运动） \n\n三、自由落体运动 \n\n1.定义：物体只在重力作用下从静止开始下落的运动，叫做自由落体运动。即自由落体运动是初\n\n速度为 0 的匀加速直线运动。 \n\n2.速度公式： \n\n0tv v at \n\n2\n\n0\n\n1\n\n2\nx v t at \n\n2 2\n\n0 2tv v ax \n\ntv gt\n\n\n\n学员专用 请勿外泄 \n\n \n\n27 中公教育学员专用资料 报名专线：400-6300-999 \n\n3.位移公式： \n\n \n\n四、匀变速直线运动的几个推论', 486, 486, 1, '428a7ba3-847e-4595-b81f-2fa950ce7ddb', NULL, '2026-03-27 20:07:39');
INSERT INTO `document_chunk` VALUES (261, 6, 2, 57, 'v v ax \n\ntv gt\n\n\n\n学员专用 请勿外泄 \n\n \n\n27 中公教育学员专用资料 报名专线：400-6300-999 \n\n3.位移公式： \n\n \n\n四、匀变速直线运动的几个推论 \n\n1.某段时间中间时刻的瞬时速度为该段时间内的平均速度：\n2\n\n0\n\n2\n\nt\nt\n\nvv\nv\n\nt\n\nx\nv\n\n\n ； \n\n2.某段位移中点的瞬时速度等于初速度和末速度平方和的一半的平方根： ； \n\n \n\n3.连续相等时间内的位移之差是一恒量： ：\n2\n\n2\n\n12\n\n)( aTnmxx\n\naTxx\n\nnm \n\n\n\n \n\n21\n\n2\nx gt\n\n2 2\n\n0\n\n2\n2\n\nt\nx\n\nv v\nv\n\n\n\n\n2x at  恒量\n\n方法规律：\n\n2\n\ntv 与\n\n2\n\nxv 相比较 \n\n①在匀速运动中，\n\n22\n\nxt vv  \n\n②在匀变速运动中：\n\n22\n\nxt vv  ；解析如下图所示： \n\n \n\n \n\n注： \n\n1.研究竖直上抛运动的方法 \n\n（1）分阶段法：将竖直上抛运动分为上升和下降两个阶段考虑、上升阶段为匀减速', 479, 479, 1, 'e1d08bcd-9e72-4389-9b6c-f5c65fd7306b', NULL, '2026-03-27 20:07:39');
INSERT INTO `document_chunk` VALUES (262, 6, 2, 58, '在匀变速运动中：\n\n22\n\nxt vv  ；解析如下图所示： \n\n \n\n \n\n注： \n\n1.研究竖直上抛运动的方法 \n\n（1）分阶段法：将竖直上抛运动分为上升和下降两个阶段考虑、上升阶段为匀减速\n\n直线运动，下降阶段为自由落体运动，两个阶段分别运用匀变速直线运动的规律求解。 \n\n（2）全过程法：将整个运动过程看成是有往返的匀减速直线运动来处理。应用时要\n\n注意速度、位移和加速度 g 的正负及物理意义、 \n\n2.竖直上抛运动的多解问题： \n\n在竖直上抛运动中，物体进过抛出点上方某一位置时，可能处于上升阶段，也可能\n\n处于下降阶段，因此这类问题可能有多解 \n\n\n\n学员专用 请勿外泄 \n\n \n\n28 中公教育学员专用资料 报名专线：400-6300-999 \n\n \n\n例 1.（2016 年下半年教资）探究物块沿斜面匀加速直线运动的规律时，将一块物块自 O 点由静\n\n止释放一段时间后，用频闪照相机记录下物块相同时间间隔的图像 a、b、c、d（如图），测得 ab=2.5m，\n\nbc=3.5m，cd=4.5m。由此可推知 oa 之间的距离为（ ）', 475, 475, 1, '6644ee90-fbf4-4a13-a62b-937c56f5ea12', NULL, '2026-03-27 20:07:39');
INSERT INTO `document_chunk` VALUES (263, 6, 2, 59, '由此可推知 oa 之间的距离为（ ） \n\n \n\nA.0.5m B.1.0m C.1.5m D.2m \n\n4.初速度为零的匀加速直线运动的特点： \n\n（1）1s 末，2s 末，3s 末…速度之比（推导公式： atv  ） \n\n \n\n（2）1s 内，2s 内，3s 内…位移之比（推导公式：\n2\n\n2\n\n1\natx  ） \n\n \n\n（3）连续相等时间内，所发生的位移之比 \n\n \n\n（4）通过前 x ，前 x2 ，前 x3 …时间之比（推导公式：\n2\n\n2\n\n1\natx  ，\n\na\n\nx\nt\n\n2\n ） \n\nnttt  :3:2:1::: 321\n \n\n1 2 3: : : ... : 1: 2 :3:... :nv v v v n\n\n2 2 2 2\n\n1 2 3: : :...: 1 : 2 :3 :...:nS S S S n\n\n1 2 3: : : ... : 1:3:5 :... : (2 1)nS S S S n \n\n注意：这里的 1x 、 2x 、 3x 指的是相等时间的位移，如下图所示 \n\n \n\n注意陷阱：', 478, 478, 1, '0d638fe3-0272-484a-a87d-732c1bb13a49', NULL, '2026-03-27 20:07:39');
INSERT INTO `document_chunk` VALUES (264, 6, 2, 60, '3: : : ... : 1:3:5 :... : (2 1)nS S S S n \n\n注意：这里的 1x 、 2x 、 3x 指的是相等时间的位移，如下图所示 \n\n \n\n注意陷阱： \n\n \n\n此时 12211 , ddxdx  \n\n \n\n\n\n学员专用 请勿外泄 \n\n \n\n29 中公教育学员专用资料 报名专线：400-6300-999 \n\n（5）连续相等位移，所需时间之比 \n\n \n\n五、图象问题 \n\n1.分析要素：横纵轴物理意义；斜率物理意义；面积物理意义；截距的物理意义。 \n\n2.位移时间图象（x-t 图象） \n\n（1）图象≠轨迹，位移时间图象只能表示直线运动，只有正负两个方向。 \n\n（2）斜率\nt\n\nx\n\n\n\n\n表示物体运动速度，根据斜率判断，图象中的线表示的物体的运动情况： \n\n①直线：静止或匀速直线运动 \n\n②曲线：变速直线运动 \n\n③抛物线:匀变速直线运动 \n\n \n\n（3）交点及截距 \n\n①图象交点表示在 t 时刻两物体相遇。 \n\n②图象与 x 轴交点表示初始时刻位移 s，图象与 t 轴交点表示在 t 时刻物体回到 O 点（参考点）所\n\n用时间。', 492, 492, 1, 'e72d6c9e-b3c5-4032-9b16-322d865c668d', NULL, '2026-03-27 20:07:40');
INSERT INTO `document_chunk` VALUES (265, 6, 2, 61, '②图象与 x 轴交点表示初始时刻位移 s，图象与 t 轴交点表示在 t 时刻物体回到 O 点（参考点）所\n\n用时间。 \n\n3.速度图象（v-t 图象）应用要点 \n\n（1）面积 tv  表示物体运动的位移，面积为正，表示物体沿 x 轴正方向运动，面积为负，表\n\n示物体沿 x 轴负方向运动。 \n\n（2）斜率\nt\n\nv\n\n\n\n\n表示物体的加速度，根据斜率判断，图象中的线表示的物体的运动情况： \n\n①直线：匀速或匀变速直线运动 \n\n②曲线：变加速直线运动 \n\n \n\n1 2 3: : : ... : 1: ( 2 1) : ( 3 2) : ... : ( 1)nt t t t n n    \n\n\n\n学员专用 请勿外泄 \n\n \n\n30 中公教育学员专用资料 报名专线：400-6300-999 \n\n（3）交点及截距 \n\n①图象交点表示在 t 时刻两物体速度相等（通常为判断追及相遇问题的关键点） \n\n②图象与 x 轴交点表示初始时刻速度 v，图象与 t 轴交点表示在 t 时刻物体速度为零，将反向运动\n\n（即掉头）', 466, 466, 1, '85caf23d-7826-47ea-ad34-d2fa2d9eee94', NULL, '2026-03-27 20:07:40');
INSERT INTO `document_chunk` VALUES (266, 6, 2, 62, '①图象交点表示在 t 时刻两物体速度相等（通常为判断追及相遇问题的关键点） \n\n②图象与 x 轴交点表示初始时刻速度 v，图象与 t 轴交点表示在 t 时刻物体速度为零，将反向运动\n\n（即掉头） \n\n例 2.某物体从 A 点开始沿一直线运动，它运动的 v-t 图象如图所示，下列说法正确的是( ) \n\n \n\nA.物体在第 1 s 末和第 5 s 末离 A 点距离最远 \n\nB.物体在第 2 s 内和第 3 s 内的加速度是相同的 \n\nC.物体在 4 s 末返回出发点 A \n\nD.物体在 1 s 末、3 s 末、5 s 末速度方向改变 \n\n六、相遇和追及问题 \n\n1.追及问题“交点” \n\n（1）速度大者减速（如匀减速直线运动）追速度小者（如匀速直线运动）：主要看当速度相等时，\n\n两者的运动状态。 \n\n2.抓住“一个条件”“两个关系” \n\n条件：两物体速度满足的临界条件，两物体距离最大、最小、恰好追上或恰好追不上等 \n\n两个关系：时间关系和位移关系，利用图象关系进行分析。 \n\n\n\n学员专用 请勿外泄 \n\n \n\n31 中公教育学员专用资料 报名专线：400-6300-999', 489, 489, 1, '7dd7445e-120a-4e0f-88b4-4ad72a1a2705', NULL, '2026-03-27 20:07:40');
INSERT INTO `document_chunk` VALUES (267, 6, 2, 63, '学员专用 请勿外泄 \n\n \n\n31 中公教育学员专用资料 报名专线：400-6300-999 \n\n \n\n（2）速度小者加速（如初速度为零的匀加速运动）追速度大者（如匀速直线运动）：速度相等时，\n\n两者有最大距离。 \n\n \n\n \n\n例题：甲、乙两车在一平直道路上同向运动，其 v-t 图象如图所示。甲车以 8m/s 的速度\n\n做匀速，直线运动。乙车的初始速度为 4m/s，以 4m/s2的速度做匀加速运动。初始时刻，甲\n\n车在乙车前方 20 s m 处，则当甲、乙速度相等时，两车是否能够相遇？ \n\n \n\n \n\n \n\n【例题】：甲、乙两车在一平直道路上同向运动，其 v-t 图象如图所示。甲车的初始速\n\n度为 8m/s，以 4m/s2的速度做匀减速运动。乙车的初始速度为 4m/s，以 4m/s2的速度做匀\n\n加速运动。 \n\n \n\n（1）初始时，乙车在甲车前方 100 s m 处，则当甲乙速度相等时，两车是否能够相\n\n遇？ \n\n（2）甲、乙两车同时同地出发。则当甲乙速度相等时，两车是否能够相遇？ \n\n \n\n\n\n学员专用 请勿外泄', 467, 467, 1, 'a4e405f2-5832-4648-b8bd-96ccf0d27ab9', NULL, '2026-03-27 20:07:40');
INSERT INTO `document_chunk` VALUES (268, 6, 2, 64, '则当甲乙速度相等时，两车是否能够相遇？ \n\n \n\n\n\n学员专用 请勿外泄 \n\n \n\n32 中公教育学员专用资料 报名专线：400-6300-999 \n\n第二节 相互作用 \n\n \n\n一、常见的三种力 \n\n1.重力： \n\n（1）定义：重力是由于地球的吸引而使物体受到的力。重力是万有引力的分力。 \n\n（2）重力的大小：地球表面 mgG  ，g 大小随纬度的升高而增大，随高度的升高而减小。 \n\n（3）重力的方向：竖直向下（不一定指向地心） \n\n（4）重心：一个物体各部分都受到重力作用，从效果上看，我们可以认为各部分受到的重力作用\n\n集中于一点，这一点叫做物体的重心，物体的重心不一定在物体上。 \n\n（5）重心在物体的几何中心的条件是：①具有规则几何图形；②质量分布均匀。 \n\n2.弹力 \n\n（1）产生条件：接触并发生弹性形变。 \n\n（2）弹力有无的判断 \n\n对于形变不明显的情况，可用如下两种方法判断弹力的有无： \n\n条件法：根据物体是否直接接触并发生弹性形变来判断是否存在弹力。此方法多用来判断形变较\n\n明显的情况。', 459, 459, 1, 'a8f64d82-63ea-4eff-b180-37677782d27c', NULL, '2026-03-27 20:07:40');
INSERT INTO `document_chunk` VALUES (269, 6, 2, 65, '（2）弹力有无的判断 \n\n对于形变不明显的情况，可用如下两种方法判断弹力的有无： \n\n条件法：根据物体是否直接接触并发生弹性形变来判断是否存在弹力。此方法多用来判断形变较\n\n明显的情况。 \n\n假设法：对于形变不明显的情况，可假设两个物体之间弹力不存在，看物体能否保持原有的状态，\n\n若状态不变，则此处不存在弹力，若状态改变，则此处一定有弹力。 \n\n \n\n（3）弹力方向的判定 \n\n①根据物体形变的方向判断：A 对 B 的弹力与 A 物体形变的方向相反。 \n\n例题：如图所示，用细绳悬挂的小球与光滑斜面相接触，并保持静止，甲中细绳倾斜，\n\n乙中细绳呈竖直方向。判断图甲、乙中小球是否受到斜面的弹力作用？ \n\n \n\n答案：甲中小球受到斜面的弹力，乙中小球不受斜面弹力。 \n\n解析：物体形变不明显，可用假设法进行判断，假设甲乙情况中都不受斜面的弹力，用\n\n平衡条件知甲中小球会向右运动，状态改变，故甲中小球受到斜面的弹力；对于乙中小球，\n\n小球还是保持静止状态，故已中小球不受斜面弹力。 \n\n \n\n\n\n学员专用 请勿外泄 \n\n \n\n33 中公教育学员专用资料 报名专线：400-6300-999', 494, 494, 1, 'a97f7598-f5fd-4ac1-96f8-16797b95a4ad', NULL, '2026-03-27 20:07:40');
INSERT INTO `document_chunk` VALUES (270, 6, 2, 66, '学员专用 请勿外泄 \n\n \n\n33 中公教育学员专用资料 报名专线：400-6300-999 \n\n②绳上的拉力方向总是沿绳并指向绳的收缩方向，且一根轻绳上的张力大小处处相等； \n\n③轻杆的弹力既可以是压力，又可以是拉力，且方向不一定沿杆；具体用二力平衡或者牛顿第二\n\n定律来判断。 \n\n \n\n④“活”“死“杆 \n\n \n\n结论：若轻杆一端不固定，则另一端合力必沿杆方向，若固定，则可以受任何方向的力，应根据\n\n实际情况（如受力平衡等）加以分析。 \n\n（4）弹力的大小 \n\n①弹簧弹力的大小 \n\n胡克定律：实验表明，弹簧发生弹性形变时，弹力的大小 F 跟弹簧的伸长（或缩短）的长度 x 成\n\n正比，即 F=kx（一般的表达式为 xkF  ），k 称为弹簧的劲度系数，单位 N/m。 \n\n②非弹簧类弹力：根据运动状态和受力情况，利用平衡条件或牛顿运动定律来综合判断。 \n\n3.摩擦力 \n\n（1）定义：两个相互接触的物体，在它们发生相对运动或具有相对运动趋势时，就会在接触面上\n\n产生阻碍相对运动或相对运动趋势的力，这个力叫做摩擦力。', 465, 465, 1, 'bb08694c-73be-4766-a394-391500e6723b', NULL, '2026-03-27 20:07:41');
INSERT INTO `document_chunk` VALUES (271, 6, 2, 67, '3.摩擦力 \n\n（1）定义：两个相互接触的物体，在它们发生相对运动或具有相对运动趋势时，就会在接触面上\n\n产生阻碍相对运动或相对运动趋势的力，这个力叫做摩擦力。 \n\n（2）产生条件：①相互接触的物体间存在压力；②接触面不光滑；③接触的物体间有相对运动或\n\n相对运动趋势。 \n\n（3）摩擦力的方向判断。 \n\n①沿接触面切线方向，与物体相对运动或相对运动趋势的方向相反。 \n\n②假设法：所研究的对象运动趋势不明显时，先假设接触面光滑，研究对象不受摩擦力，看物体\n\n会怎样运动。该运动方向即为物体相对运动趋势的方向，则物体受到静摩擦力的方向与该方向相反。 \n\n\n\n学员专用 请勿外泄 \n\n \n\n34 中公教育学员专用资料 报名专线：400-6300-999 \n\n \n\n（4）摩擦力的大小：先判断是何种摩擦力，然后再根据各自的规律去分析求解。 \n\n①滑动摩擦力：利用公式 NFf  进行计算；或者根据运动状态利用平衡条件或牛顿运动定律来\n\n求解。 \n\n②静摩擦力：静摩擦力大小在 0与 maxF 之间变化，一般根据物体运动状态由平衡条件或牛顿定律来\n\n求解。', 477, 477, 1, '05962c1b-28f8-4063-abba-176ba023c093', NULL, '2026-03-27 20:07:41');
INSERT INTO `document_chunk` VALUES (272, 6, 2, 68, '②静摩擦力：静摩擦力大小在 0与 maxF 之间变化，一般根据物体运动状态由平衡条件或牛顿定律来\n\n求解。 \n\n例 1.表面粗糙的长直木板上放有一铁块，木板的一端不动，另一端由水平位置缓慢向上抬起，木\n\n板与水平面的夹角为 α，如图所示，设最大静摩擦力等于滑动摩擦力，则铁块受到的摩擦力 f 随 α 的\n\n变化图像可能正确的是（ ）。 \n\n \n\n \n\n二、力的合成与分解 \n\n1.力的合成：求几个力的合力的过程叫力的合成。 \n\n（1）矢量相加法则：既有大小又有方向的物理量，相加时遵循平行四边形定则和三角形定则。 \n\n（2）一般来说，当求解三个及三个以上的力的合成时，可先把在同一条直线上的力先进行合成，\n\n再按照平行四边形定则进行力的合成。 \n\n（3）特别记忆：大小均为 F 的两个力，它们合力的大小随角度的变化情况 \n\n夹 180 120° 90° 60° 0° \n\n例：如下图所示皮带传动装置，A为主动轮，B 为从动轮，传送带沿逆时针方向运动\n\n（皮带不打滑），P、Q分别为两轮边缘上的点，则此时 P、Q所受静摩擦力的方向为？', 466, 466, 1, '3be71f4c-7d0b-4442-b032-8777c9610ffa', NULL, '2026-03-27 20:07:41');
INSERT INTO `document_chunk` VALUES (273, 6, 2, 69, '20° 90° 60° 0° \n\n例：如下图所示皮带传动装置，A为主动轮，B 为从动轮，传送带沿逆时针方向运动\n\n（皮带不打滑），P、Q分别为两轮边缘上的点，则此时 P、Q所受静摩擦力的方向为？ \n\n \n答案：P点受到的摩擦力向上，Q 点受到的摩擦力向上。 \n\n解析：假设 A轮光滑，则皮带不会转动，由于皮带实际逆时针转动，所以与 P接触\n\n的皮带受到向下的静摩擦力，故轮上的 P点受到先上的摩擦力。同理，可假设 B轮光滑，\n\n则皮带在 B轮上打滑，B 轮不会转动，但实际上 B轮受到了摩擦力逆时针转动，所以 Q\n\n点受到先上的静摩擦力。 \n\n\n\n学员专用 请勿外泄 \n\n \n\n35 中公教育学员专用资料 报名专线：400-6300-999 \n\n角 ° \n\n合\n\n力 \n0 F \n\nF2\n\n \n\nF3\n\n \n\n2F \n\n例 2.如图所示，在同一平面内有六个共点力，大小分别为 F、2F、3F、4F、5F、6F，相邻的两个\n\n力之间的夹角均为 60°，则它们合力的大小和方向是（ ）。 \n\n \n\nA.大小为 3F，方向与 5F 方向相同 B.大小为 3F，方向与 6F 方向相同', 488, 488, 1, '0618d31f-3316-4f05-8a20-797123a801bf', NULL, '2026-03-27 20:07:41');
INSERT INTO `document_chunk` VALUES (274, 6, 2, 70, 'A.大小为 3F，方向与 5F 方向相同 B.大小为 3F，方向与 6F 方向相同 \n\nC.大小为 6F，方向与 5F 方向相同 D.大小为 6F，方向与 6F 方向相同 \n\n（4）“四点”提醒： \n\n①合力不一定大于分力； \n\n②合力与分力的作用效果相同，但它们并不是同时作用在物体上； \n\n③合力与分力是等效替代关系； \n\n④二个分力一定时，夹角 θ越大，合力越小。 \n\n2.力的分解：求一个已知力的分力的过程，叫做力的分解。 \n\n（1）有唯一解的条件： \n\n①已知两个分力的方向； \n\n \n\n②已知一个分力的大小和方向。 \n\n \n\n（2）力的矢量三角形定则分析力最小的规律 \n\n①已知合力的大小、方向及一个分力的方向，另一个分力最小的条件是两个分力垂直。 \n\n②已知合力的方向及一个分力的大小、方向，另一个分力最小的条件是：另一个分力与合力垂直。 \n\n三、共点力作用下物体的平衡 \n\n1.共点力的平衡条件： 0F \n\n\n\n学员专用 请勿外泄 \n\n \n\n36 中公教育学员专用资料 报名专线：400-6300-999', 462, 462, 1, '8fd64ffb-b553-4900-8d2f-b8ad31a9bc9b', NULL, '2026-03-27 20:07:41');
INSERT INTO `document_chunk` VALUES (275, 6, 2, 71, '三、共点力作用下物体的平衡 \n\n1.共点力的平衡条件： 0F \n\n\n\n学员专用 请勿外泄 \n\n \n\n36 中公教育学员专用资料 报名专线：400-6300-999 \n\n2.三力平衡的基本特性：不共线的三个共点力通过平移构成封闭三角形，三力共点。 \n\n3.平衡问题中常用方法 \n\n（1）图解法（动态平衡） \n\n适用条件：物体受到三个力，其中：一个力是恒力，一个力方向不变，另一个力方向改变。 \n\n解题方法：①受力分析。②把恒力和方向不变的力平行移动，与方向改变的力形成闭合三角形。\n\n③让第三个力根据题意发生变化，观察三角形的边的变化从而确定物体受力的大小的变化。 \n\n例 3.如图，一小球放置在木板与竖直墙面之间。设墙面对球的压力大小为 N1，球对木板的压力大\n\n小为 N2。以木板与墙连接点所形成的水平直线为轴，将木板从图示位置开始缓慢地转到水平位置。不\n\n计摩擦，在此过程中 N1和 N2 的变化？ \n\n \n\n（2）三角形相似法（动态平衡） \n\n适用条件：物体受到三个力。在绳、球形、支架、滑轮等问题中常见。', 458, 458, 1, '5824c611-cda2-4b8e-85bb-cbc9df0399df', NULL, '2026-03-27 20:07:41');
INSERT INTO `document_chunk` VALUES (276, 6, 2, 72, '不\n\n计摩擦，在此过程中 N1和 N2 的变化？ \n\n \n\n（2）三角形相似法（动态平衡） \n\n适用条件：物体受到三个力。在绳、球形、支架、滑轮等问题中常见。 \n\n解题方法：①受力分析。②找出图中与三个力构成的三角形相似的三角形。③列出数学关系式，\n\n根据题意发生变化，观察三角形的边的变化从而确定物体受力的大小的变化。 \n\n例 4.如图所示，缓慢的拉动细绳的另一端，使小球沿球面从 A 点拉至 B 点，在此过程中，小球所\n\n受球面的支持力 N 以及细绳对小球的拉力 F 的变化情况是？ \n\n \n\n（3）正交分解法 \n\n首先建立适当的坐标系，是尽量多的力落在坐标系上。 \n\n将物体受力分别沿坐标系的 X 方向、Y 方向进行分解。然后在这个方向上分别列平衡方程。 \n\n（4）整体隔离法 \n\n 整体法 隔离法 \n\n概念 \n将加速度相同的几个物体作为一\n\n个整体来分析的方法 \n\n将单个物体作为研究对象与周围物体分\n\n隔开的方法 \n\n\n\n学员专用 请勿外泄 \n\n \n\n37 中公教育学员专用资料 报名专线：400-6300-999 \n\n选用原则 \n研究系统外的物体对系统整体的\n\n作用力或系统的加速度', 497, 497, 1, 'c62838fd-f645-4ed3-ab7c-248f7542899a', NULL, '2026-03-27 20:07:42');
INSERT INTO `document_chunk` VALUES (277, 6, 2, 73, '围物体分\n\n隔开的方法 \n\n\n\n学员专用 请勿外泄 \n\n \n\n37 中公教育学员专用资料 报名专线：400-6300-999 \n\n选用原则 \n研究系统外的物体对系统整体的\n\n作用力或系统的加速度 \n\n研究系统内物体之间的相互作用 \n\n注意问题 \n受力分析时不要再考虑系统内物\n\n体间的相互作用 \n\n一般隔离受力较少的物体 \n\n \n\n\n\n学员专用 请勿外泄 \n\n \n\n38 中公教育学员专用资料 报名专线：400-6300-999 \n\n第三节 牛顿运动定律 \n\n \n\n一、牛顿第一定律 \n\n1.内容：一切物体总保持匀速直线运动状态或静止状态，除非作用在它上面的力迫使它改变这种\n\n状态。牛顿第一定律又称惯性定律。 \n\n2.惯性：物体具有保持原来匀速直线运动状态或静止状态的性质。惯性大小唯一量度是物体的质\n\n量。 \n\n（1）牛顿第一定律定性的分析了 F、m、a 三者之间的关系。 \n\n（2）牛顿第一定律是建立在大量实验的基础上，推理得到的。不能用实验直接验证。 \n\n二、牛顿第二定律 \n\n1.内容：物体加速度的大小跟它受到的作用力成正比、跟它的质量成反比，加速度的方向跟作用\n\n力的方向相同。', 495, 495, 1, '7a5e2a7a-352a-44e9-abf7-86453e1bc1ec', NULL, '2026-03-27 20:07:42');
INSERT INTO `document_chunk` VALUES (278, 6, 2, 74, '不能用实验直接验证。 \n\n二、牛顿第二定律 \n\n1.内容：物体加速度的大小跟它受到的作用力成正比、跟它的质量成反比，加速度的方向跟作用\n\n力的方向相同。 \n\n2.公式： maF  \n\n3.适用范围：宏观、低速运动物体。 \n\n4.区别加速度定义式和决定式：定义式\nt\n\nv\na\n\n\n\n\n ，即加速度定义为速度变化量与所用时间的比值；\n\n而\nm\n\nF\na  则揭示了加速度取决于物体所受的合外力与物体的质量。 \n\n5.国际单位制（SI）中七个基本物理量及相应的基本单位 \n\n物理量名称及符号 单位名称 单位符号 \n\n长度 l 米 m \n\n质量 m 千克（公斤） kg \n\n时间 t 秒 s \n\n电流 i 安[培] A \n\n热力学温度 T 开[尔文] K \n\n物质的量 n，（v） 摩[尔] mol \n\n发光强度 I，（IV） 坎[德拉] cd \n\n三、牛顿第三定律 \n\n两个物体之间的作用力和反作用力总是大小相等，方向相反，作用在同一条直线上。 \n\n\n\n学员专用 请勿外泄 \n\n \n\n39 中公教育学员专用资料 报名专线：400-6300-999 \n\n四、牛顿第二定律的应用', 490, 490, 1, '287f390b-4714-434c-b7e3-d6eb91c46a0d', NULL, '2026-03-27 20:07:42');
INSERT INTO `document_chunk` VALUES (279, 6, 2, 75, '学员专用 请勿外泄 \n\n \n\n39 中公教育学员专用资料 报名专线：400-6300-999 \n\n四、牛顿第二定律的应用 \n\n1.动力学两类问题 \n\n（1）已知受力情况求运动情况； \n\n（2）已知运动情况求受力情况。 \n\n关键：加速度是受力情况和运动情况的联系桥梁。 \n\n \n\n例 1.如图所示，用跨过光滑定滑轮将水平面上没有动力的小船沿直线拖向岸边。若拖动的电机功\n\n率恒为 ，小船质量为 ，小船受到阻力大小恒为，经过 点时绳与水平方向夹角为 ，小船速度大小\n\n为v0，绳的质量忽略不计，则小船加速度为（ ）和绳对船的拉力的大小为（ ） \n\n \n\nA.a =\n1\n\nm\n(\n\nP\n\nv0cosθ\n− f)，F =\n\nP\n\nv0cosθ\n \n\nB.a =\n1\n\nm\n(\nP\n\nv0\n− f)，F =\n\nP\n\nv0cosθ\n \n\nC.a =\n1\n\nm\n(\n\nP\n\nv0cosθ\n− f)，F =\n\nP\n\nv0\n \n\nD.a =\n1\n\nm\n(\nP\n\nv0\n− f)，F =\n\nP\n\nv0\n \n\n \n\n2.连接体问题 \n\n关键：明确研究对象 \n\n 整体法 隔离法', 478, 478, 1, '3e063d6e-d7ce-41b5-bb99-19d9d71c0096', NULL, '2026-03-27 20:07:42');
INSERT INTO `document_chunk` VALUES (280, 6, 2, 76, 'v0cosθ\n− f)，F =\n\nP\n\nv0\n \n\nD.a =\n1\n\nm\n(\nP\n\nv0\n− f)，F =\n\nP\n\nv0\n \n\n \n\n2.连接体问题 \n\n关键：明确研究对象 \n\n 整体法 隔离法 \n\n选用原则 \n研究系统外的物体对系统整体的作用力\n\n或系统的加速度 \n研究系统内物体之间的相互作用 \n\n注意问题 \n受力分析时不要再考虑系统内物体间的\n\n相互作用 \n一般隔离受力较少的物体 \n\n常见连接体：①直接接触或者通过介质连接的物体②不直接接触但有相互作用力的物体系统（如\n\n两个带电小球之间） \n\n例 2.如图所示，光滑水平面上放置分别为 m 和 2m 的四个木块，其中两个质量为 m 的木块间用一\n\n\n\n学员专用 请勿外泄 \n\n \n\n40 中公教育学员专用资料 报名专线：400-6300-999 \n\n不可伸长的轻绳相连，木块间的最大静摩擦力是 mg 。现用水平拉力F拉其中一个质量为 2m的木块，\n\n使四个木块以同一加速度运动，则轻绳对 m 的最大拉力为（ ）。 \n\n \n\nA.\n5\n\n3 mg\n B.\n\n4\n\n3 mg\n C.\n\n2\n\n3 mg\n D. mg3', 491, 491, 1, '50309eb3-25bb-411d-9db1-42a672babd4b', NULL, '2026-03-27 20:07:42');
INSERT INTO `document_chunk` VALUES (281, 6, 2, 77, 'A.\n5\n\n3 mg\n B.\n\n4\n\n3 mg\n C.\n\n2\n\n3 mg\n D. mg3 \n\n3.超重、失重、完全失重 \n\n（1）超重：物体对支持物的压力（或对悬挂物的拉力）大于物体所受重力的现象，称为超重现象。\n\n物体具有向上的加速度。 \n\n一般运动状态为：减速下降或加速上升。 \n\n（2）失重：物体对支持物的压力（或对悬挂物的拉力）小于物体所受重力的现象，称为失重现象。\n\n物体具有向下的加速度。 \n\n一般运动状态为：减速上升或加速下降。 \n\n完全失重：重力提供物体的加速度，即 a=g。 \n\n在完全失重的状态下，平常一切由重力产生的物理现象全都完全消失。 \n\n如单摆停摆、天平失效、浸在水中的物体不再受浮力、液体注不再产生压强 \n\n注意：超重和失重现象中，物体的实际重力并没有变化。改变的是视重。 \n\n4.弹簧问题（1）速度、加速度最大的确定 \n\n \n\n（2）弹力突变问题 \n\n例 3.如图 3 所示，轻质弹簧上端与一质量为 m 的物中公教师研究院提供块相连，下端与另一质量', 444, 444, 1, 'daf09e33-af2d-46ef-a3ba-2fddf9d5f9b5', NULL, '2026-03-27 20:07:42');
INSERT INTO `document_chunk` VALUES (282, 6, 2, 78, '改变的是视重。 \n\n4.弹簧问题（1）速度、加速度最大的确定 \n\n \n\n（2）弹力突变问题 \n\n例 3.如图 3 所示，轻质弹簧上端与一质量为 m 的物中公教师研究院提供块相连，下端与另一质量\n\n为 M 的物块 2 相连，整个系统置于水平放置的光滑木板上，并处于静止状态，将木板沿水平方向突然\n\n抽出后的瞬间，物块 1、2 的加速度大小分别为 a1、a2，重力加速度大小为 g，则（）。 \n\n \n\nA.a1=0，a2=g B.a1=g，a2=g \n\nA→O：mg-F 弹=ma，弹力逐渐增大，a 逐渐减小（方向向\n\n下），所以小球做 a 减小的加速运动； \n\nO 点：mg=F 弹，a=0，v 最大； \n\nO→B，F 弹-mg =ma，弹力继续增大，a 逐渐增大（方向向\n\n上），所以小球做 a 增大的的减速运动； \n\n \n\n\n\n学员专用 请勿外泄 \n\n \n\n41 中公教育学员专用资料 报名专线：400-6300-999 \n\nC.a1=0， g\nM\n\nMm \n2a D.a1=g， g\n\nM\n\nMm \n2a \n\n \n\n\n\n学员专用 请勿外泄', 475, 475, 1, '0d550ed8-b2e8-418d-a401-0af4b25a4d90', NULL, '2026-03-27 20:07:42');
INSERT INTO `document_chunk` VALUES (283, 6, 2, 79, '1 中公教育学员专用资料 报名专线：400-6300-999 \n\nC.a1=0， g\nM\n\nMm \n2a D.a1=g， g\n\nM\n\nMm \n2a \n\n \n\n\n\n学员专用 请勿外泄 \n\n \n\n42 中公教育学员专用资料 报名专线：400-6300-999 \n\n第四节 曲线运动、圆周运动 \n\n \n\n一、曲线运动 \n\n1.定义：轨迹是一条曲线的运动叫做曲线运动。 \n\n2.条件：当物体所受合力（加速度）的方向与它的速度方向不在同一直线上时，物体做曲线运动。 \n\n3.特点： \n\n（1）曲线运动的位移和速度方向时刻在变。某点的瞬时速度的方向，就是通过该点的切线方向，\n\n曲线运动一定是变速运动。 \n\n（2）做曲线运动的物体其轨迹向合外力所指一方弯曲，若已知物体的运动轨迹，可判断出物体所\n\n受合外力的大致方向。合外力始终指向运动轨迹的凹侧或内侧。 \n\n \n\n二、运动的合成与分解 \n\n1.合运动和分运动的关系 \n\n（1）等时性：各分运动经历的时间与合运动经历的时间相同。 \n\n（2）独立性：一个物体同时参与几个分运动，各分运动独立进行，不受其他分运动的影响。', 481, 481, 1, '52a5cb71-6e57-4f3c-8bcb-0958909b7183', NULL, '2026-03-27 20:07:43');
INSERT INTO `document_chunk` VALUES (284, 6, 2, 80, '（2）独立性：一个物体同时参与几个分运动，各分运动独立进行，不受其他分运动的影响。 \n\n（3）等效性：各分运动叠加起来与合运动有相同的效果。 \n\n2.运动的合成与分解 \n\n（1）运动的合成与分解均满足平行四边形定则。即速度、加速度、位移的合成与分解的均满足平\n\n行四边形定则。 \n\n（2）运动分解原则：根据运动的实际效果分解（一般为正交分解），物体的实际运动为合运动。 \n\n3.不同运动类型的合成 \n\n（1）两个匀速直线运动合成：匀速直线运动 \n\n（2）两个匀变速直线运动合成：可能是匀变速直线运动，也可能是匀变速曲线运动 \n\n（3）一个匀速直线运动，一个匀变速直线运动合成：匀变速曲线运动 \n\n例 1.如图所示，红蜡块能在玻璃管的水中匀速上升。若红蜡块在 A 点匀速上升的同时，使玻璃管\n\n水平向右做匀加速直线运动，则红蜡块实际运动的轨迹是图中的（ ） \n\n\n\n学员专用 请勿外泄 \n\n \n\n43 中公教育学员专用资料 报名专线：400-6300-999 \n\n \n\nA.直线 P B.曲线 Q C.曲线 R D.无法确定 \n\n4.运动的合成与分解两类问题 \n\n（1）小船渡河问题', 490, 490, 1, '2af07923-235f-4898-8a84-35471e9e2725', NULL, '2026-03-27 20:07:43');
INSERT INTO `document_chunk` VALUES (285, 6, 2, 81, '43 中公教育学员专用资料 报名专线：400-6300-999 \n\n \n\nA.直线 P B.曲线 Q C.曲线 R D.无法确定 \n\n4.运动的合成与分解两类问题 \n\n（1）小船渡河问题 \n\n小船渡河两个分运动：一是相对水面的横渡运动，二是随水的漂流运动。 \n\n小船渡河合运动（实际运动）：小船相对河岸（大地）的运动，也就是岸上观察者看到的实际运\n\n动。 \n\n求解问题：最短时间渡河，最短位移渡河。 \n\n①最短时间渡河：\n船v\n\nd\nt min （ 船v 垂直于河岸） \n\n②最短位移渡河 \n\na. 船水 vv  \n\ndx min \n船\n\n水\n\nv\n\nv\nc o s （ 垂直河岸合v ） \n\nb. 船水 vv  \n\nd\nv\n\nv\nx\n\n船\n\n水\nmin \n\n水\n\n船\n\nv\n\nv\nc o s （ 船合垂直vv ） \n\n注意：角如图所示指的是 船v 与河岸上游间的夹角。 \n\n（2）绳物牵连问题 \n\n绳物牵连分运动：①沿绳（杆）方向的伸长或收缩运动；②垂直于绳（杆）方向的旋转运动。 \n\n分解方法：按实际效果分，沿绳方向和垂直绳方向分解。', 479, 479, 1, '9b1a0e33-fd7f-4007-a123-28742e91c697', NULL, '2026-03-27 20:07:43');
INSERT INTO `document_chunk` VALUES (286, 6, 2, 82, '（2）绳物牵连问题 \n\n绳物牵连分运动：①沿绳（杆）方向的伸长或收缩运动；②垂直于绳（杆）方向的旋转运动。 \n\n分解方法：按实际效果分，沿绳方向和垂直绳方向分解。 \n\n绳物牵连的合运动：物体相对于地面的实际运动。 \n\n求解问题：物体运动速度。隐含条件：两物体合速度或分速度间的相等量，一般来说，绳（或杆）\n\n两端沿绳（或杆）方向的速度相等。 \n\n例 2.如图所示，人在岸上以速度 v0匀速直线前进，通过定滑轮牵引水面上的小船 A 靠岸。求：当\n\n绳子与水平方向的夹角为 θ 时，小船运动的速度大小。 \n\n\n\n学员专用 请勿外泄 \n\n \n\n44 中公教育学员专用资料 报名专线：400-6300-999 \n\n \n\n三、平抛运动规律 \n\n1.特点：①具有水平方向的初速度；②只受重力作用，是加速度为重力加速度 g 的匀变速曲线运\n\n动；③合力方向与初速度方向垂直。 \n\n2.运动规律：平抛运动可以分解为水平方向的匀速直线运动和竖直方向的自由落体运动。 \n\n \n\n \n\n \n\n3.平抛运动几个推论 \n\n（1）运动时间 ，与初速度无关，只与高度有关。 \n\n（2）落地的水平位移 ，落地速度', 490, 490, 1, 'dbc9be78-72b4-40d1-9a1e-720da93614c0', NULL, '2026-03-27 20:07:43');
INSERT INTO `document_chunk` VALUES (287, 6, 2, 83, '3.平抛运动几个推论 \n\n（1）运动时间 ，与初速度无关，只与高度有关。 \n\n（2）落地的水平位移 ，落地速度 \n\n（3）平抛运动的速率不随时间均匀变化，速度随时间均匀变化，且 v 沿竖直方向向下。 \n\n（4）平抛运动的任一时刻，物体的速度方向与水平方向的夹角 ，和位移与水平方向的夹角 有：\n\n tan2tan  \n\n（5）平抛运动的任一时刻，物体的瞬时速度的反向延长线一定通过此时水平位移的中点。 \n\n2h\nt\n\ng\n\n\n0\n\n2h\nx v\n\ng\n\n\n2\n\n0 2tv v gh \n\n\n\n学员专用 请勿外泄 \n\n \n\n45 中公教育学员专用资料 报名专线：400-6300-999 \n\n4.平抛运动常考题型 \n\n（1）利用平抛运动的轨迹解题 \n\n \n\n①若 A 点是平抛的起始点，则有： ......=1:3:5：…… \n\n②若 A 点时平抛轨迹中的任意一点，则有： \n\n \n\n \n\n例 3.如图所示，三个小球 a、b、c 分别在距离地面不同的高度 h1、h2、h3处同时以相同的速度向', 455, 455, 1, '84d5a93e-7ccc-4cd6-9280-2480bd780c8b', NULL, '2026-03-27 20:07:43');
INSERT INTO `document_chunk` VALUES (288, 6, 2, 84, '.....=1:3:5：…… \n\n②若 A 点时平抛轨迹中的任意一点，则有： \n\n \n\n \n\n例 3.如图所示，三个小球 a、b、c 分别在距离地面不同的高度 h1、h2、h3处同时以相同的速度向\n\n左边水平抛出，不计空气阻力，三个小球每隔相同的时间间隔依次落到地面，小球 a 落到地面 D 点，\n\nDE=EF=FG，下列说法正确的是（ ） \n\n \n\nA.b、c 两球落在 D 点的左边 \n\nB.b 球落在 D 点，c 球落在 E 点 \n\nC.三个小球距离地面高度 h1:h2:h3=1:3:5 \n\nD.三个小球距离地面高度 h1:h2:h3=1:4:9 \n\n四、圆周运动 \n\n（一）描述圆周运动的物理量 \n\n1.线速度： \n\n定义：做圆周运动的物体，通过的弧长与通过这段弧长所需时间的比值，叫做线速度。 \n\n物理意义：描述做圆周运动的物体运动快慢的物理量，是矢量。 \n\n公式： （匀速圆周运动中\nT\n\nr\nv\n\n2\n ） \n\n方向：线速度的方向与半径垂直，与该点的圆弧相切。 \n\n1 2 3: : :y y y\n\n2\n\n2 1y y y gT   \n\n0\n\n2 1', 489, 489, 1, 'e67791bd-4ed4-4217-9b8a-a34b65470e29', NULL, '2026-03-27 20:07:43');
INSERT INTO `document_chunk` VALUES (289, 6, 2, 85, '1 2 3: : :y y y\n\n2\n\n2 1y y y gT   \n\n0\n\n2 1\n\nx x g g\nv x x\n\nT y y yy\n\ng\n\n   \n \n\nl\nv\n\nt\n\n\n\n\n\n\n\n学员专用 请勿外泄 \n\n \n\n46 中公教育学员专用资料 报名专线：400-6300-999 \n\n \n\n2.角速度： \n\n定义：做圆周运动的物体，连接物体与圆心的半径转过的圆心角与所用的时间的比值。 \n\n物理意义：描述物体绕圆心转动快慢的物理量，是矢量。 \n\n公式： （匀速圆周运动中\nT\n\nw\n2\n\n ） \n\n3.周期、频率和转速： \n\n①周期：做圆周运动的物体，转过一周所用的时间叫做周期。 \n\n公式： \n\n②频率：周期的倒数叫做频率\nT\n\nf\n1\n\n \n\n③转速：转速是物体单位时间内转过的圈数。n=f（f 的单位是 r/s 的条件下） \n\n4.相互关系： \n\n5.向心加速度：任何做匀速圆周运动的物体的加速度都指向圆心。 \n\n公式： \n\n6.向心力：①使物体具有向心加速度的合力；②是效果力，由其他力提供，只改变线速度方向；\n\n③始终指向圆心。', 486, 486, 1, '7a0c7625-daff-4578-b732-69e05587ccb7', NULL, '2026-03-27 20:07:44');
INSERT INTO `document_chunk` VALUES (290, 6, 2, 86, '公式： \n\n6.向心力：①使物体具有向心加速度的合力；②是效果力，由其他力提供，只改变线速度方向；\n\n③始终指向圆心。 \n\n匀速圆周运动公式： \n\n（二）做圆周运动的常见模型 \n\n1.传动问题 \n\n（1）共轴传动：同一圆盘上，角速度相同。如下图， CB ww  ， CB TT  ，\n3\n\n2\n\nr\n\nr\n\nv\n\nv\n\nC\n\nB  \n\n \n\n（2）皮带传动：同一皮带上，线速度相同。如上图， BA vv  ，\n2\n\n1\n\nr\n\nr\n\nT\n\nT\n\nB\n\nA  ，\n1\n\n2\n\nr\n\nr\n\nw\n\nw\n\nB\n\nA  \n\nt\n\n\n\n\n\n\n\n\n2 r\nT\n\nv\n\n\n\n\n2\n2v r r r f\n\nT\n\n\n   \n\n2 2\n2 2 2\n\n2\n\n4\n4\n\nv\na r v r r f\n\nr T\n\n\n      \n\n2 2\n2 2 2\n\n2\n\n4\n4\n\nv\nF m mr mr mr f m v\n\nr T\n\n\n      \n\n特别注意：匀速圆周运动的“匀速”是指线速度的大小保持不变，速度的方向时刻在变化，', 483, 483, 1, 'e196ce98-296e-4c75-a767-8cc1d21b7024', NULL, '2026-03-27 20:07:44');
INSERT INTO `document_chunk` VALUES (291, 6, 2, 87, '2 2\n\n2\n\n4\n4\n\nv\nF m mr mr mr f m v\n\nr T\n\n\n      \n\n特别注意：匀速圆周运动的“匀速”是指线速度的大小保持不变，速度的方向时刻在变化，\n\n所以匀速圆周运动是变速运动；匀速圆周运动的加速度时刻指向圆心，所以它属于变加速\n\n曲线运动。 \n\n\n\n学员专用 请勿外泄 \n\n \n\n47 中公教育学员专用资料 报名专线：400-6300-999 \n\n（3）齿轮传动：齿轮咬合边缘线速度相同。如下图： BA vv  ，\n1\n\n2\n\n2\n\n1\n\nn\n\nn\n\nr\n\nr\n\nT\n\nT\n\nB\n\nA  ，\n1\n\n2\n\nr\n\nr\n\nw\n\nw\n\nB\n\nA  \n\n \n\n例 4.已知 RB：RA=3：2，RA：RC=1：2，假若皮带不打滑，则分别在三个轮边缘的 A，B，C 三点\n\n的角速度之比是________；线速度之比是_______； \n\n \n\n2.竖直平面内的临界问题 \n\n（1）轻绳模型或单轨模型（注意：绳对小球只能产生拉力） \n\n小球能过最高点的临界条件：绳子和轨道对小球刚好没有力的作用 \n\n \n\n mg =\n2v', 485, 485, 1, '9a0f55db-a186-42e6-a00e-f61702a74d32', NULL, '2026-03-27 20:07:44');
INSERT INTO `document_chunk` VALUES (292, 6, 2, 88, '___； \n\n \n\n2.竖直平面内的临界问题 \n\n（1）轻绳模型或单轨模型（注意：绳对小球只能产生拉力） \n\n小球能过最高点的临界条件：绳子和轨道对小球刚好没有力的作用 \n\n \n\n mg =\n2v\n\nm\nR\n v临界= Rg \n\n小球能过最高点条件：v ≥ Rg （当 v> Rg 时，绳对球产生拉力，轨道对球产生压力） \n\n不能过最高点条件：v < Rg （实际上球还没有到最高点时，就脱离了轨道） \n\n（2）轻杆模型或双轨模型（注意：轻杆和细线不同，轻杆对小球既能产生拉力，又能产生推力。） \n\n小球能最高点的临界条件：v = 0，F = mg（F 为支持力） \n\n \n\n当 0< v < Rg 时，F 随 v 增大而减小，且 mg > F > 0（F 为支持力） \n\n当 v = Rg 时，F=0 \n\n\n\n学员专用 请勿外泄 \n\n \n\n48 中公教育学员专用资料 报名专线：400-6300-999 \n\n当 v > Rg 时，F 随 v 增大而增大，且 F >0（F 为拉力） \n\n例 5.长为 l 的刚性轻质杆，一端固定在光滑的水平轴 O 处，另一端固定有小球，小球随杆在竖直', 493, 493, 1, 'a99ba883-370a-4f9a-b866-fc01e5f0ae17', NULL, '2026-03-27 20:07:44');
INSERT INTO `document_chunk` VALUES (293, 6, 2, 89, '6300-999 \n\n当 v > Rg 时，F 随 v 增大而增大，且 F >0（F 为拉力） \n\n例 5.长为 l 的刚性轻质杆，一端固定在光滑的水平轴 O 处，另一端固定有小球，小球随杆在竖直\n\n平面内做圆周运动，如图所示。设小球在最高点的速度大小为 v，重力加速度为 g，若小球在最高点速\n\n度的大小可以取不同的值，则下列叙述正确的是（ ）。 \n\n \n\nA. v 的取值由零开始增大时，杆对小球的作用力不变 \n\nB. v 的取值由零开始增大时，杆对小球的作用力逐渐增大 \n\nC. v 的取值由 逐渐减小时，杆对小球的作用力逐渐减小 \n\nD. v 的取值由 逐渐增大时，杆对小球的作用力逐渐增大 \n\n4.圆锥摆模型 \n\n圆锥摆模型在圆周运动中的应用： \n\n \n\n如图所示：摆球的质量为 m，摆线长度为 L ，摆动后摆线与竖直方向成 θ 角，则摆球在水平面\n\n上做匀速圆周运动，加速度必定指向圆心，依据牛顿第二定律，对摆球受力分析，得： \n\n \n\n五、生活中的圆周运动 \n\n1.火车转弯 \n\n外轨略高于内轨，使得火车所受重力和支持力的合外力 FN提供向心力。', 480, 480, 1, 'e3f8515d-22b3-4a30-9e14-587ce76657ff', NULL, '2026-03-27 20:07:44');
INSERT INTO `document_chunk` VALUES (294, 6, 2, 90, '周运动，加速度必定指向圆心，依据牛顿第二定律，对摆球受力分析，得： \n\n \n\n五、生活中的圆周运动 \n\n1.火车转弯 \n\n外轨略高于内轨，使得火车所受重力和支持力的合外力 FN提供向心力。 \n\n \n\n标准速度：v = grtanθ \n\n\n\n学员专用 请勿外泄 \n\n \n\n49 中公教育学员专用资料 报名专线：400-6300-999 \n\n（1）当 v＝ 0v 时，内外轨均不受侧向挤压的力 \n\n（2）当 v＞ 0v 时，外轨受到侧向挤压的力 \n\n（3）当 v＜ 0v 时，内轨受到侧向挤压的力 \n\n2.汽车过桥 \n\n若汽车在拱桥上以速度 v 前进，桥面的圆弧半径为 R \n\n求汽车过桥的最高点时对桥面的压力？ \n\n \n\n向\n\n2\n\nN\n\nmV\nF = G - F =\n\nr\n；\n\n2\n\nN\n\nmV\nF = G -\n\nr\n \n\n速度越快，压力越小。当 FN=0 时，向心力最大=G。 \n\n脱离桥面的临界速度v = gr \n\n3.离心现象：当提供的向心力小于所需向心力时，物体将远离轨道的现象。 \n\n \n\n从力的角度分析物体的运动： \n\n（1）匀速圆周运动 rmwF 2合', 485, 485, 1, '4869d45c-0b5e-4dc7-9127-15a3fb505498', NULL, '2026-03-27 20:07:44');
INSERT INTO `document_chunk` VALUES (295, 6, 2, 91, '脱离桥面的临界速度v = gr \n\n3.离心现象：当提供的向心力小于所需向心力时，物体将远离轨道的现象。 \n\n \n\n从力的角度分析物体的运动： \n\n（1）匀速圆周运动 rmwF 2合\n \n\n（2）离心运动 rmwF 2合 ，应用实例：洗衣机脱水、离心制管技术等。 \n\n（3）向心运动 rmwF 2合 \n\n应用实例：洗衣机脱水、离心制管技术；避免危害：汽车高速转弯、高速转动砂轮 \n\n \n\n\n\n学员专用 请勿外泄 \n\n \n\n50 中公教育学员专用资料 报名专线：400-6300-999 \n\n第五节 万有引力定律 \n\n \n\n一、开普勒三定律 \n\n1.第一定律（轨道定律）：所有行星绕太阳运动的轨道都是椭圆，太阳处在椭圆的一个焦点上。 \n\n2.第二定律（面积定律）：对任意一个行星来说，它与太阳的连线在相等的时间内扫过相等的面积。 \n\n \n\n3.第三定律（周期定律）：所有行星的轨道的半长轴的三次方跟它的公转周期的二次方的比值都\n\n相等。其数学表达式为： ，式中 k 是只与太阳有关的常量。 \n\n4.开普勒三定律的理解：', 461, 461, 1, '96d4cb4b-8fc9-4dee-8875-2f8667c3d39e', NULL, '2026-03-27 20:07:45');
INSERT INTO `document_chunk` VALUES (296, 6, 2, 92, '3.第三定律（周期定律）：所有行星的轨道的半长轴的三次方跟它的公转周期的二次方的比值都\n\n相等。其数学表达式为： ，式中 k 是只与太阳有关的常量。 \n\n4.开普勒三定律的理解： \n\n①行星速度的变化：行星经过近日点时的速度最大，经过远日点时的速度最小。（由开普勒第二\n\n定律推得）。 \n\n②行星的周期与轨道的关系：所有行星中，轨道的半长轴（或半径）越大，周期越大。因此，太\n\n阳系的行星中，离太阳越近的行星，其运动周期越小。（由开普勒第三定律得出） \n\n例 1.如图所示，两质量相等的卫星 A、B 绕地球做匀速圆周运动，用 R、T、Ek、S 分别表示卫星\n\n的轨道半径、周期、动能、与地心连线在单位时间内扫过的面积。下列关系式正确的有（ ）。 \n\n \n\nA. BA TT  B. kBkA EE  C. BA SS  D.\n2\n\n3\n\n2\n\n3\n\nB\n\nB\n\nA\n\nA\n\nT\n\nR\n\nT\n\nR\n \n\n二、万有引力定律 \n\n\n\n学员专用 请勿外泄 \n\n \n\n51 中公教育学员专用资料 报名专线：400-6300-999', 464, 464, 1, '2976fcdb-7515-422a-bb62-451b6a4fd383', NULL, '2026-03-27 20:07:45');
INSERT INTO `document_chunk` VALUES (297, 6, 2, 93, '3\n\n2\n\n3\n\nB\n\nB\n\nA\n\nA\n\nT\n\nR\n\nT\n\nR\n \n\n二、万有引力定律 \n\n\n\n学员专用 请勿外泄 \n\n \n\n51 中公教育学员专用资料 报名专线：400-6300-999 \n\n1.内容：自然界中任何两个物体都相互吸引，引力的方向在它们的连线上，引力的大小与物体的\n\n质量 1m 和 2m 的乘积成正比，与它们之间距离 r 的二次方成反比，即 \n\n2r\n\nMm\nGF  \n\n，叫做引力常量。 \n\n \n\n三、万有引力定律的应用 \n\n应用一：卫星的运行速度 v、周期 T 与半径 r 的关系 \n\nr\n\nv\nm\n\nr\n\nMm\nG\n\n2\n\n2\n ，推得\n\nr\n\nGM\nv  \n\n2\n\n2\n\n2\n\n4\n\nT\nmr\n\nr\n\nMm\nG\n\n\n ，推得\n\nGM\n\nr\nT\n\n3\n\n2 \n\n2\n\n2\nmr\n\nr\n\nMm\nG  ，推得\n\n3r\n\nGM\n\n\n \n\nma\nr\n\nMm\nG \n\n2\n，推得\n\n2r\n\nM\nGa \n\n \n卫星的运行 v、w、a 与半径 r 成反比，T 与半径 r 成正比。（越高越慢）', 465, 465, 1, '62bd91d7-02fc-4ae6-96d7-1525ba60be4a', NULL, '2026-03-27 20:07:45');
INSERT INTO `document_chunk` VALUES (298, 6, 2, 94, '（越高越慢） \n\n例 2.“神九”与“天宫一号”成功对接，创造了许多我国航天史的第一，“神九”与“天一”对\n\n接过程中需进行多次变轨，若其中两次变轨的轨道半径分别为 R1.R2，角速度大小分别为 ω1.ω2，运行\n\n轨道视为圆轨道，则对应角速度之比 等于（ ） \n\nA.\n\n2\n\n1\n\nR\n\nR\n B.\n\n1\n\n2\n\nR\n\nR\n C.\n\n3\n\n2\n\n3\n\n1\n\nR\n\nR\n\n \n\nD.\n3\n\n1\n\n3\n\n2\n\nR\n\nR\n\n \n\n应用二：天体质量 M、密度 ρ的估算 \n\n由 r\nT\n\nm\nr\n\nMm\nG\n\n2\n\n2\n\n2\n\n4\n\n\n，\n得中心天体质量\n\n2\n\n324\n\nGT\n\nr\nM\n\n\n (已知 v、w、r、T 中的任意两个均可以求太\n\n阳质量) \n\n又因\nV\n\nM\n ； 3\n\n3\n\n4\nRV \n\n，\n得密度\n\n32\n\n33\n\nRGT\n\nr\n  。 \n\n11 2 26.67 10 /G N m kg  \n\n注： \n\n1.适用条件：宏观、低速，质点间的相互作用。 \n\n2.引力常量 G 是由英国物理学家卡文迪许利用扭秤实验测得。', 482, 482, 1, 'a7591cdc-c5c4-49bd-8edb-3cbad1d905b4', NULL, '2026-03-27 20:07:45');
INSERT INTO `document_chunk` VALUES (299, 6, 2, 95, '11 2 26.67 10 /G N m kg  \n\n注： \n\n1.适用条件：宏观、低速，质点间的相互作用。 \n\n2.引力常量 G 是由英国物理学家卡文迪许利用扭秤实验测得。 \n\n3.关于半径 r：若物体的大小比它们之间的距离小得多，两物体可看做质点，则 r 表示两\n\n个点间的距离。若是地球、月球等球体，r 表示球心间的距离。 \n\n\n\n学员专用 请勿外泄 \n\n \n\n52 中公教育学员专用资料 报名专线：400-6300-999 \n\n在中心天体表面做匀速圆周运动时，r=R 代入上式得：\n2\n\n3\n\nGT\n\n\n  （仅知道周期 T 即可求得中\n\n心天体的密度） \n\n应用三：变轨问题 \n\n \n\n基本过程：发射同步卫星时，通常先将卫星发送到近地轨道Ⅰ，使其绕地球做匀速圆周运动，速\n\n率为 v1；第一次在 P 点点火加速，在短时间内将速率 K，使卫星进入椭圆形的转移轨道Ⅱ；第一次加\n\n速：卫星需要的向心力\nr\n\nmv2\n\n增大了，但万有引力\n2r\n\nGMm\n没变，因此卫星将开始做离心运动，进入椭', 456, 456, 1, '85265cdc-38fe-4769-8d67-fff51e6b51b9', NULL, '2026-03-27 20:07:45');
INSERT INTO `document_chunk` VALUES (300, 6, 2, 96, '在 P 点点火加速，在短时间内将速率 K，使卫星进入椭圆形的转移轨道Ⅱ；第一次加\n\n速：卫星需要的向心力\nr\n\nmv2\n\n增大了，但万有引力\n2r\n\nGMm\n没变，因此卫星将开始做离心运动，进入椭\n\n圆形的转移轨道Ⅱ，点火过程中卫星的线速度增大。卫星运行到远地点 Q 时的速率为 v3，此时进行第\n\n二次点火加速，在短时间内将速率由 v3增加到 v4，使卫星进入同步轨道Ⅲ，绕地球做匀速圆周运动。 \n\n结论： \n\n①从低轨到高轨，加速；从高轨道到低轨，减速； \n\n②不同轨道同一点速度不同，加速度相同； \n\n③从低轨道到高轨道，动能减少，势能增加，机械能增加（化学能转化成机械能）。 \n\n应用四：卫星超重和失重 \n\n卫星发射时，加速上升进入轨道或减速下降回收时，处于超重状态。 \n\n卫星进入轨道后，万有引力提供向心力，完全失重。 \n\n四、三种宇宙速度 \n\n（1）第一宇宙速度，v1=7.9km/s，第一宇宙速度又称为最小发射速度或绕地卫星最大环绕速度。 \n\n \n\n（2）第二宇宙速度（脱离速度），v2=11.2km/s，卫星挣脱地球引力的最小发射速度。', 476, 476, 1, '240423a2-f68f-43ca-9320-796b19f58095', NULL, '2026-03-27 20:07:45');
INSERT INTO `document_chunk` VALUES (301, 6, 2, 97, '（2）第二宇宙速度（脱离速度），v2=11.2km/s，卫星挣脱地球引力的最小发射速度。 \n\n（3）第三宇宙速度（逃逸速度），v3=16.7km/s，卫星挣脱太阳引力的束缚最小发射速度。 \n\n五、近地卫星与同步卫星 \n\n（1）近地卫星特点 \n\n轨道半径 r 近似等于地球半径 R，运行速度为 7.9 km/s，运行周期 T=85 min \n\n根据近地卫星重力提供向心力，则\nR\n\nv\nmmg\n\n2\n\n ，求得第一宇宙速度 gRv  ； \n\n注：不同天体由于 g 不同，而第一宇宙速度不同 \n\nv2 \n\nv3 \n\nv4 v1 \n\nQ \n\nP \n\nⅠ \n\nⅢ \n\nⅡ \n\n\n\n学员专用 请勿外泄 \n\n \n\n53 中公教育学员专用资料 报名专线：400-6300-999 \n\n（2）地球同步卫星的“六个一定” \n\n周期一定（T=24 h）；角速度一定；轨道一定（轨道平面在赤道平面上）；高度一定（3.6×104 km）； \n\n环绕速率一定（3.08 km/s）；向心加速度大小一定（0.23 m/s2）。', 451, 451, 1, '6c2d5568-0f1b-4b54-9103-814c780a7608', NULL, '2026-03-27 20:07:46');
INSERT INTO `document_chunk` VALUES (302, 6, 2, 98, '周期一定（T=24 h）；角速度一定；轨道一定（轨道平面在赤道平面上）；高度一定（3.6×104 km）； \n\n环绕速率一定（3.08 km/s）；向心加速度大小一定（0.23 m/s2）。 \n\n例 3.地球赤道上的山丘 e，近地卫星 p 和同步通信卫星 q 均在赤道平面上绕地心做匀速圆周运动.\n\n设 e、p、q 的圆周运动速率分别为 v1、v2、v3，向心加速度分别为 a1、a2、a3，则（ ） \n\n \n\nA. v1> v2> v3 B. v3< v1< v2 C.a1>a2>a3 D. a1< a3< a2 \n\n \n\n\n\n学员专用 请勿外泄 \n\n \n\n54 中公教育学员专用资料 报名专线：400-6300-999 \n\n第六节 功与能量 \n\n \n\n一、功的概念 \n\n1.功的定义：一个物体受到力的作用，并在力的方向上发生了一段位移，这个力就对物体做了功。 \n\n2.做功的两个因素：作用在物体上的力，物体在力的方向上发生的位移。 \n\n3.功的物理意义：功是能量转化的量度。 \n\n4.公式： cosFlW ', 458, 458, 1, 'f3a5d8e1-237a-4eba-b302-6ea6bf0566e2', NULL, '2026-03-27 20:07:46');
INSERT INTO `document_chunk` VALUES (303, 6, 2, 99, '2.做功的两个因素：作用在物体上的力，物体在力的方向上发生的位移。 \n\n3.功的物理意义：功是能量转化的量度。 \n\n4.公式： cosFlW  \n\n①该公式只适用于恒力做功， 是力与位移方向的夹角， l 为物体对地的位移。 \n\n②当恒力 F 的方向与位移 l 的方向一致时，力对物体所做的功为 FlW  。 \n\n \n\n 理解对地位移： \n\n \n\n如图，物体 A 用绳子连接在墙上，各接触面间有摩擦。用力水平向左的力 F 作用在物体 B 上，使\n\n其向左运动。问物体 A 对物体 B 的摩擦力、物体 B 对物体 A 的摩擦力、地面对物体 B 的摩擦力分别\n\n做什么功？ \n\n答案：负功、不做功（A 所受到的摩擦力没有对地位移）、负功。 \n\n5.功是标量，但有正负： \n\n力与位移的夹角 功的正负 物理意义 \n\n W > 0 力对物体做正功 \n\n W < 0 力对物体做负功或物体克服这个力做了功 \n\n W = 0 力对物体不做功 \n\n \n\n二、功的大小计算方法 \n\n（一）恒力做功 \n\n0 90o oa \n\n90 180o oa \n\n90oa ', 481, 481, 1, '9e300819-40fa-4e75-8d1e-1c11e9a2b8ca', NULL, '2026-03-27 20:07:46');
INSERT INTO `document_chunk` VALUES (304, 6, 2, 100, '力对物体做负功或物体克服这个力做了功 \n\n W = 0 力对物体不做功 \n\n \n\n二、功的大小计算方法 \n\n（一）恒力做功 \n\n0 90o oa \n\n90 180o oa \n\n90oa \n\n补充判断：①只要物体受力的同时又有位移发生，则一定有力对物体做功？（×） \n\n②一个力对物体做了负功，则说明这个力一定阻碍物体的运动？（√） \n\n\n\n学员专用 请勿外泄 \n\n \n\n55 中公教育学员专用资料 报名专线：400-6300-999 \n\n1.合外力做的功：①先求合外力，再由公式 coslFW 合合  计算；②先求各个做的功 1W 、 2W ……，\n\n再应用 21 WWW 合 +……求合外力做的功。 \n\n2.保守力做功：保守力对质点所做的功，与质点运动的路径无关，只与质点的初始位置和末位置\n\n有关。因此，保守力做正功时，系统内相应势能减少。重力、弹力、电场力、万有引力等都是保守力。 \n\n3.作用力与反作用力的功：作用力与反作用力同时存在，作用力做功时，反作用力可能做功，也\n\n可能不做功，可能做正功，也可能做负功。 \n\n4.摩擦力做功 \n\n比较 静摩擦力 滑动摩擦力', 495, 495, 1, '91b7dbc1-8ba3-448c-bb89-0681ca2424d1', NULL, '2026-03-27 20:07:46');
INSERT INTO `document_chunk` VALUES (305, 6, 2, 101, '3.作用力与反作用力的功：作用力与反作用力同时存在，作用力做功时，反作用力可能做功，也\n\n可能不做功，可能做正功，也可能做负功。 \n\n4.摩擦力做功 \n\n比较 静摩擦力 滑动摩擦力 \n\n不同点 \n\n一对相互\n\n作用摩擦\n\n力做功 \n\n一对静摩擦力所做功的代数总\n\n和等于零 \n\n一对相互作用的滑动摩擦力对物体系统所做\n\n的总功，等于摩擦力与两个物体相对路程的乘\n\n积，即 ，表示物体克服摩擦力\n\n做功，系统损失机械能转变为内能 \n\n相同点 两种摩擦力对物体可以做正功、负功，还可以不做功 \n\n如图所示，质量为 m 的小木块 A 以水平初速 υ0冲上质量为 M、长为 L、置于光滑水平面 C 上的\n\n木板 B，并正好不从木板 B 上掉下，B 间动摩擦因数为 μ。求此过程中产生的内能。 \n\nQumgLW\n\numgSW\n\nLSumgW\n\nf\n\nfAB\n\nfBA\n\n\n\n\n\n\n\n-\n\n)(\n\n总\n\n \n\n \n\n例 1.如图所示，水平传送带长为 s，以速度 v 始终保持匀速运动，质量为 m 的货物无初速放到 A', 458, 458, 1, '72f45a40-ec07-47eb-acfd-30c0cfa4766a', NULL, '2026-03-27 20:07:46');
INSERT INTO `document_chunk` VALUES (306, 6, 2, 102, 'SumgW\n\nf\n\nfAB\n\nfBA\n\n\n\n\n\n\n\n-\n\n)(\n\n总\n\n \n\n \n\n例 1.如图所示，水平传送带长为 s，以速度 v 始终保持匀速运动，质量为 m 的货物无初速放到 A\n\n点，货物运动到 B 点时恰达到速度 v，货物与皮带间的动摩擦因数为 μ，当货物从 A 点运动到 B 点的\n\n过程中，以下说法正确的是（ ）。 \n\n \n\nA.摩擦力对物体做功为 0.5mv2 \n\nB.摩擦力对物体做功为 μmgs \n\nC.传送带克服摩擦力做功为 μmgs \n\nD.因摩擦而生的热能为 2μmgs \n\nfF fW F l  相对\n\n\n\n学员专用 请勿外泄 \n\n \n\n56 中公教育学员专用资料 报名专线：400-6300-999 \n\n（二）变力做功 \n\n1.根据动能定理求解：\n2\n\n1\n\n2\n\n2\n2\n\n1\n\n2\n\n1\nmvmvW  \n\n2.当变力的功率 P 一定时，可用W Pt 求功，如机车恒定功率启动时。 \n\n3.图像法：根据 F-x 图像的面积即为力对物体做的功求解。 \n\n4.公式法：当 F 与 x 成线性关系，可以用平均值代替变力计算。', 486, 486, 1, '2e5cce30-9624-4f18-98b0-389c96ce67ce', NULL, '2026-03-27 20:07:46');
INSERT INTO `document_chunk` VALUES (307, 6, 2, 103, '3.图像法：根据 F-x 图像的面积即为力对物体做的功求解。 \n\n4.公式法：当 F 与 x 成线性关系，可以用平均值代替变力计算。 \n\n例：如图，做功大小 x\nFF\n\nW \n\n\n\n2\n\n21 \n\n \n\n三、功率 \n\n1.物理意义：描述力对物体做功的快慢。 \n\n2.公式： \n\n①\nt\n\nW\np  ，P 为时间 t 内的平均功率 \n\n② cosP F v   ，若 v 为平均速度，则 P 为平均功率；若v 为瞬时速度，则 P 为瞬时功率。 \n\n平均功率计算公式： vF\nt\n\ns\nF\n\nt\n\nW\np  或 \n\n瞬时功率计算公式： \n\n3.额定功率：机械正常工作时的最大功率。 \n\n4.实际功率：机械实际工作时的功率，要求不能大于额定功率。 \n\n例 2.如图所示，将质量为 m 的小球以初速度 v0 从 A 点水平抛出，正好垂直于斜面落在斜面上 B\n\n点.已知斜面的倾角为 α，小球落到斜面上 B 点时重力做功的瞬时功率是（ ） \n\n \n\nA. tanomgv  B. 0 cotmgv  C.\n0\n\nsin\n\nmgv\n\n\n D. 0 cosmgv ', 489, 489, 1, 'c498fa61-2c7a-4f98-8ba2-0285939336b5', NULL, '2026-03-27 20:07:47');
INSERT INTO `document_chunk` VALUES (308, 6, 2, 104, '的倾角为 α，小球落到斜面上 B 点时重力做功的瞬时功率是（ ） \n\n \n\nA. tanomgv  B. 0 cotmgv  C.\n0\n\nsin\n\nmgv\n\n\n D. 0 cosmgv  \n\n5.机车启动问题 \n\n（1）以恒定功率启动 FvP  ， mafF -牵 \n\ncosP F v  \n\ncosP F v  瞬 瞬\n\n\n\n学员专用 请勿外泄 \n\n \n\n57 中公教育学员专用资料 报名专线：400-6300-999 \n\n \n\n用 v－t 图，这一过程可表示为右图：最大速度之前是一段曲线。 \n\n \n\n（2）以恒定加速度启动 \n\n \n \n\n用 v－t 图，这一过程可表示为右图：起初匀加速运动是一段倾斜的直线，紧接着是一段曲线，最\n\n后是平行于时间轴的直线。 \n\n \n\n \n\n例 3.如图所示，为一汽车在平直的公路上，由静止开始运动的速度图象，汽车所受阻力恒定.图中\n\nOA 为一段直线，AB 为一曲线，BC 为一平行于时间轴的直线，则（ ） \n\n①无论哪种启动过程，机车的最大速度都等于其匀速运动时的速度，即\nmin\n\nm\n\nP P\nv\n\nF F\n \n\n阻', 495, 495, 1, '1d746af8-a356-46d8-9fdf-541e4ed4a38c', NULL, '2026-03-27 20:07:47');
INSERT INTO `document_chunk` VALUES (309, 6, 2, 105, 'OA 为一段直线，AB 为一曲线，BC 为一平行于时间轴的直线，则（ ） \n\n①无论哪种启动过程，机车的最大速度都等于其匀速运动时的速度，即\nmin\n\nm\n\nP P\nv\n\nF F\n \n\n阻\n\n（式中 minF 为最小牵引力，其值等于阻力F阻力）。 \n\n②机车以恒定加速度启动的运动过程中，匀加速过程结束时，功率最大，速度不是最大，\n\n即 m\n\nP P\nv v\n\nF F\n  \n\n阻\n\n。 \n\n③机车以恒定功率运行时，牵引力做的功 W=Pt。由动能定理：Pt kF x E  阻 。此式经\n\n常用于求解机车以恒定功率启动过程的位移大小。 \n\n v\n\nt\no\n\nmv\ntv\n\n FvPv ＝\n不变\n\n、fF\n\n不变\n\n－\n＝，\n\n \n\nm\nfF\n\na  一定\n额P\n\n\nm\n\nfF\na\n\nv\n\nP\nFv,\n\n－额\n\nmv v\n\n0a \n\n fF \n\n达到最大\n＝\n\n时当 \n\n匀加速直线运动 变加速直线运动\n\n保持匀速直线运动\n\n匀速运动 \n\n0,\n\nP P\n\na v\n\n\n\n\n\n额当 时，\n\n仍增大\n\n \n\n', 490, 490, 1, 'e3f53c46-8b98-4362-98c6-fe004ee03a48', NULL, '2026-03-27 20:07:47');
INSERT INTO `document_chunk` VALUES (310, 6, 2, 106, '达到最大\n＝\n\n时当 \n\n匀加速直线运动 变加速直线运动\n\n保持匀速直线运动\n\n匀速运动 \n\n0,\n\nP P\n\na v\n\n\n\n\n\n额当 时，\n\n仍增大\n\n \n\n\n\n\nm\n\nf-F\na\n\nv\n\nP\nFv\n\nmv v\n\n0a \n\n fF \n\n达到最大\n＝\n\n时当 \n保持匀速直线运动\n\n变加速运动 匀速运动\n\n v\n\nt\no\n\nmv\n\n\n\n学员专用 请勿外泄 \n\n \n\n58 中公教育学员专用资料 报名专线：400-6300-999 \n\n \n\nA.OA 段汽车发动机的功率是恒定的 \n\nB.OA 段汽车发动机的牵引力恒定 \n\nC.AB 段汽车发动机的功率可能是恒定的 \n\nD.BC 段汽车发动机的功率是恒定的 \n\n四、动能定理及其应用 \n\n1.动能：物体由于运动所具有的能称为动能。\n2\n\n2\n\n1\nmvEk  。动能是标量，是描述物体运动状态的\n\n物理量，其单位与功的单位相同。 \n\n2.动能定理 \n\n（1）内容：合外力对物体所做的功等于物体动能的变化。 \n\n（2）表达式： ， \n\n（3）注意事项：', 476, 476, 1, '03521f98-d52e-4c72-aeb5-9da76f63f4de', NULL, '2026-03-27 20:07:47');
INSERT INTO `document_chunk` VALUES (311, 6, 2, 107, '动能是标量，是描述物体运动状态的\n\n物理量，其单位与功的单位相同。 \n\n2.动能定理 \n\n（1）内容：合外力对物体所做的功等于物体动能的变化。 \n\n（2）表达式： ， \n\n（3）注意事项： \n\n①动能不进行矢量分解，无矢量式。（即不能在分速度或分位移上使用动能定理） \n\n②动能定理的应用只与初末位置物体的动能有关，无需考虑过程。 \n\n③动能定理可用于变力做功的求解。 \n\n \n\n④动能定理的局限性，无法确定速度 v 的方向。 \n\n⑤动能定理的研究对象一般是单一物体，或者可以看成单一物体的物体系（即几个运动状态相同\n\n的物体可以看做一个整体研究）。 \n\nkW E \n合\n\n2 2\n\n2 1\n\n1 1\n\n2 2\nF x mv mv 合\n\n典例：如图所示，质量为 m 的小球用长 L 的细线悬挂而静止在竖直位置。在下列三\n\n种情况下，分别用水平拉力 F 将小球拉到细线与竖直方向成 θ 角的位置。在此过程中，用\n\nF 缓慢地拉，拉力 F 做的功是多少？ \n\n \n\n解析：若用 F 缓慢地拉，则显然 F 为变力，只能用动能定理求解。等于该过程克服重力\n\n做的功 Mgl(1-cosθ)。', 495, 495, 1, '09ee885c-2171-433e-8315-bb3f325c779a', NULL, '2026-03-27 20:07:47');
INSERT INTO `document_chunk` VALUES (312, 6, 2, 108, '在此过程中，用\n\nF 缓慢地拉，拉力 F 做的功是多少？ \n\n \n\n解析：若用 F 缓慢地拉，则显然 F 为变力，只能用动能定理求解。等于该过程克服重力\n\n做的功 Mgl(1-cosθ)。 \n\n \n\n\n\n学员专用 请勿外泄 \n\n \n\n59 中公教育学员专用资料 报名专线：400-6300-999 \n\n例 4.比赛中运动员将铅球斜上方投掷出去，铅球离手后，在空中飞行过程中动能 Ek随时间 t 的变化\n\n图像最接近的是（ ）。 \n\n \n\n五、机械能守恒定律 \n\n机械能守恒定律：在只有重力或弹力做功的物体系统内，动能与势能可以相互转化，而总的机械\n\n能保持不变，这叫做机械能守恒定律。 \n\n1.条件：①只有重力或弹力做功；②其他力合力为 0 或其他力不做功。 \n\n2.表达式： \n\n（1）守恒角度：\n\n\n\n\n\n pkpk EEEE （初态的机械能等于末态的机械能） \n\n（2）转化角度： pk EE  （变化的动能大小等于变化的势能） \n\n（3）转移角度： BA EE  （A 物体机械能的变化大小等于 B 物体机械能的变化）', 474, 474, 1, '03641d45-03ff-498f-89cd-245d055e4b8f', NULL, '2026-03-27 20:07:47');
INSERT INTO `document_chunk` VALUES (313, 6, 2, 109, '能等于末态的机械能） \n\n（2）转化角度： pk EE  （变化的动能大小等于变化的势能） \n\n（3）转移角度： BA EE  （A 物体机械能的变化大小等于 B 物体机械能的变化） \n\n注意：解题时究竟选取哪一种表达形式，应根据题意灵活选取；须注意的是：选用（1）时，必须\n\n规定零势能参考面，而选用（2）和（3）时，可以不规定零势能参考面，但必须分清能量的减少量和\n\n增加量。 \n\n六、功能关系 \n\n做功 能的变化 表达式 \n\n重力做功 \n正功 重力势能减少 \n\n重力势能变化 \n 负功 重力势能增加 \n\n弹力做功 \n正功 弹性势能减少 \n\n弹性势能变化 \n 负功 弹性势能增加 \n\n合力做功 \n正功 动能增加 \n\n动能变化 \n 负功 动能减少 \n\n除重力（或系\n\n统内弹力）外\n\n其他力做功 \n\n正功 机械能增加 \n\n机械能变化 \n \n\n负功 机械能减少 \n\n负功 内能增加 \n\n \n\n安培力做功 \n正功 电能减少 \n\n电能变化 安W 21 EE  \n负功 电能增加 \n\n \n\n电场力做功 \n正功 电势能减少 \n\n电势能变化 电W \n21 EE  \n\n负功 电势能增加', 497, 497, 1, 'f1d4db83-3ebc-4e96-935a-fcc6d466ae1a', NULL, '2026-03-27 20:07:48');
INSERT INTO `document_chunk` VALUES (314, 6, 2, 110, '安培力做功 \n正功 电能减少 \n\n电能变化 安W 21 EE  \n负功 电能增加 \n\n \n\n电场力做功 \n正功 电势能减少 \n\n电势能变化 电W \n21 EE  \n\n负功 电势能增加 \n\n1 2G p pW E E \n\n1 2p pW E E 弹\n\n2 1W E E 合\n\n2 1W E E 外\n\n\n\n学员专用 请勿外泄 \n\n \n\n60 中公教育学员专用资料 报名专线：400-6300-999 \n\n \n\n七、能量转化和守恒定律 \n\n1.内容：能量既不会凭空产生，也不会凭空消失，它只能从一种形式转化为另一种形式，或者从\n\n一个物体转移到别的物体，在转化或转移的过程中，能量总量保持不变。 \n\n2.表达式： \n\n为系统中所有增加能量之和，而 为系统中所有减少能量之和。 \n\n3.两个方面来理解： \n\n（1）某种形式的能减少，一定存在其他形式的能的增加，且减少量和增加量一定相等。 \n\n（2）某个物体的能量减少，一定存在其他物体的能量增加，且减少量和增加量一定相等。 \n\n \n\n=E E 减 增\n\nE 增 E 减\n\n补充：安培力做功，机械能与电能相互转化。', 493, 493, 1, 'a42d2b66-aa73-4ff3-8ea1-09d903649bb4', NULL, '2026-03-27 20:07:48');
INSERT INTO `document_chunk` VALUES (315, 6, 2, 111, '（2）某个物体的能量减少，一定存在其他物体的能量增加，且减少量和增加量一定相等。 \n\n \n\n=E E 减 增\n\nE 增 E 减\n\n补充：安培力做功，机械能与电能相互转化。 \n\n电场力做功，电势能与其他形式的能转化。 \n\n\n\n学员专用 请勿外泄 \n\n \n\n61 中公教育学员专用资料 报名专线：400-6300-999 \n\n第七节 动量、冲量 \n\n \n\n一、动量 \n\n1.动量 \n\n（1）定义：物体的质量跟其速度的乘积叫做物体的动量，用符号 p 表示 \n\n（2）定义式 p=mv \n\n（3）动量的特点：①矢量，方向与速度同向；②状态量，对应于某一时刻或某一位置的瞬时值；\n\n③具有相对性，与参考系有关，通常取地面为参考系。 \n\n（4）动量与动能的联系 \n\nkmEp 2 ；\nm\n\np\nEk\n\n2\n\n2\n\n \n\n2.冲量 \n\n（1）定义：力与力的作用时间的乘积叫做力的冲量 \n\n（2）冲量的特点：①矢量；②过程量，冲量是描述力对物体作用的时间积累效应的物理量；③绝\n\n对性，冲量与参考系的选择无关，物体受某个力的冲量只取决于这个力及其作用时间，与物体的运动', 482, 482, 1, '56b8a7be-a252-4283-ae16-2a03a0341cb6', NULL, '2026-03-27 20:07:48');
INSERT INTO `document_chunk` VALUES (316, 6, 2, 112, '叫做力的冲量 \n\n（2）冲量的特点：①矢量；②过程量，冲量是描述力对物体作用的时间积累效应的物理量；③绝\n\n对性，冲量与参考系的选择无关，物体受某个力的冲量只取决于这个力及其作用时间，与物体的运动\n\n状态，是否受其他力无关。 \n\n（3）冲量的计算 \n\nI=Ft，只适用于计算恒力的冲量 \n\n二、动量定理 \n\n1.内容：物体在一个过程始末的动量变化量等于它在这个过程中所受力的冲量 \n\n2.表达式： \n\n（1） )( ttFmvvm  (F 不是恒力时也适用，此时 F 看做变力的平均值) \n\n（2） Ipp  \n\n3.适用范围：宏观、微观、低速、高速都适用 \n\n4.注意： \n\n使用动量定理表达式 )( ttFmvvm  ，需规定正方向。 \n\n三、动量守恒定律 \n\n1.内容：如果一个系统不受外力，或者所受外力的矢量和为 0，这个系统的总动量保持不变。 \n\n2.成立条件： \n\n\n\n学员专用 请勿外泄 \n\n \n\n62 中公教育学员专用资料 报名专线：400-6300-999 \n\n①不受外力或外力之和为零，动量守恒；', 471, 471, 1, 'a06855a4-b637-47b2-9a5d-89330959233b', NULL, '2026-03-27 20:07:48');
INSERT INTO `document_chunk` VALUES (317, 6, 2, 113, '2.成立条件： \n\n\n\n学员专用 请勿外泄 \n\n \n\n62 中公教育学员专用资料 报名专线：400-6300-999 \n\n①不受外力或外力之和为零，动量守恒； \n\n②外力远小于内力，动量近似守恒（如爆炸、子弹打物块、碰撞）； \n\n \n\n③某方向上外力之和为零，该方向上动量守恒。 \n\n3.适用对象及范围：①两个及两个以上物体组成的系统；②动量守恒定律是一个独立的实验定律，\n\n适用于目前物理学研究的一切领域。 \n\n4.表达式： \n\n①\n1 1 2 2 1 1 2 2m v m v m v m v    （常用公式）\n\n \n\n② 1 1 2 2 1 2( )m v m v m m v   \n\n③ 1 1 2 20 m v m v \n \n\n例 1.如图所示，轻弹簧的一段固定在竖直墙上，质量为m的光滑弧形槽静止停在光滑的水平面上，\n\n弧形底端与水平面相切，一个质量为 m 的小物块从槽的顶端静止下滑，下面说法正确的是（ ）。 \n\n \n\nA.在下滑过程中，小物块的机械能守恒 \n\nB.在下滑过程中，小物块和槽动量守恒 \n\nC.小物块离开弹簧后，做匀速直线运动', 488, 488, 1, 'a9fe6a57-f3df-4f44-963c-7cc054bef58e', NULL, '2026-03-27 20:07:48');
INSERT INTO `document_chunk` VALUES (318, 6, 2, 114, 'A.在下滑过程中，小物块的机械能守恒 \n\nB.在下滑过程中，小物块和槽动量守恒 \n\nC.小物块离开弹簧后，做匀速直线运动 \n\nD.小物块离开弹簧后，能够划上弧形槽 \n\n四、碰撞 \n\n1.碰撞：①作用时间极短；②系统内力远大于外力，系统总动量近似守恒；③碰撞过程中位移可\n\n忽略；④碰撞后系统的总动能小于或等于碰撞前系统的总动能。 \n\n2.碰撞特例分析 \n\n（1）完全弹性碰撞：动量守恒，机械能守恒 \n\n例 2.已知 A、B 两个钢性小球质量分别是 m1.m2，小球 B 静止在光滑水平面上，A 以初速度 v0与小\n\n球 B 发生弹性碰撞，求碰撞后小球 A 的速度 v1，物体 B 的速度 v2 大小和方向。 \n\n举例说明：以在水平桌面上发生碰撞的两个球体为例，它们之间一定有相互作用，这就是内\n\n力；而它们受到的重力、桌面对它们的支持力以及摩擦力属于外力；当外力远小于内力的时\n\n候，我们也可以运用动量守恒定律解决相关问题。 \n\n \n\n\n\n学员专用 请勿外泄 \n\n \n\n63 中公教育学员专用资料 报名专线：400-6300-999 \n\n \n\n结论：', 475, 475, 1, '43c608ad-d35a-4c5e-ab58-61054a67d121', NULL, '2026-03-27 20:07:48');
INSERT INTO `document_chunk` VALUES (319, 6, 2, 115, '学员专用 请勿外泄 \n\n \n\n63 中公教育学员专用资料 报名专线：400-6300-999 \n\n \n\n结论： \n\n（1）当 m1=m2 时，v1=0，v2=v0，显然碰撞后 A 静止，B 以 A 的初速度运动，两球速度交换，并\n\n且 A 的动能完全传递给 B，因此 m1=m2也是动能传递最大的条件； \n\n（2）当 m1＞m2 时，v1＞0，即 A、B 同方向运动，因 ＜ ，所以速度大小 v1\n\n＜v2，即两球不会发生第二次碰撞； \n\n若 m1>>m2 时，v1= v0，v2=2v0即当质量很大的物体 A 碰撞质量很小的物体 B 时，物体 A 的速度\n\n几乎不变，物体 B 以 2 倍于物体 A 的速度向前运动。 \n\n（3）当 m1＜m2时，则 v1＜0，即物体 A 反向运动。 \n\n当 m1<<m2时，v1=-v0，v2=0 即物体 A 以原来大小的速度弹回，而物体 B 不动，A 的动能完全没\n\n有传给 B，因此 m1<<m2是动能传递最小的条件。 \n\n以上弹性碰撞以动撞静的情景可以简单概括为：（质量）等大小，（速度和动能）交换了；小撞大，', 476, 476, 1, '9cc52096-c64e-47cd-8b10-c606ac08646b', NULL, '2026-03-27 20:07:48');
INSERT INTO `document_chunk` VALUES (320, 6, 2, 116, '以上弹性碰撞以动撞静的情景可以简单概括为：（质量）等大小，（速度和动能）交换了；小撞大，\n\n被弹回；大撞小，同向跑。 \n\n（2）非弹性碰撞：碰撞过程中机械能不守恒。 \n\n①完全非弹性碰撞：动量守恒，机械能损失最大 \n\n例 3.如图所示，有一质量为 m 的物体 B 静止在光滑水平面上，另一质量也为 m 的物体 A 以初速\n\n度 v0匀速向 B 运动，两物体相撞后粘在一起运动，试求碰撞中产生的热能？ \n\n \n\n②非完全弹性碰撞：动量守恒，机械能有损失 \n\n例 4.如图所示，用细线挂一质量为 M 的木块，有一质量为 m 的子弹自左向右水平射穿此木块，\n\n穿透前后子弹的速度分别为 和 v（设子弹穿过木块的时间和空气阻力不计），求此过程中产生的内\n\n能和物块上升的最大高度。 \n\n \n\n \n\n \n\n21\n\n01\n2\n\n2\n\nmm\n\nvm\nv\n\n\n\n\n21\n\n21 )(\n\nmm\n\nmm\n\n\n\n\n\n21\n\n12\n\nmm\n\nm\n\n\n\n\n\n学员专用 请勿外泄 \n\n \n\n64 中公教育学员专用资料 报名专线：400-6300-999 \n\n第二章 电磁学 \n\n第一节 静电场', 487, 487, 1, '5138272d-4a3d-4a7f-82e4-37291c0fb8bd', NULL, '2026-03-27 20:07:49');
INSERT INTO `document_chunk` VALUES (321, 6, 2, 117, '\n\n\n\n21\n\n12\n\nmm\n\nm\n\n\n\n\n\n学员专用 请勿外泄 \n\n \n\n64 中公教育学员专用资料 报名专线：400-6300-999 \n\n第二章 电磁学 \n\n第一节 静电场 \n\n \n\n一、电荷及其起电方式 \n\n1.两种电荷： \n\n（1）自然界中只存在两种电荷 \n\n正电荷：与丝绸摩擦过的玻璃棒所带的电荷 \n\n负电荷：与毛皮摩擦过的橡胶棒所带的电荷 \n\n（2）电荷间的相互作用规律：同种电荷互相排斥，异种电荷互相吸引。 \n\n2.元电荷：人们把最小的电荷量叫元电荷。 C 10×1.6 -19e \n\n电子、正电子和质子所带的电荷量都是元电荷。任何带电体所带电荷量均为元电荷 e 的整数倍。 \n\n3.起电的三种方式： \n\n（1）摩擦起电:用摩擦的方法使两个不同的物体带电的现象。 \n\n本质：电子的转移。 \n\n（2）感应起电：指利用静电感应使金属导体带电的方式。 \n\n本质：电荷的重新分配。 \n\n（3）接触起电：接触起电指一个不带电的金属导体跟另一个带电的金属导体接触后分开，而使不\n\n带电的导体带上电荷的方式。 \n\n本质：电荷的转移。', 471, 471, 1, '90775ae8-ecab-49f0-bbfe-d0490d9f610a', NULL, '2026-03-27 20:07:49');
INSERT INTO `document_chunk` VALUES (322, 6, 2, 118, '本质：电荷的重新分配。 \n\n（3）接触起电：接触起电指一个不带电的金属导体跟另一个带电的金属导体接触后分开，而使不\n\n带电的导体带上电荷的方式。 \n\n本质：电荷的转移。 \n\n \n\n接触起电的电荷量平分问题：先中和、再平分。 \n\n ①完全相同的两个金属球分别带有同种电荷，电荷量分别为 Q1和 Q2，接触后两球带\n\n的电荷量相等， \n\n2\n\n21\n21\n\nQQ\nQQ\n\n\n \n\n ②完全相同的两个带异种电荷的金属球，电荷量分别为为 Q1 和-Q2，接触后两球带\n\n的电荷量相等， \n\n2\n\n21\n21\n\nQQ\nQQ\n\n\n 。（带异种电荷的物体接触，电荷量先中和后平分。） \n\n \n\n\n\n学员专用 请勿外泄 \n\n \n\n65 中公教育学员专用资料 报名专线：400-6300-999 \n\n4.电荷守恒定律：电荷既不会创生，也不会消灭，它只能从一个物体转移到另一个物体，或者从\n\n物体的一部分转移到另一部分；在转移的过程中，电荷的总量保持不变。 \n\n例 1.如图所示为一带正电荷的物体 M 靠近一不带电的金属导体 N，N 的左边感应出负电荷，若将\n\nN 的左端接地，则（ ）。', 494, 494, 1, '98d8794c-4d7b-4572-bffa-bfb82963c041', NULL, '2026-03-27 20:07:49');
INSERT INTO `document_chunk` VALUES (323, 6, 2, 119, '例 1.如图所示为一带正电荷的物体 M 靠近一不带电的金属导体 N，N 的左边感应出负电荷，若将\n\nN 的左端接地，则（ ）。 \n\n \n\n \n\nA.N 上的正电荷流入地 B.N 上的负电荷流入地 \n\nC.N 上的所有电荷都流入地 D.N 上的所有电荷都不动 \n\n二、库仑定律 \n\n1.内容：真空中两个静止点电荷之间的相互作用力，与它们的电荷量的乘积成正比，与它们的距\n\n离的二次方成反比，作用力的方向在它们的连线上。 \n\n2.公式：\n2\n\n21\n\nr\n\nQQ\nkF  ，其中 229 /m100.9 Ck  \n\n3.适用条件：真空中点电荷。 \n\n4.三个自由点电荷静电平衡规律：三个点电荷在同一直线上，位于中间的点电荷带电量最小，且\n\n与两侧电荷异号，并靠近两侧电荷中电量较小的那一个。概括为：三点共线，两同夹异，两大夹小，\n\n近小远大。 \n\n例 2.如图，在 A、B 两点放置两个点电荷，它们的带电量分别为 q1、q2，MN 是过 A、B 的直线，\n\nP 是直线上的一点，若 P 点的场强为 0，则（ ）。', 459, 459, 1, 'ec773775-3fce-4ce7-ad5b-9ca317447984', NULL, '2026-03-27 20:07:49');
INSERT INTO `document_chunk` VALUES (324, 6, 2, 120, '例 2.如图，在 A、B 两点放置两个点电荷，它们的带电量分别为 q1、q2，MN 是过 A、B 的直线，\n\nP 是直线上的一点，若 P 点的场强为 0，则（ ）。 \n\n \n\nA.q1、q2都为正，且 q1>q2 B.q1为正，q2为负，且 q1<|q2| \n\nC.q1为负，q2为正，且|q1|>q2 D.q1、q2都为负，且|q1|<|q2| \n\n三、电场强度、电场线 \n\n1.电场：带电体周围存在的一种物质，是电荷间相互作用的媒介。电场是客观存在的，电场具有\n\n力的性质和能的性质。 \n\n电场的基本性质：对放入其中的电荷有力的作用。 \n\n2.电场强度：放入电场中某一点电荷受到的电场力跟它的电荷量的比值，叫做这一点的电场强度。\n\n电场强度是描述电场力的性质的物理量。 \n\n\n\n学员专用 请勿外泄 \n\n \n\n66 中公教育学员专用资料 报名专线：400-6300-999 \n\n定义式：\nq\n\nF\nE  （适用于任何电场）（定义式） \n\n电场强度的方向： \n\n①电场强度的方向与正电荷在该点的所受静电力的方向相同，与负电荷在该点的所受静电力的方\n\n向相反。', 480, 480, 1, '2cbb0ad6-e38a-408d-9704-922cd833d5bb', NULL, '2026-03-27 20:07:49');
INSERT INTO `document_chunk` VALUES (325, 6, 2, 121, '-999 \n\n定义式：\nq\n\nF\nE  （适用于任何电场）（定义式） \n\n电场强度的方向： \n\n①电场强度的方向与正电荷在该点的所受静电力的方向相同，与负电荷在该点的所受静电力的方\n\n向相反。 \n\n②从正电荷出发到负电荷终止。 \n\n电场强度的大小和方向由电场本身性质决定，与试探电荷无关。 \n\n在真空中点电荷 Q 产生的电场中，距离点电荷 r 处的场强\n2r\n\nkQ\nE  （决定式）。\n\n \n\n3.匀强电场：在电场中，如果各点的场强的大小和方向都相同，这样的电场叫匀强电场。匀强电\n\n场中的电场线是间距相等且互相平行的直线。 \n\n匀强电场电场强度的大小：\nd\n\nU\nE  （关系式），式中的 d 为两点在电场强度方向上的距离。\n\n \n\n4.电场线：在电场中画出一系列的从正电荷出发到负电荷终止的曲线，使曲线上每一点的切线方\n\n向都跟该点的场强方向一致，这些曲线叫做电场线。 \n\n电场线的性质： \n\n①电场线是始于正电荷（或无穷远处），终于负电荷（或无穷远处）； \n\n②电场线的疏密反映电场的强弱，切线方向表示电场强度的方向； \n\n③电场线不相交，不闭合； \n\n④电场线不是真实存在的；', 496, 496, 1, 'd644b9a0-93ea-439f-b0eb-7d25721fa05c', NULL, '2026-03-27 20:07:49');
INSERT INTO `document_chunk` VALUES (326, 6, 2, 122, '： \n\n①电场线是始于正电荷（或无穷远处），终于负电荷（或无穷远处）； \n\n②电场线的疏密反映电场的强弱，切线方向表示电场强度的方向； \n\n③电场线不相交，不闭合； \n\n④电场线不是真实存在的； \n\n⑤电场线不一定是电荷运动的轨迹。 \n\n例 3.图中是负电荷沿电场线从 A 运动到 B 的 v-t 图，符合实际情况的电场分布是（） \n\n \n\n \n\n5.几种典型的电场线 \n\n（1）点电荷周围的电场线的分布 \n\n\n\n学员专用 请勿外泄 \n\n \n\n67 中公教育学员专用资料 报名专线：400-6300-999 \n\n \n\n正电荷负电荷 \n\n特点： \n\n①离点电荷越近，电场线越密集，场强越大。方向由正点电荷指向无穷远，或由无穷远指向负点\n\n电荷。 \n\n②在正（负）点电荷的点电荷形成的电场中，不存在场强相同的点。 \n\n（2）等量同种电荷电场线分布 \n\n \n特点： \n\n①连线中点处 O 处的场强为零，向两侧逐渐变大。关于 O 对称的 A、B 两点场强等大反向。 \n\n②沿连线的中垂线由 O 点向外场强大小：O 点最小，向外先变大后变小。关于 O 对称的 C、D 两\n\n点场强等大反向。', 490, 490, 1, '17bcf57d-0e31-4706-8519-8bf2e1ddf2fa', NULL, '2026-03-27 20:07:50');
INSERT INTO `document_chunk` VALUES (327, 6, 2, 123, '关于 O 对称的 A、B 两点场强等大反向。 \n\n②沿连线的中垂线由 O 点向外场强大小：O 点最小，向外先变大后变小。关于 O 对称的 C、D 两\n\n点场强等大反向。 \n\n（3）等量异种电荷电场线分布 \n\n \n\n特点： \n\n①连线上点 O 处的场强最小，向两侧逐渐变大。关于 O 对称的 A、B 两点场强等大同向。 \n\n②沿连线的中垂线由 O 点向外场强大小：O 点最大，向外逐渐减小。关于 O 对称的 C、D 两点场\n\n强等大同向。 \n\n例 4.如图所示为电荷量为+Q 的小球放在不带电的孤立金属球附近，形成的电场线分布，a、b 为\n\n电场中的两点，下列说法错误的是（ ）。 \n\n\n\n学员专用 请勿外泄 \n\n \n\n68 中公教育学员专用资料 报名专线：400-6300-999 \n\n \n\nA.a 点的电场强度比 b 点的大 \n\nB.a 点的电势比 b 点的高 \n\nC.点电荷-q 在 a 点的电势能比在 b 点的大 \n\nD.点电荷-q 从 a 点移到 b 点的过程中，电场力做负功 \n\n四、电势能、电势 \n\n1.静电力做功的特点：静电力做功与路径无关，与初末位置有关。', 486, 486, 1, 'f0f007bd-3002-42ef-a66f-0be9856f2e2a', NULL, '2026-03-27 20:07:50');
INSERT INTO `document_chunk` VALUES (328, 6, 2, 124, '-q 在 a 点的电势能比在 b 点的大 \n\nD.点电荷-q 从 a 点移到 b 点的过程中，电场力做负功 \n\n四、电势能、电势 \n\n1.静电力做功的特点：静电力做功与路径无关，与初末位置有关。 \n\n2.电势能：电荷在电场中所具有的势能。 \n\n静电力做功与电势能变化的关系：静电力做正功，电势能减少，减少的电势能等于静电力所做的\n\n功；静电力做负功，电势能增加，增加的电势能等于克服静电力所做的功。表达式： PBPAAB EEW  \n\n3.电势 ：电荷在电场中某一点的电势能与它的电荷量的比值叫做这一点的电势。 \n\n（1）定义式：\nq\n\nE p\n （计算时需要带正、负号） \n\n（2）单位：伏特（V） \n\n（3）电势是标量，“+”“-”表示大小 \n\n（4）电势是个相对量，某点的电势与零电势点的选取有关（通常取离电场无穷远处或大地的电势\n\n为零电势）。因此，电势有正、负，电势的正负表示该点电势比零电势点高还是低。 \n\n（5）电势高低的判断：沿着电场线的方向，电势越来越低。', 442, 442, 1, '5fe46b13-810b-4148-88db-d89eae40e5ff', NULL, '2026-03-27 20:07:50');
INSERT INTO `document_chunk` VALUES (329, 6, 2, 125, '因此，电势有正、负，电势的正负表示该点电势比零电势点高还是低。 \n\n（5）电势高低的判断：沿着电场线的方向，电势越来越低。 \n\n \n\n4.电势差 U（电压）：电场中两点间电势的差值叫做电势差。即： BAABU   。电荷在电场中\n\n由一点 A 移动到另一点 B 时，电场力所做的功 ABW 与电荷量 q 的比值\nq\n\nWAB ，也等于 AB 两点间的电\n\n势差。 \n\n电势能的大小的判断方法： \n\n（1）根据电场力做功：电场力做正功，电势能减小；电场力做负功，电势能增加。 \n\n（2）根据公式\nq\n\nE p\n 判断，对于正电荷，则电势越大的地方，电势能越大；对于负电荷，\n\n电势越大的地方，电势能越小。\n\n \n\n\n\n学员专用 请勿外泄 \n\n \n\n69 中公教育学员专用资料 报名专线：400-6300-999 \n\n公式：\nq\n\nW\nU AB\n\nAB  \n\n5.等势面：电场中电势相等的点构成的面叫做等势面。 \n\n（1）等势面上各点电势相等，在等势面上移动电荷电场力不做功。 \n\n（2）等势面一定跟电场线垂直，而且电场线总是由电势高的等势面指向电势低的等势面。', 486, 486, 1, 'ae55981a-d7d0-4c29-94be-f60c8109eff5', NULL, '2026-03-27 20:07:50');
INSERT INTO `document_chunk` VALUES (330, 6, 2, 126, '（1）等势面上各点电势相等，在等势面上移动电荷电场力不做功。 \n\n（2）等势面一定跟电场线垂直，而且电场线总是由电势高的等势面指向电势低的等势面。 \n\n（3）画等势面（线）时，一般取相邻两等势面（线）间的电势差相等。这样，在等势面（线）密\n\n集处场强大，等势面（线）疏处场强小。 \n\n \n\n五、电容器的电容 \n\n1.电容器：任何两个彼此绝缘而又相互靠近的导体都可以看成一个电容器。 \n\n平行板电容器带电时，两极板带等量异种电荷，电容器所带的电量是一个极板所带电量的绝对值。\n\n电容器带电后，两极板间就有电势差。 \n\n2.电容：电容器容纳电荷本领的物理量。 \n\n（1）定义：电容器的带电量跟它的两板间的电势差的比值 \n\n（2）定义式：\nU\n\nQ\nC  ；决定式：\n\nkd\n\nS\nC\n\n\n\n\n\n4\n ； \n\n（3）单位：法拉（F），1F=106μF \n\n3.电容器动态分析问题 \n\n（1）电容改变的几种情况 \n\n①改变正对面积②改变板间距离③改变电介质（插入电介质时， 增大；拔出电介质时， 减小）\n\n④插入金属板相当于减小板间距离。 \n\n（2）电容器两类问题', 484, 484, 1, '045f8ede-c7dd-476f-8a84-d39927312a01', NULL, '2026-03-27 20:07:50');
INSERT INTO `document_chunk` VALUES (331, 6, 2, 127, '（2）电容器两类问题 \n\n U Q C E \n\n电容器始终与电源两极保持\n\n连接 \n\n不变 根据\nU\n\nQ\nC  根据\n\nkd\n\nS\nC\n\n\n\n\n\n4\n 根据\n\nd\n\nU\nE  \n\n典型的电场中等势线： \n\n \n\n图一为点电荷周围等势线分布，因为画等势线时，取相邻两等势面（线）间的电势差\n\n相等，根据\nd\n\nU\nE  ，定性分析可知，当U 一定时，E越大的地方，d越小。 \n\n注意区分图二和图三，分别为等量异号点电荷周围等势线的分布和等量同号点电荷周\n\n围等势线的分布。 \n\n \n\n\n\n学员专用 请勿外泄 \n\n \n\n70 中公教育学员专用资料 报名专线：400-6300-999 \n\n电容器充电后与电源断开 \n根据\n\nU\n\nQ\nC  \n\n不变 \n根据\n\nkd\n\nS\nC\n\n\n\n\n\n4\n 根据\n\nS\n\nkQ\nE\n\n\n\n4\n \n\n例 5.图 2 所示为一种电容式键盘的按键，它由键帽，弹簧和平行板电容器构成，电容器板间距为\n\nd，电容为 C。按键时，活动极板向下移动。若电容的改变量为 C/2，则按键下面的距离为（ ）。', 472, 472, 1, 'c66cda81-3f92-42f1-a149-6c1f5c244187', NULL, '2026-03-27 20:07:50');
INSERT INTO `document_chunk` VALUES (332, 6, 2, 128, '按键时，活动极板向下移动。若电容的改变量为 C/2，则按键下面的距离为（ ）。 \n\n \n\nA.d/4 B.d/3 C.d/2 D. 2d/3 \n\n4.电容器的串并联 \n\n两个电容器串联两个电容器并联 21 CCC 并 六、带电粒子在电场中运动 \n\n1.带电粒子在电场中加速 \n\n带电粒子在电场中加速，若不计粒子的重力，则电场力对带电粒子所做的功等于带电粒子动能的\n\n增量，即\n2\n\n0\n\n2\n\n2\n\n1\n\n2\n\n1\nmvmvqU  \n\n \n\n（2）带电粒子在电场中的偏转 \n\n \n\n带电粒子以垂直匀强电场的电场方向进入电场后，做类平抛运动。 \n\n垂直于场强方向做匀速直线运动： 0vvx  ， tvL 0 \n\n\n\n学员专用 请勿外泄 \n\n \n\n71 中公教育学员专用资料 报名专线：400-6300-999 \n\n平行于场强方向做初速度为零的匀加速直线运动：\nm\n\nqE\na  ；\n\nd\n\nU\nE  \n\n侧向位移公式为：\n2\n\n0\n\n2\n2\n\n22\n\n1\n\nmdv\n\nqUl\naty  \n\n偏向角的正切值公式为：\nl\n\ny\n\nmdv\n\nqUl\n\nv\n\nv y 2\ntan\n\n2', 497, 497, 1, '169899e1-2607-4aa7-b534-d536880e2d46', NULL, '2026-03-27 20:07:51');
INSERT INTO `document_chunk` VALUES (333, 6, 2, 129, 'U\nE  \n\n侧向位移公式为：\n2\n\n0\n\n2\n2\n\n22\n\n1\n\nmdv\n\nqUl\naty  \n\n偏向角的正切值公式为：\nl\n\ny\n\nmdv\n\nqUl\n\nv\n\nv y 2\ntan\n\n2\n\n00\n\n \n\n \n\n\n\n学员专用 请勿外泄 \n\n \n\n72 中公教育学员专用资料 报名专线：400-6300-999 \n\n第二节 恒定电流 \n\n \n\n一、电流 \n\n1.定义：通过导体横截面积的电量跟通过这些电量所用的时间的比值，\nt\n\nQ\nI  。 \n\n（1）如果是正负离子同时定向移动，Q 应为正负离子的电荷量和 \n\n（2）在金属导体中，电流的微观表达式为 neSvI  ，n 为单位体积内的自由电子个数，S 为导体\n\n的横截面积，v 为自由电荷定向移动的平均速率，e 是自由电荷量。 \n\n2.在国际单位制中电流的单位是安。1mA=10-3A，1μA=10-6 A \n\n3.电流方向：规定正电荷移动的方向为电流的方向，与负电荷定向移动的方向相反 \n\n \n\n二、电阻定律 \n\n1.内容：在温度不变时，导体的电阻 R 与它的长度 l 成正比，与它的横截面积 S 成反比。', 488, 488, 1, 'fafb3035-94b8-4179-af5e-ed416a87d687', NULL, '2026-03-27 20:07:51');
INSERT INTO `document_chunk` VALUES (334, 6, 2, 130, '.电流方向：规定正电荷移动的方向为电流的方向，与负电荷定向移动的方向相反 \n\n \n\n二、电阻定律 \n\n1.内容：在温度不变时，导体的电阻 R 与它的长度 l 成正比，与它的横截面积 S 成反比。 \n\n2.公式：\nS\n\nl\nR  （决定式） \n\n3.适用条件：粗细均匀的导线、浓度均匀的电解质 \n\n \n\n例 1.两根材料相同的均匀导线 x 和 y 串联在电路中，两导线沿长度方向的电势变化情况分别如图\n\n中的 ab 段和 bc 段图线所示，则导线 x 和 y 的横截面积之比为（ ） \n\n小资料： \n\n电阻率：反应了材料对于电流的阻碍作用，是材料本身的属性 \n\n（1）有些材料的电阻率随温度升高而增大（如金属）；有些材料的电阻率随着温度\n\n升高而降低（如半导体和绝缘体）；有些材料的电阻率几乎不变不受温度的影响（如锰\n\n铜和康铜） \n\n（2）半导体：导电性能介于导体绝缘体之间，而且电阻随着温度的增加而减小，\n\n这种材料称之为半导体，半导体有热敏特性（电阻率随温度升高而减小），光敏特性（电\n\n阻率随光照强度增大而减小）', 461, 461, 1, 'de9d4514-03e5-4431-a8f9-81a608a1f4ed', NULL, '2026-03-27 20:07:51');
INSERT INTO `document_chunk` VALUES (335, 6, 2, 131, '铜） \n\n（2）半导体：导电性能介于导体绝缘体之间，而且电阻随着温度的增加而减小，\n\n这种材料称之为半导体，半导体有热敏特性（电阻率随温度升高而减小），光敏特性（电\n\n阻率随光照强度增大而减小） \n\n（3）超导现象：当温度降低到绝对零度附近时，某些材料的电阻率突然减小到零，\n\n这种现象叫做超导现象，处于这种状态下的物体叫做超导体。 \n\n注：在外电路中电流由高电势点流向低电势，电源内部电流从低电势流向高电势 \n\n\n\n学员专用 请勿外泄 \n\n \n\n73 中公教育学员专用资料 报名专线：400-6300-999 \n\n \n\nA.2∶1 B.1∶2 C.6∶1 D.1∶6 \n\n三、部分电路欧姆定律 \n\n1.内容：导体中电流与导体两端电压成正比，跟导体电阻成反比。 \n\n2.公式： ； \n\n3.适用范围：纯电阻电路（电能全部转化为内能的电路） \n\n4.金属的伏安特性曲线（不考虑温度变化） \n\n \n\n四、电功、电功率、焦耳定律 \n\n1.电功：电流做功的实质是电场力对电荷做功，电功普遍适用公式： UItqUW  \n\n电功率：单位时间电流做的功， UItWP  /', 483, 483, 1, '08f5e867-1ac0-4f5f-965a-080973578064', NULL, '2026-03-27 20:07:51');
INSERT INTO `document_chunk` VALUES (336, 6, 2, 132, '虑温度变化） \n\n \n\n四、电功、电功率、焦耳定律 \n\n1.电功：电流做功的实质是电场力对电荷做功，电功普遍适用公式： UItqUW  \n\n电功率：单位时间电流做的功， UItWP  / \n\n2.焦耳定律： t2RIQ  ，式中 Q 中表示电流通过导体产生的热量，焦耳定律无论是对纯电阻还是\n\n非纯电阻电路都是使用的。 \n\n3.电功与电热的关系 \n\n 纯电阻电路 非纯电阻电路 \n\n实例 \n白炽灯、电炉、电饭锅、电热毯、\n\n电熨斗及转子被卡住的电动机等 \n电动机、电解槽、日光灯等 \n\n电功与电热 QWRtIQUItW  ,, 2\n \n\n电功率与热\n\n功率 \n 热电热电 PPRIPUIP  ,, 2\n\n \n\n五、串、并联电路规律 \n\n 串联电路 并联电路 \n\nU\nI\n\nR\n\n\n2\n2, ,\n\nU\nW UIt Q I Rt t W Q\n\nR\n   \n\n2\n2= = ,\n\nU\nP UI P I R P P\n\nR\n 电 热 电 热，\n\n\n\n学员专用 请勿外泄 \n\n \n\n74 中公教育学员专用资料 报名专线：400-6300-999', 484, 484, 1, '28ff708e-3faf-4854-b139-07ed8588c3b4', NULL, '2026-03-27 20:07:51');
INSERT INTO `document_chunk` VALUES (337, 6, 2, 133, ' \n\n2\n2= = ,\n\nU\nP UI P I R P P\n\nR\n 电 热 电 热，\n\n\n\n学员专用 请勿外泄 \n\n \n\n74 中公教育学员专用资料 报名专线：400-6300-999 \n\n电流 各处电流相等 电流分配和电阻成反比 \n\n电压 电压分配和电阻成正比 各支路两端电压相等 \n\n电阻 总电阻等于各电阻之和 总电阻的倒数等于各电阻倒数之和 \n\n功率分配 功率分配和电阻成正比 功率分配和电阻成反比 \n\n六、闭合电路的欧姆定律 \n\n1.内容：在外电路为纯电阻的闭合电路中，电流的大小跟电源的电动势成正比，跟内、外电路的\n\n电阻之和成反比。 \n\n2.表达式：① \nE\n\nI\nR r\n\n\n\n\n（纯电阻电路）②E U Ir 外 （所有电路）③ R\nrR\n\nE\nU\n\n\n \n\n3.路端电压随电流变化关系 \n\n用图像表示：U E Ir  \n\n \n\n当外电路断路时：(即R， 0I  )，纵轴上的截距表示电源的电动势E (E U 端 ) \n\n当外电路短路时：( 0 0R U ， )，横坐标的截距表示电源的短路电流\nE\n\nI\nr\n\n短 ；', 485, 485, 1, 'f766fe65-ab67-428f-85ac-054875cb3365', NULL, '2026-03-27 20:07:51');
INSERT INTO `document_chunk` VALUES (338, 6, 2, 134, '断路时：(即R， 0I  )，纵轴上的截距表示电源的电动势E (E U 端 ) \n\n当外电路短路时：( 0 0R U ， )，横坐标的截距表示电源的短路电流\nE\n\nI\nr\n\n短 ； \n\n图线的斜率：斜率的绝对值为电源的内电阻. \n\n某点纵坐标和横坐标值的乘积：为电源的输出功率，在图中的那块矩形的“面积”表示电源的输\n\n出功率 \n\n七、动态电路分析 \n\n1.程序法： \n\n\n\n学员专用 请勿外泄 \n\n \n\n75 中公教育学员专用资料 报名专线：400-6300-999 \n\n \n\n2.“串反并同”结论法： \n\n①所谓“串反”，即某一电阻增大时，与它串联或间接串联的电路中的电流、两端电压、电功率\n\n都将减小。 \n\n②所谓“并同”，即某一电阻增大时，与它并联或间接并联的电阻中的电流、两端电压、电功率\n\n都将增大。 \n\n例 2.在如图所示的电路中，E 为电源电动势，r 为电源内阻，R1和 R3均为定值电阻，R2为滑动变\n\n阻器。当 R2的滑动触点在 a 端时合上开关 S，此时三个电表 A、A2.V 的示数分别为 I1，I2，U，现将', 474, 474, 1, '1f641c09-8cda-408e-9e9f-6cb12b89673a', NULL, '2026-03-27 20:07:52');
INSERT INTO `document_chunk` VALUES (339, 6, 2, 135, '当 R2的滑动触点在 a 端时合上开关 S，此时三个电表 A、A2.V 的示数分别为 I1，I2，U，现将\n\nR2的滑动触点向 b 端移动，则三个电表的示数变化情况是（ ）。 \n\n \n\nA.I1增大，I2不变，V 增大 \n\nB.I1减小，I2增大，V 减小 \n\nC.I1增大，I2减小，V 增大 \n\nD.I1减小，I2不变，V 增大 \n\n八、含电容器电路的分析方法 \n\n1.确定电容器和哪个电阻并联，该电阻两端电压即为电容器两端电压。 \n\n2.当电容器和某一电阻串联后接在某一电路两端时，此电路两端电压即为电容器两端电压。 \n\n3.当电容器与电源直接相连，则电容器两极板间电压即等于电源电动势大小。 \n\n4.对于较复杂电路，需要将电容器两端的电势与基准点的电势比较后才能确定电容器两端的电压，\n\n并根据电势判断极板带电性质；若电路电压变化，还要判断电压是升高还是降低，从而确定电流的方\n\n向。 \n\n例 3.如图所示的电路中，电源电压 U＝5 V，定值电阻 R1＝3Ω，R2＝2Ω，R3＝2Ω，电路稳定后\n\n电容器两端的电压为多少？ \n\n\n\n学员专用 请勿外泄', 479, 479, 1, '3aac1b65-0f79-491c-ba13-0b9c675fe45a', NULL, '2026-03-27 20:07:52');
INSERT INTO `document_chunk` VALUES (340, 6, 2, 136, '例 3.如图所示的电路中，电源电压 U＝5 V，定值电阻 R1＝3Ω，R2＝2Ω，R3＝2Ω，电路稳定后\n\n电容器两端的电压为多少？ \n\n\n\n学员专用 请勿外泄 \n\n \n\n76 中公教育学员专用资料 报名专线：400-6300-999 \n\n \n\n九、电源的功率和效率问题 \n\n1.电源的总功率： \n\n①任意电路：P EI总 。 \n\n②纯电阻电路：\n2\n\n2 E\nP I R r\n\nR r\n  \n\n\n总 （ ） 。 \n\n2.电源内部消耗的功率：\n2P I r内 \n\n3.电源的输出功率： \n\n①任意电路：\n2- -P UI EI I r P P  出 总 内 \n\n②纯电阻电路：\n\n2 2\n2\n\n22\n\nE R\nP =I R=\n\n( )R\n4\n\nE\n\nR r\nr\n\nR\n\n\n\n\n\n出\n\n（ +r） \n\n输出功率随 R的变化关系： \n\n \n\n①当R r 时，电源的输出功率最大，为\n2\n\n4\nm\n\nE\nP\n\nr\n ； \n\n②当R r 时，随着 R 的增大输出功率越来越小； \n\n③当R r 时，随着 R 的增大输出功率越来越大； \n\n4.电源的效率：', 489, 489, 1, 'f67cef99-a55c-4b8d-bc19-2db0acb18da8', NULL, '2026-03-27 20:07:52');
INSERT INTO `document_chunk` VALUES (341, 6, 2, 137, '的输出功率最大，为\n2\n\n4\nm\n\nE\nP\n\nr\n ； \n\n②当R r 时，随着 R 的增大输出功率越来越小； \n\n③当R r 时，随着 R 的增大输出功率越来越大； \n\n4.电源的效率： \n\n①任意电路： 100% 100%\nP U\n\nP E\n    出\n\n总\n\n。 \n\n②纯电阻电路：\n\n1\n100% 100%\n\n1\n\nR\n\nrR r\n\nR\n\n    \n\n\n\n。 \n\n在纯电阻电路中 R 越大，越大；当R r 时，电源有最大输出功率，电源的效率仅为 50%。 \n\n例 4.如图所示的 U～I 图线中，I 是电源的路端电压随电流变化的图线，Ⅱ是某电阻两端的电压随\n\n电流变化的图线，用该电源向该电阻供电时电阻上消耗的功率和电源的电动势（ ）。 \n\n\n\n学员专用 请勿外泄 \n\n \n\n77 中公教育学员专用资料 报名专线：400-6300-999 \n\n \n\nA.4W 和 2V B.2W 和 3V C.2W 和 2V D.4W 和 3V \n\n十、伏安法测电阻 \n\n1.电流表的两种接法 \n\n①电流表接在电压表两接线柱的内侧，通常叫“内接法”。', 488, 488, 1, 'aa071bd9-65ee-45e4-8ffd-0e5d034973eb', NULL, '2026-03-27 20:07:52');
INSERT INTO `document_chunk` VALUES (342, 6, 2, 138, 'A.4W 和 2V B.2W 和 3V C.2W 和 2V D.4W 和 3V \n\n十、伏安法测电阻 \n\n1.电流表的两种接法 \n\n①电流表接在电压表两接线柱的内侧，通常叫“内接法”。 \n\n \n\n测量值偏大。内接法的误差来源：电流变有分压作用，分压越少，误差越小，所以该电路适合测\n\n大电阻。即 x AU U U 测 ， x A x\n\nU\nR R R R\n\nI\n   测\n\n测\n\n测\n\n（测量值大于真实值）。 \n\n②电流表接在电压表两接线柱的外侧，通常叫“外接法”。 \n\n \n\n测量值偏小。外接法的误差来源：电压表有分流作用，分流越小，误差越小，所以该电路适合测\n\n量小电阻。即 x VI I I 测 ，\nx V\n\nx\n\nx V\n\nU R R\nR R\n\nI R R\n  \n\n\n\n测\n测\n\n测\n\n（测量值小于真实值）。 \n\n \n\n例 5.如图所示，电压表和电流表的读数分别为 10V 和 0.1A，电流表的内阻为 0.2Ω，那么有关待\n\n测电阻 Rx的说法正确的是（ ） \n\n大内偏大（大电阻用内接法测量，测量值偏大）；小外偏小（小电阻用外接法测量，测量值偏\n\n小）；', 495, 495, 1, 'ebabb202-5aaf-43e3-808c-162916d29a46', NULL, '2026-03-27 20:07:52');
INSERT INTO `document_chunk` VALUES (343, 6, 2, 139, '10V 和 0.1A，电流表的内阻为 0.2Ω，那么有关待\n\n测电阻 Rx的说法正确的是（ ） \n\n大内偏大（大电阻用内接法测量，测量值偏大）；小外偏小（小电阻用外接法测量，测量值偏\n\n小）； \n\n两种电路的选择。 \n\n①阻值的比较法：若 xv RR  ，宜采用电流表外接法；若 xA RR  ，宜采用电流表内接法。 \n\n②临界值计算法： x V AR R R 时，用电流表外接法； 时，用电流表内接法。 \n\n \n\nx V AR R R\n\n\n\n学员专用 请勿外泄 \n\n \n\n78 中公教育学员专用资料 报名专线：400-6300-999 \n\n \n\nA. Rx的测量值比真实值小 \n\nB. Rx的真实值为 100Ω \n\nC. Rx的真实值为 100.2Ω \n\nD. Rx的真实值为 99.8Ω \n\nRxRx2.滑动变阻器的两种接法 \n\n①限流法 \n\n \n\n适用于测量阻值较小的电阻，用限流接法。 \n\n②分压法 \n\n \n\n适用于测量阻值较大的电阻。 \n\n三种情况下必须使用分压法：①要求电压从零开始调节，或要求电压调节范围尽量大时应该用分', 473, 473, 1, '9bb76b7f-f1bf-45ef-8e72-6cea055e7b86', NULL, '2026-03-27 20:07:52');
INSERT INTO `document_chunk` VALUES (344, 6, 2, 140, '②分压法 \n\n \n\n适用于测量阻值较大的电阻。 \n\n三种情况下必须使用分压法：①要求电压从零开始调节，或要求电压调节范围尽量大时应该用分\n\n压接法；②滑动变阻器的最大阻值远小于待测电阻的阻值时；③实验仪器的最大允许电流、电压不够\n\n时。 \n\n \n\n\n\n学员专用 请勿外泄 \n\n \n\n79 中公教育学员专用资料 报名专线：400-6300-999 \n\n第三节 磁场 \n\n \n\n一、磁场 \n\n1.磁场：磁场是存在于磁体、电流和运动电荷周围的一种物质。永磁体和电流都能在空间产生磁\n\n场，变化的电场也能产生磁场。 \n\n2.磁场的方向：规定在磁场中任一点小磁针 N 极受力的方向（或者小磁针静止时 N 极的指向）就\n\n是那一点的磁场方向；与 S 极的受力方向相反。 \n\n3.磁场的基本特点：磁场对处于其中的磁体、电流和运动电荷有力的作用。 \n\n4.地磁场：地球的磁场与条形磁体的磁场相似，地磁场的 N 极在地球南极附近，S 极在地球北极\n\n附近。 \n\n \n\n \n\n二、磁感线 \n\n1.在磁场中人为地画出一系列曲线，曲线的切线方向表示该位置的磁场方向，曲线的疏密能定性', 479, 479, 1, 'a26cc809-7d48-4bce-9877-49c5ad7d9d19', NULL, '2026-03-27 20:07:53');
INSERT INTO `document_chunk` VALUES (345, 6, 2, 141, '二、磁感线 \n\n1.在磁场中人为地画出一系列曲线，曲线的切线方向表示该位置的磁场方向，曲线的疏密能定性\n\n地表示磁场的强弱，这一系列曲线称为磁感线。 \n\n2.磁铁外部的磁感线，都从磁铁 N 极出来，进入 S 极；在内部，由 S 极到 N 极，磁感线是闭合曲\n\n线，磁感线不相交。 \n\n补充： \n\n1.在赤道平面上，距离地球表面相等的各点，磁感应强度相等，且方向水平向北。 \n\n2.地磁场的水平分量总是从地球南极指向北极，而竖直分量则南北相反，在南半球垂直于\n\n地面向上，在北半球垂直于地面向下。 \n\n \n\n注意：地磁场的 N 极和地球的南极以及地磁场的 S 极和地球的北极不完全重合。 \n\n\n\n学员专用 请勿外泄 \n\n \n\n80 中公教育学员专用资料 报名专线：400-6300-999 \n\n \n\n3.几种典型磁场的磁感线的分布 \n\n①直线电流的磁场：同心圆、非匀强、距导线越远处磁场越弱。 \n\n \n\n②通电螺线管的磁场：两端分别是 N极和 S极，管内可看作匀强磁场，管外是非匀强磁场。 \n\n \n\n③环形电流的磁场：两侧是 N极和 S极，离圆环中心越远，磁场越弱。', 482, 482, 1, 'bdfc4d81-9c28-4011-8df5-a72919732c3d', NULL, '2026-03-27 20:07:53');
INSERT INTO `document_chunk` VALUES (346, 6, 2, 142, '②通电螺线管的磁场：两端分别是 N极和 S极，管内可看作匀强磁场，管外是非匀强磁场。 \n\n \n\n③环形电流的磁场：两侧是 N极和 S极，离圆环中心越远，磁场越弱。 \n\n \n\n④匀强磁场：磁感应强度的大小处处相等、方向处处相同，匀强磁场中的磁感线是分布均匀、方\n\n向相同的平行直线。 \n\n三、磁感应强度 \n\n1.定义：磁感应强度是表示磁场强弱的物理量。 \n\n2.大小：在磁场中垂直于磁场方向的通电导线，受到的磁场力 F 跟电流 I 和导线长度 L 的乘积 IL\n\n的比值，叫做通电导线所在处的磁感应强度，定义式 B=F/IL，单位 T（特斯拉），1T=1N/（A•m）。 \n\n3.方向：磁感应强度是矢量，磁场中某点的磁感应强度的方向就是该点的磁场方向，即通过该点\n\n的磁感线的切线方向，小磁针静止时 N 极所指的方向。 \n\n例 1.有 a、b、c、d 四个小磁针，分别放置在通电螺线管的附近和内部，如图所示.其中哪一个小\n\n磁针的指向是正确的（ ）。 \n\n注意：小磁针在磁铁内部 N 极指向磁铁的 N 极，而非 S 极。 \n\n\n\n学员专用 请勿外泄', 473, 473, 1, '5ab44669-07ae-4343-8e71-e69f88826acd', NULL, '2026-03-27 20:07:53');
INSERT INTO `document_chunk` VALUES (347, 6, 2, 143, '注意：小磁针在磁铁内部 N 极指向磁铁的 N 极，而非 S 极。 \n\n\n\n学员专用 请勿外泄 \n\n \n\n81 中公教育学员专用资料 报名专线：400-6300-999 \n\n \n\nA.a B.b C.c D.d \n\n四、磁通量 \n\n定义：磁感应强度 B 与垂直磁场方向的面积 S 的乘积叫做穿过这个面的磁通量，定义式： ，\n\n如果面积 S 与 B 不垂直，应以 B 乘以在垂直与磁场方向上的投影面积 ，即 ，国际单位 Wb\n\n（韦伯） \n\n五、磁场对电流的作用——安培力 \n\n \n\n1.大小： \n\n \n\n2.方向：安培力的方向由左手定则判定（手心——B，四指——I，拇指——力） \n\n \n\n例 2.通电矩形导体线框 abcd 与无线长通电直导线 AB 在同一竖直平面内，电流方向如图 3 所示，\n\nab 与导线 AB 平行，关于 AB 的磁场对线框的作用，下列叙述正确的是（ ） \n\nBS\n\n\'S \'BS\n\nsinF BIL \n\n拓展延伸： \n\nF=IL×B，利用安培力的矢量叉乘法则需要使用右手叉乘法则，即右手四指指向 L 方向，弯曲', 473, 473, 1, '3ddc22b3-33ac-4c80-849c-174e85787341', NULL, '2026-03-27 20:07:53');
INSERT INTO `document_chunk` VALUES (348, 6, 2, 144, '用，下列叙述正确的是（ ） \n\nBS\n\n\'S \'BS\n\nsinF BIL \n\n拓展延伸： \n\nF=IL×B，利用安培力的矢量叉乘法则需要使用右手叉乘法则，即右手四指指向 L 方向，弯曲\n\n指向 B 方向，大拇指指向即为 F 的方向。 \n\n补充说明： \n\n1. 是 I 与 B 的夹角，当 I 与 B 垂直时， 。 \n\n2.若载流导体是弯曲导线，且导线所在平面与磁感应强度方向垂直，则 L 指弯曲导线中始端指\n\n向末端的直线长度。 \n\n BILF \n\n\n\n学员专用 请勿外泄 \n\n \n\n82 中公教育学员专用资料 报名专线：400-6300-999 \n\n \n\nA.线框有两条边所受的安培力方向相同 \n\nB.线框有两条边所受的安培力大小相同 \n\nC.线框所受安培力的合力向下 \n\nD.线框所受安培力的合力向右 \n\n六、洛伦兹力 \n\n1.定义：运动电荷在磁场中所受到的力称为洛伦兹力，即磁场对运动电荷的作用力。 \n\n2.大小： ，其中 为 与 的夹角 \n\n3.方向：左手定则 \n\n \n\n4.性质 \n\na.洛伦兹力方向总与运动方向垂直。', 472, 472, 1, '7100181c-161f-429d-b570-e55e76925d43', NULL, '2026-03-27 20:07:53');
INSERT INTO `document_chunk` VALUES (349, 6, 2, 145, '2.大小： ，其中 为 与 的夹角 \n\n3.方向：左手定则 \n\n \n\n4.性质 \n\na.洛伦兹力方向总与运动方向垂直。 \n\nb.洛伦兹力永远不做功。（有束缚时，洛仑兹力的分力可以做功，但其总功一定为 0。） \n\nc.洛伦兹力不改变运动电荷的速率和动能，只能改变电荷的运动方向使之偏转。 \n\n七、带电粒子在匀强磁场中的运动规律 \n\n1. ∥B，带电粒子以速度 v 做匀速直线运动。 \n\n2.若 ，带电粒子在垂直于磁感线的平面内以入射速度 v 做匀速圆周运动。 \n\n（1）向心力由洛伦兹力提供： \n\n（2）轨道半径公式： \n\n（3）周期： ，频率： ，角速度： 。可见\n\n只与 有关，与 无关。 \n\n（4）动能： \n\nsinqvB   v B\n\nv\n\nv B\n\n2v\nqvB m\n\nR\n\n\nmv p\nR\n\nBq Bq\n \n\n2 2R m\nT\n\nv qB\n\n \n \n\n1\n\n2\n\nBq\nf\n\nT m\n \n\n2 qB\n\nT m\n\n\n   T f 、 、\n\nq\n\nm\nv R、\n\n2\n21 ( )\n\n2 2\nk\n\nBqR\nE mv\n\nm\n \n\n拓展延伸：', 492, 492, 1, '348c5466-674b-4166-aea8-d0e031a77a7c', NULL, '2026-03-27 20:07:53');
INSERT INTO `document_chunk` VALUES (350, 6, 2, 146, 'Bq\nf\n\nT m\n \n\n2 qB\n\nT m\n\n\n   T f 、 、\n\nq\n\nm\nv R、\n\n2\n21 ( )\n\n2 2\nk\n\nBqR\nE mv\n\nm\n \n\n拓展延伸： \n\n判断洛伦兹力还可以应用矢量叉乘法则：F=qv×B,右手四指指向 v 方向，弯曲指向 B 的方向，\n\n此时大拇指的方向即为 F 的把方向。 \n\nhttp://baike.baidu.com/view/63129.htm\n\n\n学员专用 请勿外泄 \n\n \n\n83 中公教育学员专用资料 报名专线：400-6300-999 \n\n3.确定带电粒子在磁场中做圆运动的圆心的方法 \n\n方法一：利用两个速度垂线的交点找圆心 \n\n由于向心力的方向与线速度方向互相垂直，洛伦兹力（向心力）沿半径指向圆心，知道两个速度\n\n的方向，画出粒子轨迹上两个对应的洛伦兹力，其延长线的交点即为圆心。 \n\n方法二：利用速度的垂线与弦的中垂线的交点找圆心 \n\n带电粒子在匀强磁场中做匀速运动时，如果已知轨迹上的两点的位置和其中一点的速度方向，可\n\n用联结这两点的弦的中垂线与一条半径的交点确定圆心的位置。 \n\n4.定半径', 490, 490, 1, '8408d4b3-95e1-4a5c-b2c1-89eccbdb95a2', NULL, '2026-03-27 20:07:54');
INSERT INTO `document_chunk` VALUES (351, 6, 2, 147, '4.定半径 \n\nR=mv/Bq、构造直角三角形 \n\n5.定圆心角： \n\nTt\n2\n\n圆心角\n \n\n八、带电粒子在复合场中的运动 \n\n（一）复合场的分析 \n\n1.清楚各种场力的特点： \n\n①重力的大小 ，方向竖直向下。 \n\n②电场力的大小为 ，方向与场强方向和粒子带电情况相关。注意电场力做功跟路径无关。（只\n\n跟粒子带电情况，和始末位置电势差有关。） \n\n③洛伦兹力的大小为 (速度方向与磁场垂直时)，注意洛伦兹力永远不做功。 \n\n④在匀强电场、磁场中的电场力为恒力，洛伦兹力与速度有关，可为恒力也可为变力。 \n\n2.在电场和磁场均为匀强场，且带电质点只受三场力作用的情况下，则： \n\n①若重力与电场力等大、反向，初速度为 0，质点必定静止不动；初速度不为零，质点必做匀速\n\n圆周运动，洛伦兹力提供向心力。 \n\n②若初速度不为零，且三力合力为零，质点必做匀速直线运动 \n\n3.注意带电粒子的重力考虑与否 \n\n（二）带电粒子在复合场中运动的研究方法 \n\n1.分析带电粒子的受力情况 \n\n2.分析带电粒子的运动情况 \n\n3.画出粒子的运动轨迹 \n\n4.善于利用功能关系', 484, 484, 1, 'f28f025e-ee9f-44e8-8312-e4761d759470', NULL, '2026-03-27 20:07:54');
INSERT INTO `document_chunk` VALUES (352, 6, 2, 148, '3.注意带电粒子的重力考虑与否 \n\n（二）带电粒子在复合场中运动的研究方法 \n\n1.分析带电粒子的受力情况 \n\n2.分析带电粒子的运动情况 \n\n3.画出粒子的运动轨迹 \n\n4.善于利用功能关系 \n\n注意：遇到临界问题，应该挖掘隐含条件，如：“恰好”、“最大”、“最高”、“至少”等词语。 \n\n九、应用实例 \n\nmg\n\nqE\n\nqvB\n\n\n\n学员专用 请勿外泄 \n\n \n\n84 中公教育学员专用资料 报名专线：400-6300-999 \n\n1.速度选择器： \n\n \n\n带电粒子在电场力和洛伦兹力的作用下匀速直线运动，只有 的粒子才能被选中，与带电粒\n\n子的电性无关。 \n\n2.磁流体发电机： \n\n \n\n两极板间电压达到某一值时，带电粒子不再偏转，极板间电压的最大值为 \n\n3.回旋加速器 \n\n \n\n①带电粒子飞出金属盒的速度由磁感应强度和金属盒的半径决定，与高频电源的加速电压无关，\n\n。 \n\n②回旋加速器中的电场作用是使带电粒子加速。粒子在磁场中运动一个周期被电场加速两次，而带\n\n电粒子被电场的加速次数由加速电压决定， 。 \n\n \n\nB\n\nE\nv \n\nBdvE \n\nm', 487, 487, 1, 'a8b2b685-4144-4ce0-8ae6-b6ad2f96128b', NULL, '2026-03-27 20:07:54');
INSERT INTO `document_chunk` VALUES (353, 6, 2, 149, '②回旋加速器中的电场作用是使带电粒子加速。粒子在磁场中运动一个周期被电场加速两次，而带\n\n电粒子被电场的加速次数由加速电压决定， 。 \n\n \n\nB\n\nE\nv \n\nBdvE \n\nm\n\nRBq\nmvE m\n\nmkm\n22\n\n1\n222\n\n2 \n\nqU\n\nE\nn km\n\n\n\n学员专用 请勿外泄 \n\n \n\n85 中公教育学员专用资料 报名专线：400-6300-999 \n\n第四节 电磁感应 \n\n \n\n一、电磁感应及感应电流产生的条件 \n\n1.电磁感应：“磁生电”的现象叫做电磁感应，产生的电流叫做感应电流。 \n\n2.感应电流的产生的条件 \n\n①电路闭合。 \n\n②磁通量发生变化。 \n\n二、楞次定律及其应用 \n\n1.楞次定律 \n\n（1）内容 \n\n感应电流具有这样的方向，即感应电流的磁场总要阻碍引起感应电流的磁通量的变化。 \n\n（2）适用范围 \n\n穿过闭合电路的磁通量发生变化时。 \n\n（3）理解 \n\n①阻碍对象：穿过回路的磁通量的变化，而不是磁通量本身 \n\n②阻碍方式：原磁通量增加时，感应电流磁场方向与原磁场方向相反；当原磁通量减少时，感应', 474, 474, 1, 'cd42a3d8-c776-4d26-83c7-cce1085b89ea', NULL, '2026-03-27 20:07:54');
INSERT INTO `document_chunk` VALUES (354, 6, 2, 150, '（3）理解 \n\n①阻碍对象：穿过回路的磁通量的变化，而不是磁通量本身 \n\n②阻碍方式：原磁通量增加时，感应电流磁场方向与原磁场方向相反；当原磁通量减少时，感应\n\n电流磁场方向与原磁场方向相同，即“增反减同” \n\n另一种表述，阻碍物体间（两载流导体间或载流导体与磁体间）的相对运动，靠近时二者排斥，\n\n远离时二者吸引。即“来拒去留”、“增缩减扩”。 \n\n例 1.如图所示，金属导轨 ab、cd 平行于水平面放置且固定，两金属杆 PQ、MN 放置在导轨上，\n\n没有摩擦，一条形磁铁从上往下接近框架时，下列说法中正确的是（ ） \n\n \n\nA.电流方向为 MNQP，PQ 与 MN 相互靠拢 \n\nB.电流方向为 MNQP，PQ 与 MN 相互远离 \n\nC.电流方向为 PQNM，PQ 与 MN 相互靠拢 \n\nD.电流方向为 PQNM，PQ 与 MN 相互远离 \n\n\n\n学员专用 请勿外泄 \n\n \n\n86 中公教育学员专用资料 报名专线：400-6300-999 \n\n例 2.如图所示，铜环 a 和 b 用细线悬挂于螺线管两侧，并且 a 和 b 的平面与螺线管横截面平行。\n\n则开关闭合瞬间（ ）', 493, 493, 1, '8de0d77f-9a77-4484-be58-0a87527c3d7a', NULL, '2026-03-27 20:07:54');
INSERT INTO `document_chunk` VALUES (355, 6, 2, 151, '则开关闭合瞬间（ ） \n\n \n\nA.a 和 b 同时靠拢螺线管 \n\nB.a 和 b 同时远离螺线管 \n\nC.a 靠拢螺线管，b 远离螺线管 \n\nD.a 远离螺线管，b 靠拢螺线管 \n\n③阻碍结果：阻碍并不是阻止，结果是增加的还增加，减少的还减少。 \n\n2.楞次定律的应用 \n\n（1）判断感应电流方向 \n\n明确增减和方向，增反减同莫相忘，安培定则来判断，四指环绕是流向（安培定则）。 \n\n（2）判断原磁场方向及线圈中磁通量的变化 \n\n磁通量的变化、原磁场方向、感应电流方向三个因素，只要知道了其中任意两个因素，就可以判\n\n定第三个因素。 \n\n3.右手定则 \n\n（1）适用范围 \n\n闭合电路部分导体切割磁感线 \n\n（2）定律内容： \n\n伸开右手，使拇指和其余四个手指垂直，并且都与手掌在同一平面内；让磁感线从掌心进入，并\n\n使拇指指向导体运动的方向，这时，四指所指的方向就是感应电流方向。 \n\n（3）右手定则与楞次定律的关系 \n\n右手定则与楞次定律是特殊与一般的关系。一切电磁感应现象都符合楞次定律，而右手定则只适\n\n用于单纯由于部分导体做切割磁感线运动所产生的电磁感应现象。', 486, 486, 1, 'c7c96413-9244-49e9-9213-a726fa90cdd3', NULL, '2026-03-27 20:07:54');
INSERT INTO `document_chunk` VALUES (356, 6, 2, 152, '（3）右手定则与楞次定律的关系 \n\n右手定则与楞次定律是特殊与一般的关系。一切电磁感应现象都符合楞次定律，而右手定则只适\n\n用于单纯由于部分导体做切割磁感线运动所产生的电磁感应现象。 \n\n例 3.用表面涂有绝缘层的四根相同导线分别绕成闭合线圈，a 为两匝圆形线圈。b，c 为导线交叉\n\n的 8 字形圆线圈，d 是两个分别由半根导线绕成的闭合圆形线圈且捆绑在一起。现将他们按图 6 所示\n\n从同一高度同时由静止释放。它们穿过水平向里的匀强磁场，最后落到水平地面，则最先落地的线圈\n\n是（ ）。 \n\n \n\n\n\n学员专用 请勿外泄 \n\n \n\n87 中公教育学员专用资料 报名专线：400-6300-999 \n\nA.a B.b C.c D.d \n\n三、法拉第电磁感应定律 \n\n1.磁通量的变化率：表示磁通量变化快慢的物理量，表达式 ，一般分为两种情况即 或\n\n \n\n2.法拉第电磁感应定律：电路中感应电动势的大小，跟穿过这一电路的磁通量的变化率成正比。 \n\n表达式： \n\n（1）当导体做切割磁感线运动时，其感应电动势的计算式为 \n\n① 为 B 与 v 的夹角，当 B、L、v 三者两两垂直时', 491, 491, 1, '743cfddd-bb69-445f-82b1-0936acf24b89', NULL, '2026-03-27 20:07:54');
INSERT INTO `document_chunk` VALUES (357, 6, 2, 153, '表达式： \n\n（1）当导体做切割磁感线运动时，其感应电动势的计算式为 \n\n① 为 B 与 v 的夹角，当 B、L、v 三者两两垂直时 \n\n②L 为导体切割磁感线的有效长度，即首尾相连在垂直速度方向的分量。 \n\n③ 为导体相对磁场的速度。 \n\n④转动切割型： \n\n \n\n（2）关于公式的选择： \n\n研究对象 情景图 表达式 \n\n回路 \n\n（不一定闭合） \n \n\nt\n\n\nS\n\nt\n\nB\n\n\n\n\n\n\nt\n\nS\nB\n\n\n\n\n\n\nS\nt\n\nB\nnE \n\n\n\n\n\nsinBLvE \n\n BLvE \n\nv\n\n2\n\n2\n\n1\nBlvBLE \n\nS\nt\n\nB\nnE \n\n\n\n\n\n如下图所示， \n\n \n\n当导体棒转动切割磁感线时，整个导体棒的速度取平均速度，即 \n\n带入公式可得 \n\n \n\n22\n\nlv\nv \n\n2\n\n2\n\n1\nBlvBLE \n\n\n\n学员专用 请勿外泄 \n\n \n\n88 中公教育学员专用资料 报名专线：400-6300-999 \n\n一段直导线（或等效成直导线） \n\n饶一端转动的导体棒 \n\n四、自感', 478, 478, 1, 'd1865b66-bff5-4e79-8a18-baa75fc94023', NULL, '2026-03-27 20:07:55');
INSERT INTO `document_chunk` VALUES (358, 6, 2, 154, '1\nBlvBLE \n\n\n\n学员专用 请勿外泄 \n\n \n\n88 中公教育学员专用资料 报名专线：400-6300-999 \n\n一段直导线（或等效成直导线） \n\n饶一端转动的导体棒 \n\n四、自感 \n\n1.自感现象：由于导体本身的电流发生变化而产生的电磁感应现象。 \n\n2.自感电动势：在自感现象中产生的感应电动势叫自感电动势。自感电动势的大小取决于线圈自\n\n感系数和本身电流发生的快慢，自感电动势方向总是阻碍电流的变化。公式为 （自感式），\n\n式中各量的意义为 为线圈的自感系数，简称自感或电感； 为电流变化率。 \n\n \n\n4.通电自感、断电自感 \n\n 通电自感 断电自感 \n\n电路图 \n\n \n\n分析 \n\n接通 S 一瞬间，A2直接亮，A1这一路\n\n由于有自感线圈产生感应电流阻碍原\n\n电流的增大，因此 A1逐渐变亮 \n\n线圈有内阻 RL。 \n\n①若 R 灯<RL，则 I 灯>IL。当断开 S\n\n一瞬间，线圈里产生与原电流电流\n\n方向相同的感应电流，在上方并联\n\n的回路中流动。该电流小于灯泡原\n\n来的电流，因此灯泡逐渐熄灭。 \n\n②若 R 灯>RL，则 I 灯><IL。当断开', 490, 490, 1, '522ccda4-989d-41ef-b5d7-46310ef81051', NULL, '2026-03-27 20:07:55');
INSERT INTO `document_chunk` VALUES (359, 6, 2, 155, '该电流小于灯泡原\n\n来的电流，因此灯泡逐渐熄灭。 \n\n②若 R 灯>RL，则 I 灯><IL。当断开\n\nS 一瞬间，线圈里产与原电流电流\n\n方向相同的感应电流，在上方并联\n\nsinBLvE \n\n2\n\n2\n\n1\nBlvBLE \n\nt\n\nI\nLE\n\n\n\n\n\nL\nt\n\nI\n\n\n\n\n\n自感系数 ：自感系数的大小由线圈本身的特性决定。线圈越长，单位长度的匝数越多，截\n\n面积越大，自感系数越大。若线圈中加有铁芯，自感系数会变大。单位：亨（符号：H） \n\nL\n\n\n\n学员专用 请勿外泄 \n\n \n\n89 中公教育学员专用资料 报名专线：400-6300-999 \n\n的回路中流动。该电流大于灯泡原\n\n来的电流，因此灯泡先闪亮一下再\n\n逐渐熄灭。 \n\n五、电磁感应的综合应用 \n\n1.电磁感应中图像问题 \n\n电磁感应现象中图像问题的分析，要抓住磁通量的变化是否均匀，从而推知感应电动势大小是否\n\n恒定，用楞次定律判断感应电动势（或电流）的方向，从而确定其正负，以及在坐标中的范围。 \n\n \n\n例 4. 如图 6，纸面内两个半径均为 R 的圆相切于 O 点，两半圆形区域内分别存在垂直纸面的匀', 498, 498, 1, '20e4f8f0-d10d-4ebc-a2b5-19fcef165e36', NULL, '2026-03-27 20:07:55');
INSERT INTO `document_chunk` VALUES (360, 6, 2, 156, '例 4. 如图 6，纸面内两个半径均为 R 的圆相切于 O 点，两半圆形区域内分别存在垂直纸面的匀\n\n强磁场，磁感应强度大小相等、方向相反，且不随时间变化.一长为 2R 的导体杆 OA 绕过 O 点且垂直\n\n于纸面的轴顺时针匀速旋转，角速度为 ω，t=0 时，OA 恰好位于两圆的公切线上，如图所示.若选取从\n\nO 指向 A 的电动势为正，下列描述导体杆中感应电动势随时间变化的图象可能正确的是（） \n\n \n\n2.电磁感应中的电路问题 \n\n在电磁感应中，切割磁感线的导体或磁通量发生变化的回路将产生感应电动势，该导体或回路就\n\n相当于电源，将它们接上电容器，便可使电容器充电；将它们接上电阻等用电器，便可对用电器供电，\n\n在电路中形成电流。因此，电磁感应问题往往与电路问题联系在一起，解决与电路相联系的电磁感应\n\n问题的基本方法是： \n\n（1）用法拉第电磁感应定律和楞次定律确定感应电动势的大小和方向。 \n\n（2）画等效电路 \n\n（3）运用全电路欧姆定律，串并联电路性质，电功率等公式联立求解。 \n\n注意问题：', 455, 455, 1, '20927cbf-2949-417f-9f4d-8fadb43d8212', NULL, '2026-03-27 20:07:55');
INSERT INTO `document_chunk` VALUES (361, 6, 2, 157, '（2）画等效电路 \n\n（3）运用全电路欧姆定律，串并联电路性质，电功率等公式联立求解。 \n\n注意问题： \n\n（1）关注初始时刻：如初始时刻感应电流是否为零，是正方向还是负方向； \n\n（2）关注变化过程：看电磁感应发生过程分为几个阶段，这几个阶段是否和图像变化相对\n\n应； \n\n（3）关注大小、方向的变化趋势，看图像斜率大小、图象的曲直和物理过程是否相对应； \n\n（4）求 F-t 图象时，不但要注意 i-t 变化，还需要关注 B-t 变化，有时 I≠0，但 B=0，所以\n\nF=0 \n\n\n\n学员专用 请勿外泄 \n\n \n\n90 中公教育学员专用资料 报名专线：400-6300-999 \n\n \n\n例 5.如图所示，两个互连的金属圆环，粗金属环的电阻是细金属环电阻的一半，磁场垂直穿过粗\n\n金属环所在的区域，当磁感应强度均匀变化时，在粗环内产生的电动势为 E，则 ab 两点间的电势差为\n\n（ ） \n\n \n\nA.E/2 B.E/3 C.2E/3 D.E \n\n 几个常用公式的推导 \n\n（1）通过导体横截面积的电荷量 \n\n \n\n注意：这里求出的 q 为通过干路的电荷量', 482, 482, 1, '09606dcf-965f-4dfc-9dc2-db1ded766747', NULL, '2026-03-27 20:07:55');
INSERT INTO `document_chunk` VALUES (362, 6, 2, 158, '间的电势差为\n\n（ ） \n\n \n\nA.E/2 B.E/3 C.2E/3 D.E \n\n 几个常用公式的推导 \n\n（1）通过导体横截面积的电荷量 \n\n \n\n注意：这里求出的 q 为通过干路的电荷量 \n\n（2）导体棒/导线框进入磁场时安培力的大小 \n\nBLvE\n\nR\n\nE\nI\n\nBILF\n\n\n\n\n\n\n\n总\n\n安\n\n \n总\n\n安\nR\n\nvLB\nF\n\n22\n\n \n\n例 6.两条平行且足够长的金属导轨置于磁感应强度为 B 的匀强磁场中，B 的方向垂直导轨平面.\n\n两导轨间距为 L，左端接一电阻 R，其余电阻不计.长为 2L 的导体棒 ab 如图所示放置，开始时 ab 棒\n\n与导轨垂直，在 ab 棒绕 a 点紧贴导轨滑倒的过程中，试求通过电阻 R 的电荷量. \n\n \n\n3.电磁感应现象中的力学问题 \n\n（1）通过导体的感应电流在磁场中将受到安培力作用，电磁感应问题往往和力学问题联系在一起，\n\n基本方法是： \n\n①用法拉第电磁感应定律和楞次定律求感应电动势的大小和方向。 \n\n②求回路中电流强度 \n\n注意： \n\n（1）等效电源内部的电源，方向由负极到正极，而外电路中的电流方向仍是从高电势到', 498, 498, 1, 'eac879c5-f0fb-4444-9e9d-6e5b504a982e', NULL, '2026-03-27 20:07:55');
INSERT INTO `document_chunk` VALUES (363, 6, 2, 159, '②求回路中电流强度 \n\n注意： \n\n（1）等效电源内部的电源，方向由负极到正极，而外电路中的电流方向仍是从高电势到\n\n低电势。 \n\n（2）闭合电路中，等效电源两端的电压为路端电压，而不是感应电动势，除非切割磁感\n\n线的导体或线圈的电阻为零。 \n\n（3）注意电源内阻是否存在。 \n\n\n\n学员专用 请勿外泄 \n\n \n\n91 中公教育学员专用资料 报名专线：400-6300-999 \n\n③分析研究导体受力情况（包含安培力，用左手定则确定其方向） \n\n④列动力学方程或平衡方程求解。 \n\n（2）电磁感应力学问题中，要抓好受力情况，运动情况的动态分析，导体受力运动产生感应电动\n\n势 感应电流 通电导体受安培力 合外力变化 加速度变化 速度变化 周而复始地循环，\n\n循环结束时，加速度等于零，导体达稳定运动状态，抓住 a=0 时，速度 v 达最大值得特点。 \n\n若是两个导体棒只在安培力作用下运动，最终稳定时二者速度相等； \n\n若两个导体棒在恒定的外力作用下切割匀强磁场运动，最终稳定是二者加速度相等。 \n\n \n\n4.电磁感应中的能量转化问题', 467, 467, 1, 'd2e9b422-a1e1-4b2a-b141-23f80d853786', NULL, '2026-03-27 20:07:56');
INSERT INTO `document_chunk` VALUES (364, 6, 2, 160, '若是两个导体棒只在安培力作用下运动，最终稳定时二者速度相等； \n\n若两个导体棒在恒定的外力作用下切割匀强磁场运动，最终稳定是二者加速度相等。 \n\n \n\n4.电磁感应中的能量转化问题 \n\n导体切割磁感线或闭合回路中磁通量发生变化，在回路中产生感应电流，机械能或其他形式能量\n\n便转化为电能，具有感应电流的导体在磁场中受安培力作用或通过电阻发热，又可使电能转化为机械\n\n能或电阻的内能， \n\n克服安培力做的功=产生的电能=整个回路的焦耳热（纯电阻电路） \n\n例 7.如图所示，间距为 L、电阻不计的足够长平行光滑金属导轨水平放置，导轨左端用一阻值为\n\nR 的电阻连接，导轨上横跨一根质量为 m、电阻也为 R 的金属棒，金属棒与导轨接触良好．整个装置\n\n处于竖直向上、磁感应强度为 B 的匀强磁场中．现使金属棒以初速度 v 沿导轨向右运动，若金属棒在\n\n整个运动过程中通过的电荷量为 q。下列说法正确的是（ ） \n\n \n\nA．金属棒在导轨上做匀减速运动 \n\nB．整个过程中金属棒在导轨上发生的位移为\nBL\n\nqR\n \n\nC．整个过程中金属棒克服安培力做功为\n2\n\n2\n\n1\nmv', 486, 486, 1, '85ebe0b9-cfb2-41ab-81d2-f17d23eac50e', NULL, '2026-03-27 20:07:56');
INSERT INTO `document_chunk` VALUES (365, 6, 2, 161, '下列说法正确的是（ ） \n\n \n\nA．金属棒在导轨上做匀减速运动 \n\nB．整个过程中金属棒在导轨上发生的位移为\nBL\n\nqR\n \n\nC．整个过程中金属棒克服安培力做功为\n2\n\n2\n\n1\nmv \n\nD．整个过程中电阻 R 上产生的焦耳热为\n2\n\n2\n\n1\nmv \n\n \n\n \n\n     \n\n\n\n学员专用 请勿外泄 \n\n \n\n92 中公教育学员专用资料 报名专线：400-6300-999 \n\n第五节 交变电流 \n\n \n\n一、交变电流 \n\n1.交变电流：大小和方向都随时间做周期性变化的电流，叫做交变电流，按正弦规律变化的电动势、\n\n电流称为正弦交流电。 \n\n \n\n区分直流、交流的关键：方向是否随时间做周期性变化 \n\n \n\n上图中，（a）为恒定电流、（d）为直流电；（b）、（c）、（e）为交流电。 \n\n \n\n2.正弦交变变电流 \n\n（1）产生：将一平面线圈置于匀强磁场中，并使它绕垂直于磁感线的轴做匀速转动时，线圈中就\n\n会产生正弦交流电。 \n\n（2）函数式： （其中 ） \n\n（3）图像：正弦交流电的电动势 e，电流 i，和电压 u，其变化规律可用函数图像描述。', 489, 489, 1, 'ce338b22-49f7-4262-8894-5b87dad57f42', NULL, '2026-03-27 20:07:56');
INSERT INTO `document_chunk` VALUES (366, 6, 2, 162, '（2）函数式： （其中 ） \n\n（3）图像：正弦交流电的电动势 e，电流 i，和电压 u，其变化规律可用函数图像描述。 \n\n二、描述交变电流的物理量 \n\n1.周期和频率 \n\n周期 T：交流电完成一次周期性变化所需的时间，在一个周期内，交流电的方向变化两次。 \n\n频率 f：交流电在 1s 内完成周期性变化的次数，单位赫兹（Hz），角频率： \n\n举例：若某一交流电的频率为 50Hz，则线圈转动的角速度为 100 rad/s，转速为 50r/s，周期为\n\n0.02s。 \n\n \n\n2.交流电的两个面 \n\n（1）中性面：线圈在匀强磁场中转动到线圈平面垂直于磁感线时，各边都有不切割磁感线，线圈\n\n中没有感应电动势，这个位置叫中性面。线圈平面与中性面重合时，磁通量最大，磁通量的变化率为\n\n零，电动势为零，线圈经过中性面时，其内部的电流方向要发生改变。 \n\nwtEe m sin S\nt\n\nB\nNwNNBSwE mmm )(\n\n\n\n\n \n\nf\nT\n\nw \n\n\n2\n2\n\n\n\n\n\n\n\n学员专用 请勿外泄', 459, 459, 1, '9ac01068-95a7-44ae-aae6-18aba5ecfd15', NULL, '2026-03-27 20:07:56');
INSERT INTO `document_chunk` VALUES (367, 6, 2, 163, 'wtEe m sin S\nt\n\nB\nNwNNBSwE mmm )(\n\n\n\n\n \n\nf\nT\n\nw \n\n\n2\n2\n\n\n\n\n\n\n\n学员专用 请勿外泄 \n\n \n\n93 中公教育学员专用资料 报名专线：400-6300-999 \n\n \n\n（2）最大值面：线圈在匀强磁场中转动到线圈平面与磁感线平行时，与磁场垂直的两个边切割速\n\n度最大，线圈中感应电动势最大，这个位置叫最大值面，此时，线圈平面与中心面垂直时，磁通量为\n\n零，磁通量为零，磁通量的变化率最大，电动势最大。 \n\n \n\n3.交流电的四值 \n\n（1）最大值： \n\n最大值 、 、 与线圈的形状，以及转动轴处于线圈平面内哪个位置无关，在考虑电容器\n\n的耐压值或击穿电压时，则应根据交流电的最大值。 \n\n \n\n（2）瞬时值：交流电某一时刻的值，常用 e、u、i 表示。 \n\n若从线圈平面和磁场方向平行时（最大值面）开始计时，交变电流的变化规律为 ，\n\n， ；从中性面开始计时，电动势为 ， ，\n\n；其中 ， \n\n（3）有效值：交流电的有效值是根据电流的热效应来规定的，即：让交流和恒定电流分别通过', 482, 482, 1, '72e99f8b-1a4c-4ae0-ba48-b393dcce8348', NULL, '2026-03-27 20:07:56');
INSERT INTO `document_chunk` VALUES (368, 6, 2, 164, '时（最大值面）开始计时，交变电流的变化规律为 ，\n\n， ；从中性面开始计时，电动势为 ， ，\n\n；其中 ， \n\n（3）有效值：交流电的有效值是根据电流的热效应来规定的，即：让交流和恒定电流分别通过\n\n大小相同的电阻，在交流电的一个周期内它们产生的热量相等，而这个恒定电流是 I、电压是 U，我\n\n们把这个 I、U 叫做这个交流电的有效值。 \n\n①求电功、电热、电功率、热功率以及确定保险丝的熔断电流等物理量时，要用有效值计算，有\n\n效值与最大值的关系 ， ， ，只用于正弦（或余弦）交流电，且最小适用范\n\n围为零开始的四分之一周期。其他交变电流的有效值只能根据有效值的定义来计算，切不可乱套公式。 \n\n②在正弦交流电中，各种交流电器设备上标示值及交流电表上的测量值都指有效值。保险丝的熔\n\n断电流值，电器铭牌上的额定值都是指的交变电流的有效值。 \n\nS\nt\n\nB\nNwNNBSwE mmm )(\n\n\n\n\n \n\nmE mU mI\n\nwtEe m cos\n\nwtUu m cos wtIi m cos wtEe m sin wtUu m sin', 481, 481, 1, '50f9e606-9dea-463a-ae31-6615e2da7bdc', NULL, '2026-03-27 20:07:56');
INSERT INTO `document_chunk` VALUES (369, 6, 2, 165, 'wNNBSwE mmm )(\n\n\n\n\n \n\nmE mU mI\n\nwtEe m cos\n\nwtUu m cos wtIi m cos wtEe m sin wtUu m sin\n\nwtIi m sin mm E\nrR\n\nR\nU\n\n\n\n\nR\n\nU\n\nrR\n\nE\nI mm\n\nm \n\n\n\n\n2\n\nmE\nE \n\n2\n\nmU\nU \n\n2\n\nmI\nI \n\n\n\n学员专用 请勿外泄 \n\n \n\n94 中公教育学员专用资料 报名专线：400-6300-999 \n\n \n\n（4）平均值：交变电流图象中图线与 t 轴所围成的面积与时间的比值，计算有关电量时只能\n\n用平均值。 ， ， ，计算一段时间内通过导体横截面的电荷量。 \n\n例 1.如图所示为某种交变电流的波形，每半个周期按各自的正弦规律变化，其有效值为（ ） \n\nvBLE \nt\n\nnE\n\n\n\n\n\nRr\n\nE\nI\n\n\n\n\n补充：几种典型的电流及其有效值 \n\n正弦式半波脉冲电流： ，\n\n \n\n \n\n \n\n正弦单向脉冲电流： ，\n\n \n\n \n\n矩形脉冲电流： ，\n\n \n\n \n\n非对称性交变电流： ，', 494, 494, 1, '286e2f65-c590-46c9-874d-01bb601f5f60', NULL, '2026-03-27 20:07:57');
INSERT INTO `document_chunk` VALUES (370, 6, 2, 166, '\n\n\n补充：几种典型的电流及其有效值 \n\n正弦式半波脉冲电流： ，\n\n \n\n \n\n \n\n正弦单向脉冲电流： ，\n\n \n\n \n\n矩形脉冲电流： ，\n\n \n\n \n\n非对称性交变电流： ，\n\n \n\n \n\n \n\n \n\n \n\n2\n\nmU\nU \n\n2\n\nmI\nI \n\n2\n\nmU\nU \n\n2\n\nmI\nI \n\nmU\nT\n\nt\nU 1 mI\n\nT\n\nt\nI 1\n\n)(\n2\n\n1 2\n\n2\n\n2\n\n1 UUU  )(\n2\n\n1 2\n\n2\n\n2\n\n1 III \n\n\n\n学员专用 请勿外泄 \n\n \n\n95 中公教育学员专用资料 报名专线：400-6300-999 \n\n \n\nA.4 A B.5 A C.5√2A D.4√2A \n\n例 2.在匀强磁场中，一矩形金属线框绕与磁感线垂直的转轴匀速转动，如图甲所示，产生的交变\n\n电动势的图象如图乙所示，则（ ） \n\n \n\nA.t =0.005s 时线框的磁通量变化率为零 \n\nB.t =0.01s 时线框平面与中性面重合 \n\nC.线框产生的交变电动势有效值为 311V \n\nD.线框产生的交变电动势的频率为 100Hz \n\n三、变压器', 491, 491, 1, '323b1fa8-e1ca-4085-9396-c74babd8846e', NULL, '2026-03-27 20:07:57');
INSERT INTO `document_chunk` VALUES (371, 6, 2, 167, '5s 时线框的磁通量变化率为零 \n\nB.t =0.01s 时线框平面与中性面重合 \n\nC.线框产生的交变电动势有效值为 311V \n\nD.线框产生的交变电动势的频率为 100Hz \n\n三、变压器 \n\n1.理想变压器：工作时无功率损失，因此，理想变压器原副线圈的电阻均不计。 \n\n变压器的工作原理：电磁感应，因此只能在交流电中工作 \n\n2.理想变压器的基本关系式： \n\n \n\n①功率关系： \n\n②原副边电压关系 \n\n③原副边电流关系： \n\n3.理想变压器的动态分析 \n\n（1）根据题意弄清变量与不变量 \n\n（2）弄清变压器动态变化的决定关系 \n\n出入 PP \n\n2\n\n1\n\n2\n\n1\n\nn\n\nn\n\nU\n\nU\n\n\n1\n\n2\n\n2\n\n1\n\nn\n\nn\n\nI\n\nI\n\n\n\n\n学员专用 请勿外泄 \n\n \n\n96 中公教育学员专用资料 报名专线：400-6300-999 \n\n①原、副边线圈电压的决定关系： \n\n原线圈电压制约副线圈电压；当 不变时，无论负载电阻 R 变化与否， 不会改变。 \n\n②原、副边线圈电流的决定关系：副线圈电流制约原线圈电流； 由 与负载电阻决定， 由\n\n与匝数比决定；', 494, 494, 1, '83ee86af-e7c2-45be-ab59-e1858002ddf0', NULL, '2026-03-27 20:07:57');
INSERT INTO `document_chunk` VALUES (372, 6, 2, 168, '②原、副边线圈电流的决定关系：副线圈电流制约原线圈电流； 由 与负载电阻决定， 由\n\n与匝数比决定； \n\n \n\n③输入功率与输出功率的决定关系：输出功率 决定输入功率 \n\n \n\n例 3.如图 3 所示的匝数为 2：1 的理想变压器，原线圈电阻为零的轨道，可在轨道上滑行的金属\n\n杆 PQ 形成闭合电路，闭合电路磁场强度为 1.0T 方向向里的匀强磁场，副线圈接 10 欧的电阻，金属\n\n棒 PQ 长度为 0.1m，电阻为 0.4 欧。若金属杆在外力作用下以速率 3m/s 沿轨道匀速滑行，则下列叙述\n\n正确的是（ ） \n\n \n\nA.原线圈电流 I=0.03A B.原线圈电动势为 E=0.15V \n\nC.副线圈电流大小 I=0.01A D.副线圈电功率大小 P=0W \n\n4.远距离输电问题 \n\n（1）远距离输电的关键在于：减少输电线上的电能损失。 \n\n（2）方法：①减小输电导线的电阻，如采用电阻率小的材料、加大导线的横截面积。②提高输电\n\n电压，减小输电电流。 \n\n第一种方法的作用十分有限，代价较高，一般采用第二种方法。 \n\n（3）原理： \n\n \n\n电压关系： ； ； \n\n1U 2U', 495, 495, 1, '7d3a52ae-6045-42ba-8b0e-11b10dfd79ef', NULL, '2026-03-27 20:07:57');
INSERT INTO `document_chunk` VALUES (373, 6, 2, 169, '②提高输电\n\n电压，减小输电电流。 \n\n第一种方法的作用十分有限，代价较高，一般采用第二种方法。 \n\n（3）原理： \n\n \n\n电压关系： ； ； \n\n1U 2U\n\n2I 2U 1I 2I\n\n2P 1P\n\n线耗 RIP 2\n\n2\n\n1\n\n2\n\n1\n\nn\n\nn\n\nU\n\nU\n\n\n4\n\n3\n\n4\n\n3\n\nn\n\nn\n\nU\n\nU\n\n\n根据功率 ， \n\n若 \n\nR\n\nU\nP\n\n2\n\n2\n2  21 PP \n\n 212 PIIR负\n\n\n\n学员专用 请勿外泄 \n\n \n\n97 中公教育学员专用资料 报名专线：400-6300-999 \n\n电流关系：\n\n； ； \n\n电压损失： 322 UURIU 线 \n\n功率损失： RIP 2\n\n2损\n \n\n例 4.如图是街头变压器通过降压给用户供电的示意图。变压器的输入电压是市区电网的电压，假\n\n设负载变化时输入电压保持不变。输出电压通过输电线输送给用户，两条输电线的总电阻用 R0表示，\n\n变阻器 R 代表用户用电器的总电阻，当用电器增加时，相当于 R 的值减小。忽略变压器上的能量损失，', 473, 473, 1, 'b1b021e4-a7e1-473d-b316-1094525e824e', NULL, '2026-03-27 20:07:57');
INSERT INTO `document_chunk` VALUES (374, 6, 2, 170, '输出电压通过输电线输送给用户，两条输电线的总电阻用 R0表示，\n\n变阻器 R 代表用户用电器的总电阻，当用电器增加时，相当于 R 的值减小。忽略变压器上的能量损失，\n\n不计电压表、电流表的内阻对电路的影响。当用户的用电器增加时，下列说法正确的是（ ）。 \n\n \n\nA.电压表读数增大，电流表读数增大 \n\nB.电压表读数减小，电流表读数增大 \n\nC.电压表读数不变，电流表读数增大 \n\nD.电压表读数不变，电流表读数减小 \n\n \n\n1\n\n2\n\n2\n\n1\n\nn\n\nn\n\nI\n\nI\n\n\n3\n\n4\n\n4\n\n3\n\nn\n\nn\n\nI\n\nI\n\n\n32 II \n\n\n\n学员专用 请勿外泄 \n\n \n\n98 中公教育学员专用资料 报名专线：400-6300-999 \n\n第三章 热学部分 \n\n \n\n一、分子动理论 \n\n1.物体是由大量分子组成的。 \n\n（1）分子模型：把分子看成小球（或立方体），这是一个理想化的模型。 \n\n①固体、液体被理想化地认为各个分子是一个挨一个地紧密排列。 \n\n②气体分子间距离较大，不能看成一个挨一个地紧密排列，且气体分子的体积远小于每个分子平', 478, 478, 1, '0c08ca93-4c62-4100-b41c-107fc5d87355', NULL, '2026-03-27 20:07:57');
INSERT INTO `document_chunk` VALUES (375, 6, 2, 171, '①固体、液体被理想化地认为各个分子是一个挨一个地紧密排列。 \n\n②气体分子间距离较大，不能看成一个挨一个地紧密排列，且气体分子的体积远小于每个分子平\n\n均占有的空间，通常把每个气体分子平均占有的空间看成立方体。 \n\n（2）分子的大小 \n\n①一般认为分子直径的数量级为 。 \n\n②油膜法测分子直径：利用油酸的酒精溶液在平静的水面上形成单分子油膜（如图），将油酸\n\n分子看成球形，测出一定体积油酸溶液在水面上形成的油膜面积，用 计算出油膜的厚度，其中\n\n为一滴油酸溶液中纯油酸的体积， 为油膜面积，这个厚度 就近似等于油酸分子的直径。 \n\n \n\n（3）阿伏伽德罗常数 \n\n任何物质都含相同的分子数，且数目为 。阿伏伽德罗常数是联系\n\n宏观物理量（摩尔质量、摩尔体积等）和微观物理量（分子质量、分子大小等）的桥梁。 \n\n（4）分子模型的计算 \n\n①球体模型：固体和液体可看成一个紧挨着一个地球形分子排列而成。设分子体积为 ，则\n\n，可得为 d＝\n3 6V0\n\nπ\n。 \n\n②立方体模型：气体分子间的空隙很大，把气体分成若干个小立方体，气体分子位于每个小立', 474, 474, 1, 'a00c1376-a616-4c88-aa56-80338325faf1', NULL, '2026-03-27 20:07:58');
INSERT INTO `document_chunk` VALUES (376, 6, 2, 172, '设分子体积为 ，则\n\n，可得为 d＝\n3 6V0\n\nπ\n。 \n\n②立方体模型：气体分子间的空隙很大，把气体分成若干个小立方体，气体分子位于每个小立\n\n方体的中心，每个小立方体是平均每个分子占有的活动空间，胡洛气体分子的大小，则边长为 d＝\n3\n\nV0。 \n\nm10-10\n\nS\n\nV\nd \n\nV S d\n\nmol1\n1231002.6  molN A\n\nV\n\n3\n\n23\n\n4\n\n\n\n\n\n\n\n\n\n\nd\nV \n\n\n\n学员专用 请勿外泄 \n\n \n\n99 中公教育学员专用资料 报名专线：400-6300-999 \n\n \n\n（5）分子的质量：数量级 10-27——10-26kg \n\n2.分子在永不停息地做无规则运动 \n\n（1）热运动：组成物体的分子永不停息地做无规则运动，这种运动跟温度有关，故通常把分子的\n\n这种运动称为热运动。 \n\n（2）扩散现象： \n\n①定义：不同物资互相接触时彼此进入到对方中去的现象。 \n\n②特点：扩散快慢与物质的状态、温度有关；从浓度大向浓度小处扩散。 \n\n（3）布朗运动： \n\n①定义：悬浮微粒永不停息的无规则运动叫布朗运动。', 488, 488, 1, '0fc3bf35-8d51-4e99-a7f9-60acc70f1365', NULL, '2026-03-27 20:07:58');
INSERT INTO `document_chunk` VALUES (377, 6, 2, 173, '②特点：扩散快慢与物质的状态、温度有关；从浓度大向浓度小处扩散。 \n\n（3）布朗运动： \n\n①定义：悬浮微粒永不停息的无规则运动叫布朗运动。 \n\n②特点：微粒越小，现象越明显；温度越高，运动越剧烈。 \n\n③成因：微粒周围的液体（或气体）分子对微粒的撞击作用不平衡而引起的微粒的无规则运动。 \n\n 布朗运动 热运动 \n\n活动主体 固体小颗粒 分子 \n\n区别 \n\n是固体小颗粒的运动，是比分子大\n\n得多的分子团的运动，较大的颗粒不做\n\n布朗运动，但它本身的以及周围的分子\n\n仍在做热运动 \n\n是指分子的运动，分子\n\n无论大小都做热运动，热运\n\n动不能通过光学显微镜直接\n\n观察到 \n\n共同点 \n都是永不停息的无规则运动，都随温度的升高而变得更加激烈，\n\n都是肉眼所不能看见的 \n\n联系 \n布朗运动是由于小颗粒受到周围分子做热运动的撞击力而引起\n\n的，它是分子做无规则运动的反映 \n\n3.分子间存在相互作用的引力和斥力 \n\n（1）分子间总是同时存在着相互作用的引力和斥力，“分子力”是引力与斥力的合力．分子间的引', 453, 453, 1, 'fef0ea01-ce38-4eab-a747-abbcbd2bdaa1', NULL, '2026-03-27 20:07:58');
INSERT INTO `document_chunk` VALUES (378, 6, 2, 174, '围分子做热运动的撞击力而引起\n\n的，它是分子做无规则运动的反映 \n\n3.分子间存在相互作用的引力和斥力 \n\n（1）分子间总是同时存在着相互作用的引力和斥力，“分子力”是引力与斥力的合力．分子间的引\n\n力和斥力都随分子间距离的增大而减小、随分子间距离的减小而增大，但总是斥力变化得较快．如图\n\n所示。 \n\n \n\n已知阿氏常数、摩尔质量和摩尔体积求：分子质量为 ；分子的平均占有空间\n\n为 ；物质的密度为 。 \n\nAN\n\nM\nm 0\n\nAA\n\nm\n\nN\n\nM\n\nN\n\nV\nV\n\n\n0\n\nmV\n\nM\n\n\n\n\n学员专用 请勿外泄 \n\n \n\n100 中公教育学员专用资料 报名专线：400-6300-999 \n\n①当 r＝r0时，F 引＝F 斥，F＝0； \n\n②当 r<r0时，F 引和 F 斥都随距离的减小而增大，但 F 引<F 斥，F 表现为斥力； \n\n③当 r>r0时，F 引和 F 斥都随距离的增大而减小，但 F 引>F 斥，F 表现为引力； \n\n④当 r>10r0(10\n－9 m)时，F 引和 F 斥都已经十分微弱，可以认为分子间没有相互作用力(F＝0)。 \n\n（2）规律总结：', 496, 496, 1, 'c3ea7d16-94c3-48f5-a3d0-3cf377386cdd', NULL, '2026-03-27 20:07:58');
INSERT INTO `document_chunk` VALUES (379, 6, 2, 175, '（2）规律总结： \n\n①分子力：分子间引力与斥力的合力．分子间距离增大，引力和斥力均减小；分子间距离减小，\n\n引力和斥力均增大，但斥力总比引力变化得快； \n\n(2)分子势能：分子力做正功，分子势能减小；分子力做负功，分子势能增加；当分子间距为 时，\n\n分子势能最小。 \n\n例 1.分子动理论较好地解释了物质的宏观热学性质．据此可判断下列说法中正确的是（ ） \n\nA．布朗运动是指液体分子的无规则运动 \n\nB．分子间的相互作用力随着分子间距离的增大，一定先减小后增大 \n\nC．一定质量的气体温度不变时，体积减小，压强增大，说明每秒撞击单位面积器壁的分子数增\n\n多 \n\nD．气体从外界只收热量，气体的内能一定增大 \n\n二、温度、内能 \n\n1.温度： \n\n（1）摄氏温度：以标准大气压下，冰水混合物的温度为零度，沸水的温度为 100 度而建立的。 \n\n（2）热力学温标：把-273.15℃作为零度，每一度的大小与摄氏温度相同。 \n\n（3）两种温度的换算关系： \n\n2.物体的内能 \n\n（1）分子动能：大量做热运动的分子具有的动能叫做分子动能。温度是分子热运动的平均动能的\n\n标志。', 487, 487, 1, '04afcf8b-0970-496d-ac8b-e41d2150015e', NULL, '2026-03-27 20:07:58');
INSERT INTO `document_chunk` VALUES (380, 6, 2, 176, '（3）两种温度的换算关系： \n\n2.物体的内能 \n\n（1）分子动能：大量做热运动的分子具有的动能叫做分子动能。温度是分子热运动的平均动能的\n\n标志。 \n\n（2）分子势能：由分子间相对位置决定的势能叫分子势能。 \n\n \n\n①r = r0（10-10m)时，分子势能最小，为负值； \n\n②r <r0时随 r 减小，斥力做负功，分子势能增大，最大值在零距离处。 \n\n③r >r0时随 r 增大，引力做负功，分子势能增大，最大值在无穷远处。 \n\n3.内能：物体中所有分子做热运动的动能和分子势能的总和叫做物体的内能。 \n\n4.改变内能的两种方式： \n\n0r\n\nKtT )273( \n\nr O \n\nEP \n\nr0 \n\n\n\n学员专用 请勿外泄 \n\n \n\n101 中公教育学员专用资料 报名专线：400-6300-999 \n\n①做功：本质是其他形式的能和内能之间的相互转化。 \n\n②热传递：其本质是物体间内能的转移。做功和热传递在改变物体的内能上是等效的，但有本质\n\n的区别。 \n\n例 2.如图所示，甲分子固定在坐标原点 O，乙分子沿 x 轴运动，两分子间的分子势能 Ep与两分子', 485, 485, 1, '0e70cdc3-1459-45f1-b9fe-48d506413d21', NULL, '2026-03-27 20:07:58');
INSERT INTO `document_chunk` VALUES (381, 6, 2, 177, '做功和热传递在改变物体的内能上是等效的，但有本质\n\n的区别。 \n\n例 2.如图所示，甲分子固定在坐标原点 O，乙分子沿 x 轴运动，两分子间的分子势能 Ep与两分子\n\n间距离的变化关系如图中曲线所示。图中分子势能的最小值为－E0。若两分子所具有的总能量为 0，\n\n则下列说法中正确的是（ ） \n\n \n\nA.乙分子在 P 点（x＝x2）时，其动能为 E0 \n\nB.乙分子在 P 点（x＝x2）时，加速度最大 \n\nC.乙分子在 Q 点（x＝x1）时，处于平衡状态 \n\nD.乙分子的运动范围为 x≥x1 \n\n三、气体实验规律 \n\n1.气体状态参量：T、V、P \n\n \n\n2.理想气体气体实验方程（一定质量的某种气体）： \n\n \n\n（1）玻意耳定律：在密闭容器中的定量气体，在恒温压强和体积成反比关系。即 T 一定时： \n\nPV = 恒量，或 P1V1 = P2V2 \n\n \n\n（2）查理定律：在密闭容器中的定量气体，当其体积一定时，它的压强与热力学温度成正比。 \n\n即 V 一定时：P/T = 恒量，即 P1/T1 = P2/T2 \n\nVO\n\nP\n\n2T\n\nV\n\n1\nO\n\nP\n\n1T\n\n2T', 493, 493, 1, '4c357606-b56d-4339-86e1-70583a3a1778', NULL, '2026-03-27 20:07:59');
INSERT INTO `document_chunk` VALUES (382, 6, 2, 178, '即 V 一定时：P/T = 恒量，即 P1/T1 = P2/T2 \n\nVO\n\nP\n\n2T\n\nV\n\n1\nO\n\nP\n\n1T\n\n2T\n\n理想气体是不考虑分子之间作用力的气体，即内能只与温度有关，不考虑势能 \n\n气体压强的微观意义： \n\n气体压强的两个相关因素：一个是气体分子的平均动能（则温度 T 决定）；一个是气体分\n\n子的密集程度（单位时间内气体分子对容器器壁单位面积上的碰撞次数） \n\nhttp://baike.baidu.com/view/867720.htm\nhttp://baike.baidu.com/view/82174.htm\nhttp://baike.baidu.com/view/704050.htm\n\n\n学员专用 请勿外泄 \n\n \n\n102 中公教育学员专用资料 报名专线：400-6300-999 \n\n \n\n \n\n（3）盖吕萨克定律：在密闭容器中的定量气体，压强不变时，一定质量气体的体积跟热力学温度\n\n成正比。即 P 一定时： \n\nV1/V2 = T1/T2，即 V/T = 恒量 \n\n \n\n常见的盖吕萨克定律的表示图，其中 P1<P2 \n\n四、理想气体中状态方程', 493, 493, 1, '7012cc81-4188-4092-a6fe-4db7fdff7140', NULL, '2026-03-27 20:07:59');
INSERT INTO `document_chunk` VALUES (383, 6, 2, 179, '即 P 一定时： \n\nV1/V2 = T1/T2，即 V/T = 恒量 \n\n \n\n常见的盖吕萨克定律的表示图，其中 P1<P2 \n\n四、理想气体中状态方程 \n\n1.理想气体 \n\n（1）定义：为了研究方便，可以设想有一种气体，在任何温度、任何压强下都遵循气体实验定律，\n\n我们把这样的气体叫做理想气体。 \n\n（2）特点： \n\n①是一种理想模型 \n\n②理想气体的微观本质是忽略了分子力，所以理想气体的分子势能为零，理想气体的内能等于分\n\n子的总动能。 \n\n2.理想气体状态方程 \n\n（1）内容：一定质量的某种理想气体，在从一个状态变化到另一个状态时，尽管 都可\n\n能改变，但是压强跟体积的乘积与热力学温度的比值保持不变。 \n\n（2）表达式： 或 \n\n例 3．一定质量的理想气体状态变化过程如图所示，第一种变化是从 A 到 B，第二种变化是从 A\n\n到 C.比较两种变化过程，则（ ） \n\nTVp 、、\n\n2\n\n22\n\n1\n\n11\n\nT\n\nVp\n\nT\n\nVp\n C\n\nT\n\npV\n\n\nV\n\nO T\n\n1P\n\n2P', 455, 455, 1, '1c6581e2-f8fe-4633-9215-e3abfc13117c', NULL, '2026-03-27 20:07:59');
INSERT INTO `document_chunk` VALUES (384, 6, 2, 180, '到 B，第二种变化是从 A\n\n到 C.比较两种变化过程，则（ ） \n\nTVp 、、\n\n2\n\n22\n\n1\n\n11\n\nT\n\nVp\n\nT\n\nVp\n C\n\nT\n\npV\n\n\nV\n\nO T\n\n1P\n\n2P\n\nT 表示热力学温标，t 表示摄氏温标，在图中 V1<V2。左图中斜率与 V 的倒数成正\n\n比，右图中斜率与 V 的倒数不成正比关系。 \n\nP\n\nO T\n\n1V\n\n2V\n\nt\n\nP\n\nO\n\n1V\n\n2V\n\nhttp://baike.sogou.com/lemma/ShowInnerLink.htm?lemmaId=213773\nhttp://baike.sogou.com/lemma/ShowInnerLink.htm?lemmaId=213773\n\n\n学员专用 请勿外泄 \n\n \n\n103 中公教育学员专用资料 报名专线：400-6300-999 \n\n \n\nA．A 到 C 过程气体吸收的热量较多 \n\nB．A 到 B过程气体吸收的热量较多 \n\nC．两个过程气体吸收的热量一样多 \n\nD．两个过程气体内能增量不相同', 458, 458, 1, 'dd66045d-877a-4eb5-be76-c0ae6c6e30a8', NULL, '2026-03-27 20:07:59');
INSERT INTO `document_chunk` VALUES (385, 6, 2, 181, '线：400-6300-999 \n\n \n\nA．A 到 C 过程气体吸收的热量较多 \n\nB．A 到 B过程气体吸收的热量较多 \n\nC．两个过程气体吸收的热量一样多 \n\nD．两个过程气体内能增量不相同 \n\n例 4.如图所示是一定质量理想气体的 p-V 图像，若其状态由 A→B→C→A，且 A→B 为等容过程，\n\nB→C 为等压过程，C→A 为等温过程，则对该气体在 A、B、C 三个状态时的描述，正确的是( )。 \n\n \n\nA.气体分子的平均速率 vA>vB>vC \n\nB.单位体积内气体的分子数 nA=nB=nC \n\nC.气体分子在单位时间内对器壁的平均作用力 FA>FB，FB>FC \n\nD.气体分子在单位时间内对器壁单位面积碰撞的次数 NA>NB，NA>NC \n\n五、晶体与非晶体 \n\n1．晶体 \n\n（1）分类：单晶体和多晶体 \n\n①单晶体：如果一块具有规则形状的晶体，把它碾成小颗粒后，这些小颗粒仍然保持与原来整块\n\n晶体形状相似的规则外形，这样的晶体叫单晶体。单晶体具有各向异性。 \n\n②多晶体：如果一块晶体，它是由许多取向不同的单晶体颗粒组成，这样的晶体叫多晶体。多晶', 488, 488, 1, '954a0801-288b-417d-97d2-50649c4b9082', NULL, '2026-03-27 20:07:59');
INSERT INTO `document_chunk` VALUES (386, 6, 2, 182, '单晶体具有各向异性。 \n\n②多晶体：如果一块晶体，它是由许多取向不同的单晶体颗粒组成，这样的晶体叫多晶体。多晶\n\n体具有各向同性。 \n\n（2）形状：单晶体有规则的几何形状，多晶体形状不规则 \n\n（3）实例：石英、云母、明矾、食盐、硫酸铜、味精 \n\n（4）特点：有固定的熔点 \n\n说明：有些晶体沿不同方向的导热和导电性能不同，有些晶体沿不同方向的光学性质不同，这类\n\n现象称为各向异性，有些晶体沿各个方向的物理性质都是一样的，叫做各向同性。 \n\n2．非晶体 \n\n（1）形状：没有确定的几何形状 \n\n（2）实例：玻璃、蜂蜡、沥青、橡胶等 \n\n\n\n学员专用 请勿外泄 \n\n \n\n104 中公教育学员专用资料 报名专线：400-6300-999 \n\n（3）特点：没有固定的熔点 \n\n3．区分单晶体、晶体和非晶体的方法 \n\n 单晶体 多晶体 非晶体 \n\n有无确定熔点 有 有 无 \n\n几何外形 规则 不规则 不规则 \n\n物理性质 各向异性 各向同性 各向同性 \n\n说明：晶体和非晶体在在适当条件下是可以互相转化的。 \n\n例 5．关于晶体和非晶体，下列说法正确的是（ ） \n\nA．所有的晶体都表现为各向异性', 497, 497, 1, '9e292a2c-65d6-4280-8488-24a37c1676a3', NULL, '2026-03-27 20:07:59');
INSERT INTO `document_chunk` VALUES (387, 6, 2, 183, '例 5．关于晶体和非晶体，下列说法正确的是（ ） \n\nA．所有的晶体都表现为各向异性 \n\nB．所有的晶体都有确定的熔点，而非晶体没有确定的熔点。 \n\nC．晶体一定有规则的几何形状，形状不规则的金属一定是非晶体。 \n\nD．晶体可以转变为非晶体，但非晶体不可以转化为晶体。 \n\n六、液体表面张力 \n\n1.定义：如果在液体表面上任意画一条线，如图所示，线两侧的液体之间具有作用力，是引力，\n\n它的是使液体表面绷紧，叫做液体的表面张力。表面张力的方向垂直于页面分界线，又与液面相切。 \n\n \n\n \n\n2.形成表面张力的原因：在液体的表层内，分子间距大，分子间的相互作用力表现为引力。 \n\n例 6．关于液体的表面张力，下列说法不正确的是（ ） \n\nA．表面张力是液体内部各部分之间的相互作用力 \n\nB．液体表面层分子的分布比内部稀疏，分子力表现为引力 \n\nC．液体的表面张力随温度的升高而减小 \n\nD．液体的表面张力随温度的升高而增大 \n\nE．表面张力的方向与液面垂直 \n\n七、液晶 \n\n1.定义：有些化合物像液体一样具有流动性，而其光学性质与某些晶体相似，具有各向异性，人', 482, 482, 1, '2dcbdd73-35c4-4a81-adae-5969d3182f1e', NULL, '2026-03-27 20:07:59');
INSERT INTO `document_chunk` VALUES (388, 6, 2, 184, '度的升高而减小 \n\nD．液体的表面张力随温度的升高而增大 \n\nE．表面张力的方向与液面垂直 \n\n七、液晶 \n\n1.定义：有些化合物像液体一样具有流动性，而其光学性质与某些晶体相似，具有各向异性，人\n\n们把这些化合物叫液晶，它是一种介于固态和液态之间的中间态物质。 \n\n2.特点： \n\n（1）具有流动性 \n\n\n\n学员专用 请勿外泄 \n\n \n\n105 中公教育学员专用资料 报名专线：400-6300-999 \n\n（2）其光学性质具有各向异性 \n\n（3）不是所有物质都具有液晶态 \n\n（4）液晶分子的空间排列是不稳定的 \n\n例 7．下列有关液晶的说法，正确的是（ ） \n\nA．液晶具有流动性 \n\nB．液晶具有各向异性 \n\nC．液晶具有稳定的空间排列规律 \n\nD．液晶就是液态的晶体 \n\n八、热力学三大定律与永动机 \n\n1.热力学第一定律 \n\n内容：一个热力学系统的内能增量等于外界向它传递的热量与外界对它所做的功的和。它揭示了\n\n能量的转化和守恒定律。 \n\n表达式： \n\n \n\n例 8.某一密闭容器内装有一定质量的理想气体，起初处于状态甲，现设法降低气体的温度同时增', 481, 481, 1, '7c931566-2066-4f9a-a0ab-3ee333b5b808', NULL, '2026-03-27 20:08:00');
INSERT INTO `document_chunk` VALUES (389, 6, 2, 185, '它揭示了\n\n能量的转化和守恒定律。 \n\n表达式： \n\n \n\n例 8.某一密闭容器内装有一定质量的理想气体，起初处于状态甲，现设法降低气体的温度同时增\n\n大气体的压强，达到状态乙，则关于该气体，下列判断错误的是（ ） \n\nA.状态甲的密度比状态乙的大 \n\nB.状态甲的内能比状态乙的大 \n\nC.状态甲的分子平均动能比状态乙的大 \n\nD.从状态甲变化到状态乙的过程中，放出的热量多于外界对气体做的功 \n\n2.热力学第二定律 \n\n克劳修斯：不可能使热量由低温物体传递到高温物体，而不引起其他变化（按热传导的方向性表\n\n述） \n\n开尔文：不可能从单一热源吸收热量并把它全部用来做功，而不引起其他变化。 \n\n3.热力学第三定律：热力学零度不可能达到。 \n\n \n\n4.永动机 \n\n（1）第一类永动机 \n\n①概念：不消耗能量而对外做功的机器 \n\nWQU \n\n热力学温度又被称为绝对温度，是热力学和统计物理中的重要参数之一。一般所说的绝\n\n对零度指的便是 0K，对应零下 273.15 摄氏度。 \n\n注意 \n\n为正表示内能增加。在理想气体中，温度不变， 不变。', 475, 475, 1, 'f52ee073-adb6-441a-a191-4f02f9f0ddd8', NULL, '2026-03-27 20:08:00');
INSERT INTO `document_chunk` VALUES (390, 6, 2, 186, '一般所说的绝\n\n对零度指的便是 0K，对应零下 273.15 摄氏度。 \n\n注意 \n\n为正表示内能增加。在理想气体中，温度不变， 不变。 \n\nQ 为正表示吸收热量。绝热情况下，Q 不变。 \n\nW 为正表示外界对气体做正功。等容变化，W 不变。 \n\nU U\n\nhttp://baike.baidu.com/view/78147.htm\nhttp://baike.baidu.com/view/23658.htm\nhttp://baike.baidu.com/view/23658.htm\n\n\n学员专用 请勿外泄 \n\n \n\n106 中公教育学员专用资料 报名专线：400-6300-999 \n\n②原因：违背了能量的转化和守恒定律 \n\n（2）第二类永动机 \n\n①概念：只能从单一热源吸收热量并把它全部用来做功，而不引起其他变化的热机。 \n\n②原因：热机的效率不可能达到 100%。 \n\n \n\n\n\n学员专用 请勿外泄 \n\n \n\n107 中公教育学员专用资料 报名专线：400-6300-999 \n\n第四章 机械振动与机械波 \n\n第一节 机械振动 \n\n \n\n一、机械振动', 482, 482, 1, '3ba944dd-ca66-4986-bd08-16a6dd257732', NULL, '2026-03-27 20:08:00');
INSERT INTO `document_chunk` VALUES (391, 6, 2, 187, '学员专用 请勿外泄 \n\n \n\n107 中公教育学员专用资料 报名专线：400-6300-999 \n\n第四章 机械振动与机械波 \n\n第一节 机械振动 \n\n \n\n一、机械振动 \n\n1.定义：物体（或物体的一部分）在某一中心位置（也称平衡位置）两侧往复运动，这种运动叫\n\n做机械振动，简称振动。 \n\n2.平衡位置 \n\n做机械振动的物体原来静止或最终停止振动后振子所在的位置。 \n\n3.简谐运动 \n\n（1）定义：如果质点的位移与时间的关系遵循正弦函数的规律，即它的正弦图像是一条正弦曲线，\n\n这样的振动叫做简谐运动。 \n\n（2）描述简谐运动的物理量 \n\na.全振动：振动质点从运动到某一位置开始到再一次以相同的运动速度经过同一位置的振动过程。 \n\nb.位移 ：由平衡位置指向振动质点所在位置的有向线段，位移是矢量。 \n\nc.振幅 ：振子偏离平衡位置的最大距离。振幅是标量，单位是米。 \n\nd.周期 和频率 ：物体完成一次全振动所需的时间叫周期，频率等于单位时间内完成全振动的\n\n次数，他们是表示振动快慢的物理量，二者互为倒数关系：', 461, 461, 1, 'd183e4d9-cf40-413f-b730-efb206316b3e', NULL, '2026-03-27 20:08:00');
INSERT INTO `document_chunk` VALUES (392, 6, 2, 188, '振幅是标量，单位是米。 \n\nd.周期 和频率 ：物体完成一次全振动所需的时间叫周期，频率等于单位时间内完成全振动的\n\n次数，他们是表示振动快慢的物理量，二者互为倒数关系： \n\ne.相位与相位差：相位是用来描述周期性运动的物体在各个时刻所处的不同状态的物理量，用表\n\n示。时的相位，叫做初相位。两个具有相同频率的简谐运动的相位之差叫做相位差，用表示，，即表\n\n示后一个相位比前一个相位超前（3）简谐运动的表达式 )sin(   tAx \n\n（4）回复力：振动物体受到的总是指向平衡位置的力叫做回复力。它是效果力。 \n\n（5）简谐运动的受力特点及运动特点： \n\n①受力特征： \n\n \n②运动特征： \n\n加速度 ，方向与位移方向相反，总是指向平衡位置。简谐运动是一种变加速运动，在平\n\n衡位置时，速度最大，加速度为零；在最大位移处时，速度为零，加速度最大。 \n\n例 1.做简谐运动的质点，先后连续经过同一点时（非最大位移处），下列物理量哪些是不同的（ ） \n\nA.速度 B.加速度 C.动能 D.势能 \n\n（6）简谐运动的图像 \n\nx\n\nA\n\nT f\n\nf\nT\n\n1\n\n\nkxF \n\nm', 497, 497, 1, '338deef3-d94e-432a-8b43-3580874c3b0b', NULL, '2026-03-27 20:08:00');
INSERT INTO `document_chunk` VALUES (393, 6, 2, 189, '经过同一点时（非最大位移处），下列物理量哪些是不同的（ ） \n\nA.速度 B.加速度 C.动能 D.势能 \n\n（6）简谐运动的图像 \n\nx\n\nA\n\nT f\n\nf\nT\n\n1\n\n\nkxF \n\nm\n\nkx\na \n\n\n\n学员专用 请勿外泄 \n\n \n\n108 中公教育学员专用资料 报名专线：400-6300-999 \n\n如图所示为一弹簧振子做简谐运动的图像。它反映的了振子的位移随时间变化的规律（其图像为\n\n正弦曲线）。 \n\n \n\n②根据简谐运动的规律，利用该图像可以得出以下判定： \n\na.振幅 A、周期 T 以及各时刻振子的位置。 \n\nb.各时刻回复力、加速度、速度、位移的方向。 \n\nc.某段时间内位移、回复力、加速度、速度、动能、势能的变化情况。 \n\nd.某段时间内弹簧振子经过的路程。 \n\n例 2.某单摆做小角度摆动，其振动图像如图所示，则关于摆球的速率 v 和悬线对摆球的拉力 F 说法\n\n正确的是（ ） \n\n \n\nA.t1时刻 v 最大，F 最小 B.t2时刻 v 最大，F 最大 \n\nC.t3时刻 v 为零，F 最大 D.t4时刻 v 为零，F 最小 \n\n二、单摆', 491, 491, 1, 'a40c150e-894e-4a45-87a8-70eff03ca772', NULL, '2026-03-27 20:08:00');
INSERT INTO `document_chunk` VALUES (394, 6, 2, 190, '力 F 说法\n\n正确的是（ ） \n\n \n\nA.t1时刻 v 最大，F 最小 B.t2时刻 v 最大，F 最大 \n\nC.t3时刻 v 为零，F 最大 D.t4时刻 v 为零，F 最小 \n\n二、单摆 \n\n1.定义：在细线的一端挂上一个小球，另一端固定在悬点上，如果线的伸缩和质量可以忽略，球\n\n的直径比线长短得多，这样的装置叫做单摆。 \n\n \n\n2.回复力 \n\n单摆的回复力为摆球的重力沿切线方向的分力。 \n\n当摆线最大偏角 时，有 \n\n，即 和 成正比，比例系数 \n\n \n\n3.周期 \n\n 5\n\nx\nl\n\nmg\n\nl\n\nx\nmgmgF  sin回 回F x\n\nl\n\nmg\nk \n\n注意： \n\n单摆的回复力是由其所受合力的某一分力来提供的，所以“单摆振动的回复力就是摆球\n\n所受的合力”这一说法是错误的。 \n\n单摆做简谐运动的条件：单摆在摆角时做简谐运动。 \n\n \n\n\n\n学员专用 请勿外泄 \n\n \n\n109 中公教育学员专用资料 报名专线：400-6300-999 \n\n单摆的周期公式 \n\n \n\n三、弹簧振子', 465, 465, 1, '81f148f7-cb03-4d1e-a328-3fec62eacbf9', NULL, '2026-03-27 20:08:01');
INSERT INTO `document_chunk` VALUES (395, 6, 2, 191, '学员专用 请勿外泄 \n\n \n\n109 中公教育学员专用资料 报名专线：400-6300-999 \n\n单摆的周期公式 \n\n \n\n三、弹簧振子 \n\n1.定义：由一个一端固定、质量可以忽略的轻弹簧和与它另一端（自由端）相连的一个不易变形\n\n的小球组成的或与此类似的系统称为弹簧振子（有时也将系统中的小球称为弹簧振子，或简称振子）。 \n\n2.特点：它是一种理想化的模型。 \n\n3.周期：\nk\n\nm\nT 2 \n\n弹簧振子的周期和频率只取决于弹簧振子的劲度系数和振子的质量，与其放置的环境和放置的方\n\n式无任何关系。 \n\n \n\n例 3.李老师用弹簧和物块做成如图所示的弹簧振子演示振动图像。课前准备实验时，李老师觉得\n\n该弹簧振子的频率过小，想让振子的频率增大一倍，为此他将（ ） \n\n \n\nA.换一个质量为原质量两倍的物块 \n\nB.换一个质量为原质量一半的物块 \n\nC.弹簧长度减去一半 \n\nD.弹簧长度减去 3/4 \n\n四、阻尼振动 \n\n1.定义：振动系统如果受摩擦力或其他阻力的作用，振幅逐渐减小的振动，叫做阻尼振动。', 458, 458, 1, 'd03f1972-1937-4363-a928-1ad3ce4b2a23', NULL, '2026-03-27 20:08:01');
INSERT INTO `document_chunk` VALUES (396, 6, 2, 192, 'B.换一个质量为原质量一半的物块 \n\nC.弹簧长度减去一半 \n\nD.弹簧长度减去 3/4 \n\n四、阻尼振动 \n\n1.定义：振动系统如果受摩擦力或其他阻力的作用，振幅逐渐减小的振动，叫做阻尼振动。 \n\n2.特点：阻尼振动周期不变，只是振幅逐渐减小，能量逐渐减少。 \n\n \n\n五、受迫振动 \n\ng\n\nl\nT 2\n\n注意： \n\n有阻尼的振动不一定是阻尼振动。因为所谓阻尼振动是指振幅越来越小，即振动的能\n\n量越来越少的振动。若在振动过程中受到阻力，但在其间又能及时补充能量，仍可维持振\n\n幅不变，这就不是阻尼振动。 \n\n \n\n如某一弹簧组振子做简谐运动时的周期为 T，不管把它放在地球上、月球上还是卫星中；\n\n是水平放置、倾斜放置还是竖直放置；振幅是大，是小，它的周期就都是 T \n\n注意： \n\n ①单摆的摆长 是指悬点到球心间的距离。 \n\n ②单摆的振动周期与摆球质量无关，只与摆长和所处位置的重力加速度有关。 \n\nl\n\n\n\n学员专用 请勿外泄 \n\n \n\n110 中公教育学员专用资料 报名专线：400-6300-999', 460, 460, 1, '80d2ff5c-9bea-44e9-b691-c6324e638980', NULL, '2026-03-27 20:08:01');
INSERT INTO `document_chunk` VALUES (397, 6, 2, 193, '②单摆的振动周期与摆球质量无关，只与摆长和所处位置的重力加速度有关。 \n\nl\n\n\n\n学员专用 请勿外泄 \n\n \n\n110 中公教育学员专用资料 报名专线：400-6300-999 \n\n1.定义：如果系统受到周期性外力的作用，就可以利用外力对系统做功，补偿系统损失，使系统\n\n持续地震动下去，这样的振动称为受迫振动。 \n\n2.特点：物体做受迫振动时，振动稳定后的频率等于驱动力的频率，跟物体的固有频率无关 \n\n \n\n六、共振 \n\n1.定义：受迫振动的物体其振动周期（或频率）取决于驱动力的周期，并且当驱动力的周期（或\n\n频率）与物体的固有周期（或频率）相等时，受迫振动的振幅最大，这种现象叫做共振。 \n\n2.共振的条件： \n\n3.共振曲线： \n\n受迫振动的振幅随驱动力频率变化的图线，叫做共振曲线，如图所示： \n\n \n\n当驱动力的频率等于做受迫振动物体的固有频率即 时，受迫振动的振幅最大。 \n\n例 4.如图为高中物理教科书中描述的 1 个实验，A 球先发生振动。该实验可观察到的物理现象和\n\n可用于说明的物理问题分别是（ ）。', 463, 463, 1, '95dda565-c334-438b-9339-d90fd3d4a5af', NULL, '2026-03-27 20:08:01');
INSERT INTO `document_chunk` VALUES (398, 6, 2, 194, '例 4.如图为高中物理教科书中描述的 1 个实验，A 球先发生振动。该实验可观察到的物理现象和\n\n可用于说明的物理问题分别是（ ）。 \n\n \n\nA.小球 D 的振幅最大，小球 C 的振幅最小，摆长与振幅的关系 \n\nB.小球 D 的振幅最小，小球 C 的振幅最大，摆场与振幅的关系 \n\nC.小球 B 的振幅最大，共振现象 \n\nD.小球 B 和 C 的振幅相同，受迫振动现象 \n\n \n\n固驱 ff \n\n0ff \n\n驱动力：加在振动系统上的周期性的外力 \n\n\n\n学员专用 请勿外泄 \n\n \n\n111 中公教育学员专用资料 报名专线：400-6300-999 \n\n第二节 机械波 \n\n \n\n一、机械波的产生和特点 \n\n1.机械波的产生 \n\n机械振动在介质中传播，形成了机械波。机械波产生的条件有两个：一是要有做机械振动的物体\n\n作为波源，二是要有能够传播机械振动的介质。 \n\n2.横波和纵波 \n\n质点的振动方向与波的传播方向相互垂直的波叫横波。在横波中，凸起的最高处叫波峰，凹下的\n\n最低处叫波谷。 \n\n质点的振动方向与波的传播方向在同一直线上的波叫纵波。在纵波中，质点分布最密的位置叫密', 492, 492, 1, 'cf4b486c-9f4d-4b88-bac1-9d25ebf3c00a', NULL, '2026-03-27 20:08:01');
INSERT INTO `document_chunk` VALUES (399, 6, 2, 195, '在横波中，凸起的最高处叫波峰，凹下的\n\n最低处叫波谷。 \n\n质点的振动方向与波的传播方向在同一直线上的波叫纵波。在纵波中，质点分布最密的位置叫密\n\n部，分布最疏的位置叫疏部。 \n\n 横波 纵波 \n\n概念 \n在波动中，质点的振动方向和波的传播方\n\n向相互垂直 \n\n在波动中，质点的振动方向和波的传播方\n\n向在一条直线上 \n\n介质 只能在固体介质中传播 在固体、液体和气体介质中均能传播 \n\n特征 在波动中交替、间隔出现波峰和波谷 在波动中交替、间隔出现密部和疏部 \n\n例 1.下列有关横波与纵波的说法中正确的是（ ） \n\nA．沿水平方向传播的波为横波 \n\nB．纵波可以在固态、液态、气态介质中传播 \n\nC．纵波与横波不可以同时在同一介质中传播 \n\nD．凡是振动方向与波传播方向在同一条直线上的波都是纵波 \n\nE．横波只能在固体中传播 \n\n3.机械波的特点 \n\n（1）每一质点都以它的平衡位置为中心做简谐运动；后一质点的振动总是落后于带动它的前一质\n\n\n\n学员专用 请勿外泄 \n\n \n\n112 中公教育学员专用资料 报名专线：400-6300-999 \n\n点的振动。', 481, 481, 1, 'ac472492-1aac-4850-82f6-435b72296bc5', NULL, '2026-03-27 20:08:01');
INSERT INTO `document_chunk` VALUES (400, 6, 2, 196, '质点都以它的平衡位置为中心做简谐运动；后一质点的振动总是落后于带动它的前一质\n\n\n\n学员专用 请勿外泄 \n\n \n\n112 中公教育学员专用资料 报名专线：400-6300-999 \n\n点的振动。 \n\n（2）波传播的只是振动这种运动形式，介质中的质点并不随波迁移。波是传递能量的一种方式。 \n\n二、波的传播与波的图像 \n\n1.描述机械波的物理量 \n\n（1）波长 ：在振动过程中，振动相位总是相同的两个相邻质点间的距离叫波长。 \n\n（2）频率：波的频率由波源决定，在任何介质中频率不变。 \n\n（3）波速：单位时间内振动向外传播的距离。 \n\n \n\n（4）波速与波长和频率的关系： \n\n例 2.一束单色光经由空气射入水中，如图所示，这束光的（ ） \n\n \n\nA.速度变小，波长变短 B.速度不变，波长变短 \n\nC.频率变大，波长变长 D.频率不变，波长变长 \n\n2.波的图像 \n\n（1）波的图像：如图所示为一列横波的图像。反映了在波的传播过程中，某一时刻介质中各质点\n\n的位移在空间的分布。 \n\n \n\n根据机械波的传播规律，利用波的图像可以得到以下判定：', 473, 473, 1, 'c2a0d079-a4d0-455b-9da0-87744ddeeb9d', NULL, '2026-03-27 20:08:02');
INSERT INTO `document_chunk` VALUES (401, 6, 2, 197, '反映了在波的传播过程中，某一时刻介质中各质点\n\n的位移在空间的分布。 \n\n \n\n根据机械波的传播规律，利用波的图像可以得到以下判定： \n\n①介质中质点的振幅 A 和波长，及该时刻各质点的位移和加速度的方向。 \n\n②根据波的传播方向确定该时刻各质点的振动方向，画出 t 前后的波形图。 \n\n③根据某一质点的振动方向确定波的传播方向。 \n\n（2）波的图象特点 \n\n①质点振动 nT（波传播 nλ）时，波形不变． \n\n②在波的传播方向上，当两质点平衡位置间的距离为 nλ 时(n＝1，2，3…)，它们的振动步调总相\n\n\n\nfv \n\n机械波在介质中的传播速率是由介质本身的性质决定的。同一列波，在不同的介质中，波\n\n速是不同的。 \n\n \n\n\n\n学员专用 请勿外泄 \n\n \n\n113 中公教育学员专用资料 报名专线：400-6300-999 \n\n同；当两质点平衡位置间的距离为(2n＋1)\nλ\n\n2\n(n＝0，1，2，3…)时，它们的振动步调总相反． \n\n③波源质点的起振方向决定了它后面的质点的起振方向，各质点的起振方向与波源的起振方向相\n\n同．', 474, 474, 1, '56ce1361-b071-4e86-858e-e6e964dba443', NULL, '2026-03-27 20:08:02');
INSERT INTO `document_chunk` VALUES (402, 6, 2, 198, '质点平衡位置间的距离为(2n＋1)\nλ\n\n2\n(n＝0，1，2，3…)时，它们的振动步调总相反． \n\n③波源质点的起振方向决定了它后面的质点的起振方向，各质点的起振方向与波源的起振方向相\n\n同． \n\n例 3．简谐横波某时刻的波形如图所示．a 为介质中的一个质点，由图象可知（ ） \n\n \n\nA．质点 a 的加速度方向一定沿 y 轴负方向 \n\nB．质点 a 的速度方向一定沿 y 轴负方向 \n\nC．经过半个周期，质点 a 的位移一定为负值 \n\nD．经过半个周期，质点 a 通过的路程一定为 2A \n\nE．若波沿 x 轴正方向传播，则该时刻质点 a 振动方向向下 \n\n三、波的干涉和衍射 \n\n1.波的衍射 \n\n（1）定义：波绕过障碍物继续传播的现象。 \n\n（2）产生明显衍射现象的条件：障碍物或孔的尺寸比波长更小或与波长相差不多。 \n\n \n\n例 4.图 1 所示为高中物理某教科书描述的一个演示实验。该实验用于学习的物理知识是 \n\n \n\nA.衍射 B.干涉 C.折射 D.偏振 \n\n衍射是波特有的现象，一切波都会产生衍射现象，当波碰到障碍物时，衍射现象总是存在\n\n的，只是有的明显有的不明显而已。', 496, 496, 1, '53c60ecc-af00-487e-afe1-3a0adf0546c4', NULL, '2026-03-27 20:08:02');
INSERT INTO `document_chunk` VALUES (403, 6, 2, 199, '验用于学习的物理知识是 \n\n \n\nA.衍射 B.干涉 C.折射 D.偏振 \n\n衍射是波特有的现象，一切波都会产生衍射现象，当波碰到障碍物时，衍射现象总是存在\n\n的，只是有的明显有的不明显而已。 \n\n\n\n学员专用 请勿外泄 \n\n \n\n114 中公教育学员专用资料 报名专线：400-6300-999 \n\n2.波的叠加 \n\n几列波相遇时，每列波都能够保持各自原来的传播方向继续传播而不互相干扰。只是在重叠的区\n\n域里，任一质点的总位移等于各列波分别引起的位移的矢量和。 \n\n3.波的干涉 \n\n（1）定义：频率相同的两列波叠加时，某些区域的振幅加大，某些区域的振幅减小，这种现象叫\n\n做波的干涉。 \n\n（2）产生稳定的干涉现象的条件：两列波的频率相同 \n\n \n\n3.多普勒效应 \n\n（1）定义：由于波源和观察者之间的相对运动，使观察者感到波的频率发生变化的现象。 \n\n（2）当波源与观察者有相对运动时，如果二者相互接近，观察者接收到的频率增大；如果二者远\n\n离，观察者接收到的频率减小。 \n\n \n\n四、振动图像与波动图像 \n\n1.振动图像和波动图像对比 \n\n 振动图像 波动图像 \n\n曲线\n\n形状', 495, 495, 1, 'b46f33a5-3638-444f-a696-8d214a164360', NULL, '2026-03-27 20:08:02');
INSERT INTO `document_chunk` VALUES (404, 6, 2, 200, '四、振动图像与波动图像 \n\n1.振动图像和波动图像对比 \n\n 振动图像 波动图像 \n\n曲线\n\n形状 \n\n \n\n研究\n\n对象 \n\n一个振动质点 沿波传播的所有质点 \n\n研究\n\n内容 \n\n一个质点的位移随时间\n\n变化的规律 \n\n某时刻所有质点相对于平\n\n衡位置的空间分布规律 \n\n注意：发生多普勒效应时，波源本身的频率并不发生变化，只是观察者接收到的频率发生\n\n了变化。 \n\n多普勒效应是所有波动过程共有的特征。 \n\n \n\n对波的干涉图样的理解： \n\na.稳定干涉中，振动加强区域或振动减弱区域的空间位置是不变的。 \n\nb.加强区域中心质点的振幅等于两列波振幅之和，即振动加强了；减弱区域中心质点的振\n\n幅等于两列波的振幅之差，即振动减弱了。 \n\nc.振动加强点的振幅大，振动能量大，但位移不一定总是大。 \n\n \n\n\n\n学员专用 请勿外泄 \n\n \n\n115 中公教育学员专用资料 报名专线：400-6300-999 \n\n图线\n\n变化 \n\n随时间的推移图像延续\n\n但已有形状不变 \n\n随着时间的推移，图像沿\n\n波的方向平移 \n\n2.波的传播方向与各质点的振动方向的互相确定', 483, 483, 1, 'a0c68022-eb49-4fa7-aa01-175f39a7ee67', NULL, '2026-03-27 20:08:02');
INSERT INTO `document_chunk` VALUES (405, 6, 2, 201, '料 报名专线：400-6300-999 \n\n图线\n\n变化 \n\n随时间的推移图像延续\n\n但已有形状不变 \n\n随着时间的推移，图像沿\n\n波的方向平移 \n\n2.波的传播方向与各质点的振动方向的互相确定 \n\n方法一：上下坡法 \n\n如图所示，将正弦波的波形想象成一条坡路，当顺着波的传播方向行走时，“上坡”的各质点的\n\n振动方向向下，“下坡”的各质点的振动方向向上，可记为“上坡下，下坡下”。 \n\n \n\n方法二：特殊点法 \n\n由波的传播特点可知，后震动的质点总是重复与其相邻的先震动的质点的运动，而当质点处于波\n\n峰和波谷位置瞬间，速度为零，因此，若知道波的传播方向而判断某质点的振动方向时，可找到与该\n\n点距离最近的波峰或波谷，根据它与波峰和波谷的关系来判断其振动方向。 \n\n如图甲所示，若波向右传播， 点在 点前面，则 向上运动；如图乙所示，若波向左传播，\n\n点在 点前面，则 向下运动。即沿波的传播方向看过去，后面的质点总是重复前面质点的运动。 \n\n \n\n例 5.周期为 2.0s 的简谐横波沿 轴传播，该波在某时刻的图像如图所示，此时质点 沿 轴负方\n\n向运动，则该波（ ）', 486, 486, 1, '97410bbb-62f7-4dc3-8245-f018bb71a614', NULL, '2026-03-27 20:08:02');
INSERT INTO `document_chunk` VALUES (406, 6, 2, 202, '例 5.周期为 2.0s 的简谐横波沿 轴传播，该波在某时刻的图像如图所示，此时质点 沿 轴负方\n\n向运动，则该波（ ） \n\n \n\nA.沿 轴正方向传播，波速 \n\nB.沿 轴正方向传播，波速 \n\nC.沿 轴负方向传播，波速 \n\nD.沿 轴负方向传播，波速 \n\n \n\np p p p\n\np p\n\nx p y\n\nx\n\nx\n\nx\n\nx\n\n\n\n学员专用 请勿外泄 \n\n \n\n116 中公教育学员专用资料 报名专线：400-6300-999 \n\n第五章 光学 \n\n第一节 几何光学 \n\n \n\n一、光的直线传播 \n\n1.光在真空中的传播速度 c=3×108 m/s，光在介质中的传播速度为： ，(n 为介质的折射率)，\n\n光在同一种均匀介质中沿直线传播。 \n\n \n\n2.日食和月食 \n\n人位于月球的本影（图 1 中区域 3）内能看到日全食，位于月球的半影内（图 1 中区域 2、4）能\n\n看到日偏食，位于月球本影的延伸区域（即“伪本影”，图 1 中区域 5）能看到日环食；当月球全部\n\n进入地球的本影区域（图 2 中区域 3）时，人可看到月全食，月球部分进入地球的半影区域（图 2 中', 488, 488, 1, '9cc7b836-846c-4562-882e-2a26c0306716', NULL, '2026-03-27 20:08:03');
INSERT INTO `document_chunk` VALUES (407, 6, 2, 203, '看到日偏食，位于月球本影的延伸区域（即“伪本影”，图 1 中区域 5）能看到日环食；当月球全部\n\n进入地球的本影区域（图 2 中区域 3）时，人可看到月全食，月球部分进入地球的半影区域（图 2 中\n\n区域 2、4）时，看到的是月偏食。 \n\n \n\n图 1 日食 图 2 月食 \n\n \n\n \n\n二、光的反射 \n\n光线入射到两种介质的界面上时，其中一部分光线在原介质中改变传播方向的现象。 \n\n1.光的反射定律 \n\n反射光线、入射光线和法线在同一平面内，反射光线和入射光线分居于法线两侧，反射角等于入\n\n射角。（简记：共面、法线两侧、等角） \n\nc\nv\n\nn\n\n\n补充：影是光被不透光的物体挡住所形成的暗区。影可分为本影和本影，在本影区\n\n域内完全看不到光源发出的光，在半影区域内只能看到光源的某部分发出的光。点光源\n\n只形成本影，非点光源一般会形成本影和半影，本影区域的大小与光源的面积有关，发\n\n光面积越大，本影区域越小。 \n\n举例：小孔成像、影的形成，日食和月食都是光的直线传播的例证。 \n\n\n\n学员专用 请勿外泄 \n\n \n\n117 中公教育学员专用资料 报名专线：400-6300-999', 496, 496, 1, '9f83cabf-b566-4bab-8cc1-2806bcff4214', NULL, '2026-03-27 20:08:03');
INSERT INTO `document_chunk` VALUES (408, 6, 2, 204, '举例：小孔成像、影的形成，日食和月食都是光的直线传播的例证。 \n\n\n\n学员专用 请勿外泄 \n\n \n\n117 中公教育学员专用资料 报名专线：400-6300-999 \n\n2.反射的类型：漫反射、镜面反射 \n\n \n\n3.应用：平面镜成像 \n\n成像特点：等大、正立的虚像，物、像关于镜面对称。 \n\n三、光的折射和全反射 \n\n光由一种介质射入到另种介质时，在两种介质的界面上将发生光的传播方向改变的现象叫做光的\n\n折射。 \n\n1.光的折射定律 \n\n折射光线、入射光线和法线共面、折射光线和入射光线分居法线两侧、且光路可逆。 \n\n2.折射率：光从真空射入某种介质，入射角的正弦与折射角正弦之比为定值，其值叫做介质的折\n\n射率，表示为\n\n \n\n光疏和光密：两种介质相比较，折射率 n 较大的介质称为光密介质，n 较小的介质称为光疏介质。\n\n（从一种介质进入另一种介质，如果折射光线相较于入射光线偏向法线，即从光疏进入光密。） \n\n \n\n \n\n3.全反射 \n\n（1）全反射现象：光从光密介质入射到光疏介质时，在界面处一部分光被反射回原介质中，一部', 467, 467, 1, 'b43fedec-40e6-47fb-acf9-a963b20f5147', NULL, '2026-03-27 20:08:03');
INSERT INTO `document_chunk` VALUES (409, 6, 2, 205, '） \n\n \n\n \n\n3.全反射 \n\n（1）全反射现象：光从光密介质入射到光疏介质时，在界面处一部分光被反射回原介质中，一部\n\n分光被折射到另一种介质中，随着入射角的增大，折射角逐渐增大，且折射光线越来越弱，反射光线\n\n越来越强，当入射角增大到某一角度，使折射角达到 90°时，折射光线完全消失，只剩下反射光线。 \n\n（2）临界角：折射角等于 90°时的入射角，某种介质的临界角用 C 表示，sin 。 \n\n（3）全反射发生的条件 \n\n①光由光密介质射向光疏介质；②入射角≥临界角。 \n\n例 1.如图所示，空气中有一折射率为 2 的玻璃柱体，其横截面是圆心角为 90°，半径为 R 的扇\n\n形 OAB，一束平行光平行于横截面，以 45°入射角照射到 OA 上，OB 不透光，若只考虑首次入射到\n\n圆弧上的光，则\n⌒\nAB 上有光透出部分弧长为（ ） \n\nv\n\nc\nn \n\n2\n\n1\n\nsin\n\nsin\n\n\n\n\n\nn\nC\n\n1\n\n\n镜面反射是入射光线是平行光线时，反射到光滑的镜面，又以平行光线出去。 \n\n漫反射是，入射光线是平行光线时，反射到粗糙的物体，反射光线向各个方向出去。', 493, 493, 1, '6a59fe66-cd4a-413f-8478-4f612e3d093b', NULL, '2026-03-27 20:08:03');
INSERT INTO `document_chunk` VALUES (410, 6, 2, 206, '漫反射是，入射光线是平行光线时，反射到粗糙的物体，反射光线向各个方向出去。 \n\n\n\n学员专用 请勿外泄 \n\n \n\n118 中公教育学员专用资料 报名专线：400-6300-999 \n\n \n\nA. πR\n6\n\n1\n B. πR\n\n4\n\n1\n C. πR\n\n3\n\n1\n D. πR\n\n12\n\n5\n \n\n四、光的色散 \n\n白光通过三棱镜会形成由红到紫七种色光组成的彩色光谱。 \n\n \n\n（1）色散的实质是同一介质对不同色光的折射率不同，从红光到紫光，折射率依次增大。 \n\n（2）单色光的颜色是由频率决定的，红光的频率最小，紫光的频率最大，不同介质中光的频率不\n\n变。 \n\n（3）不同频率的色光在真空中的传播速度相同，同一介质中，红光的速度最大，紫光的速度最小。 \n\n \n\n \n\n \n\n补充：频率取决于振源，波速取决于介质，波长取决于频率和介质。 \n\n偏折角指的是折射光线与原来的入射光线的延长线之间的夹角（如上图所标注的角\n\n）。 \n\n从红光→紫光，总结以下六个结论： \n\n1.频率依次增大； 2.同一介质中的传播速度，依次减小；', 462, 462, 1, '61a3452f-5e38-499b-8a65-6def7c37172c', NULL, '2026-03-27 20:08:03');
INSERT INTO `document_chunk` VALUES (411, 6, 2, 207, '偏折角指的是折射光线与原来的入射光线的延长线之间的夹角（如上图所标注的角\n\n）。 \n\n从红光→紫光，总结以下六个结论： \n\n1.频率依次增大； 2.同一介质中的传播速度，依次减小； \n\n3.同一介质中的波长，依次减小； 4.经过三棱镜的偏折角，依次增大； \n\n5.同一介质中的折射率，依次增大 6.同一种介质的临界角依次减小。（临界角越小，\n\n从光密进入光疏越容易发生全反射，紫光最容易发生全反射。） \n\n总结：以上结论中三个减小、三个增大，灵活记忆。 \n\n\n\n红光波长最长 \n\n紫光频率最高 \n\n \n\n\n\n学员专用 请勿外泄 \n\n \n\n119 中公教育学员专用资料 报名专线：400-6300-999 \n\n第二节 波动光学 \n\n \n\n一、光的干涉 \n\n1.波的干涉：频率相同的两列波叠加时，空间某些区域的振幅加强，某些区域的振幅减弱。 \n\n \n\n2.双缝干涉 \n\n（1）亮条纹与暗条纹 \n\n光屏上某点到双缝的路程差（光程差）为波长的整数倍时，该点出现亮条纹。Δr=nλ(n=0、1.2.3……)', 450, 450, 1, 'fc8ec91c-b0c5-4dee-b791-10282bfd8cfb', NULL, '2026-03-27 20:08:03');
INSERT INTO `document_chunk` VALUES (412, 6, 2, 208, '2.双缝干涉 \n\n（1）亮条纹与暗条纹 \n\n光屏上某点到双缝的路程差（光程差）为波长的整数倍时，该点出现亮条纹。Δr=nλ(n=0、1.2.3……) \n\n光屏上某点到双缝的路程差（光程差）为半波长的奇数倍时，该点出现暗条纹。Δr=(2n+1)λ/2（n=0、\n\n1.2.3……） \n\n（2）条纹间距： \nd\n\nL\nx 注：L>>d \n\n \n\n例 1.某同学用单色光进行双缝干涉实验。在原上观察到如图甲所示的条纹，仅改变一个实验条件\n\n后，观察到的条纹如图乙所示，他改变的实验条件可能是（ ） \n\n \n\nA.减小光源到单缝的距离 B.减小双缝之间的距离 \n\nC.减少双缝到光源之间的距离 D.换用频率更高的单色光源 \n\n二、光的衍射 \n\n补充：形成相干波源的方法有两种：1.利用激光（因为激光发出的是单色性极好的光）；\n\n2.设法将同一束光分为两束（这样两束光都来源于同一光源，因此频率必然相等）。 \n\n\n\n学员专用 请勿外泄 \n\n \n\n120 中公教育学员专用资料 报名专线：400-6300-999', 454, 454, 1, '1aade3b9-8998-4e00-a276-f3a7b41628db', NULL, '2026-03-27 20:08:03');
INSERT INTO `document_chunk` VALUES (413, 6, 2, 209, '学员专用 请勿外泄 \n\n \n\n120 中公教育学员专用资料 报名专线：400-6300-999 \n\n1.光的衍射：光在传播过程中，遇到障碍物或小孔时，光将偏离直线传播的途径而绕到障碍物后\n\n面传播的现象，叫光的衍射。 \n\n2.单缝衍射与双缝干涉对比 \n\n 单缝衍射 双缝干涉 \n\n \n\n \n\n不 \n\n同 \n\n点 \n\n条纹宽度 条纹宽度不等，中央最宽，两侧逐渐\n\n变暗 \n\n条纹宽度相等 \n\n条纹间距 各相邻条纹间距不等 各相邻条纹等间距 \n\n亮度 中央最亮，两边变暗 清晰条纹，亮度基本相同 \n\n相同点 都是波的特有现象，属于波的叠加；都有明暗相间的条纹 \n\n例2．关于衍射，下列说法正确的是（ ） \n\nA．衍射现象中条纹的出现是光叠加后产生的结果 \n\nB．双缝干涉中也存在衍射现象 \n\nC．一切波都很容易发生明显的衍射现象 \n\nD．影的存在是一个与衍射现象相矛盾的客观事实 \n\nE．入射波的波长越大，越容易观察到明显的衍射现象 \n\n三、光的偏振 \n\n1.自然光：包含着在垂直于传播方向上沿一切方向振动的光，而且沿各个方向振动的光波强度相同。', 471, 471, 1, 'f60bd468-96a9-422a-a4b3-ea7a7dd34d11', NULL, '2026-03-27 20:08:04');
INSERT INTO `document_chunk` VALUES (414, 6, 2, 210, '与衍射现象相矛盾的客观事实 \n\nE．入射波的波长越大，越容易观察到明显的衍射现象 \n\n三、光的偏振 \n\n1.自然光：包含着在垂直于传播方向上沿一切方向振动的光，而且沿各个方向振动的光波强度相同。 \n\n2.偏振光：振动方向对于传播方向的不对称性叫做偏振，只沿着某个特定方向振动的光叫偏振光。 \n\n3.偏振是横波特有的现象，它是横波区别于其他纵波的一个最明显的标志。 \n\n \n\n\n\n学员专用 请勿外泄 \n\n \n\n121 中公教育学员专用资料 报名专线：400-6300-999 \n\n \n\n \n\n实验现象：自然光通过偏振片 P 后，只有振动方向与偏振片的透振方向一致的光波，才能通\n\n过，再通过一偏振片 Q，若 Q 的透振方向与 P 的透振方向相同则有光线通过，若旋转偏振片 Q，\n\n随着二偏振片透振方向的夹角增大，透过光线越来越暗，当透振方向垂直时，无光线透过。 \n\n \n\n\n\n学员专用 请勿外泄 \n\n \n\n122 中公教育学员专用资料 报名专线：400-6300-999 \n\n第六章 近代原子物理 \n\n第一节 光电效应 波粒二象性 \n\n \n\n一、黑体辐射', 476, 476, 1, 'e6afaafc-3ebb-40fe-82c0-f2193d0ed72e', NULL, '2026-03-27 20:08:04');
INSERT INTO `document_chunk` VALUES (415, 6, 2, 211, '学员专用 请勿外泄 \n\n \n\n122 中公教育学员专用资料 报名专线：400-6300-999 \n\n第六章 近代原子物理 \n\n第一节 光电效应 波粒二象性 \n\n \n\n一、黑体辐射 \n\n1.热辐射：一切物体都在辐射电磁波，这种辐射与物体的温度有关，所以叫做热辐射。 \n\n2.黑体：如果某种物体能够完全吸收入射的各种波长的电磁波而不发生反射，这种物体就是绝对\n\n黑体，简称黑体。 \n\n3.黑体辐射：黑体辐射电磁波的强度只与黑体的温度有关。 \n\n二、量子化理论 \n\n1.能量子：振动着的带电微粒的能量只能是某一最小能量值 的整数倍，带电微粒辐射或吸收的\n\n能量也是以这个最小能量值为单位一份一份的进行的，这个不可再分的最小能量值 叫能量子。 \n\n公式： \n\n（ 是电磁波的频率，h 是普朗克常量，h=6.626×10-34J·s） \n\n2.能量量子化：在微观世界中，能量不能连续变化，只能取某些分立值，这种现象叫做能量量子\n\n化。 \n\n三、光电效应及其实验规律 \n\n1.光的电磁说（麦克斯韦） \n\n \n\n例 1．下列电磁波光子能量最强的是（ ） \n\n\n\n\n\n h\n\n', 486, 486, 1, '0448ad62-7bd0-4526-ae11-41481a880b13', NULL, '2026-03-27 20:08:04');
INSERT INTO `document_chunk` VALUES (416, 6, 2, 212, '三、光电效应及其实验规律 \n\n1.光的电磁说（麦克斯韦） \n\n \n\n例 1．下列电磁波光子能量最强的是（ ） \n\n\n\n\n\n h\n\n\n\n\n\n学员专用 请勿外泄 \n\n \n\n123 中公教育学员专用资料 报名专线：400-6300-999 \n\nA.紫外线 B. X 射线 C. 可见光 D. 红外线 \n\n2.光电效应（电磁理论无法解释） \n\n（1）光电效应现象 \n\n照射到金属表面的光，能使金属中的电子从表面逸出的现象，叫做光电效应，发射出来的电子叫\n\n做光电子。由于光电效应在电路中形成的电流叫光电流。 \n\n \n\n光电流的大小与什么有关？ \n\n实验结论： \n\n①当入射光的频率较低时，无论光多么强，照射时间多长，光电管都不会发射光电子，不能产生\n\n光电流。 \n\n②当入射光的频率达到某一值 ν0时，才会有光子逸出，产生光电流，这个频率称为极限频率（每\n\n一种金属对应一种极限频率）。 \n\n③光电流的大小与入射光强有关。 \n\n④当入射光的频率超过极限频率时，无论光照怎样微弱，光照同时立即产生光电流（瞬时性），\n\n无需能量累积。', 467, 467, 1, 'a700eae2-e1d3-4fe9-8e7e-3fdd3e0b8573', NULL, '2026-03-27 20:08:04');
INSERT INTO `document_chunk` VALUES (417, 6, 2, 213, '③光电流的大小与入射光强有关。 \n\n④当入射光的频率超过极限频率时，无论光照怎样微弱，光照同时立即产生光电流（瞬时性），\n\n无需能量累积。 \n\n解释:光照强度指单位面积上所接受可见光的光通量。光强=nhν，n是光子数。增加光强，即\n\n增加了光子数 n，一个光子能量被一个电子吸收后，该电子逸出。故逃出的光电子数 n\' 与光子数\n\nn有统计关系，即光子数 n越多，电子数 n’也越多，即光电流越大。 \n\n例 2.（多选）在光电效应实验中，用频率为 ν 的光照射光电管阴极，发生了光电效应，下列说法\n\n正确的是（ ） \n\nA．增大入射光强度，光电流增大 \n\nB．减小入射光的强度，光电效应现象消失 \n\nC．改用频率小于 ν 的光照射，一定不发生光电效应 \n\nD．改用频率大于 ν 的光照射，光电子的最大初动能变大 \n\n（2）饱和电流和遏止电压 \n\n①饱和电流 \n\n\n\n学员专用 请勿外泄 \n\n \n\n124 中公教育学员专用资料 报名专线：400-6300-999 \n\n \n\n 饱和光电流和光强有关 \n\n例 3.利用光电管研究光电效应的实验电路如图所示，用频率为 的可见光照射阴极 K，电表中有', 495, 495, 1, '1d231286-4023-4d6a-b725-22becfd4acf2', NULL, '2026-03-27 20:08:04');
INSERT INTO `document_chunk` VALUES (418, 6, 2, 214, '124 中公教育学员专用资料 报名专线：400-6300-999 \n\n \n\n 饱和光电流和光强有关 \n\n例 3.利用光电管研究光电效应的实验电路如图所示，用频率为 的可见光照射阴极 K，电表中有\n\n电流通过，则（ ） \n\n \n\nA．只用紫外光照射 K，电流表中不一定有电流通过 \n\nB．只用红外光照射 K，电流表中一定无电流通过 \n\nC．频率为 的可见光照射 K，变阻器的滑片移到 A 端，电流表中一定无电流通过 \n\nD．频率为 的可见光照射 K，变阻器的滑片向 B 端滑动时，电流表示数可能不变 \n\n②遏止电压 \n\n \n\n遏止电压/最大初始动能的大小与什么有关？ \n\n电子逸出的初动能来自光子，光子的能量由频率决定（频率越大能量越大，越危险）。故遏止电\n\n压/最大初始动能由入射光频率决定。 \n\n（3）光电效应的四条基本规律 \n\n①当入射光的频率达到某一值 νc时，才会有光子逸出，产生光电流，这个频率称为极限频率（每\n\n一种金属对应一种极限频率） \n\n②光强决定逸出光电流的大小 \n\n③光频率决定遏止电压和最大初动能的大小 \n\n0\n\n0\n\n0', 477, 477, 1, '53680cf8-2838-45d0-8a61-71699cf93d03', NULL, '2026-03-27 20:08:04');
INSERT INTO `document_chunk` VALUES (419, 6, 2, 215, '值 νc时，才会有光子逸出，产生光电流，这个频率称为极限频率（每\n\n一种金属对应一种极限频率） \n\n②光强决定逸出光电流的大小 \n\n③光频率决定遏止电压和最大初动能的大小 \n\n0\n\n0\n\n0\n\n加正向电压时，无光：无 Ι；增大光频率，U↑，Ι↑ \n\n阴极跑出的电子全部被阳极吸收时，无论 U 如何\n\n增大，电流都不再变化，此时的光电流称为饱和光电\n\n流。 \n\n \n\n加反向电压，电场阻碍光电子的运动 \n\n \n\n可见，光电子的最大初始动能与遏止电压成正比。 \n\n2\n\nmax\n2\n\n1\n0 mveU \n\n\n\n学员专用 请勿外泄 \n\n \n\n125 中公教育学员专用资料 报名专线：400-6300-999 \n\n④光电效应不需要时间积累，具有瞬时性 \n\n3.爱因斯坦光电效应方程 \n\n（1）爱因斯坦光子假说 \n\n受到普朗克的启发，爱因斯坦于 1905 年提出：在空间传播的光也不是连续的，是以光速 C 运动\n\n的粒子（称为光子）流，是一份一份的，每一份叫做一个光子。一个光子的能量为 E = hν。 \n\n（2）光电效应方程 \n\n表达式：', 471, 471, 1, 'd0db464b-a231-4694-80fe-542f97bf30cc', NULL, '2026-03-27 20:08:05');
INSERT INTO `document_chunk` VALUES (420, 6, 2, 216, '一个光子的能量为 E = hν。 \n\n（2）光电效应方程 \n\n表达式： \n\n由于原子外层价电子受到原子核的束缚，所以电子要脱离束缚逸出金属表面，就需要克服这种阻\n\n碍做功，是电子脱离某种金属所做功的最小值，叫做这种金属的逸出功，用 W0 表示。逸出功对应金\n\n属的极限频率： 。 \n\n4.光电效应中的图像问题 \n\n（1）Ek-ν 曲线：光电子的最大初动能 Ek随入射光频率 ν 的变化曲线。 \n\n \n\n由于 ，横轴截距即为该种金属的极限频率，纵轴的截距是金属逸出功的负值，斜率\n\n为普朗克常量。 \n\n（2）I-U 图：光电流强度 I 随光电管两极板间电压 U 的变化曲线。 \n\n \n\nIm：饱和光电流，由光照强度决定 \n\nUc：遏止电压，由光电子的最大初动能决定（ ），而光电子的最大初动能取决于\n\n入射光的频率。 \n\n例 4.爱因斯坦提出了光量子概念并成功地解释光电效应的规律而获得 1921 年的诺贝尔物理学\n\n奖．某种金属逸出光电子的最大初动能 Ekm与入射光频率 ν 的关系如图所示，其中 ν0为极限频率．从\n\n图中可以确定的是（填选项前的字母）（ ） \n\n0\n\n2\n\nmax\n2', 494, 494, 1, '008535cb-1999-43e1-bf47-fa77f0f7af87', NULL, '2026-03-27 20:08:05');
INSERT INTO `document_chunk` VALUES (421, 6, 2, 217, '1 年的诺贝尔物理学\n\n奖．某种金属逸出光电子的最大初动能 Ekm与入射光频率 ν 的关系如图所示，其中 ν0为极限频率．从\n\n图中可以确定的是（填选项前的字母）（ ） \n\n0\n\n2\n\nmax\n2\n\n1\nwmvh \n\nh\n\nW\nc\n\n0\n\nkEWh  0\n\nceUmv 2\n\nmax\n2\n\n1\n\n\n\n学员专用 请勿外泄 \n\n \n\n126 中公教育学员专用资料 报名专线：400-6300-999 \n\n \n\nA．逸出功与 ν 有关 \n\nB．Ekm于入射光强度成正比 \n\nC．ν＜ν0时，会逸出光电子 \n\nD．图中直线的斜率与普朗克常量有关 \n\n例 5.研究光电效应的电路如图所示。用频率相同、强度不同的光分别照射密封真空管的钠极板（阴\n\n极 K），钠极板发射出的光电子被阳极 A 吸收，在电路中形成光电流。下列光电流 I 与 A、K 之间的\n\n电压 UAK的关系图象中，正确的是（ ） \n\n \n\n \n\n四.康普顿效应 \n\n1.内容：光在介质中与物质微粒发生相互作用，因而传播方向发生改变，这种现象叫做光的散射。', 463, 463, 1, 'f310121b-859e-410e-89c6-57e079f6bbb5', NULL, '2026-03-27 20:08:05');
INSERT INTO `document_chunk` VALUES (422, 6, 2, 218, '流 I 与 A、K 之间的\n\n电压 UAK的关系图象中，正确的是（ ） \n\n \n\n \n\n四.康普顿效应 \n\n1.内容：光在介质中与物质微粒发生相互作用，因而传播方向发生改变，这种现象叫做光的散射。\n\n康普顿在研究石墨对 X 射线的散射时，发现在散射的 X 射线中，除了与入射波长 相同的成分外，\n\n还有波长大于 的成分，这个现象称为康普顿效应。 \n\n \n\n2.康普顿效应的意义 \n\n①证明了爱因斯坦光子说的正确性 \n\n②证明了光不仅具有能量，还具有动量 \n\n0\n\n0\n\n\n\n学员专用 请勿外泄 \n\n \n\n127 中公教育学员专用资料 报名专线：400-6300-999 \n\n③揭示了光的粒子性的一面 \n\n④证实了在微观粒子的单个碰撞事件中动量守恒定律和能量守恒定律依然成立 \n\n3.光子的动量： \n\n推导：根据爱因斯坦质能方程 \n\n一个光子能量为 \n\n则 ，质量 \n\n由于动量 \n\n又由于 ，所以 \n\n五、光的波粒二象性 \n\n1.不可把光当成经典观念中的波，也不可把光子当成经典观念中的粒子。 \n\n 波动性：干涉、衍射（泊松亮斑） \n\n 粒子性：光电效应、康普顿效应', 487, 487, 1, '5050e6d2-1a9e-4bf1-a461-fca8a481cbdf', NULL, '2026-03-27 20:08:05');
INSERT INTO `document_chunk` VALUES (423, 6, 2, 219, ' 波动性：干涉、衍射（泊松亮斑） \n\n 粒子性：光电效应、康普顿效应 \n\n2.光在传播过程中表现为波动性，在与物质相互作用时表现为粒子性； \n\n3.大量光子产生的效果表现为波动性，个别光子产生的效果表现为粒子性； \n\n4.频率越低的光子波动性越明显，频率越高的光子粒子性越明显。 \n\n例 6.关于物质的波粒二象性，下列说法中不正确的是（ ） \n\nA．不仅光子具有波粒二象性，一切运动的微粒都具有波粒二象性 \n\nB．运动的微观粒子与光子一样，当它们通过一个小孔时，都没有特定的运动轨道 \n\nC．波动性和粒子性，在宏观现象中是矛盾的、对立的，但在微观高速运动的现象中是统一的 \n\nD．实物粒子的运动有特定的轨道，所以实物不具有波粒二象性 \n\n\n\nh\np \n\n2mcE \n\nh\n\nhmc 2\n\n2c\n\nh\nm\n\n\n\n\nc\n\nh\nmcp\n\n\n\n\n\n\n\nc\n\n\n\n\nh\np \n\n\n\n学员专用 请勿外泄 \n\n \n\n128 中公教育学员专用资料 报名专线：400-6300-999 \n\n第二节 原子结构 \n\n \n\n一、原子的核式结构模型 \n\n1.电子的发现', 489, 489, 1, 'a902f3b5-d232-4636-ac4b-0d0cac9760b5', NULL, '2026-03-27 20:08:05');
INSERT INTO `document_chunk` VALUES (424, 6, 2, 220, '\n\nh\np \n\n\n\n学员专用 请勿外泄 \n\n \n\n128 中公教育学员专用资料 报名专线：400-6300-999 \n\n第二节 原子结构 \n\n \n\n一、原子的核式结构模型 \n\n1.电子的发现 \n\n（1）阴极射线 \n\n \n\n真空玻璃管中有金属板制成的阴、阳极，在两极间加有高压时，阴极会发出一种射线，这种射线\n\n叫做阴极射线。 \n\n（2）电子：组成阴极射线的粒子称为电子，是原子的组成部分。 \n\n电子的电荷量 ；电子的质量 \n\n2.汤姆生的原子模型 \n\n \n\n在汤姆生的原子模型中，原子是一个球体；正电核均匀分布在整个球内，而电子镶嵌在内。 \n\n3.原子核式结构模型 \n\n（1）α 粒子散射实验 \n\nCe 191060.1  kgme\n\n31101.9 \n\n\n\n学员专用 请勿外泄 \n\n \n\n129 中公教育学员专用资料 报名专线：400-6300-999 \n\n \n\n实验现象 \n\n \n\n结论： \n\n 绝大多数 α 粒子穿过金箔不偏移——原子内部绝大部分是空的 \n\n 少数 α 粒子发生较大偏转——不可能是与电子碰撞导致的，原因是具有原子大部分质量的带', 485, 485, 1, '6536534b-de88-48b0-ac23-8dd016622ee8', NULL, '2026-03-27 20:08:05');
INSERT INTO `document_chunk` VALUES (425, 6, 2, 221, '实验现象 \n\n \n\n结论： \n\n 绝大多数 α 粒子穿过金箔不偏移——原子内部绝大部分是空的 \n\n 少数 α 粒子发生较大偏转——不可能是与电子碰撞导致的，原因是具有原子大部分质量的带\n\n正电部分对 α 粒子产生了较大的斥力 \n\n 极少数 α 粒子被弹回——作用力很大（电量集中），质量很大（质量集中） \n\n（2）卢瑟福核式结构模型 \n\n在原子的中心有一个很小的核，叫做原子核。原子的全部正电荷和几乎全部质量都集中在原子核\n\n里。带负电的电子在核外空间绕着核旋转。 \n\n \n\n例 1.（多选）英国物理学家卢瑟福用 α 粒子轰击金箔，发现了 α 粒子的散射现象．图中 O 表示\n\n金原子核的位置，则能正确表示该实验中经过金原子核附近的 α 粒子的运动轨迹的图是（ ） \n\nA. B. \n\nC. D. \n\n二、玻尔理论 \n\n绝大多数：α粒子穿过金箔后，基本上仍沿原来的方\n\n向前进。 \n\n少数：α粒子(约占八千分之一)发生了大角度偏转 \n\n极少数：超过了 90°,也就说几乎被“撞了回来” \n\n \n\n\n\n学员专用 请勿外泄', 462, 462, 1, '69c24d25-2059-48e2-9bc1-b8dbc5bd7bed', NULL, '2026-03-27 20:08:05');
INSERT INTO `document_chunk` VALUES (426, 6, 2, 222, '少数：α粒子(约占八千分之一)发生了大角度偏转 \n\n极少数：超过了 90°,也就说几乎被“撞了回来” \n\n \n\n\n\n学员专用 请勿外泄 \n\n \n\n130 中公教育学员专用资料 报名专线：400-6300-999 \n\n1.能量量子化假说（定态假设）：原子只能处于一系列不连续的能量状态中，在这些状态中原子\n\n是稳定的，电子虽然绕核运动，但并不向外辐射能量。这个状态叫定态。 \n\n2.能级跃迁假设：当原子从一种定态跃迁道另一种定态时，它要发射（或吸收）一定频率的光子.\n\n光子的能量由这两个定态的能量差决定，即 hv= E 初- E 末 \n\n \n\n高能级向低能级跃迁，放出能量；低能级向高能级跃迁，吸收能量。 \n\n3.轨道量子化假设：原子的不同能量状态跟电子沿不同的圆形轨道绕核运动相对应。原子的能量\n\n状态是不连续的，因此电子的可能轨道的分布也是不连续的。 \n\n \n\n能级：原子的各个定态的能量值就叫做它的能级 \n\n基态：在正常状态下，氢原子处于最低的能级 E1 （n=1），这个最低能级对应的定态称为基态。', 453, 453, 1, '5b9613db-4fd1-464d-8a6f-11fc6d4401ff', NULL, '2026-03-27 20:08:06');
INSERT INTO `document_chunk` VALUES (427, 6, 2, 223, '能级：原子的各个定态的能量值就叫做它的能级 \n\n基态：在正常状态下，氢原子处于最低的能级 E1 （n=1），这个最低能级对应的定态称为基态。 \n\n激发态：当电子受到外界激发时，可从基态迁到较高的能级 E2，E3…上，这些能级对应的定态称\n\n为激发态。 \n\n处于激发态的原子是不稳定的，它会向较低的能级跃迁，跃迁时释放出来的能量以光子的形色向\n\n外辐射，这就是氢原子发光的现象。原子辐射出的光子的能量等于两能级间的能量差。 \n\n三、氢原子能级 \n\n \n\n理解： \n\n\n\n学员专用 请勿外泄 \n\n \n\n131 中公教育学员专用资料 报名专线：400-6300-999 \n\n（1）处于基态的原子是稳定的，处于激发态的原子不稳定； \n\n（2）原子的能量与原子轨道半径相对应，轨道半径大，能量大，半径小，能量小； \n\n（3）注意直接跃迁与间接跃迁：原子从一种能量状态跃迁到另一种能量状态时，有可能是直接跃\n\n迁，有可能是间接跃迁，两种情况辐射（或吸收）光子的频率不同。氢原子跃迁过程产生的光子种类\n\n有 种。', 449, 449, 1, '74669685-1222-4a1c-86f6-345a82efb9d3', NULL, '2026-03-27 20:08:06');
INSERT INTO `document_chunk` VALUES (428, 6, 2, 224, '氢原子跃迁过程产生的光子种类\n\n有 种。 \n\n（4）使处于基态或激发态的原子的核外电子跃迁到 n=∞时，称为电离，所需的能量为电离能。 \n\n（5）使原子能级改变的两种粒子——光子与实物粒子 \n\n原子若是吸收了光子能量而被激发，其光子能量必须等于两能级的级差，否则不被吸收； \n\n原子还可以吸收外来实物粒子（如自由电子）的能量而被激发只要入射粒子的能量大于或等于两\n\n能级的能量差值，就可以使原子发生能级跃迁。 \n\n例 2.（多选）如图为氢原子的能级示意图，锌的逸出功是 3.34eV，那么对氢原子在能级跃迁过程\n\n中发射或吸收光子的特征认识正确的是（ ） \n\n \n\nA.用氢原子从高能级向基态跃迁时发射的光照射锌板一定不能产生光电效应 \n\nB.一群处于 n=3 能级的氢原子向基态跃迁时，能放出 3 种不同频率的光 \n\nC.一群处于 n=3 能级的氢原子向基态跃迁时，发出的光照射锌板，锌板表面所发出的光电子的最\n\n大初动能为 8.75eV \n\nD.用能量为 10.3eV 的光子照射，可使处于基态的氢原子跃迁到激发态 \n\nE.用能量为 14.0eV 的光子照射，可使处于基态的氢原子电离', 494, 494, 1, '7645eaa5-de35-4d9e-9fbb-e562eeae8f45', NULL, '2026-03-27 20:08:06');
INSERT INTO `document_chunk` VALUES (429, 6, 2, 225, '的光电子的最\n\n大初动能为 8.75eV \n\nD.用能量为 10.3eV 的光子照射，可使处于基态的氢原子跃迁到激发态 \n\nE.用能量为 14.0eV 的光子照射，可使处于基态的氢原子电离 \n\n \n\n2\n\n)1(2 \n\n\nnn\nCn\n\n\n\n学员专用 请勿外泄 \n\n \n\n132 中公教育学员专用资料 报名专线：400-6300-999 \n\n第三节 原子核 \n\n \n\n一、天然放射现象 \n\n1．概念：放射性元素自发的发出射线的现象叫做天然放射现象。 \n\n2．三种射线： \n\n① 射线：实质是氦原子核，带正电，穿透能力很差，电离作用很强。 \n\n②  射线：实质是电子，带负电，穿透能力较强，电离能力较弱。 \n\n③  射线：实质是光子，不带电，穿透能力最强，电离能力最弱。 \n\n例 1．放射性元素放出的射线，在电场中分成 A、B、C 三束，如图所示，其中（ ） \n\n \n\nA．C 为氦核组成的粒子流 \n\nB．A的电离能力最强 \n\nC．B 的穿透能力最弱 \n\nD．B 为比 X 射线波长更长的光子流 \n\n二、原子核的组成及衰变 \n\n（一）原子核的组成', 476, 476, 1, '2cbde8c8-c6d9-408e-bc67-85a5dc5d00f3', NULL, '2026-03-27 20:08:06');
INSERT INTO `document_chunk` VALUES (430, 6, 2, 226, '（ ） \n\n \n\nA．C 为氦核组成的粒子流 \n\nB．A的电离能力最强 \n\nC．B 的穿透能力最弱 \n\nD．B 为比 X 射线波长更长的光子流 \n\n二、原子核的组成及衰变 \n\n（一）原子核的组成 \n\n1．原子核由质子和中子组成，质子和中子统称核子，质子带正电，中子不带电。 \n\n2．原子核符号： ，其中 X 为元素符号，上角标 A 表示核的质量数，下角标 Z 表示核电荷数\n\n（即原子序数） \n\n3．基本关系：①质子数（Z）=核电荷数 =元素的原子序数=核外电子数；②质量数（A）=核子数=\n\n质子数+中子数 \n\n（一）原子核的衰变 \n\n（1）定义：原子核放出 粒子或  粒子，由于核电荷数变了，它在元素周期表中的位置就变了，\n\n变成了另一种原子核，我们把这种变化称为原子核的衰变。 \n\n（2） 衰变与  衰变 \n\n  衰变  衰变 \n\nA\n\nZ X\n\n\n\n学员专用 请勿外泄 \n\n \n\n133 中公教育学员专用资料 报名专线：400-6300-999 \n\n衰变方程 HeYX A\n\nZ\n\nA\n\nZ\n\n4\n\n2\n\n4\n\n2  \n\n eYX A\n\nZ\n\nA\n\nZ\n\n0', 493, 493, 1, '1f6b773a-eceb-482a-8e4d-4399b231f63b', NULL, '2026-03-27 20:08:06');
INSERT INTO `document_chunk` VALUES (431, 6, 2, 227, '133 中公教育学员专用资料 报名专线：400-6300-999 \n\n衰变方程 HeYX A\n\nZ\n\nA\n\nZ\n\n4\n\n2\n\n4\n\n2  \n\n eYX A\n\nZ\n\nA\n\nZ\n\n0\n\n11   \n\n衰变实质 \n\n2个质子和 2个中子结合成一个整体射出 \n\nHenH 4\n\n2\n\n1\n\n0\n\n1\n\n1 22  \n\n中子转化为质子和电子 \n\neHn 0\n\n1\n\n1\n\n1\n\n1\n\n0  \n\n衰变规律 电荷数守恒，质量数守恒 \n\n（3） 射线经常是伴随 射线与 射线产生的。 \n\n（三）半衰期 \n\n1．定义：放射性元素的原子核有半数发生衰变所需的时间，叫这种元素的半衰期。 \n\n2．特点： \n\n①放射性元素衰变的快慢由核内部自身的因素决定，跟元素所处的化学状态和外部条件无关。 \n\n②半衰期具有统计意义，只对大量放射性元素的原子核有意义，对少量或个别原子核没有意义。 \n\n例 2．原子核\n234\n\n90 Th表示（ ） \n\nA．核外有 90个电子 B．核内有 234个质子 \n\nC．核内有 144个中子 D．核内有 90个核子 \n\n三、核力与结合能', 486, 486, 1, '91ba2088-d9de-4835-94d4-3b1ffa688b2d', NULL, '2026-03-27 20:08:06');
INSERT INTO `document_chunk` VALUES (432, 6, 2, 228, '例 2．原子核\n234\n\n90 Th表示（ ） \n\nA．核外有 90个电子 B．核内有 234个质子 \n\nC．核内有 144个中子 D．核内有 90个核子 \n\n三、核力与结合能 \n\n1．核力：核子之间的相互作用力叫做核力，核力是很强的短程力，核力只存在于相邻的核子之间。 \n\n2．结合能和比结合能 \n\n（1）原子核是核子结合在一起构成的，要把他们分开，也需要能量，这就是原子核的结合能。 \n\n（2）结合能与核子数之比叫做比结合能，也叫平均结合能。比结合能越大，表示原子核中核子结\n\n合的越牢固，原子核越稳定。 \n\n3．质量亏损与质能方程 \n\n（1）质量亏损：原子核的质量小于组成它的核子质量之和，这个现象叫做质量亏损。 \n\n（2）质能方程：原子核释放能量时，要产生质量亏损，物体的能量和质量之间存在着密切的联系。 \n\n爱因斯坦质能方程： 2mcE  或 2mcE  \n\n四、核反应 \n\n1．核反应定义：原子核在其他粒子的轰击下产生新原子核的过程，称为核反应。在核反应过程中\n\n质量数守恒，电荷数守恒。 \n\n2．示例：', 462, 462, 1, '1cb47c45-ad75-4635-b69d-a4dc3918865d', NULL, '2026-03-27 20:08:07');
INSERT INTO `document_chunk` VALUES (433, 6, 2, 229, '在核反应过程中\n\n质量数守恒，电荷数守恒。 \n\n2．示例： \n\n①卢瑟福用 粒子轰击氮原子核，产生质子的核反应方程： HOHeN 1\n\n1\n\n17\n\n8\n\n4\n\n2\n\n14\n\n7  \n\n②查德威克发现中子的核反应方程： nCHeBe 1\n\n0\n\n12\n\n6\n\n4\n\n2\n\n9\n\n4  \n\n3．核裂变 \n\n（1）定义：核物理中把重核分裂成中等质量的原子核，释放出核能的反应叫核裂变。 \n\n（2）铀核的典型裂变方程： \n\n4．核聚变 \n\nEnKrBanU  1\n\n0\n\n92\n\n36\n\n141\n\n56\n\n1\n\n0\n\n235\n\n92 3\n\n\n\n学员专用 请勿外泄 \n\n \n\n134 中公教育学员专用资料 报名专线：400-6300-999 \n\n（1）定义：两个轻核结合成质量较大的核，这样的核反应叫做核聚变。 \n\n（2）典型的核聚变方程：\n2 3 4 1\n\n1 1 2 0H H He n E    \n\n例 3．下列核反应中，表达正确的是（ ） \n\nA．238\n92U—235\n\n90Th+ 42He 属于裂变 \n\nB．9\n4 Be+4\n\n2He—12\n6C+1', 496, 496, 1, 'bf7fc7f2-1a1d-4648-874e-529d8af8c0b8', NULL, '2026-03-27 20:08:07');
INSERT INTO `document_chunk` VALUES (434, 6, 2, 230, 'H He n E    \n\n例 3．下列核反应中，表达正确的是（ ） \n\nA．238\n92U—235\n\n90Th+ 42He 属于裂变 \n\nB．9\n4 Be+4\n\n2He—12\n6C+1\n\n0n 属于人工转变 \n\nC．235\n92U+1\n\n0n—141\n56Ba+92\n\n36Kr+3 10n 属于衰变 \n\nD．3\n1H+2\n\n1H—4\n2He+1\n\n0n属于聚变 \n\n \n\n5.人工转变 \n\n卢瑟福发现质子的核反应方程： \n\n查德威克发现中子的核反应方程： \n\n6.质能方程 \n\n爱因斯坦的相对论指出：物体的能量和质量之间存在着密切的联系，它们的关系是： \n\nE = mc2，这就是爱因斯坦的质能方程。 \n\n质能方程的另一个表达形式是：ΔE=Δmc2。 \n\nHOHeN 1\n\n1\n\n17\n\n8\n\n4\n\n2\n\n14\n\n7 \n\nnCHeBe 1\n\n0\n\n12\n\n6\n\n4\n\n2\n\n9\n\n4 \n\n\n\n学员专用 请勿外泄 \n\n \n\n135 中公教育学员专用资料 报名专线：400-6300-999 \n\n第三部分 义务教育物理课程标准 \n\n第一节 课程理论 \n\n一、课程性质', 494, 494, 1, 'aa76303b-e870-457e-beaf-f34456382f11', NULL, '2026-03-27 20:08:07');
INSERT INTO `document_chunk` VALUES (435, 6, 2, 231, '9\n\n4 \n\n\n\n学员专用 请勿外泄 \n\n \n\n135 中公教育学员专用资料 报名专线：400-6300-999 \n\n第三部分 义务教育物理课程标准 \n\n第一节 课程理论 \n\n一、课程性质 \n\n义务教育物理课程应综合反映人类在探索物质、相互作用和运动规律等过程中的成果。物理学不\n\n仅含有人类探索大自然的知识成果，而且含有探索者的科学思想、科学方法、科学态度和科学精神等。 \n\n义务教育物理课程作为科学教育的组成部分，是以提高全体学生科学素养为目标的自然科学基础\n\n课程。此阶段的物理课程不仅应注重科学知识的传授和技能的训练，而且应注重对学生学习兴趣、探\n\n究能力、创新意识以及科学态度、科学精神等方面的培养。 \n\n义务教育物理课程是一门注重实验的自然科学基础课程。此阶段的物理课程应注意让学生经历实\n\n验探究过程，学习科学知识和科学探究方法，提高分析问题及解决问题的能力。 \n\n义务教育物理课程应注重与生产、生活实际及时代发展的联系。此阶段的物理课程应关注学生的\n\n认知特点，加强课程内容与学生生活、现代社会和科技发展的联系，关注技术应用带来的社会进步和', 481, 481, 1, '188b73d0-c29a-45e8-8547-f65b1db436b5', NULL, '2026-03-27 20:08:07');
INSERT INTO `document_chunk` VALUES (436, 6, 2, 232, '义务教育物理课程应注重与生产、生活实际及时代发展的联系。此阶段的物理课程应关注学生的\n\n认知特点，加强课程内容与学生生活、现代社会和科技发展的联系，关注技术应用带来的社会进步和\n\n问题，培养学生的社会责任感和正确的世界观。 \n\n二、课程的基本理念（一）面向全体学生，提高科学素养 \n\n以学生终身发展为本，以提高全体学生科学素养为目标，为每个学生的学习与发展提供机会，关\n\n注学生的个体差异，使每个学生学习科学的潜能都得到发展。 \n\n解读：义务教育阶段的物理目的是培养全体学生的科学素养，该阶段的物理课程应以满足所有学\n\n生发展需要为基本定位，尽量为每个学生的发展提供相对均等的机会，正如《国家中长制教育改革和\n\n发展规划纲要（2010-2020年）》指出“推进义务教育均衡发展。均衡发展是义务教育的战略性任务，\n\n《基础教育课程改革纲要（试行）》指出:“改变课程过于注重知识传授的倾向，强调形成积极主动的\n\n学习态度，使获得基础知识与基本技能的过程成为学会学习和形成正确价值观的过程。”这条理念侧\n\n重体现了义务教育阶段物理课程的功能，在这条理念的定位下便有了与物理课程内容、课程实施、课', 494, 494, 1, 'dea89f9c-d439-475a-bcb7-235c95f4df46', NULL, '2026-03-27 20:08:07');
INSERT INTO `document_chunk` VALUES (437, 6, 2, 233, '”这条理念侧\n\n重体现了义务教育阶段物理课程的功能，在这条理念的定位下便有了与物理课程内容、课程实施、课\n\n程评价相关的理念。 \n\n（二）从生活走向物理，从物理走向社会 \n\n贴近学生生活，符合学生认知特点，激发并保持学生的学习兴趣，让学生通过学习和探索掌握物\n\n理学的基础知识与基本技能，并能将其应用于实践，为以后的学习、生活和工作打下基础。 \n\n解读：物理学研究的是自然界最基本的运动规律，而自然界中的物理现象蕴藏着无穷奥秘，认识\n\n主体在探索物理现象的过程应充满乐趣，这两方面的客观存在与结合是建构初中物理课程的关键，也\n\n是物理课程设计的起点。自然界的神奇现象震撼人心，生活中的物理现象妙趣横生，初中物理课程是\n\n学生在综合科学课程的基础上第一次学习物理分科课程。因此，该课程的设置应贴近学生的生活，让\n\n学生从身边熟悉的生活现象中去探究并认识物理规律，同时还应将学生认识到的物理知识及科学研究\n\n方法与社会实践及其应用结合起来，让他们体会到物理在生活与生产中的实际应用，这不仅可以增加\n\n学生学习物理的乐趣，而且还将培养学生良好的思维习惯和科学探究的能力。正如《基础教育改革纲', 492, 492, 1, '813a410d-7b2b-4612-870d-049856a0a5cd', NULL, '2026-03-27 20:08:07');
INSERT INTO `document_chunk` VALUES (438, 6, 2, 234, '正如《基础教育改革纲\n\n\n\n学员专用 请勿外泄 \n\n \n\n136 中公教育学员专用资料 报名专线：400-6300-999 \n\n要（试行）》所指出的，要改变课程内容“难、繁、偏、旧”和过于注重书本知识的现状，加强课程\n\n内容与学生生活以及现代社会和科技发展的联系，关注学生的学习兴趣和经验，精选终身学习必备的\n\n基础知识和技能。 \n\n（三）注意学科渗透，关心科技发展 \n\n让学生了解自然界事物的相互联系，注意学科间的联系与渗透，关心科学技术的新进展，关注科技\n\n发展给社会进步带来的影响，逐步树立正确的世界观。 \n\n解读：1687 年牛顿的论文《自然哲学的数学原理》的发表，标志着经典物理学的诞生。然而直至当\n\n时，物理学仍然被认为属于自然哲学的内容。随后，由于认识发展的需要，更加深化细分的研究方式逐\n\n渐成为主流，不同的学科分类便随之产生了，如，法国实证主义哲学创始人孔德（A.Comte，1798-1857）\n\n对各门知识进行了分类，天文学、物理学、化学、生理学等被发展成为实证的科学。这种人为的划分能', 454, 454, 1, '418591bf-7b87-416c-9725-86742eeae93b', NULL, '2026-03-27 20:08:08');
INSERT INTO `document_chunk` VALUES (439, 6, 2, 235, '这种人为的划分能\n\n更方便地描述事物不同类别的性质，却弱化了对自然界的整体把握。随着科学的进一步发展，各门学科\n\n间的联系与共性再次凸显，需要进一步的综合研究。因此为了培养符合时代发展需要的人才，为了使学\n\n生全面发展，应有意识让学生整体了解科学的发展以及与其他学科的联系，让学生了解科学技术在为人\n\n类带来福音的同时也带来了一些负面的影响。 \n\n（四）提倡教学方式多样化，注重科学探究 \n\n在教学中，根据教学目标、教学内容及教学对象灵活采用教学方式，提倡教学方式多样化。注重\n\n采用探究式的教学方法，让学生经历探究过程，学习科学方法，培养其创新精神和实践能力。鼓励在\n\n物理教学中合理运用信息技术。 \n\n解读：在物理教学中既要让学生学习科学知识，还要增强其能力，培养其科学态度与科学精神等。\n\n课堂教学是实现课程目标的重要环节，在课堂教学中要根据教学目标、学生特点及教学环境等灵活采\n\n用教学方式。《国家中长期教育改革和发展规划纲要（2010-2020 年）》指出，“注重学思结合、倡\n\n导启发式、探究式、讨论式、参与式教学，帮助学生学会学习”，不同的教学方式有其不同的功能，', 489, 489, 1, 'e51cb289-6a62-4215-aa75-15c32981673a', NULL, '2026-03-27 20:08:08');
INSERT INTO `document_chunk` VALUES (440, 6, 2, 236, '《国家中长期教育改革和发展规划纲要（2010-2020 年）》指出，“注重学思结合、倡\n\n导启发式、探究式、讨论式、参与式教学，帮助学生学会学习”，不同的教学方式有其不同的功能，\n\n具有综合使用多种教学方式，才可能更有效地教学。另外，学习的意义最好让学生去发现，而不是简\n\n单地给予，富有探索性的物理学习实践是发现物理现象背后意义的关键，《基础教育课程改革纲要（试\n\n行）》指出，“改变课程实施中过于强调接受学习、死记硬背、机械训练的现状、倡导学生主动参与、\n\n乐手探究、勤于动手，培养学生收集和处理信息的能力、获取新知识的能力、分析和解决问期的能力、\n\n以及交流与合作的能力。”探究式学习方法是学习科学的一个强有力的工具之一，能使学习者保持好\n\n奇心和求知欲，让学生通过学习物理知识，学会学习，学会探究，养成正确的价值观。另外，在教学\n\n中可适当采用信息技术辅助物理教学。 \n\n（五）注重评价改革导向，促进学生发展 \n\n在新的评价观念指导下，构建多元化、发展性的评价体系，注重形成性评价与终结性评价结合，', 453, 453, 1, 'a3b4075f-c30b-4d16-b1ff-c09f132d3db1', NULL, '2026-03-27 20:08:08');
INSERT INTO `document_chunk` VALUES (441, 6, 2, 237, '另外，在教学\n\n中可适当采用信息技术辅助物理教学。 \n\n（五）注重评价改革导向，促进学生发展 \n\n在新的评价观念指导下，构建多元化、发展性的评价体系，注重形成性评价与终结性评价结合，\n\n发展性评价与甄别性评价结合，以促进学生科学素养的提高、教师专业素质的发展和物理教学的改进。 \n\n解读：《基础教育课程改革纲要（试行）》指出，应注意改变课程评价过分强调甄别与选拔功能。\n\n发挥评价促进学生发展、教师提高和改进教学实践的功能。在评价内容上不能多倚重学科知识，特别\n\n是课本知识的考测，应注意评测分析问题和解决问题的能力，实验探究能力等，应探索对科学精神、\n\n\n\n学员专用 请勿外泄 \n\n \n\n137 中公教育学员专用资料 报名专线：400-6300-999 \n\n科学态度等方面的综合素质的评定；在评价指标上，注意评价对象的共性及个体的差异，注意量化与\n\n质性评价的结合；在评价结果上，注意不能过分强调终结性评价，应注意评价不同时期个体的进步状\n\n况，注意发挥评价的发展及激励功能。评价改革是推进课程改革的关键，合理评价并调控，将促进素\n\n质教育朝纵深发展。 \n\n【能力提升】', 486, 486, 1, 'e06fad39-557c-466e-89d0-5d426f9dbf40', NULL, '2026-03-27 20:08:08');
INSERT INTO `document_chunk` VALUES (442, 6, 2, 238, '评价改革是推进课程改革的关键，合理评价并调控，将促进素\n\n质教育朝纵深发展。 \n\n【能力提升】 \n\n1.（判断题）“面向全体学生，提高学生科学素养”是义务教育物理课程标准基本理念之一。（ ） \n\n2.新课改提倡的探究学习方式，其本质是强调学生的学习需要重视（ ）。 \n\nA.自主 B.合作 C.体验 D.记忆 \n\n3. “从生活走向物理，从物理走向社会”，是《义务教育课程标准（2011 年版）》的基本理论之\n\n一。结合初中物理教学实例简述倡导“从生活走向物理，从物理走向社会”的意义。 \n\n \n\n \n\n \n\n \n\n4.“提倡教学方式多样化，注重科学探究”是《义务教育物理课程标准（2011 年版）》的基本理\n\n念之一。结合初中物理教学实际，简述“注重科学探究”的意义。 \n\n \n\n\n\n学员专用 请勿外泄 \n\n \n\n138 中公教育学员专用资料 报名专线：400-6300-999 \n\n第二节 课程目标 \n\n一、课程总目标 \n\n义务教育物理课程旨在提高学生的科学素养，让学生： \n\n学习终身发展必需的物理基础知识和方法，养成良好的思维习惯，在分析问题和解决问题时尝试', 483, 483, 1, 'e53b154e-790d-4e17-94a4-2f4ea1dfe7c7', NULL, '2026-03-27 20:08:08');
INSERT INTO `document_chunk` VALUES (443, 6, 2, 239, '0-999 \n\n第二节 课程目标 \n\n一、课程总目标 \n\n义务教育物理课程旨在提高学生的科学素养，让学生： \n\n学习终身发展必需的物理基础知识和方法，养成良好的思维习惯，在分析问题和解决问题时尝试\n\n运用科学知识和科学研究方法； \n\n经历科学探究过程，具有初步的科学探究能力，乐于参加与科学技术有关的活动，有运用研究方\n\n法的意识； \n\n保持探索科学的兴趣与热情，在认识自然的过程中获得成就感，能独立思考、敢于质疑、尊重事\n\n实、勇于创新； \n\n关心科学技术的发展，具有环境保护和可持续发展的意识，树立正确的世界观，有振兴中华、将\n\n科学服务于人类的使命感与责任感。 \n\n二、课程具体目标 \n\n（一）知识与技能 \n\n1.认识物质的形态和变化、物质的属性、物质的结构与物体的尺度，了解新材料及其应用等内容，\n\n关注资源利用与环境保护等问题。 \n\n2.了解自然界多种多样的运动形式，认识机械运动和力、声和光、电和磁等内容，了解相互作用\n\n规律及其在生产、生活中的应用。 \n\n3.认识机械能、内能、电磁能、能量的转化和转移、能量守恒等内容，了解新能源的开发与应用，\n\n关注能源利用与可持续发展等问题。', 497, 497, 1, '5ae4b9ac-91ff-4fc4-9294-1f04c0487b2b', NULL, '2026-03-27 20:08:08');
INSERT INTO `document_chunk` VALUES (444, 6, 2, 240, '3.认识机械能、内能、电磁能、能量的转化和转移、能量守恒等内容，了解新能源的开发与应用，\n\n关注能源利用与可持续发展等问题。 \n\n4.了解物理学及其相关技术发展的大致历程，知道物理学不仅含有物理知识，而且还含有科学研\n\n究的过程与方法、科学态度与科学精神。 \n\n5.有初步的实验操作技能，会用简单的实验仪器，能测量一些基本的物理量，具有安全意识，知\n\n道简单的数据记录和处理方法，会用简单图表等描述实验结果，会写简单的实验报告。 \n\n（二）过程与方法 \n\n1.经历观察物理现象的过程，能简单描述所观察物理现象的主要特征，能在观察和学习中发现问\n\n题，具有初步的观察能力及提出问题的能力。 \n\n2.通过参与科学探究活动，学习拟订简单的科学探究计划和实验方案，有控制实验条件的意识，\n\n能通过实验收集数据，会利用多种渠道收集信息，有初步的信息收集能力。 \n\n3.经历信息处理过程，有对信息的有效性、客观性做出判断的意识，经历从信息中分析、归纳规\n\n律的过程，尝试解释根据调查或实验数据得出的结论，有初步的分析概括能力。', 457, 457, 1, '21812f99-7e07-41a0-a4bf-5df9c6c2088f', NULL, '2026-03-27 20:08:08');
INSERT INTO `document_chunk` VALUES (445, 6, 2, 241, '3.经历信息处理过程，有对信息的有效性、客观性做出判断的意识，经历从信息中分析、归纳规\n\n律的过程，尝试解释根据调查或实验数据得出的结论，有初步的分析概括能力。 \n\n4.能书面或口头表述自己的观点，能与他人交流，有自我反思和听取意见的意识，有初步的信息\n\n交流能力。 \n\n\n\n学员专用 请勿外泄 \n\n \n\n139 中公教育学员专用资料 报名专线：400-6300-999 \n\n5.通过学习物理知识，提高分析问题与解决问题的能力，养成自学能力，学习物理学家在科学探\n\n索中的研究方法，并能在解决问题中尝试应用科学研究方法。 \n\n（三）情感·态度·价值观 \n\n1.有学习物理的兴趣，有对科学的求知欲，能保持对自然界的好奇，乐于探索自然，能领略自然\n\n界的美妙与和谐，对大自然有亲近、热爱及和谐相处的情感。 \n\n2.有将科学技术应用于日常生活、社会实践的意识，乐于探究日常用品或新产品中的物理学原理，\n\n乐于参与观察、实验、制作、调查等科学实践活动，有团队精神。 \n\n3.有克服困难的信心和决心，能总结成功的经验，分析失败的原因，体验战胜困难、解决物理问\n\n题时的喜悦。', 482, 482, 1, 'e52bb4c2-cb4d-46a5-ba5f-a6f8f923e062', NULL, '2026-03-27 20:08:09');
INSERT INTO `document_chunk` VALUES (446, 6, 2, 242, '3.有克服困难的信心和决心，能总结成功的经验，分析失败的原因，体验战胜困难、解决物理问\n\n题时的喜悦。 \n\n4.养成实事求是、尊重自然规律的科学态度，不迷信权威，勇于创新，有判断大众传媒信息是否\n\n符合科学规律的初步意识，有将自己的见解与他人交流的意识，敢于提出与别人不同的见解，勇于放\n\n弃或修正不正确的观点。 \n\n5.关注科学技术对社会发展、自然环境及人类生活的影响，有保护环境及可持续发展的意识，能\n\n在个人力所能及的范围内对社会的可持续发展做出贡献，有将科学服务于人类的意识，热爱祖国，有\n\n振兴中华的使命感与责任感。 \n\n \n\n \n\n\n\n学员专用 请勿外泄 \n\n \n\n140 中公教育学员专用资料 报名专线：400-6300-999 \n\n第三节 课程内容 \n\n“课程内容”规定了义务教育物理课程的基本学习内容和应达到的基本要求。 \n\n课程内容由科学探究和科学内容两部分组成，其中科学内容包括特质、运动和相互作用、能量三\n\n个部分。 \n\n科学内容中的样例是对科学内容要求的进一步解释，活动建议是为教学提供参考的活动实例。 \n\n一、科学探究', 473, 473, 1, '5d20e943-4afd-4534-9162-6e7ffd12068a', NULL, '2026-03-27 20:08:09');
INSERT INTO `document_chunk` VALUES (447, 6, 2, 243, '科学内容中的样例是对科学内容要求的进一步解释，活动建议是为教学提供参考的活动实例。 \n\n一、科学探究 \n\n在本标准中，科学探究既是学生的学习目标，又是重要的教学方式。将科学探究列入“课程内容”，\n\n旨在让学生经历与科学工作者进行相似的探究过程，主动获取物理知识，领悟科学探究方法，发展科\n\n学探究能力，体验科学探究的乐趣，养成实事求是的科学态度和勇于创新的科学精神。 \n\n通常，科学探究涉及提出问题、猜想与假设、设计实验与制订计划、进行实验与收集证据、分析\n\n与论证、评估、交流与合作等要素。科学探究的形式是多种多样的，在学生的科学探究中，其探究过\n\n程可涉及所有的要素，也可只涉及部分要素。科学探究的要素应灵活渗透在教材和教学的各个方面。 \n\n在义务教育物理课程的学习中，对学生科学探究能力的基本要求主要体现在以下几个方面。 \n\n科学探究要素 科学探究能力的基本要求 \n\n提出问题 \n\n·能从日常生活、自然现象或实验观察中发现与物理学有关的问题。 \n\n·能书面或口头表述发现的问题。 \n\n·了解发现问题和提出问题在科学探究中的意义。 \n\n猜想与假设', 475, 475, 1, '6a80fb84-2806-42e7-9c0d-e94cad063d59', NULL, '2026-03-27 20:08:09');
INSERT INTO `document_chunk` VALUES (448, 6, 2, 244, '·能书面或口头表述发现的问题。 \n\n·了解发现问题和提出问题在科学探究中的意义。 \n\n猜想与假设 \n\n·尝试根据经验和已有知识对问题的可能答案提出猜想。 \n\n·能对探究的方向和可能出现的探究结果进行推测与假设。 \n\n·了解猜想与假设在科学探究中的意义。 \n\n设计实验与制订计划 \n\n·经历设计实验与制订计划的过程。 \n\n·明确探究目的和已有条件。 \n\n·尝试考虑影响问题的主要因素，有控制变量的意识。 \n\n·尝试选择科学探究方法及所需要的器材。 \n\n·了解设计实验与制订计划在科学探究中的意义。 \n\n进行实验与收集证据 \n\n·能通过观察、实验和公共信息资源收集证据。 \n\n·会阅读简单仪器的说明书，能按要求进行操作。 \n\n·会使用简单仪器进行实验，会正确记录实验数据。 \n\n·具有安全操作的意识。 \n\n·了解进行实验与收集证据在科学探究中的意义。 \n\n分析与论证 \n\n·经历从物理现象和实验中归纳科学规律的过程。 \n\n·能对收集的信息进行简单归类及比较。 \n\n·能进行简单的因果推理。 \n\n·尝试对探究结果进行描述和解释。 \n\n\n\n学员专用 请勿外泄', 475, 475, 1, '7678adf4-826c-4211-8f10-1b06f8711e88', NULL, '2026-03-27 20:08:09');
INSERT INTO `document_chunk` VALUES (449, 6, 2, 245, '·能对收集的信息进行简单归类及比较。 \n\n·能进行简单的因果推理。 \n\n·尝试对探究结果进行描述和解释。 \n\n\n\n学员专用 请勿外泄 \n\n \n\n141 中公教育学员专用资料 报名专线：400-6300-999 \n\n·了解分析与论证在科学探究中的意义。 \n\n评估 \n\n·有评估探究过程和探究结果的意识。 \n\n·能关注探究活动中出现的新问题。 \n\n·有从评估中吸取经验教训的意识。 \n\n·尝试改进探究方案。 \n\n·了解评估在科学探究中的意义。 \n\n交流与合作 \n\n·有准确表达自己观点的意识。 \n\n·能表述探究的问题、过程和结果。 \n\n·能听取别人的意见，调整自己的方案。 \n\n·能坚持原则又尊重他人，有团队意识。 \n\n·了解交流与合作在科学探究中的意义。 \n\n二、科学内容 \n\n本标准的科学内容分为“物质”“运动和相互作用”“能量”三大部分，下表为科学内容的一级\n\n主题与二级主题。这种呈现形式不代表教材的结构或教学的顺序，教材编者可根据本标撰写不同特色\n\n的教材。 \n\n科学内容中的样例与活动建议是为教师提供的教学参考，教师可以从中选用，也可以结合当地情\n\n况开展更切合实际的教学活动。', 493, 493, 1, 'b8451e40-7f08-4349-91a8-a30fa7b2cb2d', NULL, '2026-03-27 20:08:09');
INSERT INTO `document_chunk` VALUES (450, 6, 2, 246, '科学内容中的样例与活动建议是为教师提供的教学参考，教师可以从中选用，也可以结合当地情\n\n况开展更切合实际的教学活动。 \n\n义务教育物理课程应让学生通过观察、操作、体验等方式，经历科学探究过程，认识物理概念和\n\n规律，学习科学方法，树立正确的世界观。 \n\n一级主题 二级主题 \n\n1.物质 \n\n1.1 物质的形态和变化 \n\n1.2 物质的属性 \n\n1.3 物质的结构与物体的尺度 \n\n1.4 新材料及其应用 \n\n2.运动和相互作用 \n\n2.1 多种多样的运动形式 \n\n2.2 机械运动和力 \n\n2.3 声和光 \n\n2.4 电和磁 \n\n3.能量 \n\n3.1 能量、能量的转化和转移 \n\n3.2 机械能 \n\n3.3 内能 \n\n3.4 电磁能 \n\n3.5 能量守恒 \n\n3.6 能源与可持续发展', 343, 343, 1, '9fefe42a-d8a5-4339-935b-7679026fa29f', NULL, '2026-03-27 20:08:09');
INSERT INTO `document_chunk` VALUES (451, 7, 1, 0, 'Java面向对象 第2章 - 类与类之间的关系 \n【学习目标】理解、了解、应用、记忆\n\n通过今天的学习，参训学员能够\n\n1. 【应用】继承的概述及特点\n\na. 【应用】独立编写代码完成一个对象作为另一个类的成员变量的练习\n\nb. 【理解】阐述继承的作用和好处\n\nc. 【应用】阐述继承的代码格式,独立编写一个继承的案例\n\nd. 【应用】独立编写代码通过set和get方法给对象设置属性\n\ne. 【理解】阐述java中继承的特点\n\n2. 【理解】方法重写及继承内存图解\n\na. 【理解】阐述方法重写的概念及格式\n\nb. 【了解】阐述Override注解的作用及使用方法\n\nc. 【理解】阐述继承中子父类创建的先后顺序\n\nd. 【理解】描述继承后子父类内存关系图\n\n3. 【应用】this与super\n\na. 【应用】阐述this和super访问普通成员的格式\n\nb. 【应用】阐述super和this如何访问父类构造方法\n\nc. 【理解】能够独立写出继承的案例\n\n4. 【应用】关联关系和依赖关系\n\na. 【应用】关联关系\n\nb. 【应用】依赖关系', 473, 473, 1, '60b1606b-25b4-4c3f-8882-aa614859b055', NULL, '2026-03-27 20:11:10');
INSERT INTO `document_chunk` VALUES (452, 7, 1, 1, '的格式\n\nb. 【应用】阐述super和this如何访问父类构造方法\n\nc. 【理解】能够独立写出继承的案例\n\n4. 【应用】关联关系和依赖关系\n\na. 【应用】关联关系\n\nb. 【应用】依赖关系\n\nc. 【理解】能够独立写出关联关系和依赖关系的案例\n\n第1章 继承的概述及特点 \n\n1.1 继承的概念 \n\n1.1.1 继承的概述 is-a \n\n继承是面向对象的核心特性，是面向对象的学习重点。\n\n继承是代码复用的重要方式，是类与类之间的一种关系。\n\n从类与类之间的设计关系来看,子类必须属于父类的一种时，才会继承。\n\naf://n0\naf://n54\naf://n55\naf://n56\n\n\n父类抽取出了共性的内容，子类可以在父类基础上扩展新的属性与行为。\n\n子类拥有父类的所有属性与方法，无需重新定义。并且可以直接使用非私有的父类成员。\n\n下例展示了一个继承关系\n\n1.1.2 案例 \n\n \n\n1.2 继承的代码格式 \n\n1.2.1 继承格式说明 \n\n使用extends关键字完成继承关系。\n\n格式：', 452, 452, 1, '0abf274e-7361-4700-a6d6-fd820ab5833d', NULL, '2026-03-27 20:11:10');
INSERT INTO `document_chunk` VALUES (453, 7, 1, 2, '下例展示了一个继承关系\n\n1.1.2 案例 \n\n \n\n1.2 继承的代码格式 \n\n1.2.1 继承格式说明 \n\n使用extends关键字完成继承关系。\n\n格式：\n\n/**  \n * @ClassName: ExtendsDemo  \n * @Description: 继承关系\n\n *    \n * 继承关系:类与类之间的关系\n\n *\n * 人:定义一些共性内容定义为父类\n\n *  共性的成员变量:年龄,姓名     \n\n *  共性的成员方法:吃饭,睡觉     \n\n * \n * 程序员、老师、工人定义为人类的子类,子类可以在父类的基础上扩展新的成员变量与成员方法\n\n * \n * 当有了子父类关系后,子类拥有了父类的成员,可以直接访问父类的非私有成员\n\n * 继承通过这样的方式,提高了代码的复用性,让类与类之间产生了关系\n\n * 继承关系必须符合is a的关系,即我是你的一种\n\n * \n */\n \npublic class ExtendsDemo {\n\npublic static void main(String[] args) {    \n\n        \n\n}    ', 494, 494, 1, 'c7e7ec52-4d8a-451c-8dfc-b67a12a95d5f', NULL, '2026-03-27 20:11:11');
INSERT INTO `document_chunk` VALUES (454, 7, 1, 3, '* \n */\n \npublic class ExtendsDemo {\n\npublic static void main(String[] args) {    \n\n        \n\n}    \n\n}\n\naf://n75\naf://n79\naf://n80\n\n\n \n\n注意：所有的类都直接或间接继承自Object，所以如果没有继承其他类，则默认继承Object类。即Object是所\n有类的父类(或超类)\n\n1.2.2 案例 \n\n父类Person类：\n\nclass 子类 extends 父类 {\n    \n}\n\naf://n90\n\n\n /**  \n* @ClassName: Person  \n* @Description: Person类\n*    \n* 父类‐人类:\n*  年龄,姓名      \n\n*  吃饭,睡觉      \n\n*/\npublic class Person extends Object {\n\n/**      \n\n* @Fields name : 姓名      \n\n*/      \n\nString name;    \n\n/**      ', 486, 486, 1, '4c41b9bf-5313-4c60-8241-d56052d97d66', NULL, '2026-03-27 20:11:11');
INSERT INTO `document_chunk` VALUES (455, 7, 1, 4, 'rson extends Object {\n\n/**      \n\n* @Fields name : 姓名      \n\n*/      \n\nString name;    \n\n/**      \n\n* @Fields age : 年龄      \n\n*/      \n\nint age;    \n\n    \n\n/**      \n\n* @Title: Person          \n\n*/    \n\npublic Person() {    \n\n}    \n\n \n/**      \n\n* @Title: Person      \n\n* @param name    \n\n* @param age        \n\n*/    \n\npublic Person(String name, int age) {    \n\nthis.name = name;        \n\nthis.age = age;        \n\n}    \n\n    \n\n/**      \n\n* @Title: eat      \n\n* @Description: 吃东西的方法          ', 491, 491, 1, '65ada6db-dbc1-4f2f-a7aa-46a9cef416e9', NULL, '2026-03-27 20:11:11');
INSERT INTO `document_chunk` VALUES (456, 7, 1, 5, '.age = age;        \n\n}    \n\n    \n\n/**      \n\n* @Title: eat      \n\n* @Description: 吃东西的方法          \n\n*/    \n\npublic void eat() {    \n\nSystem.out.println(\"我吃了\");        \n\n}    \n\n \n/**      \n\n* @Title: sleep      \n\n* @Description: 睡觉的方法          \n\n*/    \n\npublic void sleep() {    \n\nSystem.out.println(\"我睡了\");        \n\n}    \n\n \n}\n\n\n\n定义子类Coder：\n\n \n\n定义子类Teacher：\n\n/**  \n* @ClassName: Coder  \n* @Description: 程序员类\n\n*    \n* 定义子类程序员类,继承人类\n\n* 在人类共性内容的基础上,添加编程功能\n\n*/\npublic class Coder extends Person {\n    ', 497, 497, 1, '4dbd7c18-c7fa-48ad-859e-8ef08b124d17', NULL, '2026-03-27 20:11:11');
INSERT INTO `document_chunk` VALUES (457, 7, 1, 6, 'on: 程序员类\n\n*    \n* 定义子类程序员类,继承人类\n\n* 在人类共性内容的基础上,添加编程功能\n\n*/\npublic class Coder extends Person {\n    \n\n/**      \n\n* @Title: code      \n\n* @Description: 编写代码的方法          \n\n*/    \n\npublic void code() {    \n\nSystem.out.println(\"我写了一个百度!\");        \n\n}    \n\n \n}\n\n\n\n \n\n测试类ExtendsDemo：\n\n/**  \n* @ClassName: Teacher  \n* @Description: 老师类\n\n*    \n* 定义子类老师类,继承人类\n\n* 在人类共性内容的基础上,添加教学功能\n\n*/\npublic class Teacher extends Person {\n\n/**      \n\n* @Title: teach      \n\n* @Description: 教书的方法          \n\n*/    ', 487, 487, 1, '2954a308-456c-4269-9a5c-4c4e81209af6', NULL, '2026-03-27 20:11:11');
INSERT INTO `document_chunk` VALUES (458, 7, 1, 7, 'eacher extends Person {\n\n/**      \n\n* @Title: teach      \n\n* @Description: 教书的方法          \n\n*/    \n\npublic void teach() {    \n\nSystem.out.println(\"传授知识!\");        \n\n}    \n\n \n}\n\n\n\n \n\n1.3 子类通过get&set方法访问父类成员变量 \n\n/**  \n* @ClassName: ExtendsDemo  \n* @Description: 继承关系的测试类\n\n*    \n*    继承关系：类与类之间的关系\n\n*    \n*    人：定义一些共性内容 定义为父类 \n\n*     共性的成员变量：姓名、年龄       \n\n*     共性的成员方法：吃饭、睡觉       \n\n*    \n*    程序员、老师、工人 定义为人类的子类，子类可以在父类的基础上扩展新的成员变量与方法  \n\n*    \n*    当有了子父类关系后，子类拥有了父类的成员，可以直接访问父类的非私有成员', 484, 484, 1, 'c910e653-1c40-425f-9b79-8af2a7741ec9', NULL, '2026-03-27 20:11:11');
INSERT INTO `document_chunk` VALUES (459, 7, 1, 8, ' \n*    程序员、老师、工人 定义为人类的子类，子类可以在父类的基础上扩展新的成员变量与方法  \n\n*    \n*    当有了子父类关系后，子类拥有了父类的成员，可以直接访问父类的非私有成员\n\n*    继承通过这样的方式，提高了代码的复用性，让类与类之间产生了关系\n\n*    继承关系必须符合is a的关系，即我是你的一种\n\n*   \n继承的格式:        \n\n*  public class 子类   extends  父类 {      \n\n*           \n*  }      \n\n* \n* 注意:\n*  所有的类(除Object类)都有父类,所有的类都直接或间接是Object的子类      \n\n*/\npublic class ExtendsDemo {\n\npublic static void main(String[] args) {    \n\n//创建子类对象        \n\nCoder coder = new Coder();        \n\n        \n\n//使用子类可以访问父类的非私有成员变量        ', 484, 484, 1, '7f5017e4-dee8-40fc-8df0-c083c9194de8', NULL, '2026-03-27 20:11:12');
INSERT INTO `document_chunk` VALUES (460, 7, 1, 9, '    \n\n//创建子类对象        \n\nCoder coder = new Coder();        \n\n        \n\n//使用子类可以访问父类的非私有成员变量        \n\ncoder.name = \"拜伦\";        \n\ncoder.age = 18;        \n\nSystem.out.println(coder.name+\"的年龄是:\"+coder.age);        \n\n//使用子类可以访问父类的非私有成员方法        \n\ncoder.eat();        \n\ncoder.sleep();        \n\n//使用子类可以访问子类的自身的成员方法        \n\ncoder.code();        \n\n}    \n\n}\n\naf://n111\n\n\n1.3 子类通过get&set方法访问父类成员变量 \n\n 当父类的成员变量用private修饰后,子类无法访问父类的成员变量,但是如果父类提供了public修饰的get/set方法,\n则子类可以通过get/set方法,正常访问父类的成员变量。\n\n案例', 488, 488, 1, '7fda075b-90d7-437c-8e97-81d27999fbb2', NULL, '2026-03-27 20:11:12');
INSERT INTO `document_chunk` VALUES (461, 7, 1, 10, '当父类的成员变量用private修饰后,子类无法访问父类的成员变量,但是如果父类提供了public修饰的get/set方法,\n则子类可以通过get/set方法,正常访问父类的成员变量。\n\n案例\n\n父类Person类：\n\naf://n111\n\n\n /**  \n* @ClassName: Person  \n* @Description: Person类\n*    \n* 父类‐人类:\n*  年龄,姓名      \n\n*  吃饭,睡觉      \n\n*/\npublic class Person extends Object {\n    //使用private修饰后,子类无法访问\n\n/**      \n\n* @Fields name : 姓名      \n\n*/      \n\nprivate String name;    \n\n/**      \n\n* @Fields age : 年龄      \n\n*/      \n\nprivate int age;    \n\n    \n\n/**      \n\n* @Title: Person          \n\n*/    ', 484, 484, 1, '3f301966-933a-437d-b795-249de5da534d', NULL, '2026-03-27 20:11:12');
INSERT INTO `document_chunk` VALUES (462, 7, 1, 11, 'ge : 年龄      \n\n*/      \n\nprivate int age;    \n\n    \n\n/**      \n\n* @Title: Person          \n\n*/    \n\npublic Person() {    \n\n}    \n\n \n/**      \n\n* @Title: Person      \n\n* @param name    \n\n* @param age        \n\n*/    \n\npublic Person(String name, int age) {    \n\nthis.name = name;        \n\nthis.age = age;        \n\n}    \n\n    \n\n/**      \n\n* @Title: eat      \n\n* @Description: 吃东西的方法          \n\n*/    \n\npublic void eat() {    \n\nSystem.out.println(\"我吃了\");        \n\n}    \n\n \n/**      ', 477, 477, 1, '4a1a3d91-0266-44eb-8cbb-79809fdcb607', NULL, '2026-03-27 20:11:12');
INSERT INTO `document_chunk` VALUES (463, 7, 1, 12, '         \n\n*/    \n\npublic void eat() {    \n\nSystem.out.println(\"我吃了\");        \n\n}    \n\n \n/**      \n\n* @Title: sleep      \n\n* @Description: 睡觉的方法          \n\n*/    \n\npublic void sleep() {    \n\nSystem.out.println(\"我睡了\");        \n\n}    \n\n \n//成员变量被private修饰,子类无法直接访问,但是可以通过get/set方法访问    \n\n/**    \n\n * @return the name\n\n\n\n定义子类Coder：\n\n * @return the name    \n\n */    \n\npublic String getName() {    \n\nreturn name;        \n\n}    \n\n \n/**    \n\n * @param name the name to set    \n\n */    ', 477, 477, 1, '0cf5bc07-e4c1-4fa7-bc9e-c1bab33643bf', NULL, '2026-03-27 20:11:12');
INSERT INTO `document_chunk` VALUES (464, 7, 1, 13, 'tName() {    \n\nreturn name;        \n\n}    \n\n \n/**    \n\n * @param name the name to set    \n\n */    \n\npublic void setName(String name) {    \n\nthis.name = name;        \n\n}    \n\n \n/**    \n\n * @return the age    \n\n */    \n\npublic int getAge() {    \n\nreturn age;        \n\n}    \n\n \n/**    \n\n * @param age the age to set    \n\n */    \n\npublic void setAge(int age) {    \n\nthis.age = age;        \n\n}    \n\n}\n\n\n\n \n\n测试类ExtendsDemo：\n\n/**  \n* @ClassName: Coder  \n* @Description: 程序员类\n\n*    \n* 定义子类程序员类,继承人类', 490, 490, 1, '03e1af92-9b12-4c42-a6eb-12e4f7739ad6', NULL, '2026-03-27 20:11:12');
INSERT INTO `document_chunk` VALUES (465, 7, 1, 14, '}\n\n\n\n \n\n测试类ExtendsDemo：\n\n/**  \n* @ClassName: Coder  \n* @Description: 程序员类\n\n*    \n* 定义子类程序员类,继承人类\n\n* 在人类共性内容的基础上,添加编程功能\n\n*/\npublic class Coder extends Person {\n    \n\n/**    \n\n * @Title: code      \n\n * @Description: 编写代码的方法          \n\n */    \n\npublic void code() {    \n\nSystem.out.println(\"我写了一个百度!\");        \n\n}    \n\n \n}\n\n\n\n \n\n1.4 继承的特点 \n\n1.4.1 特点概述 \n\nJava支持单继承\n\nJava支持多层继承\n\n父类定义了继承树中共性内容，子类定义了该类个性内容。\n\n在结合多态后，能使用父类时尽量使用父类，提高程序扩展性。\n\n1.4.2 案例 \n\n测试类：ExtendsNotesDemo', 463, 463, 1, 'd2618f8b-be66-41d6-bb48-6d1d55ef57cc', NULL, '2026-03-27 20:11:12');
INSERT INTO `document_chunk` VALUES (466, 7, 1, 15, '在结合多态后，能使用父类时尽量使用父类，提高程序扩展性。\n\n1.4.2 案例 \n\n测试类：ExtendsNotesDemo\n\n/**  \n* @ClassName: ExtendsDemo  \n* @Description: 继承关系的测试类\n\n*    \n* 当父类的成员变量用private修饰后,子类无法访问父类的成员变量,\n* 但是如果父类提供了public修饰的get/set方法,则子类可以通过get/set方法,正常访问父类的成员变量\n\n*/\npublic class ExtendsDemo {\n\npublic static void main(String[] args) {    \n\n//创建子类对象        \n\nCoder coder = new Coder();        \n\n        \n\n//使用子类可以通过public修饰的get/set方法访问父类的私有成员变量        \n\ncoder.setName(\"拜伦\");        \n\ncoder.setAge(18);        ', 471, 471, 1, '7ad69e02-d50a-4c3d-8148-f77645eada9a', NULL, '2026-03-27 20:11:13');
INSERT INTO `document_chunk` VALUES (467, 7, 1, 16, '可以通过public修饰的get/set方法访问父类的私有成员变量        \n\ncoder.setName(\"拜伦\");        \n\ncoder.setAge(18);        \n\nSystem.out.println(coder.getName()+\"的年龄是:\"+coder.getAge()); //使用子类可以访问父\n\n类的非私有成员方法\n\n              \n\ncoder.eat();        \n\ncoder.sleep();        \n\n//使用子类可以访问子类的自身的成员方法        \n\ncoder.code();        \n\n \n}    \n\n}\n\naf://n135\naf://n136\naf://n147\n\n\n \n\n父类Fu1\n\n \n\n父类Fu2\n\n \n\n子类Zi1\n\n/**  \n* @ClassName: ExtendsNotesDemo  \n* @Description: 继承特点\n\n*    \n* Java支持单继承\n\n* Java支持多层继承', 465, 465, 1, 'bacae140-27ce-4fb1-8bb5-b1891e26c052', NULL, '2026-03-27 20:11:13');
INSERT INTO `document_chunk` VALUES (468, 7, 1, 17, '类Zi1\n\n/**  \n* @ClassName: ExtendsNotesDemo  \n* @Description: 继承特点\n\n*    \n* Java支持单继承\n\n* Java支持多层继承\n\n*/\n \npublic class ExtendsNotesDemo {\n\npublic static void main(String[] args) {    \n\n        \n\n}    \n\n}\n\n/**  \n* @ClassName: Fu1  \n* @Description: 父类1\n*/\npublic class Fu1 {\n \n}\n\n/**  \n* @ClassName: Fu2  \n* @Description: 父类2\n*/\npublic class Fu2 {\n \n}\n\n\n\n \n\n孙子类Sun1\n\n \n\n第2章 方法重写及继承内存图解 \n\n2.1 方法重写的概念与格式 \n\n2.1.1 方法重写的概述 \n\n当子类继承父类后，拥有了父类的成员并可以直接调用父类非私有方法。如果子类认为父类提供的方法不够强大，', 468, 468, 1, '6de96558-edc1-47fa-b919-483593b78e5f', NULL, '2026-03-27 20:11:13');
INSERT INTO `document_chunk` VALUES (469, 7, 1, 18, '如果子类认为父类提供的方法不够强大，\n\n子类可以按照子类自身的逻辑重新定义继承过来的父类方法，这个重新定义父类方法的过程叫做方法重写。\n\n方法重写后，调用该方法时不再调用父类的方法，而调用子类重写后的方法。\n\n举例：\n\n当描述一个人类(父类)时，它具有吃饭，睡觉等功能\n\n/**  \n* @ClassName: Zi1  \n* @Description: 子类\n\n*    \n* 一个子类不能拥有多个直接父类,继承只支持单继承\n\n* public class Zi1 extends Fu1,Fu2{\n* \n* }\n* \n* 一个子类可以有一个父类\n\n*/\npublic class Zi1 extends Fu1 {\n \n}\n\n/**  \n* @ClassName: Sun1  \n* @Description: 孙子类\n\n*    \n* Sun1类直接继承Zi1类,间接继承Fu1类与Object类\n* 继承存在多层继承\n\n*/\n \npublic class Sun1 extends Zi1 {\n \n}\n\naf://n173\naf://n174\naf://n175', 485, 485, 1, 'b04ecfbb-840b-4aed-b507-883d8d51767e', NULL, '2026-03-27 20:11:13');
INSERT INTO `document_chunk` VALUES (470, 7, 1, 19, '承Fu1类与Object类\n* 继承存在多层继承\n\n*/\n \npublic class Sun1 extends Zi1 {\n \n}\n\naf://n173\naf://n174\naf://n175\n\n\n中国人类(子类)吃饭比较复杂，使用筷子吃饭，则可以继承原有的人类。并重写吃饭功能，在其中修改为更为复杂\n\n的用筷子吃的逻辑即可。\n\n(注：在学习完多态和抽象类后我们会对方法重写有更深的理解)\n\n2.1.2 方法重写的案例 \n\n格式:\n\n 定义一个与父类方法声明完全相同的方法,方法体重写\n\n测试类：OverrideDemo\n\n \n\n定义父类Animal\n\n/**  \n* @ClassName: OverrideDemo  \n* @Description: override测试类\n\n*    \n* 方法重写:\n*  当子类想加强父类继承过来的方法时,可以重写该方法      \n\n* \n* 重写格式:\n*  定义一个与父类方法声明完全相同的方法,方法体重写      \n\n*/\npublic class OverrideDemo {', 467, 467, 1, '8c195038-afc6-4a94-aa44-d8e09fad3426', NULL, '2026-03-27 20:11:13');
INSERT INTO `document_chunk` VALUES (471, 7, 1, 20, '过来的方法时,可以重写该方法      \n\n* \n* 重写格式:\n*  定义一个与父类方法声明完全相同的方法,方法体重写      \n\n*/\npublic class OverrideDemo {\n\npublic static void main(String[] args) {    \n\n//创建子类对象        \n\nDog dog = new Dog();        \n\n        \n\n//调用方法        \n\n//调用了子类重写的方法功能        \n\ndog.eat();        \n\n//调用了还是子类从父类继承下来的方法功能        \n\ndog.sleep();             \n\n}    \n\n}\n\naf://n190\n\n\n \n\n定义子类Dog类\n\n/**\n* @ClassName: Animal  \n* @Description: 父类Animal\n*/\npublic class Animal {\n\n/**      \n\n* @Title: eat      \n\n* @Description: 吃东西的方法         ', 498, 498, 1, '423e4108-f1ca-467d-a3fa-2d30f8c3dc0a', NULL, '2026-03-27 20:11:13');
INSERT INTO `document_chunk` VALUES (472, 7, 1, 21, '父类Animal\n*/\npublic class Animal {\n\n/**      \n\n* @Title: eat      \n\n* @Description: 吃东西的方法         \n\n*/    \n\npublic void eat() {    \n\nSystem.out.println(\"吃了!\");        \n\n}    \n\n    \n\n/**      \n\n* @Title: sleep      \n\n* @Description: 睡觉的方法          \n\n*/    \n\npublic void sleep() {    \n\nSystem.out.println(\"睡了!\");        \n\n}    \n\n}\n\n\n\n \n\n2.2 Override注解解释 \n\n2.2.1 Override \n\n子类重写父类的方法时在方法上添加 @Override注解,表示该方法是子类重写父类中的方法。\n\n2.2.2 案例 \n\n测试类：OverrideDemo\n\n/**  \n* @ClassName: Dog  \n* @Description: 子类狗类', 494, 494, 1, '231178b7-c292-481f-9635-3b80d72a8735', NULL, '2026-03-27 20:11:14');
INSERT INTO `document_chunk` VALUES (473, 7, 1, 22, '2.2.2 案例 \n\n测试类：OverrideDemo\n\n/**  \n* @ClassName: Dog  \n* @Description: 子类狗类\n\n*    \n*    子类狗类:\n*     增强父类的吃饭方法,于是可以重写该方法   \n\n*\n*    格式:\n*     定义一个与父类方法声明完全相同的方法,方法体重写   \n\n*/\npublic class Dog extends Animal {\n    \n\n/**      \n\n* @Title: eat      \n\n* @Description: 狗吃东西的方法      \n\n*/    \n\npublic void eat() {    \n\nSystem.out.println(\"我是小狗,我汪汪汪着吃骨头!\");        \n\n}    \n\n}\n\naf://n212\naf://n213\naf://n218\n\n\n \n\n定义父类Animal\n\n/**  \n* @ClassName: OverrideDemo  \n* @Description: override测试类', 475, 475, 1, 'a657915e-de42-4519-bb34-63136cc90354', NULL, '2026-03-27 20:11:14');
INSERT INTO `document_chunk` VALUES (474, 7, 1, 23, 'f://n213\naf://n218\n\n\n \n\n定义父类Animal\n\n/**  \n* @ClassName: OverrideDemo  \n* @Description: override测试类\n\n*    \n* 方法重写:\n*  当子类想加强父类继承过来的方法时,可以重写该方法      \n\n* \n* 重写格式:\n*  定义一个与父类方法声明完全相同的方法,方法体重写      \n\n*/\n \npublic class OverrideDemo {\n\npublic static void main(String[] args) {    \n\n//创建子类对象        \n\nDog dog = new Dog();        \n\n        \n\n//调用方法        \n\n//调用了子类重写的方法功能        \n\n        dog.eat();\n//调用了还是子类从父类继承下来的方法功能        \n\ndog.sleep();        \n\n}    \n\n}\n\n\n\n \n\n定义子类Dog类', 468, 468, 1, '74fd737a-1720-47f2-aac7-5eccce2faf24', NULL, '2026-03-27 20:11:14');
INSERT INTO `document_chunk` VALUES (475, 7, 1, 24, ' \n\n        dog.eat();\n//调用了还是子类从父类继承下来的方法功能        \n\ndog.sleep();        \n\n}    \n\n}\n\n\n\n \n\n定义子类Dog类\n\n/**  \n* @ClassName: Animal  \n* @Description: 父类Animal\n*/\npublic class Animal {\n\n/**      \n\n* @Title: eat      \n\n* @Description: 吃东西的方法         \n\n*/    \n\npublic void eat() {    \n\nSystem.out.println(\"吃了!\");        \n\n}    \n\n    \n\n/**      \n\n* @Title: sleep      \n\n* @Description: 睡觉的方法          \n\n*/    \n\npublic void sleep() {    \n\nSystem.out.println(\"睡了!\");        \n\n}    \n\n \n}\n\n\n\n \n\n2.3 方法重写注意事项', 494, 494, 1, '9e33b3e4-f622-43fa-a562-3f2fa66d4d2d', NULL, '2026-03-27 20:11:14');
INSERT INTO `document_chunk` VALUES (476, 7, 1, 25, '   \n\npublic void sleep() {    \n\nSystem.out.println(\"睡了!\");        \n\n}    \n\n \n}\n\n\n\n \n\n2.3 方法重写注意事项 \n\n2.3.1 注意事项概述 \n\n发生在继承关系中\n\n方法名称必须相同\n\n参数列表必须相同\n\n访问权限相同或子类方法访问权限更大(访问权限顺序public>默认)\n\n返回值为一般必须相同(并不适用于所有情况)\n\n子类抛出异常比父类小\n\n/**  \n* @ClassName: Dog  \n* @Description: 子类狗类\n\n*    \n*    子类狗类:\n*     增强父类的吃饭方法,于是可以重写该方法   \n\n*    \n*    格式:\n*     定义一个与父类方法声明完全相同的方法,方法体重写   \n\n*/\npublic class Dog extends Animal {\n\n//方法重写的注解    \n\n/**      \n\n* @Title: eat      \n\n* @Description: 狗吃东西的方法      ', 475, 475, 1, '953c3cb2-1e63-438a-bc84-ce9c6f0dcca6', NULL, '2026-03-27 20:11:14');
INSERT INTO `document_chunk` VALUES (477, 7, 1, 26, 'Dog extends Animal {\n\n//方法重写的注解    \n\n/**      \n\n* @Title: eat      \n\n* @Description: 狗吃东西的方法      \n\n* @see com.igeek_02.Animal#eat()    \n\n*/    \n\n@Override    \n\npublic void eat() {    \n\nSystem.out.println(\"我是小狗,我汪汪汪着吃骨头!\");        \n\n}    \n\n    \n\n// @Override用于限定该方法必须是重写父类的方法  \n\n// @Override  \n\n// public void eet() {  \n\n// System.out.println(\"我是小狗,我汪汪汪着吃骨头!\");      \n\n// }  \n\n}\n\naf://n234\naf://n235\n\n\n2.3.2 案例 \n\n父类Animal\n\n \n\n子类Dog', 431, 431, 1, '023bc910-6d7e-42d4-80c5-fa6034221610', NULL, '2026-03-27 20:11:14');
INSERT INTO `document_chunk` VALUES (478, 7, 1, 27, 't.println(\"我是小狗,我汪汪汪着吃骨头!\");      \n\n// }  \n\n}\n\naf://n234\naf://n235\n\n\n2.3.2 案例 \n\n父类Animal\n\n \n\n子类Dog\n\n/**  \n* @ClassName: Animal  \n* @Description: 父类Animal\n* @date 2017年11月13日 下午5:08:09    \n* Company www.igeekhome.com\n*    \n*/\npublic class Animal {\n\n/**      \n\n* @Title: eat      \n\n* @Description: 吃东西的方法         \n\n*/    \n\nvoid eat() {    \n\nSystem.out.println(\"吃了!\");        \n\n}    \n\n    \n\n/**      \n\n* @Title: sleep      \n\n* @Description: 睡觉的方法          \n\n*/    \n\nvoid sleep() {    ', 481, 481, 1, '4184a9a1-08c5-4e13-ae65-1523a1f66f83', NULL, '2026-03-27 20:11:14');
INSERT INTO `document_chunk` VALUES (479, 7, 1, 28, '   \n\n/**      \n\n* @Title: sleep      \n\n* @Description: 睡觉的方法          \n\n*/    \n\nvoid sleep() {    \n\nSystem.out.println(\"睡了!\");        \n\n}    \n\n \n}\n\naf://n250\n\n\n \n\n2.4 继承后子父类构造方法调用先后顺序 \n\n2.4.1 继承中子父类构造调用顺序概述 \n\n在每次创建子类对象时，我们均会先初始化父类内容，再初始化其子类本身内容。目的在于子类对象中包含了其对\n\n应的父类存储空间，便可以包含了其父类的成员，如果父类成员非private修饰，则子类可以随意使用父类成员。\n\n代码体现在子类的构造方法调用时，一定先调用父类的构造方法。\n\n2.4.2 案例 \n\n测试类ConstructorDemo\n\n/**  \n* @ClassName: Dog  \n* @Description: 子类狗类\n\n*    \n* 方法重写的注意事项:\n*  访问权限:父类的访问权限 小于等于 子类的访问权限      ', 479, 479, 1, 'a845b003-079e-4aa8-aa33-df08a0517028', NULL, '2026-03-27 20:11:15');
INSERT INTO `document_chunk` VALUES (480, 7, 1, 29, '  \n* @ClassName: Dog  \n* @Description: 子类狗类\n\n*    \n* 方法重写的注意事项:\n*  访问权限:父类的访问权限 小于等于 子类的访问权限      \n\n*   默认权限 < public              \n\n*/\npublic class Dog extends Animal {\n    \n\n//方法重写子类权限大于或等于父类权限    \n\n    //返回值类型相同\n\n//方法名必须相同    \n\n//方法参数必须相同    \n\n/**      \n\n* @Title: eat      \n\n* @Description: 狗吃东西的方法      \n\n* @see com.igeek_02.Animal#eat()    \n\n*/    \n\n@Override    \n\npublic void eat() {    \n\nSystem.out.println(\"我是小狗,我汪汪汪着吃骨头!\");        \n\n}    \n\n    \n\n}\n\naf://n261\naf://n262\naf://n269\n\n\n \n\n父类Fu', 498, 498, 1, 'c9be33fa-d96e-4247-99a4-8bc6e9b3a510', NULL, '2026-03-27 20:11:15');
INSERT INTO `document_chunk` VALUES (481, 7, 1, 30, 'em.out.println(\"我是小狗,我汪汪汪着吃骨头!\");        \n\n}    \n\n    \n\n}\n\naf://n261\naf://n262\naf://n269\n\n\n \n\n父类Fu\n\n/**  \n* @ClassName: ConstructorDemo  \n* @Description: 构造方法测试类\n\n*    \n*    子类的构造方法会先调用父类的无参构造，从而保证父类的相关内容会先于子类内容的初识化\n\n*    子类就可以使用父类的内容了\n\n*/\n \npublic class ConstructorDemo {\n\npublic static void main(String[] args) {    \n\n//创建子类对象,验证注释部分的结论        \n\nZi zi = new Zi();        \n\n}    \n\n}\n\n\n\n /**  \n* @ClassName: Fu  \n* @Description: Fu父类', 433, 433, 1, '30391333-b620-4aa4-b3e5-58c39ec9b708', NULL, '2026-03-27 20:11:15');
INSERT INTO `document_chunk` VALUES (482, 7, 1, 31, '的结论        \n\nZi zi = new Zi();        \n\n}    \n\n}\n\n\n\n /**  \n* @ClassName: Fu  \n* @Description: Fu父类\n\n* @date 2017年11月13日 下午5:34:15    \n* Company www.igeekhome.com\n*    \n*/\npublic class Fu {\n\n/**      \n\n* @Fields name : 姓名      \n\n*/      \n\nprivate String name;    \n\n \n/**      \n\n* @Title: Fu          \n\n*/    \n\npublic Fu() {    \n\n// super();        \n\nSystem.out.println(\"父类的空参构造方法被调用了\");        \n\n}    \n\n \n/**      \n\n* @Title: Fu      \n\n* @param name        \n\n*/    \n\npublic Fu(String name) {    ', 494, 494, 1, 'f62b712b-b49d-4229-b5fd-ae403ff2c511', NULL, '2026-03-27 20:11:15');
INSERT INTO `document_chunk` VALUES (483, 7, 1, 32, '    \n\n \n/**      \n\n* @Title: Fu      \n\n* @param name        \n\n*/    \n\npublic Fu(String name) {    \n\n// super();        \n\nthis.name = name;        \n\nSystem.out.println(\"父类的带参构造方法被调用了\");        \n\n}    \n\n    /**\n * @return the name    \n\n */    \n\npublic String getName() {    \n\nreturn name;        \n\n}    \n\n \n/**    \n\n * @param name the name to set    \n\n */    \n\npublic void setName(String name) {    \n\nthis.name = name;        \n\n}    \n\n    \n\n}\n\n\n\n子类Zi\n\n \n\n2.5 继承后，子父类内存图 \n\n2.5.1 案例 \n\n测试类：', 485, 485, 1, '19b9fcc7-3e8d-41dc-877c-044bfa57e1dd', NULL, '2026-03-27 20:11:15');
INSERT INTO `document_chunk` VALUES (484, 7, 1, 33, 'ame) {    \n\nthis.name = name;        \n\n}    \n\n    \n\n}\n\n\n\n子类Zi\n\n \n\n2.5 继承后，子父类内存图 \n\n2.5.1 案例 \n\n测试类：\n\n/**  \n* @ClassName: Zi  \n* @Description: Zi子类\n\n*    \n*/\npublic class Zi extends Fu {\n\npublic Zi() {    \n\nsuper();//这个super语句决定了子类构造方法调用父类空参构造        \n\nSystem.out.println(\"子类的构造方法被调用了\");        \n\n}    \n\n}\n\naf://n285\naf://n286\n\n\n \n\n定义父类Person\n\n/**  \n* @ClassName: ThisSuperDemo  \n* @Description: 继承测试类\n\n*    \n* this:当前对象\n\n* super:父类存储空间\n\n* \n* Person父类\n\n*  name,age  \n\n* \n* Chinese子类\n\n*   address ', 494, 494, 1, '363d728b-c6c2-4ec3-9558-e3b58b99e30f', NULL, '2026-03-27 20:11:16');
INSERT INTO `document_chunk` VALUES (485, 7, 1, 34, '测试类\n\n*    \n* this:当前对象\n\n* super:父类存储空间\n\n* \n* Person父类\n\n*  name,age  \n\n* \n* Chinese子类\n\n*   address \n\n*/\npublic class ThisSuperDemo {\n\npublic static void main(String[] args) {    \n\n//创建子类对象        \n\nChinese c = new Chinese(\"Jack\",18,\"中南海\");        \n\n//调用该类方法        \n\nSystem.out.println(c.getName()+\"住在\"+c.getAddress());        \n\n}    \n\n}\n\n\n\n /**  \n* @ClassName: Person  \n* @Description: Person类\n*    \n* 父类‐人类:\n*  属性：name，age      \n\n*/\n \npublic class Person extends Object {\n\n/**      ', 483, 483, 1, '8ee6fa63-3952-4931-8ade-1fd7864b6ded', NULL, '2026-03-27 20:11:16');
INSERT INTO `document_chunk` VALUES (486, 7, 1, 35, ' Person类\n*    \n* 父类‐人类:\n*  属性：name，age      \n\n*/\n \npublic class Person extends Object {\n\n/**      \n\n* @Fields name : 姓名      \n\n*/      \n\nprivate String name;    \n\n/**      \n\n* @Fields age : 年龄      \n\n*/      \n\nprivate int age;    \n\n    \n\n/**      \n\n* @Title: Person          \n\n*/    \n\npublic Person() {    \n\n}    \n\n \n/**      \n\n* @Title: Person      \n\n* @param name    \n\n* @param age        \n\n*/    \n\npublic Person(String name, int age) {    \n\nthis.name = name;        \n\nthis.age = age;        ', 494, 494, 1, 'ca69cd19-249a-4f49-afa4-0374a3e67c70', NULL, '2026-03-27 20:11:16');
INSERT INTO `document_chunk` VALUES (487, 7, 1, 36, '   \n\npublic Person(String name, int age) {    \n\nthis.name = name;        \n\nthis.age = age;        \n\n}    \n\n    \n\n/**    \n\n * @return the name    \n\n */    \n\npublic String getName() {    \n\nreturn name;        \n\n}    \n\n \n/**    \n\n * @param name the name to set    \n\n */    \n\npublic void setName(String name) {    \n\nthis.name = name;        \n\n}    \n\n \n/**    \n\n * @return the age    \n\n */    \n\npublic int getAge() {    \n\nreturn age;        \n\n}\n\n\n\n定义子类Chinese\n\n}    \n\n \n/**    ', 472, 472, 1, '2b0881c6-5ccc-4566-a395-3827ce959d62', NULL, '2026-03-27 20:11:16');
INSERT INTO `document_chunk` VALUES (488, 7, 1, 37, 'e    \n\n */    \n\npublic int getAge() {    \n\nreturn age;        \n\n}\n\n\n\n定义子类Chinese\n\n}    \n\n \n/**    \n\n * @param age the age to set    \n\n */    \n\n    public void setAge(int age) {\nthis.age = age;        \n\n}    \n\n \n}\n\n\n\n /**  \n* @ClassName: Chinese  \n* @Description: Chinese子类\n\n* @date 2017年11月13日 下午6:33:43    \n* Company www.igeekhome.com\n*  \n* 在父类Person的基础上,多了地址属性：\n\n*  address  \n\n*/\npublic class Chinese extends Person{\n    \n\n/**      \n\n* @Fields address : 地址      \n\n*/      ', 474, 474, 1, '6571600c-762e-41ca-8618-e22c0ae160d8', NULL, '2026-03-27 20:11:16');
INSERT INTO `document_chunk` VALUES (489, 7, 1, 38, ' \n\n*/\npublic class Chinese extends Person{\n    \n\n/**      \n\n* @Fields address : 地址      \n\n*/      \n\nprivate String address;    \n\n \n/**      \n\n* @Title: Chinese          \n\n*/    \n\npublic Chinese() {    \n\nsuper();        \n\n}    \n\n \n//定义三个参数的构造方法,无需了解细节,在super的讲解时会详细介绍    \n\n/**      \n\n* @Title: Chinese      \n\n* @param name    \n\n* @param age    \n\n* @param address        \n\n*/    \n\npublic Chinese(String name, int age,String address) {    \n\nsuper(name, age);        \n\nthis.address = address;        ', 496, 496, 1, '05c5884e-7f28-480a-969b-ca6d9831ab9b', NULL, '2026-03-27 20:11:16');
INSERT INTO `document_chunk` VALUES (490, 7, 1, 39, 'ng name, int age,String address) {    \n\nsuper(name, age);        \n\nthis.address = address;        \n\n}    \n\n    /**\n * @return the address    \n\n */    \n\npublic String getAddress() {    \n\nreturn address;        \n\n}    \n\n \n/**    \n\n * @param address the address to set    \n\n */    \n\npublic void setAddress(String address) {    \n\nthis.address = address;        \n\n}    \n\n \n}\n\n\n\n2.5.2 对象内存图 \n\n第3章 this与super \n\n3.1 this与super访问普通成员 \n\n3.1.1 this和super访问注意事项 \n\n调用普通成员：\n\nthis.成员变量 可以访问本类对象的成员变量', 484, 484, 1, 'c3b52460-0ef7-48d0-8b25-daefbba9dfef', NULL, '2026-03-27 20:11:17');
INSERT INTO `document_chunk` VALUES (491, 7, 1, 40, '第3章 this与super \n\n3.1 this与super访问普通成员 \n\n3.1.1 this和super访问注意事项 \n\n调用普通成员：\n\nthis.成员变量 可以访问本类对象的成员变量\n\nsuper.成员变量 可以访问父类的成员变量\n\nthis.成员方法() 可以访问本类对象的成员方法\n\nsuper.成员方法() 可以访问父类的成员方法\n\n子类方法中\n\n 访问子类自身的成员用this.\n\n 访问父类的成员super.\n\n就近原则:\n\n 局部 > 本类成员 > 父类成员\n\naf://n302\naf://n307\naf://n308\naf://n309\n\n\n3.1.2 案例 \n\n测试类ThisSuperDemo\n\n \n\n父类Person\n\n/**  \n* @ClassName: ThisSuperDemo  \n* @Description: 继承测试类\n\n*    \n*/\npublic class ThisSuperDemo {\n    public static void main(String[] args) {', 468, 468, 1, 'd12b902d-4c0a-4559-920f-c6d27b2fc491', NULL, '2026-03-27 20:11:17');
