INSERT INTO `document_chunk` VALUES (496, 7, 1, 45, '  \n\n* @Title: Chinese      \n\n* @param name    \n\n* @param age    \n\n* @param address        \n\n*/    \n\npublic Chinese(String name, int age,String address) {    \n\nsuper(name, age);        \n\nthis.address = address;        \n\n}    \n\n \n/**      \n\n* @Title: eat      \n\n* @Description: 子类吃饭的方法      \n\n* @see com.igeek_01.Person#eat()    \n\n*/    \n\n@Override    \n\npublic void eat() {    \n\nSystem.out.println(\"子类吃饭\");        \n\n}    \n\n    \n\n/**      \n\n* @Title: testAccess      ', 464, 464, 1, '9c022963-7df0-42c0-aa87-71bbcee147d3', NULL, '2026-03-27 20:11:18');
INSERT INTO `document_chunk` VALUES (497, 7, 1, 46, 't() {    \n\nSystem.out.println(\"子类吃饭\");        \n\n}    \n\n    \n\n/**      \n\n* @Title: testAccess      \n\n* @Description: 测试访问成员的方法          \n\n*/    \n\npublic void testAccess() {    \n\n        \n\n//访问成员时,在不考虑private修饰的情况下\n\n\n\n3.2 super访问父类构造方法 \n\n3.2.1 super调用父类构造方法的格式 \n\n调用构造方法：\n\n this(其他参数) 可以访问本类其他的构造方法\n\n super(其他参数) 可以访问父类其他的构造方法\n\n默认子类调用父类构造方法：\n\n 子类的每个构造方法中均有默认的super(),调用父类的空参构造。手动调用父类构造会覆盖默认的super();\n\n3.2.2 案例 \n\n//访问成员时,在不考虑private修饰的情况下        \n\n//本类对象成员用this.调用        \n\n//父类成员用super.调用        ', 493, 493, 1, '87f47dac-1637-4077-a679-74f7543660f7', NULL, '2026-03-27 20:11:18');
INSERT INTO `document_chunk` VALUES (498, 7, 1, 47, ';\n\n3.2.2 案例 \n\n//访问成员时,在不考虑private修饰的情况下        \n\n//本类对象成员用this.调用        \n\n//父类成员用super.调用        \n\nSystem.out.println(this.address);        \n\nSystem.out.println(super.name);        \n\nSystem.out.println(super.age);        \n\n        \n\nthis.eat();        \n\n        super.eat();\n        \n\nint i = 100;        \n\n        \n\nSystem.out.println(i);        \n\nSystem.out.println(this.i);        \n\nSystem.out.println(super.i);        \n\n}    \n\n}\n\naf://n351\naf://n352\naf://n367\n\n\n测试类ThisSuperConstructorsDemo\n\n ', 498, 498, 1, '8fe9f455-9236-43c2-aab3-3f865e56aebe', NULL, '2026-03-27 20:11:18');
