INSERT INTO `document_chunk` VALUES (501, 7, 1, 50, '   \n\n/**      \n\n* @Fields age : 年龄      \n\n*/      \n\nprivate int age = 16;    \n\n        \n\n/**      \n\n* @Title: Person          \n\n*/    \n\npublic Person() {    \n\nSystem.out.println(\"父类空参构造\");        \n\n}    \n\n    /**  \n* @Title: Person      \n\n* @param name    \n\n* @param age        \n\n*/    \n\npublic Person(String name, int age) {    \n\nSystem.out.println(\"父类带参构造\");        \n\nthis.name = name;        \n\nthis.age = age;        \n\n}    \n\n    \n\n/**      \n\n* @Title: eat      \n\n* @Description: 吃饭的方法          ', 498, 498, 1, '41f41e63-181a-4b77-a1be-63f5944a7a1e', NULL, '2026-03-27 20:11:18');
