INSERT INTO `document_chunk` VALUES (522, 7, 1, 71, ',工作方法为打印\"做饭\"\n*/\npublic class Cook extends Employee{\n \n\n/**      \n\n* @Title: Cook          \n\n*/    \n\npublic Cook() {    \n\nsuper();        \n\n}    \n\n \n/**      \n\n* @Title: Cook      \n\n* @param name    \n\n* @param salary        \n\n*/    \n\npublic Cook(String name, double salary) {    \n\nsuper(name, salary);        \n\n}    \n\n \n/**      \n\n* @Title: work      \n\n* @Description: 厨师的工作方法      \n\n* @see com.igeek_04.Employee#work()    \n\n*/    \n\n@Override    \n\npublic void work() {    ', 471, 471, 1, '44c81958-5475-442e-9a7e-3404d1c6efe4', NULL, '2026-03-27 20:11:22');
INSERT INTO `document_chunk` VALUES (523, 7, 1, 72, '方法      \n\n* @see com.igeek_04.Employee#work()    \n\n*/    \n\n@Override    \n\npublic void work() {    \n\nSystem.out.println(\"做饭\");        \n\n}    \n\n \n}\n\n\n\n /**  \n* @ClassName: DemoTest  \n* @Description: 测试类\n\n*    \n*  员工类  \n\n*  员工姓名,员工薪水,员工工作方法      \n\n* \n*  经理类,多加了奖金,工作方法为打印\"管理酒店\"  \n\n*  服务员类,工作方法为打印\"上菜与结账\"  \n\n*  厨师类,工作方法为打印\"做饭\"  \n\n* \n*  共有1个经理,2个服务员,1个厨师,(所有人的属性任意定义)  \n\n*  让所有的员工工作  \n\n*  并求所有人的总收入是多少?  \n\n*/\npublic class DemoTest {\n\npublic static void main(String[] args) {    \n\n//创建四个员工        ', 491, 491, 1, '01bef538-0de4-464c-adba-2fb6578228b3', NULL, '2026-03-27 20:11:22');
INSERT INTO `document_chunk` VALUES (524, 7, 1, 73, '是多少?  \n\n*/\npublic class DemoTest {\n\npublic static void main(String[] args) {    \n\n//创建四个员工        \n\nManager manager= new Manager(\"Jack\", 5000, 2000);        \n\nWaiter w1 = new Waiter(\"Rose\", 3000);        \n\nWaiter w2 = new Waiter(\"Obama\", 3000);        \n\nCook c = new Cook(\"Trump\", 6000);        \n\n        \n\n//调用让所有的员工工作的方法        \n\nemployee_work(manager, w1, w2, c);        \n\n        \n\n//调用方法，返回所有人的收入        \n\ndouble sum = getSum(manager, w1, w2, c);        ', 459, 459, 1, '402b1700-695d-45e7-ae8c-2c46c7a3382f', NULL, '2026-03-27 20:11:22');
INSERT INTO `document_chunk` VALUES (525, 7, 1, 74, ', c);        \n\n        \n\n//调用方法，返回所有人的收入        \n\ndouble sum = getSum(manager, w1, w2, c);        \n\nSystem.out.println(\"sum:\"+sum); }          \n\n    \n\n/**      \n\n* @Title: employee_work      \n\n* @Description: 让所有的员工工作的方法      \n\n* @param m    \n\n* @param w1    \n\n* @param w2    \n\n* @param c        \n\n*/    \n\npublic static void employee_work(Manager m,Waiter w1,Waiter w2,Cook c){    \n\nm.work();        \n\nw1.work();        \n\nw2.work();        \n\nc.work();        \n\n}        \n\n    \n\n/**      ', 487, 487, 1, '94652a3d-794e-42ef-bc57-3d2db636b9b4', NULL, '2026-03-27 20:11:22');
INSERT INTO `document_chunk` VALUES (526, 7, 1, 75, '();        \n\nw1.work();        \n\nw2.work();        \n\nc.work();        \n\n}        \n\n    \n\n/**      \n\n* @Title: getSum      \n\n* @Description: 计算所有人的总收入的方法      \n\n* @param m    \n\n* @param w1    \n\n* @param w2    \n\n* @param c    \n\n* @return        \n\n*/\n\n\n\n3.4.2 课堂练习 \n\n*/    \n\npublic static double getSum(Manager m,Waiter w1,Waiter w2,Cook c){    \n\nreturn m.getSalary()+m.getBonus()+w1.getSalary()+w2.getSalary()+c.getSalary();        \n\n}    \n\n}\n\naf://n469\n\n\n \n\n第4章 关联关系及依赖关系 \n\n1.创建一个“人”的类，有姓名和年龄，', 492, 492, 1, '1f52f020-a735-483a-93c9-59f8d04ed206', NULL, '2026-03-27 20:11:22');
INSERT INTO `document_chunk` VALUES (527, 7, 1, 76, '2.getSalary()+c.getSalary();        \n\n}    \n\n}\n\naf://n469\n\n\n \n\n第4章 关联关系及依赖关系 \n\n1.创建一个“人”的类，有姓名和年龄，\n\n有学生和工人继承这个类，他们也有姓名和年龄。\n\n学生有自己的学习方法，工人有自己的工作方法。\n\n现在有个学生叫张三，22岁，正在学习，有个工人叫李四，25岁，正在工作。\n\n \n \n2.\n/**\n\n1、创建GrandFather类，其中包括    \n\na)属性：姓名（name），年龄（age）    \n\nb)方法getGrandFather()：显示爷爷的信息    \n\nc)构造方法：给爷爷的姓名，年龄赋值    \n\n \n2、创建Father类，继承Grandfather类    \n\na)属性：除了继承爷爷的属性以外，还要增加自己的属性：“职业”(occupation)    \n\nb)构造方法：显式调用父类的构造方法，为Father类的姓名和年龄赋初始值。再为职业输入初始值。    \n\nc)方法getFather(): 显示父亲的相关信息    ', 477, 477, 1, '0f7451bf-8ebc-467a-86bb-3cd37f8ac4c5', NULL, '2026-03-27 20:11:22');
INSERT INTO `document_chunk` VALUES (528, 7, 1, 77, '再为职业输入初始值。    \n\nc)方法getFather(): 显示父亲的相关信息    \n\n \n3、创建ClassMain类，定义main()方法，构造GrandFather类的对象和Father类的对象，并分别显示详细信息    \n\n */\n \n \n \n/**\n * 3.写一个类Person,包含以下属性：\n\nString  name;    \n\nint  age;     \n\nboolean  gender;  //性别  true男  false女    \n\nPerson  partner;  //伴侣    \n\nPhone  phone;    \n\n  为Person类写一个marry(Person  p)方法，代表当前对象和p结婚，如若可以结婚，则输出恭贺信息，\n\n  否则输出不能结婚原因。要求在另外一个类中写一个主方法，来测试以上程序。\n\n （下列情况不能结婚：1，同性；2，未达到结婚年龄，男<24，女<22；3，某一方已婚）\n\n */\n \n \n \n4.现有员工Employee类，有姓名，地址，基本工资属性，', 469, 469, 1, '0f8a9f88-2569-41b5-97b3-bb4dd3de28f8', NULL, '2026-03-27 20:11:23');
INSERT INTO `document_chunk` VALUES (529, 7, 1, 78, ' （下列情况不能结婚：1，同性；2，未达到结婚年龄，男<24，女<22；3，某一方已婚）\n\n */\n \n \n \n4.现有员工Employee类，有姓名，地址，基本工资属性，\n\n董事类和经理类除以上属性，董事类有交通补助，经理类有所管部门，\n\n三个类中都有显示其基本信息的方法show，但其实现方式不同，\n\n请写出各类构造方法，及属性的get，set方法。\n\n并要用到this和super关键字。\n\naf://n475\n\n\n第4章 关联关系及依赖关系 \n\n4.1 关联关系 \n\n 对象和对象之间的连接。在Java中，关联关系的代码表现形式为一个类做为另一个类的属性类型存在。即“有”的关\n\n系：”has-a”。\n\n案例\n\n人Person与宠物Pet就是一种组合的关系，是一种类与类之间的设计关系。\n\nPet宠物类:\n\naf://n475\naf://n476\n\n\n /**  \n* @ClassName: Pet  \n* @Description: Pet宠物类\n\n*    \n* 宠物姓名,宠物颜色,宠物种类三个成员变量\n\n*/\n \npublic class Pet {\n\n/**      ', 495, 495, 1, 'bc357cf4-7534-4d6a-9ad7-2c7cb80c86f8', NULL, '2026-03-27 20:11:23');
INSERT INTO `document_chunk` VALUES (530, 7, 1, 79, 'me: Pet  \n* @Description: Pet宠物类\n\n*    \n* 宠物姓名,宠物颜色,宠物种类三个成员变量\n\n*/\n \npublic class Pet {\n\n/**      \n\n* @Fields name : 宠物姓名      \n\n*/      \n\nprivate String name;    \n\n/**      \n\n* @Fields color : 宠物颜色      \n\n*/      \n\nprivate String color;    \n\n/**      \n\n* @Fields kind : 宠物种类      \n\n*/      \n\nprivate String kind;    \n\n \n/**      \n\n* @Title: Pet          \n\n*/    \n\npublic Pet() {    \n\n}    \n\n \n/**      \n\n* @Title: Pet      \n\n* @param name    \n\n* @param color    \n\n* @param kind        \n\n*/    ', 494, 494, 1, 'f9dcb7d9-6b74-49ed-b995-51b820fadf59', NULL, '2026-03-27 20:11:23');
