INSERT INTO `document_chunk` VALUES (533, 7, 1, 82, 'eturn the kind    \n\n */    \n\npublic String getKind() {    \n\nreturn kind;        \n\n}    \n\n \n/**    \n\n * @param kind the kind to set    \n\n */    \n\npublic void setKind(String kind) {    \n\nthis.kind = kind;        \n\n}    \n\n}\n\n\n\n /**  \n* @ClassName: Person  \n* @Description: Person类\n*    \n* 姓名,年龄,宠物三个成员变量\n\n* 有showInfo(显示信息)的方法\n\n* \n* 当Pet作为Person的成员变量时,两个数据类型的关系为关联\n\n*/\n \npublic class Person {\n \n\n/**      \n\n* @Fields name : 姓名      \n\n*/      \n\nprivate String name;    \n\n/**      ', 475, 475, 1, '9a9f1d2c-a831-482b-b6fc-749f90699e7d', NULL, '2026-03-27 20:11:23');
INSERT INTO `document_chunk` VALUES (534, 7, 1, 83, 'ss Person {\n \n\n/**      \n\n* @Fields name : 姓名      \n\n*/      \n\nprivate String name;    \n\n/**      \n\n* @Fields age : 年龄      \n\n*/      \n\nprivate int age;    \n\n    \n\n/**      \n\n* @Fields pet : 宠物      \n\n*/      \n\nprivate Pet pet;    \n\n \n/**      \n\n* @Title: Person          \n\n*/    \n\npublic Person() {    \n\n}    \n\n \n/**      \n\n* @Title: Person      \n\n* @param name    \n\n* @param age        \n\n* @param pet    \n\n*/    \n\npublic Person(String name, int age, Pet pet) {    \n\nthis.name = name;        ', 493, 493, 1, '07f64cb9-c3fc-48c9-8c41-33121f1584a8', NULL, '2026-03-27 20:11:24');
INSERT INTO `document_chunk` VALUES (535, 7, 1, 84, 'ram pet    \n\n*/    \n\npublic Person(String name, int age, Pet pet) {    \n\nthis.name = name;        \n\nthis.age = age;        \n\nthis.pet = pet;        \n\n}    \n\n \n/**      \n\n* @Title: showInfo      \n\n* @Description: 显示个人信息          \n\n*/    \n\npublic void showInfo() {    \n\nSystem.out.println(\"我的名字是:\" + this.name + \"，我的年龄是:\" + this.age);        \n\nSystem.out.println(\"我的宠物是\"+pet.getColor()+\"色的\"+pet.getKind()+\",它\n叫\"+pet.getName());\n        \n\n}    \n\n\n\nCompositionDemo 测试类：\n\n \n\n4.2 依赖关系', 478, 478, 1, '233a1b66-c668-45a6-aa7d-380ab3130a49', NULL, '2026-03-27 20:11:24');
INSERT INTO `document_chunk` VALUES (536, 7, 1, 85, '()+\"色的\"+pet.getKind()+\",它\n叫\"+pet.getName());\n        \n\n}    \n\n\n\nCompositionDemo 测试类：\n\n \n\n4.2 依赖关系 \n\n 依赖关系(use-a)：指一个类A使用到了另一个类B。依赖关系的特性：这种关系是具有偶然性的、临时性的、非常\n\n弱的，但是类B的变化会影响到类A。\n\n案例：\n\n \n}\n\n/**  \n * @ClassName: CompositionDemo  \n * @Description: 关联关系的测试类\n\n *    \n * 当一个自定义类型A的成员变量的数据类型是自定义类型B时，A类与B类叫做组合关系。\n\n */\npublic class CompositionDemo {\n\npublic static void main(String[] args) {    \n\n//准备新创建的Person对象的属性值        \n\nString name = \"Jack\";        \n\nint age = 18;        ', 468, 468, 1, '48e925dd-68bc-4c5f-bc11-3044dc33252a', NULL, '2026-03-27 20:11:24');
INSERT INTO `document_chunk` VALUES (537, 7, 1, 86, '[] args) {    \n\n//准备新创建的Person对象的属性值        \n\nString name = \"Jack\";        \n\nint age = 18;        \n\nPet pet = new Pet(\"大黄\",\"黄\",\"大狼狗\");        \n\n        \n\n//创建Person对象        \n\nPerson p = new Person(name, age, pet);        \n\n        \n\n//调用Person对象的方法        \n\n        p.showInfo();\n}    \n\n}\n\naf://n498\n\n\n人上班需要交通工具的 1.分析出人与交通工具的关系 2.测试类（调用执行）\n\nPerson类：\n\n\n\n /*\n * 依赖关系：use‐a 用\n * 一个类作为另外一个类的方法的形式参数类型使用\n\n */\npublic class Person {\n \n\nprivate String name;    \n\nprivate String sex;    \n\n    ', 485, 485, 1, '39b267af-6be0-4204-91f9-e86fd12b4337', NULL, '2026-03-27 20:11:24');
INSERT INTO `document_chunk` VALUES (538, 7, 1, 87, '的方法的形式参数类型使用\n\n */\npublic class Person {\n \n\nprivate String name;    \n\nprivate String sex;    \n\n    \n\npublic Person() {    \n\nsuper();        \n\n}    \n\npublic Person(String name, String sex) {    \n\nsuper();        \n\nthis.name = name;        \n\nthis.sex = sex;        \n\n}    \n\n    \n\npublic String getName() {    \n\nreturn name;        \n\n}    \n\npublic void setName(String name) {    \n\nthis.name = name;        \n\n}    \n\npublic String getSex() {    \n\nreturn sex;        \n\n}    ', 467, 467, 1, '5ef8cbd3-44aa-447a-b891-3f4aacbb496b', NULL, '2026-03-27 20:11:24');
INSERT INTO `document_chunk` VALUES (539, 7, 1, 88, ' {    \n\nthis.name = name;        \n\n}    \n\npublic String getSex() {    \n\nreturn sex;        \n\n}    \n\npublic void setSex(String sex) {    \n\nthis.sex = sex;        \n\n}    \n\n    \n\n//依赖关系    \n\npublic void goWork(Bus bus) {    \n\nSystem.out.println(\"一位\"+sex+\"性，名字叫：\"+name+\"，每天搭乘\"+bus.getName()+\"上班！\");        \n\n}    \n\n    \n\npublic void showPerson() {    \n\nSystem.out.println(\"姓名：\"+name+\",性别：\"+sex);        \n\n}    \n\n}\n\n\n\nBus类：\n\n \n\nTest测试类\n\n \n\n4.3 课堂练习1 \n\npublic class Bus {\n \n\nprivate String name;    ', 493, 493, 1, 'ef40d642-3cee-43ac-a0b6-a64e62c4d180', NULL, '2026-03-27 20:11:24');
INSERT INTO `document_chunk` VALUES (540, 7, 1, 89, '    \n\n}    \n\n}\n\n\n\nBus类：\n\n \n\nTest测试类\n\n \n\n4.3 课堂练习1 \n\npublic class Bus {\n \n\nprivate String name;    \n\n \npublic Bus() {    \n\nsuper();        \n\n}    \n\n \npublic Bus(String name) {    \n\nsuper();        \n\nthis.name = name;        \n\n}    \n\n \npublic String getName() {    \n\nreturn name;        \n\n}    \n\n \npublic void setName(String name) {    \n\nthis.name = name;        \n\n}    \n\n    \n\n}\n\npublic class Test {\n \n\npublic static void main(String[] args) {    \n\n        \n\nPerson p = new Person(\"张三\",\"男\");        ', 498, 498, 1, '00b8b864-8911-49ef-8069-ee322ca1dc04', NULL, '2026-03-27 20:11:25');
INSERT INTO `document_chunk` VALUES (541, 7, 1, 90, 'public static void main(String[] args) {    \n\n        \n\nPerson p = new Person(\"张三\",\"男\");        \n\np.showPerson();        \n\n \nBus bus = new Bus(\"公交车\");        \n\np.goWork(bus);        \n\n}    \n\n \n}\n\naf://n522\n\n\n\n\n \n\n4.4 课堂练习2 \n\n游戏需求：\n\n1、定义一个英雄类Hero，可以通过这个类创建英雄角色\n\n属性：\n\n    游戏角色拥有昵称name，等级level，血量blood，攻击力power，防御力defence，种族kind，\n装备Equip（只能装3个装备，初始没有装备）。\n\n方法：\n\n    游戏角色拥有基本攻击方法（拥有一定几率打出暴击）attack(Monster m)，死亡判定方法isDead()，添加装备的\n\n方法addEquip(Equip e)，获取角色信息的方法show()。\n \n2、定义一个怪兽类Monster，可以通过这个类创建怪兽角色', 495, 495, 1, '2868b6be-eae4-48c9-9c29-85b3ca70b575', NULL, '2026-03-27 20:11:25');
INSERT INTO `document_chunk` VALUES (542, 7, 1, 91, ' \n2、定义一个怪兽类Monster，可以通过这个类创建怪兽角色\n\n属性：\n\n    怪兽拥有名称name，等级level，血量blood，攻击力power，防御力defence，种族kind。\n方法：\n\n    怪兽拥有基本攻击方法attack(Hero h)，死亡判定方法isDead()，获取怪兽信息的方法show()。\n \n3、定义装备类Equip，可以通过这个类创建各种装备\n\n属性：\n\n    装备拥有名称name，级别level，颜色color，类别kind，攻击力power，防御力defence。\n方法：\n\n    装备拥有获取装备信息的方法show()。\n \n4、测试类\n\n创建一个游戏角色：英雄类Hero、装备Equip、怪兽Monster，英雄类Hero装上装备，双方使用回合制的形式进行攻击\n\n（一人打一下，角色英雄类Hero先攻击，失血量=攻击‐防御 ，攻击<防御，不产生攻击），直到一方死亡，游戏结束。\n\n \n其中：\n\n产生一个随机暴击值 [0,100]\n随机暴击值>50 时  （暴击率 50%）\n失血量=(攻击+暴击)‐防御 \n\naf://n528', 491, 491, 1, '4fbfe0d3-702d-4475-8274-b65706685ebe', NULL, '2026-03-27 20:11:25');
INSERT INTO `document_chunk` VALUES (543, 7, 1, 92, ' \n其中：\n\n产生一个随机暴击值 [0,100]\n随机暴击值>50 时  （暴击率 50%）\n失血量=(攻击+暴击)‐防御 \n\naf://n528\n\n\n 订单和货物，用户：\n\n1.一个订单会有多个货物（一对多的关系）,订单中一个方法（查看商品详情信息）\n\n2.货物是订单的属性\n\n3.订单与用户之间的关系，用户类中有下单的方法（用户姓名和订单号）\n\n4.测试类（调用执行下单方法和查看商品详情信息的方法）\n\n备注：用户User、订单Order、货物Goods    \n\n\n Java面向对象 第2章 - 类与类之间的关系\n 第1章 继承的概述及特点\n 1.1 继承的概念\n 1.1.1 继承的概述 is-a\n 1.1.2 案例\n\n 1.2 继承的代码格式\n 1.2.1 继承格式说明\n 1.2.2 案例\n\n 1.3 子类通过get&set方法访问父类成员变量\n 1.4 继承的特点\n 1.4.1 特点概述\n 1.4.2 案例\n\n\n 第2章 方法重写及继承内存图解\n 2.1 方法重写的概念与格式\n 2.1.1 方法重写的概述\n 2.1.2 方法重写的案例', 477, 477, 1, 'c80ee2b7-00d6-4683-969b-77e7b3a7eacc', NULL, '2026-03-27 20:11:25');
INSERT INTO `document_chunk` VALUES (544, 7, 1, 93, '1.4 继承的特点\n 1.4.1 特点概述\n 1.4.2 案例\n\n\n 第2章 方法重写及继承内存图解\n 2.1 方法重写的概念与格式\n 2.1.1 方法重写的概述\n 2.1.2 方法重写的案例\n\n 2.2 Override注解解释\n 2.2.1 Override\n 2.2.2 案例\n\n 2.3 方法重写注意事项\n 2.3.1 注意事项概述\n 2.3.2 案例\n\n 2.4 继承后子父类构造方法调用先后顺序\n 2.4.1 继承中子父类构造调用顺序概述\n 2.4.2 案例\n\n 2.5 继承后，子父类内存图\n 2.5.1 案例\n 2.5.2 对象内存图\n\n\n 第3章 this与super\n 3.1 this与super访问普通成员\n 3.1.1 this和super访问注意事项\n 3.1.2 案例\n\n 3.2 super访问父类构造方法\n 3.2.1 super调用父类构造方法的格式\n 3.2.2 案例\n\n 3.3 this访问子类构造方法\n 3.3.1 案例\n\n 3.4 继承的课堂练习\n 3.4.1 案例\n 3.4.2 课堂练习', 468, 468, 1, '7ebdfbb9-a55b-49c3-8e1d-aab594d87177', NULL, '2026-03-27 20:11:25');
INSERT INTO `document_chunk` VALUES (545, 7, 1, 94, '3.2.1 super调用父类构造方法的格式\n 3.2.2 案例\n\n 3.3 this访问子类构造方法\n 3.3.1 案例\n\n 3.4 继承的课堂练习\n 3.4.1 案例\n 3.4.2 课堂练习\n\n\n 第4章 关联关系及依赖关系\n 4.1 关联关系\n 4.2 依赖关系\n 4.3 课堂练习1\n 4.4 课堂练习2', 156, 156, 1, 'd53aef79-fa8f-4e48-8ff5-a29b4ad32ef3', NULL, '2026-03-27 20:11:25');
INSERT INTO `document_chunk` VALUES (546, 8, 5, 0, '第十七届蓝桥杯全国大学生软件和信息技术大赛\n\n软件赛（Java 软件开发科目）\n\n竞赛规则及说明\n\n一、参赛对象\n\n具有正式全日制学籍并且符合相关科目报名要求的研究生、本科及高职高专学生（以报\n\n名时状态为准)。\n\n每位选手配备一名指导教师，同一名指导教师可指导多位选手。省赛和全国总决赛比赛\n\n后指导教师原则上不能更改。\n\n二、组别设置\n\n该科目分为研究生组、大学 A组、大学 B 组和大学 C组四个组别，每个组别单独评奖。\n\n每位选手只能申请参加其中一个组别的竞赛。\n\n研究生只能报研究生组；重点本科院校（985、211）本科生只能报研究生组或大学 A\n\n组；其它本科院校本科生可报大学 B 组及以上组别；高职高专院校可自行选择报任意组别。\n\n三、竞赛赛制\n\n本届大赛采用校赛、省赛、全国总决赛三级竞赛体系。\n\n校赛：由参赛院校自行组织并进行评审。\n\n省赛：由大赛组委会统一组织。比赛时长为 4 小时。\n\n全国总决赛：由大赛组委会统一组织。比赛时长为 4小时。\n\n详细赛程安排以组委会公布信息为准。\n\n四、竞赛形式', 459, 459, 1, 'c42cd71c-8401-4548-95fc-8d031bdf75ea', NULL, '2026-03-27 23:19:33');
INSERT INTO `document_chunk` VALUES (547, 8, 5, 1, '省赛：由大赛组委会统一组织。比赛时长为 4 小时。\n\n全国总决赛：由大赛组委会统一组织。比赛时长为 4小时。\n\n详细赛程安排以组委会公布信息为准。\n\n四、竞赛形式\n\n1.省赛、全国总决赛均采用封闭、限时方式举办。选手以个人为单位，独立进行作答。\n\n2.选手原则上需在线下赛点集中参赛。\n\n3.选手机器通过局域网连接到各个赛场的比赛服务器。答题过程中不允许访问互联网，\n\n\n\n也不允许使用本机以外的资源（如 USB 连接）。\n\n4.比赛系统以“服务器-浏览器”方式发放赛题、回收选手答案。\n\n五、参赛选手机器环境\n\n1.选手机器配置：\n\nX86 兼容机器，内存不小于 4G，硬盘不小于 60G\n\n操作系统：Windows7、Windows8、Windows10 或 Windows11\n\n2.编程环境：\n\nJDK 1.8\n\nEclipse-java-2020-06\n\nAPI 帮助文档\n\n六、赛题形式\n\n竞赛题目完全为客观题型，具体题型及题目数量以正式比赛时赛题为准。根据选手所提\n\n交答案的测评结果为评分依据。\n\n1.结果填空题\n\n题目描述一个具有确定解的问题。要求选手对问题的解填空。', 493, 493, 1, '0c000d40-5f79-4ba0-a329-5c41beb75564', NULL, '2026-03-27 23:19:34');
INSERT INTO `document_chunk` VALUES (548, 8, 5, 2, '根据选手所提\n\n交答案的测评结果为评分依据。\n\n1.结果填空题\n\n题目描述一个具有确定解的问题。要求选手对问题的解填空。\n\n不要求解题过程，不限制解题手段（可以使用任何开发语言或工具，甚至是手算），只\n\n要求填写最终的结果。\n\n最终的解是一个整数或者是一个字符串，最终的解可以使用 ASCII 字符表达。\n\n2.编程大题\n\n(1) 题目构成：包含明确的问题描述、输入输出格式，以及需要用于解释问题的样例数\n\n据。\n\n(2) 评判标准：问题具备明确、客观的结果判断标准，可通过程序实现自动化评判；选\n\n手程序需遵循“从标准输入读入数据、向标准输出输出结果”的交互规则。\n\n(3) 程序要求：问题描述会明确给定条件、限制及核心任务，选手程序需覆盖符合条件\n\n与限制的所有可能场景，具备普遍性，不可仅适配样例数据。\n\n(4) 性能考量：用于评分的评测数据可能包含大数据量的压力测试，选手需优先选择兼\n\n具可行性与效率的算法。\n\n七、赛题考查范围\n\n赛题考查选手解决实际问题的能力，对于结果填空题，选手可以使用手算、软件、编程\n\n\n\n等方法解决，对于编程大题，选手只能使用编程解决。', 487, 487, 1, 'c848b604-dae5-4263-aa9e-818a83a13044', NULL, '2026-03-27 23:19:34');
INSERT INTO `document_chunk` VALUES (549, 8, 5, 3, '七、赛题考查范围\n\n赛题考查选手解决实际问题的能力，对于结果填空题，选手可以使用手算、软件、编程\n\n\n\n等方法解决，对于编程大题，选手只能使用编程解决。\n\n竞赛侧重考查选手对于算法和数据结构的灵活运用能力，很多赛题需要使用计算机算法\n\n才能有效地解决。\n\n考查范围包括：Java 软件开发基础、计算机算法及数据结构。\n\nJava 软件开发基础：包含使用 Java 编写程序的能力。该部分不考查选手对某一语法的\n\n理解程度，选手可以使用自己喜欢的语句编写程序。选手可在程序中使用 JDK 中自带的类，\n\n但不能使用其它的第三方类。\n\n考查知识范围详见软件赛竞赛大纲。链接：dasai.lanqiao.cn/notices/846。\n\n八、答案提交\n\n选手只有在比赛时间内提交的答案内容是可以用来评测的，比赛之后的任何提交均无效。\n\n选手应使用比赛指定的网页来提交代码，任何其他方式的提交（如邮件、U盘）均不作为评\n\n测依据。\n\n选手可在比赛中的任何时间查看自己之前提交的代码，也可以重新提交任何题目的答案，\n\n对于每个赛题，仅有最后的一次提交被保存并作为评测的依据。在比赛中，评测结果不会显', 494, 494, 1, '68db5a86-7d44-4339-abcd-1143edd20e44', NULL, '2026-03-27 23:19:34');
INSERT INTO `document_chunk` VALUES (550, 8, 5, 4, '选手可在比赛中的任何时间查看自己之前提交的代码，也可以重新提交任何题目的答案，\n\n对于每个赛题，仅有最后的一次提交被保存并作为评测的依据。在比赛中，评测结果不会显\n\n示给选手，选手应当在没有反馈的情况下自行设计数据调试自己的程序。\n\n对于每个赛题，选手应将赛题的答案内容拷贝粘贴到网页上进行提交。\n\n程序中应只包含计算模块，不要包含任何其他的模块，比如图形、系统接口调用、系统\n\n中断等。对于系统接口的调用都应通过标准库来进行。\n\n程序中引用的库应该在程序中以源代码的方式写出，在提交时也应当和程序的其他部分\n\n一起提交。\n\n九、评分\n\n全部使用机器自动评分。\n\n对于结果填空题，题目保证只有唯一解，选手的结果只有和解完全相同才得分，出现格\n\n式错误或有多余内容时不得分。\n\n对于编程大题，评测系统将使用多个评测数据来测试程序。每个评测数据有对应的分数。\n\n选手所提交的程序将分别用每个评测数据作为输入来运行。对于某个评测数据，如果选手程\n\n序的输出与正确答案相匹配，则选手获得该评测数据的分数。\n\n评测使用的评测数据一般与赛题中给定的样例输入输出不一样，因此建议选手在提交程', 488, 488, 1, 'f1f5b011-d407-40cd-803e-53fa6c32d005', NULL, '2026-03-27 23:19:34');
INSERT INTO `document_chunk` VALUES (551, 8, 5, 5, '对于某个评测数据，如果选手程\n\n序的输出与正确答案相匹配，则选手获得该评测数据的分数。\n\n评测使用的评测数据一般与赛题中给定的样例输入输出不一样，因此建议选手在提交程\n\n序前使用不同的数据测试自己的程序。\n\n\n\n提交的程序应严格按照输出格式的要求来输出，包括输出空格和换行的要求。如果程序\n\n没有遵循输出格式的要求将被判定为答案错误。请注意，程序在输出的时候多输出了内容也\n\n属于没有遵循输出格式要求的一种，所以在输出的时候请不要输出任何多余的内容，比如调\n\n试输出。\n\n选手请务必不要使用 package 语句，并且确保自己的主类名称为 Main，否则会导致评\n\n测系统运行时找不到主类而得 0 分。\n\n选手如果程序中引用了类库，在提交时必须将 import 语句与程序的其他部分同时提交。\n\n只允许使用 Java 自带的类库。\n\n十、历届真题及样题\n\n1.历届真题\n\n参赛选手可在蓝桥杯官方网站-关于大赛-历届真题里查看以往蓝桥杯大赛的历届真题。\n\n链接：www.lanqiao.cn/courses/2786。\n\n2.样题\n\n样题详见文档附录。\n\n十一、奖项设置及评选办法\n\n1.省赛', 495, 495, 1, '5db63260-3103-4046-bba3-207e87edc663', NULL, '2026-03-27 23:19:35');
INSERT INTO `document_chunk` VALUES (552, 8, 5, 6, '链接：www.lanqiao.cn/courses/2786。\n\n2.样题\n\n样题详见文档附录。\n\n十一、奖项设置及评选办法\n\n1.省赛\n\n省赛每个组别设立一、二、三等奖，原则上各奖项的获奖比例为 10%、15%、25%，总获\n\n奖比例不超过 50%。获奖比例仅作为参考，组委会将根据赛题难易程度及整体答题情况，制\n\n定各奖项获奖最低分数线，未达到获奖最低分数线者不得奖。省赛一等奖选手获得全国总决\n\n赛参赛资格。\n\n2.全国总决赛\n\n全国总决赛每个组别设立一、二、三等奖，原则上各奖项的获奖比例为 10%、25%、40%，\n\n总获奖比例不超过 75%。获奖比例仅作为参考，组委会将根据赛题难易程度及整体答题情况，\n\n制定各奖项获奖最低分数线，未达到获奖最低分数线者不得奖。\n\n十二、奖项查询\n\n省赛及全国总决赛评审完成后，大赛组委会将在报名系统开放奖项查询。参赛选手若对\n\n奖项有异议，可在 3个工作日内按照大赛组委会相关要求提出复核申请。\n\n十三、监督反馈\n\n\n\n详见《蓝桥杯全国大学生软件和信息技术大赛章程》。\n\n十四、其它注意事项', 469, 469, 1, 'bc6e107e-d74f-46f4-b1e7-d8b29e2fa669', NULL, '2026-03-27 23:19:35');
INSERT INTO `document_chunk` VALUES (553, 8, 5, 7, '参赛选手若对\n\n奖项有异议，可在 3个工作日内按照大赛组委会相关要求提出复核申请。\n\n十三、监督反馈\n\n\n\n详见《蓝桥杯全国大学生软件和信息技术大赛章程》。\n\n十四、其它注意事项\n\n1.选手必须符合参赛资格，不得弄虚作假。资格审查中一旦发现问题，则取消其报名资\n\n格；竞赛过程中发现问题，则取消竞赛资格；竞赛后发现问题，则取消竞赛奖项，收回获奖\n\n证书及奖品等，并在蓝桥杯官方网站上公示。\n\n2.参赛选手应严格遵守蓝桥杯大赛比赛管理办法（办法链接：dasai.lanqiao.cn/noti\n\nces/844），服从大赛组委会的指挥和安排，爱护竞赛场地的设备。未尽事宜请参照组委会在\n\n蓝桥杯官方网站公布的通知、章程、比赛管理办法及相关要求并遵照执行。\n\n3.赛项采用智能化评审系统自动评分与人工复核双轨校验机制，确保评审效率与精度。\n\n选手需要特别注意提交答案的形式。必须仔细阅读题目的输入、输出要求以及示例，不要随\n\n意添加不需要的内容。\n\n蓝桥杯大赛组委会\n\n2025 年 10 月 20 日\n\n\n\n附录：\n\n样题 1：矩形切割（结果填空题）\n\n【问题描述】', 482, 482, 1, 'f90cbe39-f758-42fb-8aad-d8012bf2052a', NULL, '2026-03-27 23:19:35');
INSERT INTO `document_chunk` VALUES (554, 8, 5, 8, '必须仔细阅读题目的输入、输出要求以及示例，不要随\n\n意添加不需要的内容。\n\n蓝桥杯大赛组委会\n\n2025 年 10 月 20 日\n\n\n\n附录：\n\n样题 1：矩形切割（结果填空题）\n\n【问题描述】\n\n小明有一些矩形的材料，他要从这些矩形材料中切割出一些正方形。\n\n当他面对一块矩形材料时，他总是从中间切割一刀，切出一块最大的正方形，剩下一块矩形，\n\n然后再切割剩下的矩形材料，直到全部切为正方形为止。\n\n例如，对于一块两边分别为 5和 3的材料（记为 5×3），小明会依次切出 3×3、2×2、\n\n1×1、1×1 共 4 个正方形。\n\n现在小明有一块矩形的材料，两边长分别是 2019 和 324。请问小明最终会切出多少个\n\n正方形？\n\n【答案提交】\n\n这是一道结果填空的题，你只需要算出结果后提交即可。本题的结果为一个整数，在提\n\n交答案时只填写这个整数，填写多余的内容将无法得分。\n\n说明：以上是问题描述的部分，选手做题时可以直接手算答案，即按照题目意思一步一\n\n步切割，最后得到切出的矩形个数，手算可能花费一些时间。如果选手在手算时使用除法等', 473, 473, 1, 'dc0cfae2-54f9-44bb-b015-3fe86996dfa5', NULL, '2026-03-27 23:19:35');
INSERT INTO `document_chunk` VALUES (555, 8, 5, 9, '说明：以上是问题描述的部分，选手做题时可以直接手算答案，即按照题目意思一步一\n\n步切割，最后得到切出的矩形个数，手算可能花费一些时间。如果选手在手算时使用除法等\n\n方式加快速度，时间可能少一些。如果选手编写程序来计算，可以减少手算中出现的失误。\n\n本题答案为：21\n\n样题 2：特别数的和（编程大题）\n\n【问题描述】\n\n小明对数位中含有 2、0、1、9 的数字很感兴趣（不包括前导 0），在 1 到 40 中这样的\n\n数包括 1、2、9、10 至 32、39 和 40，共 28 个，他们的和是 574。\n\n请问，在 1到 n中，所有这样的数的和是多少？\n\n【输入格式】\n\n输入一行包含一个整数 n。\n\n【输出格式】\n\n输出一行，包含一个整数，表示满足条件的数的和。\n\n【样例输入】\n\n40\n\n\n\n【样例输出】\n\n574\n\n【评测用例规模与约定】\n\n对于 20%的评测用例，1≤n≤10。\n\n对于 50%的评测用例，1≤n≤100。\n\n对于 80%的评测用例，1≤n≤1000。\n\n对于所有评测用例，1≤n≤10000。', 460, 460, 1, 'fbb169a3-a2f3-4715-a648-c6d16ad18bee', NULL, '2026-03-27 23:19:36');
INSERT INTO `document_chunk` VALUES (556, 8, 5, 10, '对于 50%的评测用例，1≤n≤100。\n\n对于 80%的评测用例，1≤n≤1000。\n\n对于所有评测用例，1≤n≤10000。\n\n说明：本题是一道编程题，选手需要编写一个程序来解决问题。以下给出一个参考程序，\n\n选手所编写的其他程序只要能给出正确的结果即可得分。\n\nimport java.util.*;\n\npublic class Main\n\n{\n\npublic static void main(String[] args)\n\n{\n\nScanner sc = new Scanner(System.in);\n\nint n = sc.nextInt(), ans = 0;\n\nfor (int i = 1; i &lt;= n; ++i)\n\n{\n\nint t = i;\n\nboolean ok = false;\n\nwhile (t &gt; 0)\n\n{\n\nint g = t % 10;\n\nif (g==2 || g==0 || g==1 || g==9)\n\nok = true;\n\nt = t / 10;\n\n}\n\nif (ok)\n\nans += i;\n\n}', 481, 481, 1, '08092265-3466-4d14-836e-fd17e2dd9990', NULL, '2026-03-27 23:19:36');
INSERT INTO `document_chunk` VALUES (557, 8, 5, 11, '= t % 10;\n\nif (g==2 || g==0 || g==1 || g==9)\n\nok = true;\n\nt = t / 10;\n\n}\n\nif (ok)\n\nans += i;\n\n}\n\n\n\nSystem.out.println(ans);\n\n}\n\n}', 129, 129, 1, '97d95de8-a1d3-49bb-8557-2e415687cd1c', NULL, '2026-03-27 23:19:36');
INSERT INTO `document_chunk` VALUES (558, 9, 5, 0, '第十七届蓝桥杯大赛软件赛（编程类）\n\n竞赛大纲\n\n组别 竞赛大纲（1-10 难度系数依次递增）\n\n大学 C 组 1.枚举[1-3]\n\n2.排序\n\n（1）冒泡排序[2]\n\n（2）选择排序[3]\n\n（3）插入排序[3]\n\n3.搜索(bfs, dfs)[1-5]\n\n4.贪心[1-5]\n\n5.模拟[1-3]\n\n6.二分[2-5]\n\n7.DP(普通一维问题)[3-5]\n\n8.高精度[1-5]\n\n9.数据结构\n\n（1）栈[2-4]；\n\n（2）队列[2-5]\n\n（3）链表 [2-5]\n\n10.数学\n\n\n\n（1）初等数论[3-5]\n\n大学 B 组 11.排序\n\n（1）归并排序[4-5]\n\n（2）快速排序[4-5]\n\n（3）桶排序[4]\n\n（4）堆排序[4]\n\n（5）基数排序[4~5]\n\n12.搜索\n\n（1）剪枝[4-6]\n\n（2）双向 BFS[5-6]\n\n（3）记忆化搜索[5]\n\n（4）迭代加深搜索[5-6]\n\n（5）启发式搜索[7]\n\n13.DP\n\n（1）背包 DP[4-6]\n\n（2）树形 DP[4-6]\n\n（3）状压 DP[5-6]\n\n（4）数位 DP[5-6]\n\n（5）DP 的常见优化[7]', 498, 498, 1, 'a11db3a2-cb97-4c98-be45-1d6ad450cfa1', NULL, '2026-03-27 23:19:40');
INSERT INTO `document_chunk` VALUES (559, 9, 5, 1, '6]\n\n（5）启发式搜索[7]\n\n13.DP\n\n（1）背包 DP[4-6]\n\n（2）树形 DP[4-6]\n\n（3）状压 DP[5-6]\n\n（4）数位 DP[5-6]\n\n（5）DP 的常见优化[7]\n\n14.字符串\n\n（1）哈希[4-5]\n\n（2）kmp[4-6]\n\n\n\n（3）manacher[4-6]\n\n15.图论\n\n（1）欧拉回路[5-7]\n\n（2）最小生成树[5-7]\n\n（3）单源最短路及差分约束系统[5-7]\n\n（4）拓扑序列[5-7]\n\n（5）二分图匹配[7]\n\n（6）图的连通性问题（割点、桥、强连通\n\n分量）[7]\n\n（7）DFS 序[5-7]\n\n（8）最近共同祖先[5-7]\n\n16.数学\n\n（1）排列组合[5-6]\n\n（2）二项式定理[6]\n\n（3）容斥原理[6-7]\n\n（4）模意义下的逆元[5]\n\n（5）矩阵运算[6-7]\n\n（6）高斯消元[7]\n\n17.数据结构\n\n（1）ST 表[5-6]\n\n（2）堆[5-6]\n\n（3）树状数组[5-6]\n\n\n\n（4）线段树[6-7]\n\n（5）Trie 树[5-7]\n\n（6）并查集[5-6]', 477, 477, 1, '9e8c8f34-a423-4f3e-bf27-ba616f684ba7', NULL, '2026-03-27 23:19:40');
INSERT INTO `document_chunk` VALUES (560, 9, 5, 2, '斯消元[7]\n\n17.数据结构\n\n（1）ST 表[5-6]\n\n（2）堆[5-6]\n\n（3）树状数组[5-6]\n\n\n\n（4）线段树[6-7]\n\n（5）Trie 树[5-7]\n\n（6）并查集[5-6]\n\n（7）平衡树(利用系统自带的标准库实现简\n\n单平衡树)[5-7]\n\n18.计算几何\n\n（1）基础计算和基本位置关系判定[6-7]\n\n（2）概率论[7+]\n\n（3）博弈论[7+]\n\n研究生及大学 A 组 19.字符串\n\n（1）AC 自动机[7-8]\n\n（2）拓展 kmp[7-8]\n\n（3）后缀数组[8-10]\n\n（4）后缀自动机[8-10]\n\n（5）回文自动机[8-10]\n\n20.图论\n\n（1）网络流[8-10]\n\n（2）一般图匹配[9-10]\n\n21.数学\n\n（1）生成函数[8-10]\n\n（2）莫比乌斯反演[8-10]\n\n（3）快速傅里叶变换[9-10]\n\n\n\n22.数据结构\n\n（1）树链剖分[7-8]\n\n（2）二维/动态开点线段树[7-8]\n\n（3）平衡树[8-9]\n\n（4）可持久化数据结构[8-9]\n\n（5）树套树[9-10]\n\n（6）动态树[9-10]', 484, 484, 1, 'a72f0e66-d5d7-4737-8664-d67a7175dae3', NULL, '2026-03-27 23:19:40');
INSERT INTO `document_chunk` VALUES (561, 9, 5, 3, '.数据结构\n\n（1）树链剖分[7-8]\n\n（2）二维/动态开点线段树[7-8]\n\n（3）平衡树[8-9]\n\n（4）可持久化数据结构[8-9]\n\n（5）树套树[9-10]\n\n（6）动态树[9-10]\n\n说明：此表中各组考点难度向上兼容。A 组需同时掌握 B 组和C 组知\n\n识点，B 组需同时掌握 C 组知识点。大纲列举内容仅供参考，实际比\n\n赛内容不限于大纲列举内容。', 184, 184, 1, 'c27a5da0-30b5-4409-aff2-47f905a3fd8a', NULL, '2026-03-27 23:19:41');
INSERT INTO `document_chunk` VALUES (562, 10, 1, 0, '智能知识库问答系统 — 前后端接口契约\n一、通用约定\n1.1 基础信息\n项目 说明\n后端地址（开发） http://localhost:8080\n数据格式 JSON（UTF-8）\n认证方式 暂用请求头传 userId（后续可升级为 Token）\n请求头 Content-Type: application/json，需要认证的接口传 userId: 用户ID\n1.2 统一响应格式\nJSON\n\n{\n \"code\": 200,\n \"message\": \"success\",\n \"data\": {}\n}\n字段 类型 说明\ncode Integer 状态码：200成功，400参数错误，401未认证，403无权限，404不存在，500服务器错误\nmessage String 提示信息\ndata Object 响应数据（成功时返回，失败时为null）\n1.3 分页请求与响应\n分页请求参数（Query）：\n\n参数 类型 必填 默认值 说明\npage Integer 否 1 页码\nsize Integer 否 20 每页条数\n分页响应数据格式：\n\nJSON', 475, 475, 1, '9077c2cf-dab8-403b-ad89-81eaeaa5c85b', NULL, '2026-03-27 23:33:22');
INSERT INTO `document_chunk` VALUES (563, 10, 1, 1, '分页请求与响应\n分页请求参数（Query）：\n\n参数 类型 必填 默认值 说明\npage Integer 否 1 页码\nsize Integer 否 20 每页条数\n分页响应数据格式：\n\nJSON\n\n{\n \"code\": 200,\n \"message\": \"success\",\n \"data\": {\n \"records\": [],\n \"total\": 100,\n \"page\": 1,\n \"size\": 20,\n \"pages\": 5\n }\n}\n二、用户模块\nAPI-001 用户注册\n项目 说明\n接口地址 POST /api/user/register\n认证 不需要\n请求体：\n\nJSON\n\n{\n \"username\": \"xdx2026\",\n \"password\": \"123456\",\n \"nickname\": \"杜萱\"\n}\n参数 类型 必填 说明\nusername String 是 用户名，3-50字符，唯一\npassword String 是 密码，6-20字符\nnickname String 否 昵称\n成功响应：\n\nJSON', 470, 470, 1, 'c90d26e7-60e6-4503-9ee3-eb6b02e929fc', NULL, '2026-03-27 23:33:22');
INSERT INTO `document_chunk` VALUES (564, 10, 1, 2, '必填 说明\nusername String 是 用户名，3-50字符，唯一\npassword String 是 密码，6-20字符\nnickname String 否 昵称\n成功响应：\n\nJSON\n\n{\n \"code\": 200,\n \"message\": \"注册成功\",\n \"data\": {\n \"id\": 1,\n \"username\": \"xdx2026\",\n \"nickname\": \"杜萱\"\n }\n}\n失败响应示例：\n\nJSON\n\n{\n \"code\": 400,\n \"message\": \"用户名已存在\",\n \"data\": null\n}\nAPI-002 用户登录\n项目 说明\n接口地址 POST /api/user/login\n认证 不需要\n请求体：\n\nJSON\n\n{\n \"username\": \"xdx2026\",\n \"password\": \"123456\"\n}\n参数 类型 必填 说明\nusername String 是 用户名\npassword String 是 密码\n成功响应：\n\nJSON', 453, 453, 1, '6d5cc70f-e1d4-4cf4-9f81-7dc522f11493', NULL, '2026-03-27 23:33:22');
INSERT INTO `document_chunk` VALUES (565, 10, 1, 3, 'x2026\",\n \"password\": \"123456\"\n}\n参数 类型 必填 说明\nusername String 是 用户名\npassword String 是 密码\n成功响应：\n\nJSON\n\n{\n \"code\": 200,\n \"message\": \"登录成功\",\n \"data\": {\n \"id\": 1,\n \"username\": \"xdx2026\",\n \"nickname\": \"杜萱\",\n \"avatar\": null,\n \"lastLoginTime\": \"2026-03-25T10:30:00\"\n }\n}\nAPI-003 获取当前用户信息\n项目 说明\n接口地址 GET /api/user/info\n认证 需要（请求头传 userId）\n成功响应：\n\nJSON', 339, 339, 1, '0fef73b3-4574-4a2e-ab6b-24988f7b01ea', NULL, '2026-03-27 23:33:23');
INSERT INTO `document_chunk` VALUES (566, 10, 1, 4, '03-25T10:30:00\"\n }\n}\nAPI-003 获取当前用户信息\n项目 说明\n接口地址 GET /api/user/info\n认证 需要（请求头传 userId）\n成功响应：\n\nJSON\n\n{\n \"code\": 200,\n \"message\": \"success\",\n \"data\": {\n \"id\": 1,\n \"username\": \"xdx2026\",\n \"nickname\": \"杜萱\",\n \"avatar\": null,\n \"status\": 0,\n \"lastLoginTime\": \"2026-03-25T10:30:00\",\n \"createTime\": \"2026-03-25T09:00:00\"\n }\n}\nAPI-004 修改用户信息\n项目 说明\n接口地址 PUT /api/user/update\n认证 需要\n请求体：\n\nJSON', 380, 380, 1, '20c55740-0395-4f76-be12-89dfa4c28f12', NULL, '2026-03-27 23:33:23');
INSERT INTO `document_chunk` VALUES (567, 10, 1, 5, 'eTime\": \"2026-03-25T09:00:00\"\n }\n}\nAPI-004 修改用户信息\n项目 说明\n接口地址 PUT /api/user/update\n认证 需要\n请求体：\n\nJSON\n\n{\n \"nickname\": \"新昵称\",\n \"avatar\": \"https://xxx.com/avatar.png\"\n}\n参数 类型 必填 说明\nnickname String 否 昵称\navatar String 否 头像URL\n成功响应：\n\nJSON\n\n{\n \"code\": 200,\n \"message\": \"修改成功\",\n \"data\": null\n}\nAPI-005 获取用户设置\n项目 说明\n接口地址 GET /api/user/settings\n认证 需要\n成功响应：\n\nJSON', 350, 350, 1, '0122b35f-92eb-44ad-b0fe-0069b8928f3b', NULL, '2026-03-27 23:33:23');
INSERT INTO `document_chunk` VALUES (568, 10, 1, 6, 'ssage\": \"修改成功\",\n \"data\": null\n}\nAPI-005 获取用户设置\n项目 说明\n接口地址 GET /api/user/settings\n认证 需要\n成功响应：\n\nJSON\n\n{\n \"code\": 200,\n \"message\": \"success\",\n \"data\": {\n \"theme\": \"system\",\n \"defaultModel\": \"qwen-plus-2025-07-28\"\n }\n}\nAPI-006 更新用户设置\n项目 说明\n接口地址 PUT /api/user/settings\n认证 需要\n请求体：\n\nJSON\n\n{\n \"theme\": \"dark\",\n \"defaultModel\": \"qwen-plus-2025-07-28\"\n}\n参数 类型 必填 说明\ntheme String 否 主题：light/dark/system\ndefaultModel String 否 默认模型名称\n成功响应：\n\nJSON', 432, 432, 1, '23c5e35a-2ec6-4510-88fe-a301882d332e', NULL, '2026-03-27 23:33:23');
