INSERT INTO `document_chunk` VALUES (572, 10, 1, 10, 'updateTime\": \"2026-03-26T11:00:00\"\n }\n ]\n}\nAPI-103 获取知识库详情\n项目 说明\n接口地址 GET /api/kb/{id}\n认证 需要\n路径参数：\n\n参数 类型 说明\nid Long 知识库ID\n成功响应：\n\nJSON\n\n{\n \"code\": 200,\n \"message\": \"success\",\n \"data\": {\n \"id\": 1,\n \"name\": \"操作系统复习\",\n \"description\": \"大三上学期操作系统课程相关资料\",\n \"docCount\": 3,\n \"chunkCount\": 45,\n \"createTime\": \"2026-03-25T10:00:00\",\n \"updateTime\": \"2026-03-25T14:30:00\"\n }\n}\nAPI-104 更新知识库\n项目 说明\n接口地址 PUT /api/kb/{id}\n认证 需要\n请求体：\n\nJSON', 423, 423, 1, 'ccabcac1-a9fa-492c-aba9-a62afbb6d2e1', NULL, '2026-03-27 23:33:24');
INSERT INTO `document_chunk` VALUES (573, 10, 1, 11, 'updateTime\": \"2026-03-25T14:30:00\"\n }\n}\nAPI-104 更新知识库\n项目 说明\n接口地址 PUT /api/kb/{id}\n认证 需要\n请求体：\n\nJSON\n\n{\n \"name\": \"操作系统期末复习\",\n \"description\": \"更新后的描述\"\n}\nAPI-105 删除知识库\n项目 说明\n接口地址 DELETE /api/kb/{id}\n认证 需要\n说明： 级联删除该知识库下的所有文档、分块（MySQL + ES）。\n\n成功响应：\n\nJSON\n\n{\n \"code\": 200,\n \"message\": \"删除成功\",\n \"data\": null\n}\n四、文档模块\nAPI-201 上传文档\n项目 说明\n接口地址 POST /api/doc/upload\n认证 需要\nContent-Type multipart/form-data\n请求参数：\n\n参数 类型 必填 说明\nfile File 是 上传的文件（pdf/docx/md/txt，最大50MB）\nkbId Long 是 所属知识库ID\n成功响应：\n\nJSON', 485, 485, 1, '0b631f7d-bd34-416d-8197-4a89e8690e26', NULL, '2026-03-27 23:33:24');
INSERT INTO `document_chunk` VALUES (574, 10, 1, 12, '-data\n请求参数：\n\n参数 类型 必填 说明\nfile File 是 上传的文件（pdf/docx/md/txt，最大50MB）\nkbId Long 是 所属知识库ID\n成功响应：\n\nJSON\n\n{\n \"code\": 200,\n \"message\": \"上传成功，正在处理中\",\n \"data\": {\n \"id\": 1,\n \"kbId\": 1,\n \"fileName\": \"操作系统教材.pdf\",\n \"fileType\": \"pdf\",\n \"fileSize\": 5242880,\n \"status\": 0,\n \"createTime\": \"2026-03-25T10:30:00\"\n }\n}\nstatus 说明：\n\n值 含义\n0 处理中（正在解析/分块/向量化）\n1 已完成\n2 处理失败\nAPI-202 获取文档列表\n项目 说明\n接口地址 GET /api/doc/list\n认证 需要\n请求参数（Query）：\n\n参数 类型 必填 说明\nkbId Long 是 知识库ID\n成功响应：\n\nJSON\n\n{\n \"code\": 200,\n \"message\": \"success\",', 494, 494, 1, 'f6d9aaab-7662-4e74-98cd-b9d3f92ed870', NULL, '2026-03-27 23:33:24');
INSERT INTO `document_chunk` VALUES (575, 10, 1, 13, '需要\n请求参数（Query）：\n\n参数 类型 必填 说明\nkbId Long 是 知识库ID\n成功响应：\n\nJSON\n\n{\n \"code\": 200,\n \"message\": \"success\",\n \"data\": [\n {\n \"id\": 1,\n \"kbId\": 1,\n \"fileName\": \"操作系统教材.pdf\",\n \"fileType\": \"pdf\",\n \"fileSize\": 5242880,\n \"charCount\": 85000,\n \"chunkCount\": 170,\n \"status\": 1,\n \"errorMsg\": null,\n \"createTime\": \"2026-03-25T10:30:00\"\n },\n {\n \"id\": 2,\n \"kbId\": 1,\n \"fileName\": \"课件笔记.docx\",\n \"fileType\": \"docx\",\n \"fileSize\": 1048576,\n \"charCount\": 12000,\n \"chunkCount\": 24,\n \"status\": 1,\n \"errorMsg\": null,', 485, 485, 1, '6f8a2e6a-7f07-4602-bff1-a953d2a3616a', NULL, '2026-03-27 23:33:24');
