INSERT INTO `message` VALUES (17, 6, 16, 'assistant', '你好！😊  \n欢迎回来～  \n之前我们聊了考研和考公的区别，如果你有新的问题，比如：\n\n- 想了解「如何同时备考考研+考公」？  \n- 不确定自己更适合哪条路，需要性格/能力/目标匹配分析？  \n- 想要某科（如行测、英语、政治）的高效备考方法？  \n- 或者关心应届生身份、选调生、非全研究生考公政策等细节？\n\n随时告诉我，我很乐意为你定制建议！ 🌟', 0, '[]', 'qwen-plus', 3082, '2026-03-27 14:58:44', 1, NULL, 0, 0, NULL);
