INSERT INTO `message` VALUES (123, 19, 122, 'assistant', '你好！我是通义千问（Qwen），阿里巴巴集团研发的超大规模语言模型。我能够回答问题、创作文字（如故事、公文、邮件、剧本等）、进行逻辑推理、编程，也能表达观点、辅助学习和娱乐等。我支持多种语言，注重准确、友好与实用。如果你有任何问题或需要帮助，随时告诉我，我很乐意为你效劳！😊', 0, '[]', 'qwen-plus', 2086, '2026-03-28 00:39:38', 0, '1774629575743_6e6dae60160eb8', 0, 0, NULL);
