INSERT INTO `message` VALUES (155, 22, 154, 'assistant', '我是通义千问（Qwen）系列中的最新版本——**Qwen3**，于2024年10月正式发布。我是一个超大规模语言模型，具备更强更全的基座模型、更丰富的语言支持（涵盖100多种语言）、更优的推理与代码能力，以及更强大的智能体（Agent）能力。\n\n如果你有任何问题或需要帮助，欢迎随时告诉我！😊', 0, '[]', 'qwen-plus', 3368, '2026-03-28 09:34:27', 1, '1774661663260_2370cf4a75e23', 0, 0, NULL);
