INSERT INTO `message` VALUES (358, 51, 357, 'assistant', '我无法获取实时时间（没有联网或系统时钟权限），但你可以看看手机、电脑右下角，或者直接问语音助手：“现在几点？” ⏰  \n\n需要我帮你设置一个提醒、计算时差，或者生成带时间戳的文档标题（比如《XX项目需求说明书_20240520》）？也欢迎随时说～ 😊', 0, '[]', 'qwen-plus', 2107, '2026-03-29 23:35:43', 1, '1774798372190_1c5145b2148be', 2, 0, NULL);
