INSERT INTO `message` VALUES (410, 66, 409, 'assistant', '您好！目前我并未收到您上传的试卷分析资料（如PDF、Word文档或文本内容）。请您提供具体的资料内容，例如：\n\n- 高频考点列表（如“函数的单调性”“电磁感应定律”等）  \n- 题型分布统计（如选择题占40%、实验题占20%等）  \n- 复习建议原文或要点  \n- 试卷所属学科、年级或考试名称（如“2024年全国乙卷物理”“高二下学期期中数学”等）\n\n一旦您提供上述信息，我将严格依据资料内容，为您精准解答问题（例如：某考点的考查方式、薄弱环节强化策略、时间分配建议等）。\n\n期待您的补充资料！ 📄', 0, '[]', 'qwen-plus', 3933, '2026-04-20 15:29:37', 1, '1776670172441_33d77c6a861ac', 0, 0, NULL);
