INSERT INTO `mind_map` VALUES (7, 1, 2, '4', '{\"data\":{\"text\":\"4\",\"expand\":true,\"uid\":\"d66acedd-285d-4cdf-a527-f919abb02112\",\"isActive\":false,\"fillColor\":\"transparent\",\"fontSize\":32,\"color\":\"#1e293b\"},\"children\":[{\"data\":{\"text\":\"二级节点\",\"uid\":\"b1d4cd48-b0c5-4e87-bda1-1294ef701db7\",\"expand\":true,\"richText\":false,\"isActive\":false,\"fillColor\":\"#4f46e5\",\"color\":\"#ffffff\",\"borderRadius\":8,\"borderColor\":\"#94a3b8\"},\"children\":[{\"data\":{\"text\":\"分支主题\",\"uid\":\"341c957f-112d-45a3-a01b-972e018184c0\",\"expand\":true,\"richText\":false,\"isActive\":false,\"fillColor\":\"rgba(79, 70, 229, 0.2)\",\"color\":\"#4f46e5\",\"borderRadius\":6,\"borderColor\":\"#94a3b8\",\"borderWidth\":1},\"children\":[{\"data\":{\"text\":\"分支主题\",\"uid\":\"691173b3-6a2a-4a4f-9bd2-01b3bce5f79c\",\"expand\":true,\"richText\":false,\"isActive\":false,\"color\":\"var(--color-text)\",\"borderColor\":\"#94a3b8\",\"borderWidth\":1,\"associativeLineTargets\":[\"ad828fae-4bc9-4bcd-af0a-f1b15cc633b2\"],\"associativeLineTargetControlOffsets\":[[{\"x\":-65.78559996155741,\"y\":23.33331298828125},{\"x\":91.33331298828125,\"y\":-0.10965726084856442}]],\"associativeLinePoint\":[{\"startPoint\":{\"x\":1297.7855999615574,\"y\":384.16668701171875,\"dir\":\"bottom\",\"range\":40.88108705016125},\"endPoint\":{\"x\":1098.6666870117188,\"y\":478.60965726084856,\"dir\":\"right\",\"range\":0.057029750870213745}}]},\"children\":[]},{\"data\":{\"text\":\"分支主题\",\"uid\":\"fe0a913e-75cb-4122-973e-8fcfe482090a\",\"expand\":true,\"richText\":false,\"isActive\":false,\"color\":\"var(--color-text)\",\"borderColor\":\"#94a3b8\",\"borderWidth\":1},\"children\":[]}]}]},{\"data\":{\"text\":\"二级节点\",\"uid\":\"ad828fae-4bc9-4bcd-af0a-f1b15cc633b2\",\"expand\":true,\"richText\":false,\"isActive\":false,\"fillColor\":\"#ef4444\",\"color\":\"#ffffff\",\"borderRadius\":8,\"borderColor\":\"#94a3b8\"},\"children\":[]},{\"data\":{\"text\":\"二级节点\",\"uid\":\"59076274-c439-44d1-87c3-7