INSERT INTO `mind_map` VALUES (30, 1, NULL, '联调三重鸿沟', '{\"data\":{\"text\":\"前后端联调高效实践\"},\"children\":[{\"data\":{\"text\":\"联调难点本质（三重鸿沟）\"},\"children\":[{\"data\":{\"text\":\"契约鸿沟：接口文档过时、模糊、无示例\"},\"children\":[]},{\"data\":{\"text\":\"时序鸿沟：开发节奏不同步导致等待与返工\"},\"children\":[]},{\"data\":{\"text\":\"环境鸿沟：本地/mock/测试/线上环境不一致引发CORS、鉴权等问题\"},\"children\":[]}]},{\"data\":{\"text\":\"高效联调五大实践\"},\"children\":[{\"data\":{\"text\":\"活接口文档：Swagger + OpenAPI 3.0 自动生成可交互文档\"},\"children\":[]},{\"data\":{\"text\":\"契约先行开发：MSW 拦截请求 + 自动生成 TypeScript 类型\"},\"children\":[]},{\"data\":{\"text\":\"后端联调友好模式：dev 环境提供 debug mock 接口\"},\"children\":[]},{\"data\":{\"text\":\"联调黄金3分钟检查清单：URL/Method/Headers/Body/日志/Network比对\"},\"children\":[]},{\"data\":{\"text\":\"标准化错误处理：错误码字典 + 高频问题速查表\"},\"children\":[]}]},{\"data\":{\"text\":\"核心心法\"},\"children\":[{\"data\":{\"text\":\"联调即契约验证：契约需活、准、可见、可执行\"},\"children\":[]}]}]}', '2026-04-20 00:38:10', '2026-04-20 00:38:10');
INSERT INTO `mind_map` VALUES (31, 1, 1, 'Vue-LLM全栈设计', '{\"data\":{\"text\":\"Vue-LLM全栈项目技术设计文档评价\"},\"children\":[{\"data\":{\"text\":\"结构清晰，逻辑严谨\"},\"children\":[{\"data\":{\"text\":\"ER图→建表SQL→字段语义→接口契约→时序流程→安全规范\"}},{\"data\":{\"text\":\"模块目的明确（如字段说明专解JSON/role枚举）\"}},{\"data\":{\"text\":\"接口按功能聚类（/auth、/conversations等）并配树状图\"}}]},{\"data\":{\"text\":\"细节扎实，可直接开发\"},\"children\":[{\"data\":{\"text\":\"数据库：主键/索引/外键/字符集/注释全覆盖，attachments含JSON Schema\"}},{\"data\":{\"text\":\"接口：认证标记、示例、错误码、逻辑步骤、前端场景、SSE流式解析伪代码\"}},{\"data\":{\"text\":\"边界处理：上传失败返回200、会话空状态、自动标题、删除后计数更新\"}}]},{\"data\":{\"text\":\"前后端协同友好\"},\"children\":[{\"data\":{\"text\":\"明确区分后端实现 vs 前端状态管理（localStorage/Pinia）\"}},{\"data\":{\"text\":\"提供完整时序图（注册→登录→对话→重试）\"}},{\"data\":{\"text\":\"错误码模块化编号（1xxx认证/2xxx会话）、CORS/JWT/Spring校验注解直给\"}}]},{\"data\":{\"text\":\"工程化与安全性兼顾\"},\"children\":[{\"data\":{\"text\":\"安全清单：BCrypt、JWT密钥强度、API Key隔离、SQL参数化、路径穿越防护、SSE超时\"}},{\"data\":{\"text\":\"扩展性：user_settings标注可选、models接口说明可硬编码\"}},{\"data\":{\"text\":\"性能提示：索引设计、MEDIUMTEXT、附件存JSON而非BLOB\"}}]},{\"data\":{\"text\":\"表达专业，无歧义\"},\"children\":[{\"data\":{\"text\":\"标准化：ISO 8601时间、UTF-8编码、HTTP/HTTPS、text/event-stream\"}},{\"data\":{\"text\":\"用词精准：冗余计数、系统消息（前端不渲染）、流式转发（非透传）\"}},{\"data\":{\"text\":\"枚举显式列出：role、theme、file_type等无模糊表述\"}}]}]}', '2026-04-20 00:39:15', '2026-04-20 00:39:28');
INSERT INTO `mind_map` VALUES (35, 1, 2, '初中物理知识图谱', '{\"data\":{\"text\":\"初中物理课程体系\"},\"children\":[{\"data\":{\"text\":\"核心物理内容\"},\"children\":[{\"data\":{\"text\":\"声现象：产生、传播与误区辨析\"},\"children\":[]},{\"data\":{\"text\":\"物态变化：相变规律与条件\"},\"children\":[]}]},{\"data\":{\"text\":\"课程定位与功能\"},\"children\":[{\"data\":{\"text\":\"分科起点：综合科学后的首门物理课\"},\"children\":[]},{\"data\":{\"text\":\"双路径导向：从生活走向物理，从物理走向社会\"},\"children\":[]},{\"data\":{\"text\":\"基础目标：掌握知识技能，服务实践与发展\"},\"children\":[]}]},{\"data\":{\"text\":\"课程理念与育人目标\"},\"children\":[{\"data\":{\"text\":\"根本目标：提升全体学生科学素养\"},\"children\":[]},{\"data\":{\"text\":\"能力培养：科学探究、思维习惯、实践应用\"},\"children\":[]},{\"data\":{\"text\":\"价值引领：社会责任感与正确世界观\"},\"children\":[]}]}]}', '2026-04-20 14:55:40', '2026-04-20 14:57:05');
INSERT INTO `mind_map` VALUES (37, 1, NULL, '冒泡排序', '{\"data\":{\"text\":\"冒泡排序\"},\"children\":[{\"data\":{\"text\":\"算法原理\"},\"children\":[{\"data\":{\"text\":\"相邻元素比较与交换\"}},{\"data\":{\"text\":\"每轮将最大（或最小）元素冒泡至一端\"}}]},{\"data\":{\"text\":\"实现特性\"},\"children\":[{\"data\":{\"text\":\"时间复杂度：O(n²)\"}},{\"data\":{\"text\":\"空间复杂度：O(1)，原地排序\"}},{\"data\":{\"text\":\"稳定性：稳定排序\"}}]},{\"data\":{\"text\":\"优化与应用\"},\"children\":[{\"data\":{\"text\":\"提前终止：无交换时结束\"}},{\"data\":{\"text\":\"适用场景：教学、小规模数据\"}},{\"data\":{\"text\":\"替代方案：Timsort（Python内置）\"}}]}]}', '2026-04-20 20:51:33', '2026-04-20 20:51:33');
