INSERT INTO `mind_map` VALUES (49, 1, 32, '四六级高频考点', '{\"data\":{\"text\":\"英语四六级试卷分析（CET-4）\"},\"children\":[{\"data\":{\"text\":\"高频考点\"},\"children\":[{\"data\":{\"text\":\"议论文写作：观点类\"},\"children\":[]},{\"data\":{\"text\":\"新闻听力：社会/科技/环保/健康/文化\"},\"children\":[]},{\"data\":{\"text\":\"长对话听力：校园生活/日常交流/学习规划/人际关系\"},\"children\":[]},{\"data\":{\"text\":\"独白听力：语言起源/动物行为/认知科学/消费心理/历史/交通工程\"},\"children\":[]},{\"data\":{\"text\":\"选词填空：心理学/教育学/神经科学/影视文化\"},\"children\":[]},{\"data\":{\"text\":\"匹配题：教育实践/健康科普/社会现象分析\"},\"children\":[]},{\"data\":{\"text\":\"仔细阅读：生态保护/个人成长/职业发展/文化传承/社会心理/公共政策\"},\"children\":[]},{\"data\":{\"text\":\"汉译英：中国科技成就/地域文旅发展/民生建设/农业创新\"},\"children\":[]},{\"data\":{\"text\":\"核心能力：逻辑衔接与语义复现、同义替换与词性转换、主旨归纳与推断判断、细节定位与信息匹配\"},\"children\":[]},{\"data\":{\"text\":\"学术词汇：hemispherectomy, bilateral control, grit, genetic diversity\"},\"children\":[]},{\"data\":{\"text\":\"高频功能表达：be associated with, contribute to, in turn, as much as...twice\"},\"children\":[]},{\"data\":{\"text\":\"批判性思维：AI学习、果汁健康、快时尚、着装影响等流行观念反思\"},\"children\":[]}]},{\"data\":{\"text\":\"题型分布\"},\"children\":[{\"data\":{\"text\":\"写作：15%\"},\"children\":[]},{\"data\":{\"text\":\"听力：35%\"},\"children\":[]},{\"data\":{\"text\":\"选词填空：7.5%\"},\"children\":[]},{\"data\":{\"text\":\"匹配题：7.5%\"},\"children\":[]},{\"data\":{\"text\":\"仔细阅读：20%\"},\"children\":[]},{\"data\":{\"text\":\"翻译：15%\"},\"children\":[]}]}]}', '2026-04-23 17:56:21', '2026-04-23 17:56:49');
