INSERT INTO `mind_map` VALUES (51, 1, 33, '教育观与数据素养', '{\"data\":{\"text\":\"教师招聘考试核心备考体系\"},\"children\":[{\"data\":{\"text\":\"考点结构\"},\"children\":[{\"data\":{\"text\":\"教育观（素质教育、学生主体性、全面发展）\"},\"children\":[]},{\"data\":{\"text\":\"教育研究与数据处理（Excel函数、IP地址、实证能力）\"},\"children\":[]},{\"data\":{\"text\":\"人机关系伦理（AI教育应用中的技术向善与教育不可替代性）\"},\"children\":[]}]},{\"data\":{\"text\":\"命题逻辑\"},\"children\":[{\"data\":{\"text\":\"单选题：概念辨析力（维度混淆、程度偷换、术语缩写陷阱）\"},\"children\":[]},{\"data\":{\"text\":\"主观题：政策语言转译力（理论名称+政策全称+精准行为动词）\"},\"children\":[]}]},{\"data\":{\"text\":\"能力要求\"},\"children\":[{\"data\":{\"text\":\"现象解码力（识别行为—反应—生态链式反应）\"},\"children\":[]},{\"data\":{\"text\":\"理论锚定力（匹配最小颗粒度理论）\"},\"children\":[]},{\"data\":{\"text\":\"对策生成力（可操作、可验证、合政策红线）\"},\"children\":[]}]},{\"data\":{\"text\":\"复习盲区\"},\"children\":[{\"data\":{\"text\":\"技术类考点（IPv4格式、SUMIF等教学场景化应用）\"},\"children\":[]},{\"data\":{\"text\":\"传统文化代际认知断层（艺术史坐标轴：朝代+流派+代表作）\"},\"children\":[]}]},{\"data\":{\"text\":\"提分杠杆点\"},\"children\":[{\"data\":{\"text\":\"三圈定位法（理论+政策+动词）每日精练\"},\"children\":[]},{\"data\":{\"text\":\"干扰项类型库（归类维度混淆/程度偷换/缩写陷阱）\"},\"children\":[]},{\"data\":{\"text\":\"政策术语对照卡（原文 vs 易错缩写）\"},\"children\":[]}]}]}', '2026-06-18 20:13:14', '2026-06-18 20:13:23');
INSERT INTO `mind_map` VALUES (52, 1, 1, '冒泡排序', '{\"data\":{\"text\":\"冒泡排序\"},\"children\":[{\"data\":{\"text\":\"算法实现\"},\"children\":[{\"data\":{\"text\":\"Python代码及注释\"}}]},{\"data\":{\"text\":\"算法特性\"},\"children\":[{\"data\":{\"text\":\"时间复杂度：O(n²)（最坏/平均），O(n)（最好）\"}},{\"data\":{\"text\":\"空间复杂度：O(1)，原地排序\"}},{\"data\":{\"text\":\"稳定性：稳定排序\"}}]},{\"data\":{\"text\":\"核心机制\"},\"children\":[{\"data\":{\"text\":\"相邻元素比较与交换\"}},{\"data\":{\"text\":\"每轮将最大元素‘冒泡’至末尾\"}},{\"data\":{\"text\":\"优化：提前终止（无交换即有序）\"}}]}]}', '2026-07-16 17:46:28', '2026-07-16 17:46:41');
