INSERT INTO `system_config` VALUES (1, 'prompt.system.rag', '你是一个专业的知识库问答助手。请根据以下参考资料回答用户的问题。\n\n要求：\n1. 只根据提供的参考资料回答，不要编造信息\n2. 如果参考资料中没有相关内容，请明确告知用户\n3. 回答要准确、简洁、有条理\n4. 如果可以，请指出信息来源于哪个文档', 'string', 'RAG问答系统提示词', '2026-03-24 18:44:54', '2026-03-24 18:44:54');
INSERT INTO `system_config` VALUES (2, 'prompt.system.general', '你是一个友好的AI助手，请用简洁准确的语言回答用户的问题。', 'string', '通用对话系统提示词', '2026-03-24 18:44:54', '2026-03-24 18:44:54');
INSERT INTO `system_config` VALUES (3, 'prompt.context.template', '以下是从知识库中检索到的相关参考资料：\n\n{context}\n\n请根据以上参考资料回答用户问题。如果参考资料不足以回答问题，请如实告知。', 'string', 'RAG上下文模板', '2026-03-24 18:44:54', '2026-03-24 18:44:54');
INSERT INTO `system_config` VALUES (4, 'rag.chunk_size', '500', 'number', '文档分块大小（字符数）', '2026-03-24 18:44:54', '2026-03-24 18:44:54');
INSERT INTO `system_config` VALUES (5, 'rag.chunk_overlap', '100', 'number', '分块重叠大小（字符数）', '2026-03-24 18:44:54', '2026-03-24 18:44:54');
INSERT INTO `system_config` VALUES (6, 'rag.top_k', '5', 'number', '向量检索返回数量', '2026-03-24 18:44:54', '2026-03-24 18:44:54');
INSERT INTO `system_config` VALUES (7, 'rag.min_score', '0.6', 'number', '最低相似度阈值', '2026-03-24 18:44:54', '2026-03-24 18:44:54');
