  `content` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL COMMENT '试卷文件提取的文本内容',
  `key_points` json NULL COMMENT '高频考点JSON',
  `question_distribution` json NULL COMMENT '题型分布JSON',
  `suggestions` text CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL COMMENT '复习建议',
  `mind_map_id` bigint NULL DEFAULT NULL COMMENT '关联的思维导图ID',
